INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/1] การอ่านออกเสียงบทร้อยแก้วและบทร้อยกรอง', 'easy', 'mcq', 'คำในข้อใดอ่านออกเสียงอักษรนำถูกต้อง?', '["ผลิต อ่านว่า ผะ-ลิด","ปรารถนา อ่านว่า ปราด-ถะ-หนา","ตลาด อ่านว่า ตะ-หลาด","สมาคม อ่านว่า สะ-มา-คม"]'::jsonb, '2'::jsonb, '"ตลาด" เป็นคำที่มีอักษรนำ (ต นำ ล) อ่านออกเสียงสองพยางค์ พยางค์หลังออกเสียงเหมือนมี ห นำ คือ ตะ-หลาด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/1] การอ่านออกเสียงคำที่มี ร ล ว ควบกล้ำ', 'easy', 'mcq', 'ข้อใดมีคำควบกล้ำแท้ทุกคำ?', '["สร้างเสริม, จริงจัง","กราบพระ, กว้างขวาง","เศรษฐี, ทรงทราบ","เสร็จสิ้น, ปราศจาก"]'::jsonb, '1'::jsonb, 'กราบพระ (กร), กว้างขวาง (กว) เป็นคำควบกล้ำแท้ที่ออกเสียงพยัญชนะต้นสองตัวพร้อมกัน ส่วนข้ออื่นมีคำควบไม่แท้ปนอยู่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การอธิบายความหมายของคำ ประโยค และสำนวน', 'medium', 'mcq', 'สำนวน "ขี่ช้างจับตั๊กแตน" มีความหมายตรงกับข้อใด?', '["ทำงานใหญ่แต่ได้ผลประโยชน์น้อย","ทำสิ่งที่เป็นไปไม่ได้ให้สำเร็จ","มีความพยายามอย่างยิ่งยวด","ทำลายสิ่งของเพื่อประโยชน์ส่วนตัว"]'::jsonb, '0'::jsonb, '"ขี่ช้างจับตั๊กแตน" หมายถึง การลงทุนหรือลงแรงทำสิ่งใหญ่โตแต่ได้ผลตอบแทนเพียงเล็กน้อย ไม่คุ้มค่า');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การเข้าใจความหมายของคำศัพท์ในบริบท', 'medium', 'mcq', 'คำว่า "มัธยัสถ์" มีความหมายตรงข้ามกับคำในข้อใด?', '["ตระหนี่","ฟุ่มเฟือย","รอบคอบ","ประหยัด"]'::jsonb, '1'::jsonb, 'มัธยัสถ์ หมายถึง การใช้จ่ายอย่างประหยัดพอเหมาะ จึงมีความหมายตรงข้ามกับคำว่า "ฟุ่มเฟือย"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/3] การอ่านจับใจความจากสื่อต่างๆ', 'medium', 'mcq', '"ต้นไม้ช่วยดูดซับก๊าซคาร์บอนไดออกไซด์และคายก๊าซออกซิเจนให้สิ่งมีชีวิตใช้หายใจ นอกจากนี้รากยังช่วยยึดดินไม่ให้พังทลาย" ใจความสำคัญของข้อความนี้คืออะไร?', '["รากของต้นไม้ยึดดินได้ดี","ต้นไม้มีประโยชน์ต่อสิ่งมีชีวิตและสิ่งแวดล้อม","สิ่งมีชีวิตทุกชนิดต้องหายใจ","ก๊าซออกซิเจนเกิดจากต้นไม้เท่านั้น"]'::jsonb, '1'::jsonb, 'ใจความสำคัญสรุปรวมถึงประโยชน์ของต้นไม้ทั้งในด้านการให้อากาศหายใจและการช่วยยึดหน้าดิน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น', 'medium', 'mcq', 'ข้อความใดต่อไปนี้เป็น "ข้อคิดเห็น"?', '["ประเทศไทยตั้งอยู่ในทวีปเอเชีย","น้ำจะเดือดที่อุณหภูมิ 100 องศาเซลเซียส","ดอกกุหลาบสีแดงเป็นดอกไม้ที่สวยงามที่สุดในโลก","ดวงอาทิตย์ขึ้นทางทิศตะวันออก"]'::jsonb, '2'::jsonb, 'ความสวยงามเป็นความรู้สึกส่วนบุคคล ไม่สามารถพิสูจน์ให้ทุกคนยอมรับตรงกันได้ จึงเป็นข้อคิดเห็น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น', 'easy', 'mcq', 'ข้อความใดเป็น "ข้อเท็จจริง"?', '["วันนี้อากาศร้อนจนน่าหงุดหงิด","เด็กที่เล่นกีฬาเป็นคนมีน้ำใจทุกคน","จังหวัดขอนแก่นตั้งอยู่ในภาคตะวันออกเฉียงเหนือ","วิชาคณิตศาสตร์ยากกว่าวิชาภาษาไทย"]'::jsonb, '2'::jsonb, 'ที่ตั้งของจังหวัดขอนแก่นเป็นความจริงทางภูมิศาสตร์ที่มีหลักฐานยืนยันชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/5] การคาดคะเนเหตุการณ์จากเรื่องที่อ่าน', 'medium', 'mcq', '"เมฆดำทมิฬลอยปกคลุมทั่วท้องฟ้า ลมพัดกรรโชกแรง ฟ้าแลบแปลบปลาบ" จากข้อความนี้จะเกิดเหตุการณ์ใดตามมา?', '["อากาศหนาวจัดจนเกิดหิมะ","ฝนกำลังจะตกหนักและอาจมีพายุ","เกิดแผ่นดินไหวรุนแรง","เกิดน้ำท่วมฉับพลันในทันที"]'::jsonb, '1'::jsonb, 'สัญญาณเมฆดำ ลมแรง และฟ้าแลบ เป็นสัญญาณบ่งบอกว่าฝนและพายุกำลังจะตก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/6] การสรุปความรู้และข้อคิดจากการอ่านเพื่อนำไปใช้', 'hard', 'mcq', 'นิทานเรื่อง "กระต่ายกับเต่า" ให้ข้อคิดเตือนใจเรื่องใดมากที่สุด?', '["ความคล่องแคล่วว่องไวทำให้ชนะเสมอ","ความประมาทเป็นหนทางสู่ความล้มเหลว","การเดินช้าช่วยรักษาสุขภาพ","ควรแข่งขันกับคนที่อ่อนแอกว่า"]'::jsonb, '1'::jsonb, 'กระต่ายแพ้เพราะประมาทและชะล่าใจ นอนหลับระหว่างทาง ส่วนเต่าชนะเพราะความเพียรพยายาม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/7] การอ่านหนังสือที่มีคุณค่าตามความสนใจ', 'easy', 'mcq', 'มารยาทในการอ่านหนังสือในห้องสมุดข้อใดถูกต้องที่สุด?', '["พูดคุยปรึกษาการบ้านกับเพื่อนเสียงดัง","นำขนมและน้ำหวานเข้าไปรับประทานขณะอ่าน","พับมุมหนังสือเพื่อทำเครื่องหมายหน้าคั่น","รักษาความเงียบและเก็บหนังสือเข้าที่ให้เรียบร้อย"]'::jsonb, '3'::jsonb, 'การรักษาความเงียบและการเก็บหนังสือเข้าที่เดิมเป็นมารยาทสำคัญของการใช้ห้องสมุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/8] การมีมารยาทในการอ่าน', 'easy', 'mcq', 'หากต้องการอ่านหนังสือพิมพ์ที่ผู้อื่นกำลังอ่านอยู่ ควรทำอย่างไร?', '["ดึงมาอ่านทันทีเพราะอยากอ่านมาก","ชะโงกหน้าเข้าไปอ่านใกล้ๆ","รอให้ผู้อื่นอ่านเสร็จก่อนแล้วจึงขออ่านต่อ","หยิบหน้าอื่นที่เขายังไม่ได้เปิดมาอ่าน"]'::jsonb, '2'::jsonb, 'การรอให้ผู้อื่นอ่านเสร็จอย่างสุภาพเป็นมารยาทที่ดีในการอ่านร่วมกับผู้อื่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 1.1 ป.4/2] การเข้าใจความหมายของสำนวนไทย', 'medium', 'mcq', 'คนที่ไม่ยอมลงมือทำงานแต่วิพากษ์วิจารณ์คนอื่น ตรงกับสำนวนใด?', '["มือไม่พายเอาเท้าราน้ำ","น้ำขึ้นให้รีบตัก","จับปลาสองมือ","ชี้โพรงให้กระรอก"]'::jsonb, '0'::jsonb, '"มือไม่พายเอาเท้าราน้ำ" หมายถึง คนที่ไม่ช่วยเหลืองานแล้วยังทำตัวเกะกะขัดขวางการทำงานของผู้อื่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/1] การคัดลายมือตัวบรรจงเต็มบรรทัดและครึ่งบรรทัด', 'easy', 'mcq', 'ข้อใดเป็นหลักการคัดลายมือตัวบรรจงที่ถูกต้อง?', '["เขียนตัวเอียงมากๆ เพื่อความสวยงาม","เขียนหัวพยัญชนะให้ชัดเจน วางสระวรรณยุกต์ตรงตำแหน่ง","เว้นวรรคช่องไฟให้ห่างมากที่สุด","ลากเส้นตวัดหางให้ยาวทับบรรทัดอื่น"]'::jsonb, '1'::jsonb, 'การคัดลายมือที่ถูกต้องต้องเขียนหัวตัวอักษรกลมชัดเจน วางสระและวรรณยุกต์ตรงตำแหน่งตามหลักเกณฑ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/2] การเขียนสื่อความโดยใช้คำได้ถูกต้องชัดเจน', 'medium', 'mcq', 'ประโยคใดใช้คำลักษณนามถูกต้อง?', '["คุณพ่อซื้อช้อนมา 2 อัน","คุณแม่ซื้อแหวนทอง 1 วง","คุณครูมีดินสอ 3 ด้าม","พี่ชายกางร่ม 1 อัน"]'::jsonb, '1'::jsonb, 'แหวนใช้ลักษณนามว่า "วง" (ช้อนใช้ "คัน", ดินสอใช้ "แท่ง", ร่มใช้ "คัน")');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/3] การเขียนแผนภาพโครงเรื่องและแผนภาพความคิด', 'medium', 'mcq', 'องค์ประกอบใด "ไม่จำเป็น" ต้องมีในแผนภาพโครงเรื่องของนิทาน?', '["ตัวละคร","สถานที่และเวลา","เหตุการณ์และผลของเหตุการณ์","ราคาจำหน่ายของหนังสือนิทาน"]'::jsonb, '3'::jsonb, 'แผนภาพโครงเรื่องประกอบด้วย ใคร (ตัวละคร), ที่ไหน (ฉาก/เวลา), ทำอะไร (เหตุการณ์), และผลเป็นอย่างไร ข้อคิดที่ได้ ไม่เกี่ยวกับราคาหนังสือ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/4] การเขียนย่อความจากเรื่องสั้นๆ', 'hard', 'mcq', 'ข้อใดเป็นข้อปฏิบัติที่ถูกต้องในการเขียนย่อความ?', '["คัดลอกข้อความเดิมทั้งหมดมาตัดต่อใหม่","เปลี่ยนสรรพนามบุรุษที่ 1 และ 2 เป็นบุรุษที่ 3","ใส่เครื่องหมายอัญประกาศแสดงคำพูดเดิมเสมอ","เติมความรู้สึกส่วนตัวของผู้เขียนลงไปด้วย"]'::jsonb, '1'::jsonb, 'การเขียนย่อความต้องเรียบเรียงด้วยสำนวนตนเอง และเปลี่ยนสรรพนามบุรุษที่ 1 และ 2 ให้เป็นบุรุษที่ 3 เสมอ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/5] การเขียนจดหมายถึงเพื่อนและบิดามารดา', 'medium', 'mcq', 'คำขึ้นต้นในการเขียนจดหมายถึงบิดามารดาที่ถูกต้องคือข้อใด?', '["สวัสดีคุณพ่อคุณแม่ที่รัก","กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง","ถึงคุณพ่อคุณแม่","เรียนคุณพ่อคุณแม่ที่นับถือ"]'::jsonb, '1'::jsonb, 'คำขึ้นต้นจดหมายถึงบิดามารดาตามแบบแผนคือ "กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง" และคำลงท้ายคือ "ด้วยความเคารพรักอย่างสูง"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/6] การเขียนบันทึกและการเขียนรายงานความรู้', 'easy', 'mcq', 'ข้อใดเป็นข้อมูลสำคัญที่ต้องระบุในการเขียนบันทึกประจำวัน?', '["ชื่อสำนักพิมพ์","วัน เดือน ปี และเวลาที่เกิดเหตุการณ์","ราคาของสมุดบันทึก","เลขบัตรประจำตัวประชาชน"]'::jsonb, '1'::jsonb, 'การบันทึกประจำวันต้องระบุ วัน เดือน ปี และเวลาเพื่อบันทึกลำดับเหตุการณ์ที่เกิดขึ้นจริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/7] การเขียนเรื่องตามจินตนาการ', 'medium', 'mcq', 'สิ่งสำคัญที่สุดในการเขียนเรื่องตามจินตนาการคือข้อใด?', '["การคัดลอกเนื้อเรื่องจากภาพยนตร์ชื่อดัง","ความคิดริเริ่มสร้างสรรค์และข้อคิดที่เป็นประโยชน์","การใช้คำศัพท์ภาษาต่างประเทศให้มากที่สุด","การเขียนเรื่องที่ยาวเกิน 10 หน้ากระดาษ"]'::jsonb, '1'::jsonb, 'การเขียนเรื่องตามจินตนาการต้องอาศัยความคิดริเริ่มสร้างสรรค์ ความสมเหตุสมผล และมีข้อคิดสอนใจที่ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 2.1 ป.4/8] การมีมารยาทในการเขียน', 'easy', 'mcq', 'การกระทำใดถือว่า "ไม่มีมารยาท" ในการเขียน?', '["ใช้น้ำยาลบคำผิดลบให้สะอาดเรียบร้อย","เขียนข้อความขีดเขียนบนโต๊ะเรียนและผนังห้องน้ำ","ใช้ภาษาที่สุภาพ เหมาะสมกับกาลเทศะ","ตรวจสอบความถูกต้องของตัวสะกดก่อนส่ง"]'::jsonb, '1'::jsonb, 'การขีดเขียนในที่สาธารณะ เช่น โต๊ะเรียน ผนังห้องน้ำ ถือเป็นการทำลายทรัพย์สินและขาดมารยาทอย่างยิ่ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/1] การจำแนกข้อเท็จจริงและข้อคิดเห็นจากเรื่องที่ฟังและดู', 'medium', 'mcq', 'จากการฟังโฆษณา "ยาสีฟันนี้ใช้แล้วฟันขาวสะอาดใน 3 วินาที ดาราชื่อดังทุกคนเลือกใช้" ข้อใดคือข้อคิดเห็นเกินจริง?', '["ยาสีฟันเป็นของใช้ในชีวิตประจำวัน","ดาราใช้ยาสีฟันทำความสะอาดฟัน","ใช้แล้วฟันขาวสะอาดภายใน 3 วินาที","ยาสีฟันมีจำหน่ายในท้องตลาด"]'::jsonb, '2'::jsonb, 'การกล่าวอ้างว่าฟันขาวได้ในเวลาเพียง 3 วินาทีเป็นการโฆษณาชวนเชื่อที่เกินความเป็นจริงทางวิทยาศาสตร์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/2] การจับใจความและพูดแสดงความคิดเห็น', 'medium', 'mcq', 'เมื่อฟังเพื่อนพูดรายงานหน้าชั้นเรียน การกระทำใดเหมาะสมที่สุด?', '["นั่งหลับพักผ่อน","ตั้งใจฟังและจดบันทึกประเด็นสำคัญ","คุยล้อเลียนน้ำเสียงของเพื่อน","ลุกเดินไปมาในห้องเรียน"]'::jsonb, '1'::jsonb, 'การตั้งใจฟังและจดบันทึกเป็นมารยาทและทักษะที่ดีในการรับสารจากการพูดรายงาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/3] การพูดรายงานเรื่องหรือประเด็นที่ศึกษาค้นคว้า', 'medium', 'mcq', 'ขั้นตอนแรกในการเตรียมตัวพูดรายงานหน้าชั้นเรียนคือข้อใด?', '["แต่งกายด้วยชุดแฟนซี","กำหนดหัวข้อและวางแผนค้นคว้าข้อมูล","ฝึกพูดเสียงดังตะโกน","เตรียมของแจกให้เพื่อน"]'::jsonb, '1'::jsonb, 'การกำหนดหัวข้อและค้นคว้าข้อมูลอย่างเป็นระบบเป็นขั้นตอนแรกที่สำคัญที่สุดในการเตรียมรายงาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/4] การตั้งคำถามและตอบคำถามเชิงเหตุผล', 'easy', 'mcq', 'คำถามข้อใดเป็นคำถามเชิงเหตุผล?', '["วันแม่แห่งชาติตรงกับวันที่เท่าไร?","ทำไมเราจึงต้องช่วยกันประหยัดน้ำและไฟฟ้า?","ใครเป็นหัวหน้าห้อง ป.4?","เธอชอบสีอะไรมากที่สุด?"]'::jsonb, '1'::jsonb, 'คำถามที่ขึ้นต้นด้วย "ทำไม" ต้องการคำตอบที่อธิบายเหตุผล ผลกระทบ และความสำคัญ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/5] การพูดลำดับขั้นตอนการปฏิบัติงาน', 'medium', 'mcq', 'คำเชื่อมข้อใดเหมาะสำหรับใช้พูดลำดับขั้นตอนการทำงานมากที่สุด?', '["อย่างไรก็ตาม, แม้ว่า","ขั้นแรก, ต่อมา, จากนั้น, สุดท้าย","เพราะฉะนั้น, จึง","เช่น, ได้แก่"]'::jsonb, '1'::jsonb, 'คำว่า "ขั้นแรก, ต่อมา, จากนั้น, สุดท้าย" ช่วยบอกลำดับขั้นตอนก่อนหลังได้อย่างชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 3.1 ป.4/6] การมีมารยาทในการฟัง การดู และการพูด', 'easy', 'mcq', 'หากมีข้อสงสัยขณะที่วิทยากรกำลังบรรยาย ควรปฏิบัติอย่างไร?', '["ตะโกนถามแทรกขึ้นมาทันที","ยกมือขึ้นรอให้วิทยากรเปิดโอกาสให้ถามก่อน","คุยถามเพื่อนข้างๆ ให้รู้เรื่องเดี๋ยวนั้น","เดินขึ้นไปถามบนเวที"]'::jsonb, '1'::jsonb, 'มารยาทที่ดีคือการยกมือและรอจังหวะที่ผู้พูดอนุญาตหรือช่วงเปิดซักถามท้ายการบรรยาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] อักษรสามหมู่ (ไตรยางศ์)', 'easy', 'mcq', 'พยัญชนะในข้อใดจัดเป็น "อักษรสูง" ทั้งหมด?', '["ข, ฉ, ถ, ผ, ส","ก, จ, ด, ต, บ","ค, ช, ซ, ท, พ","ง, ญ, น, ย, ม"]'::jsonb, '0'::jsonb, 'อักษรสูงมี 11 ตัว ได้แก่ ข ฃ ฉ ฐ ถ ผ ฝ ศ ษ ส ห (ท่องจำ: ผีฝากถุงข้าวสารให้ฉัน)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] อักษรกลางและการผันวรรณยุกต์', 'easy', 'mcq', 'คำในข้อใดผันเสียงวรรณยุกต์ได้ครบทั้ง 5 เสียง?', '["ไข่ (อักษรสูง)","กา (อักษรกลาง คำเป็น)","คา (อักษรต่ำ คำเป็น)","กบ (อักษรกลาง คำตาย)"]'::jsonb, '1'::jsonb, 'อักษรกลางที่เป็นคำเป็น เช่น "กา" สามารถผันได้ครบทั้ง 5 เสียงวรรณยุกต์ (กา ก่า ก้า ก๊า ก๋า)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำเป็นและคำตาย', 'medium', 'mcq', 'ข้อใดมีคำตายทุกคำ?', '["มด, กบ, นก, เมฆ","บ้าน, เมือง, นอน, ลม","ใจ, ดำ, ไป, มา","ดาว, เดือน, ลอย, น้ำ"]'::jsonb, '0'::jsonb, 'มด (กด), กบ (กบ), นก (กก), เมฆ (กก) มีตัวสะกดในแม่ กบด (กบ กบด) ซึ่งเป็นคำตายทั้งหมด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] มาตราตัวสะกดตรงมาตราและไม่ตรงมาตรา', 'easy', 'mcq', 'คำว่า "มงกุฎ, ปรากฏ, ตำรวจ" สะกดในมาตราใด?', '["แม่กก","แม่กด","แม่กน","แม่กบ"]'::jsonb, '1'::jsonb, 'ฎ, ฏ, จ ออกเสียงตัวสะกดเหมือน ด จึงจัดอยู่ในมาตราแม่กด (ไม่ตรงรูป)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] สระเดี่ยวและสระประสม', 'medium', 'mcq', 'คำในข้อใดใช้ "สระประสม" ทั้งหมด?', '["กิน, นอน","เสือ, เรือ, เกลือ","ตา, ยาย","เด็ก, เล็ก"]'::jsonb, '1'::jsonb, 'สระประสมมี 3 เสียงหลักคือ เอียะ/เอีย, เอือะ/เอือ, อัวะ/อัว (เสือ เรือ เกลือ ใช้สระเอือ)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำนาม', 'easy', 'mcq', 'คำนามที่ชี้เฉพาะเจาะจง (วิสามานยนาม) คือคำในข้อใด?', '["โรงเรียน","โรงเรียนบ้านคำไผ่","คุณครู","นักเรียน"]'::jsonb, '1'::jsonb, '"โรงเรียนบ้านคำไผ่" เป็นชื่อเฉพาะเจาะจงของโรงเรียนแห่งเดียว จัดเป็นวิสามานยนาม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำสรรพนาม', 'easy', 'mcq', '"ข้าพเจ้าขอขอบคุณทุกท่านที่มาร่วมงาน" คำว่า "ข้าพเจ้า" เป็นคำสรรพนามชนิดใด?', '["สรรพนามบุรุษที่ 1","สรรพนามบุรุษที่ 2","สรรพนามบุรุษที่ 3","สรรพนามชี้เฉพาะ"]'::jsonb, '0'::jsonb, '"ข้าพเจ้า" ใช้แทนตัวผู้พูด จึงเป็นสรรพนามบุรุษที่ 1');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำกริยา', 'medium', 'mcq', 'ประโยคใดมี "สกรรมกริยา" (คำกริยาที่ต้องมีกรรมมารับ)?', '["น้องหัวเราะเสียงดัง","นกบินบนท้องฟ้า","ชาวนาเกี่ยวข้าวในทุ่ง","ฝนตกหนักมาก"]'::jsonb, '2'::jsonb, '"เกี่ยว" เป็นสกรรมกริยา เพราะต้องมีกรรมมารับคือ "ข้าว" ส่วนหัวเราะ บิน ตก ไม่ต้องมีกรรมรับ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/2] ชนิดของคำ: คำวิเศษณ์', 'medium', 'mcq', 'ในประโยค "เต่าตัวโตเดินช้ามาก" คำใดเป็นคำวิเศษณ์บอกอาการ?', '["เต่า","เดิน","ช้า","ตัวโต"]'::jsonb, '2'::jsonb, '"ช้า" ทำหน้าที่ขยายกริยา "เดิน" เพื่อบอกลักษณะท่าทางการเคลื่อนที่ จึงเป็นคำวิเศษณ์บอกอาการ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/3] การใช้พจนานุกรมค้นหาความหมายของคำ', 'hard', 'mcq', 'การเรียงลำดับคำตามพจนานุกรม ข้อใดเรียงได้ถูกต้อง?', '["กล้วย, กวาง, ข้าว, ไข่","ขวด, ข้าว, กล้วย, กาก","จาน, ชาม, ข้าว, ดิน","ปลา, นก, ม้า, ลิง"]'::jsonb, '0'::jsonb, 'พจนานุกรมเรียงตามพยัญชนะ ก-ฮ (กล้วย -> กวาง -> ข้าว -> ไข่ โดย ก มาก่อน ข)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/3] การเรียงลำดับสระในพจนานุกรม', 'hard', 'mcq', 'คำที่มีพยัญชนะต้นเหมือนกัน ข้อใดเรียงตามลำดับรูปสระในพจนานุกรมถูกต้อง?', '["กา, กะ, กิ, กี","กะ, กา, กิ, กี","กิ, กี, กะ, กา","กา, กิ, กะ, กี"]'::jsonb, '1'::jsonb, 'ลำดับรูปสระเริ่มจาก -ะ (วิสรรชนีย์), -า (ลากข้าง), -ิ (พินทุ์อิ), -ี (ฟันหนู) ตามลำดับ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/4] ส่วนประกอบของประโยค', 'medium', 'mcq', 'ประโยคใดมีส่วนประกอบครบ "ประธาน + กริยา + กรรม"?', '["ดวงอาทิตย์ส่องแสงเจิดจ้า","คุณแม่ทำอาหารในครัว","เด็กๆ วิ่งเล่นในสนาม","น้ำไหลรินอย่างช้าๆ"]'::jsonb, '1'::jsonb, 'ประธาน = คุณแม่, กริยา = ทำ, กรรม = อาหาร (ในครัว = ขยายสถานที่)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/4] ประโยค 2 ส่วน และประโยค 3 ส่วน', 'medium', 'mcq', 'ข้อใดจัดเป็น "ประโยค 2 ส่วน"?', '["แมวจับหนู","คุณครูสอนหนังสือ","ดอกมะลิส่งกลิ่นหอมฟุ้ง","พี่ชายอ่านนิทาน"]'::jsonb, '2'::jsonb, 'ดอกมะลิ (ประธาน) + ส่งกลิ่นหอมฟุ้ง (กริยาและขยายกริยา) ไม่มีกรรมมารับ จัดเป็นประโยค 2 ส่วน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] ประโยคบอกเล่า ปฏิเสธ คำถาม ขอร้อง และคำสั่ง', 'easy', 'mcq', '"กรุณาถอดรองเท้าก่อนเข้าห้องเรียน" เป็นประโยคชนิดใด?', '["ประโยคคำสั่ง","ประโยคขอร้อง","ประโยคปฏิเสธ","ประโยคบอกเล่า"]'::jsonb, '1'::jsonb, 'ประโยคที่มีคำว่า "กรุณา", "โปรด", "วาน" เป็นประโยคขอร้องเพื่อขอความร่วมมืออย่างสุภาพ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำราชาศัพท์สำหรับพระมหากษัตริย์และพระสงฆ์', 'medium', 'mcq', 'คำราชาศัพท์ว่า "พระเนตร" หมายถึงอวัยวะใด?', '["หู","ตา","จมูก","ปาก"]'::jsonb, '1'::jsonb, 'พระเนตร หมายถึง ดวงตา (พระกรรณ = หู, พระนาสิก = จมูก, พระโอษฐ์ = ปาก)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำสุภาพที่ใช้สำหรับพระสงฆ์', 'easy', 'mcq', 'คำว่า "กิน" สำหรับพระภิกษุสงฆ์ควรใช้คำใด?', '["เสวย","ฉัน","รับประทาน","จำวัด"]'::jsonb, '1'::jsonb, 'พระสงฆ์ใช้คำว่า "ฉัน" (เสวย ใช้กับพระมหากษัตริย์, จำวัด หมายถึง นอน)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/6] คำสุภาพในภาษาไทย', 'medium', 'mcq', 'คำสุภาพของคำว่า "ผักบุ้ง" คือคำในข้อใด?', '["ผักรู้นอน","ผักทอดยอด","ฟักเหลือง","นารีจำศีล"]'::jsonb, '1'::jsonb, 'ผักทอดยอด เป็นคำสุภาพของผักบุ้ง (ผักรู้นอน = ผักกระเฉด, ฟักเหลือง = ฟักทอง)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/7] สำนวน สุภาษิต และคำพังเพย', 'medium', 'mcq', 'สำนวนใดหมายถึง "การพูดหรือกระทำสิ่งที่เป็นภัยต่อตนเอง"?', '["ปลาหมอตายเพราะปาก","ช้างตายทั้งตัวเอาใบบัวมาปิด","ไก่เห็นตีนงู งูเห็นนมไก่","ขี่ช้างจับตั๊กแตน"]'::jsonb, '0'::jsonb, '"ปลาหมอตายเพราะปาก" หมายถึง คนที่พูดพล่อยจนได้รับอันตรายหรือความเดือดร้อนถึงตัว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/7] การใช้สำนวนเปรียบเทียบ', 'easy', 'mcq', 'คนที่ทำความดีโดยไม่ต้องการให้ใครชมเชย ตรงกับสำนวนใด?', '["ปิดทองหลังพระ","กบในกะลาครอบ","น้ำซึมบ่อทราย","เข็นครกขึ้นภูเขา"]'::jsonb, '0'::jsonb, '"ปิดทองหลังพระ" หมายถึง การทำความดีโดยไม่ป่าวประกาศหรือหวังชื่อเสียงลาภยศ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำที่มีเครื่องหมายทัณฑฆาต (การันต์)', 'easy', 'mcq', 'คำในข้อใดเขียนสะกดการันต์ถูกต้อง?', '["สัตว์แพทย์","สัตย์แพทย์","สัตวแพทย์","สัตถ์แพทย์"]'::jsonb, '2'::jsonb, '"สัตวแพทย์" (สัต-ตะ-วะ-แพด) เขียนโดยไม่มีไม้ทัณฑฆาตที่ ว เพื่อให้ออกเสียงเชื่อมสมาส');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำพ้องรูปและคำพ้องเสียง', 'medium', 'mcq', 'คำว่า "กานต์, กาล, การ, กาฬ" จัดเป็นคำประเภทใด?', '["คำพ้องรูป","คำพ้องเสียง","คำพ้องความหมาย","คำซ้อน"]'::jsonb, '1'::jsonb, 'ออกเสียงว่า "กาน" เหมือนกันทุกคำ แต่เขียนต่างรูปและมีความหมายต่างกัน จึงเป็น "คำพ้องเสียง"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/1] คำพ้องรูป', 'hard', 'mcq', '"เพลา" สามารถอ่านออกเสียงได้ 2 แบบที่มีความหมายต่างกัน คือข้อใด?', '["เพ-ลา (เวลา) และ เพลา (แกนดุมล้อ/เบาลง)","เพ-ลา (ต้นไม้) และ เพ-ลา (แม่น้ำ)","เพลา (ลม) และ เพลา (ไฟ)","เพ-ลา (ความสุข) และ เพลา (ความเศร้า)"]'::jsonb, '0'::jsonb, '"เพลา" เขียนเหมือนกันแต่อ่านได้สองแบบ: เพ-ลา หมายถึง กาลเวลา และ เพลา หมายถึง แกนล้อหรือเบาลง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] การใช้เครื่องหมายวรรคตอน', 'easy', 'mcq', 'เครื่องหมาย "ไม้ยมก" (ๆ) ใช้ในกรณีใด?', '["ใช้แสดงคำตกหล่น","ใช้เขียนซ้ำคำหรือวลี","ใช้แสดงความตกใจ","ใช้ละข้อความตอนท้าย"]'::jsonb, '1'::jsonb, 'ไม้ยมก (ๆ) ใช้เขียนไว้หลังคำ วลี หรือประโยคเพื่อให้อ่านซ้ำคำ เช่น เด็กๆ, นานๆ ครั้ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 4.1 ป.4/5] การใช้เครื่องหมายอัศเจรีย์ (!)', 'easy', 'mcq', 'เครื่องหมายอัศเจรีย์ (!) นิยมใช้หลังคำชนิดใด?', '["คำนาม","คำอุทานแสดงอารมณ์","คำสรรพนาม","คำสันธาน"]'::jsonb, '1'::jsonb, 'เครื่องหมายอัศเจรีย์ (!) วางไว้หลังคำอุทานบอกอาการ เช่น ไชโย! โอ๊ย! คุณพระช่วย!');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณคดีเรื่อง พระอภัยมณี (ตอน กำเนิดสุดสาคร)', 'easy', 'mcq', 'สุดสาครเป็นโอรสของพระอภัยมณีกับใคร?', '["นางผีเสื้อสมุทร","นางสุวรรณมาลี","นางเงือก","นางละเวงวัณฬา"]'::jsonb, '2'::jsonb, 'สุดสาครเป็นบุตรของพระอภัยมณีกับนางเงือกที่ช่วยพาพระอภัยมณีหนีนางผีเสื้อสมุทรไปยังเกาะแก้วพิสดาร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] สัตว์พาหนะคู่ใจของสุดสาคร', 'easy', 'mcq', 'ม้านิลมังกร พาหนะของสุดสาคร มีลักษณะผสมระหว่างสัตว์ชนิดใด?', '["หัวเป็นม้า ตัวเป็นช้าง","หัวเป็นมังกร ตัวเป็นม้า หางเป็นนาค ลำตัวดั่งนิลกาฬ","หัวเป็นสิงโต ตัวเป็นม้า","หัวเป็นพญานาค ตัวเป็นนกอินทรี"]'::jsonb, '1'::jsonb, 'ม้านิลมังกรมีเขี้ยวเป็นเพชร เกล็ดเป็นนิล ลิ้นเป็นปาน หัวเป็นมังกร ตัวเป็นม้า หางเป็นนาค ดำน้ำได้ วิ่งบนผิวน้ำได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] ข้อคิดจากเรื่อง พระอภัยมณี ตอน กำเนิดสุดสาคร', 'medium', 'mcq', 'กลอนบทที่ว่า "แล้วสอนว่าอย่าไว้ใจมนุษย์ มันแสนสุดลึกล้ำเหลือกำหนด..." ให้ข้อคิดเตือนใจเรื่องใด?', '["อย่าหลงเชื่อใจใครง่ายๆ เพราะจิตใจคนยากแท้หยั่งถึง","มนุษย์ทุกคนเป็นคนชั่วร้าย","ไม่ควรพูดคุยกับคนแปลกหน้าตลอดชีวิต","ให้ระวังอันตรายจากสัตว์ป่า"]'::jsonb, '0'::jsonb, 'พระโยคีสอนสุดสาครหลังถูกชีเปลือยหลอกผลักตกเหว สอนว่าจิตใจของมนุษย์นั้นคดเคี้ยวยิ่งกว่าสิ่งใด ไม่ควรไว้ใจคนง่ายเกินไป');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณกรรมพื้นบ้านและนิทานไทย', 'medium', 'mcq', 'นิทานเรื่อง "น้ำผึ้งหยดเดียว" มีสาเหตุเริ่มต้นเกิดจากสิ่งใด?', '["สงครามแย่งชิงเมือง","เด็กทำน้ำผึ้งหกหยดเดียวลงบนพื้นดิน","มดกับปลวกแย่งอาหารกัน","สุนัขกัดกับแมว"]'::jsonb, '1'::jsonb, 'เรื่องเริ่มจากเด็กทำน้ำผึ้งหยดลงพื้น มดแมลงวันตอม จิ้งจกมากิน แมวตะครุบจิ้งจก หมากัดแมว คนตีกันจนลุกลามใหญ่โต');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] ข้อคิดจากนิทานเรื่อง น้ำผึ้งหยดเดียว', 'medium', 'mcq', 'ข้อคิดหลักที่ได้จากเรื่อง "น้ำผึ้งหยดเดียว" คือข้อใด?', '["น้ำผึ้งเป็นอาหารที่มีคุณค่าทางยา","เรื่องเล็กน้อยหากไม่ระงับอารมณ์อาจลุกลามเป็นเรื่องใหญ่โต","สัตว์เลี้ยงนำพาความเดือดร้อนมาสู่เจ้าของเสมอ","ไม่ควรรับประทานน้ำผึ้งในที่สาธารณะ"]'::jsonb, '1'::jsonb, 'สอนให้มีสติยับยั้งชั่งใจ เรื่องเพียงเล็กน้อยหากขาดสติอาจบานปลายกลายเป็นความเสียหายใหญ่หลวงได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/3] เพลงพื้นบ้านและบทกล่อมเด็ก', 'easy', 'mcq', 'บทเพลงร้องเล่น "รีรีข้าวสาร" มีคุณค่าต่อเด็กในด้านใด?', '["สอนการคำนวณราคาสินค้า","สร้างความสนุกสนานและฝึกความสามัคคีในการละเล่นพื้นบ้าน","ฝึกการขับขี่พาหนะ","สอนวิธีการทำนาปลูกข้าวแบบโบราณ"]'::jsonb, '1'::jsonb, 'การละเล่นรีรีข้าวสารเป็นการละเล่นไทยที่ให้ความสนุกสนาน ฝึกการเคลื่อนไหวร่างกาย และสร้างความสัมพันธ์ที่ดีในหมู่เพื่อน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/4] บทอาขยานบทหลัก: พฤษภกาสร', 'hard', 'mcq', '"พฤษภกาสร อีกกุญชรอันปลดปลง..." คำว่า "พฤษภ" และ "กาสร" หมายถึงสัตว์ชนิดใดตามลำดับ?', '["วัว และ ควาย","ช้าง และ ม้า","เสือ และ สิงโต","นก และ ปลา"]'::jsonb, '0'::jsonb, 'พฤษภ หมายถึง วัว, กาสร หมายถึง ควาย, กุญชร หมายถึง ช้าง บทนี้สอนเรื่องความดีคงอยู่แม้ความตายมาถึง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/4] คุณค่าของบทอาขยาน พฤษภกาสร', 'medium', 'mcq', 'วรรคทอง "อินทรีย์ร่วงทบทับ สูญสิ้นสุดเสน่หา แต่ชั่วดีประดับ คงไว้ในโลกา" มีความหมายตรงกับข้อใด?', '["เมื่อมนุษย์ตายไป มีเพียงความดีและความชั่วเท่านั้นที่ยังคงหลงเหลือให้คนจดจำ","ร่างกายมนุษย์ไม่มีวันเน่าเปื่อย","ความรักเป็นสิ่งที่ไม่ยั่งยืน","สัตว์มีค่ามากกว่ามนุษย์"]'::jsonb, '0'::jsonb, 'บทนี้เปรียบเทียบว่าสัตว์เมื่อตายยังมีเขาและงา แต่มนุษย์เมื่อสิ้นชีวิตจะเหลือเพียงชื่อเสียงความดีความชั่วที่ทำไว้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/1] วรรณคดีเรื่อง บทละครเรื่อง เงาะป่า', 'medium', 'mcq', 'ตัวละครเอกที่เป็นเด็กชาวป่า (เงาะซาไก) ในเรื่องเงาะป่าชื่อว่าอะไร?', '["คนัง","สุดสาคร","สังข์ทอง","สินสมุทร"]'::jsonb, '0'::jsonb, 'พระบาทสมเด็จพระจุลจอมเกล้าเจ้าอยู่หัว (ร.5) ทรงรับเด็กชาวป่าชื่อ "คนัง" มาชุบเลี้ยง และทรงพระราชนิพนธ์เรื่องเงาะป่า');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาไทย', 'ป.4', '[ท 5.1 ป.4/2] การนำความรู้จากวรรณคดีไปใช้ในชีวิตจริง', 'easy', 'mcq', 'การอ่านวรรณคดีไทยมีประโยชน์อย่างไรต่อตัวนักเรียนมากที่สุด?', '["ทำให้จดจำเนื้อเรื่องไปเล่นเกม","ช่วยให้เข้าใจภาษา วัฒนธรรม ได้ข้อคิดสอนใจและสุนทรียภาพ","ช่วยประหยัดค่าใช้จ่ายในบ้าน","ทำให้มีอายุยืนยาวกว่าผู้อื่น"]'::jsonb, '1'::jsonb, 'วรรณคดีไทยช่วยปลูกฝังคุณธรรม ค่านิยมอันดีงาม ความซาบซึ้งในภาษาไทย และข้อคิดในการดำเนินชีวิต');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] การอ่านและการเขียนตัวเลขฮินดูอารบิก ตัวเลขไทย และตัวหนังสือ', 'easy', 'mcq', 'ตัวเลข "๔๘๕,๒๐๙" เขียนเป็นตัวหนังสือได้อย่างไร?', '["สี่แสนแปดหมื่นห้าพันสองร้อยเก้า","สี่หมื่นแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดหมื่นห้าพันยี่สิบเก้า"]'::jsonb, '0'::jsonb, '4 ในหลักแสน, 8 ในหลักหมื่น, 5 ในหลักพัน, 2 ในหลักร้อย, 0 ในหลักสิบ, 9 ในหลักหน่วย อ่านว่า สี่แสนแปดหมื่นห้าพันสองร้อยเก้า');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] ค่าประจำหลักและค่าของเลขโดด', 'easy', 'mcq', 'ในจำนวน 3,745,820 เลขโดด 4 อยู่ในหลักใด และมีค่าเท่าใด?', '["หลักแสน มีค่า 400,000","หลักหมื่น มีค่า 40,000","หลักพัน มีค่า 4,000","หลักร้อย มีค่า 400"]'::jsonb, '1'::jsonb, '3 (ล้าน), 7 (แสน), 4 (หมื่น) ดังนั้นเลข 4 อยู่ในหลักหมื่น มีค่าเท่ากับ 40,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] การเขียนในรูปกระจาย', 'easy', 'mcq', 'ข้อใดเป็นการเขียน 609,450 ในรูปกระจายที่ถูกต้อง?', '["600,000 + 9,000 + 400 + 50","60,000 + 9,000 + 400 + 5","600,000 + 90,000 + 400 + 50","6,000,000 + 9,000 + 450"]'::jsonb, '0'::jsonb, '609,450 = 600,000 + 0 + 9,000 + 400 + 50 + 0 ซึ่งเขียนแบบย่อคือ 600,000 + 9,000 + 400 + 50');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การเปรียบเทียบและเรียงลำดับจำนวน', 'medium', 'mcq', 'ข้อใดเรียงลำดับจำนวนจาก "มากไปน้อย" ได้ถูกต้อง?', '["785,100  792,400  810,000","950,210  948,990  948,750","523,000  532,000  519,000","405,600  406,500  404,900"]'::jsonb, '1'::jsonb, '950,210 > 948,990 > 948,750 เรียงลำดับจากค่ามากที่สุดไปหาค่าน้อยที่สุดถูกต้อง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มสิบ', 'easy', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มสิบของ 4,876 คือเท่าใด?', '["4,870","4,880","4,900","5,000"]'::jsonb, '1'::jsonb, 'พิจารณาหลักหน่วยคือ 6 (มากกว่าหรือเท่ากับ 5) จึงปัดขึ้นจาก 70 เป็น 80 ได้ 4,880');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มร้อยและเต็มพัน', 'medium', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มร้อยของ 52,438 คือจำนวนใด?', '["52,400","52,500","52,000","53,000"]'::jsonb, '0'::jsonb, 'พิจารณาหลักสิบคือ 3 (น้อยกว่า 5) จึงปัดลง ได้ค่าประมาณเป็นจำนวนเต็มร้อยคือ 52,400');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มหมื่น', 'medium', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มหมื่นของ 768,490 คือข้อใด?', '["760,000","770,000","800,000","768,000"]'::jsonb, '1'::jsonb, 'พิจารณาหลักพันคือ 8 (มากกว่าหรือเท่ากับ 5) ปัดขึ้นในหลักหมื่นจาก 60,000 เป็น 70,000 ได้ 770,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มแสน', 'medium', 'mcq', 'จำนวนในข้อใดมีค่าประมาณเป็นจำนวนเต็มแสนเท่ากับ 500,000?', '["429,999","551,000","478,500","580,200"]'::jsonb, '2'::jsonb, '478,500 พิจารณาหลักหมื่นคือ 7 (ปัดขึ้น) จะได้ 500,000 ส่วน 429,999 ปัดลงได้ 400,000 และ 551,000 ปัดขึ้นได้ 600,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] แบบรูปและความสัมพันธ์ของจำนวน', 'medium', 'mcq', 'จากแบบรูป 125, 250, 500, 1,000, ... จำนวนถัดไปคือจำนวนใด?', '["1,250","1,500","2,000","2,500"]'::jsonb, '2'::jsonb, 'เป็นแบบรูปที่มีความสัมพันธ์แบบเพิ่มขึ้นโดยการคูณด้วย 2 ทีละเท่าตัว ดังนั้น 1,000 x 2 = 2,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การประมาณผลลัพธ์', 'hard', 'mcq', 'ผลบวกโดยประมาณของ 39,850 + 20,400 มีค่าใกล้เคียงข้อใดมากที่สุด?', '["50,000","60,000","70,000","80,000"]'::jsonb, '1'::jsonb, '39,850 ประมาณเป็น 40,000 และ 20,400 ประมาณเป็น 20,000 รวมกันได้ประมาณ 40,000 + 20,000 = 60,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/7] การบวกจำนวนนับที่มากกว่า 100,000', 'easy', 'mcq', 'ผลลัพธ์ของ 458,920 + 324,159 คือเท่าใด?', '["783,079","782,079","773,079","883,079"]'::jsonb, '0'::jsonb, '458,920 + 324,159 = 783,079');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/7] การลบจำนวนนับที่มากกว่า 100,000', 'easy', 'mcq', 'ผลลัพธ์ของ 800,000 - 347,650 มีค่าเท่าใด?', '["452,350","552,350","462,350","453,350"]'::jsonb, '0'::jsonb, '800,000 - 347,650 = 452,350');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/8] การคูณจำนวนที่มีหลายหลัก', 'medium', 'mcq', 'ผลคูณของ 1,245 x 36 มีค่าเท่ากับเท่าใด?', '["44,820","43,820","44,720","45,820"]'::jsonb, '0'::jsonb, '1,245 x 30 = 37,350 และ 1,245 x 6 = 7,470 นำมารวมกันได้ 37,350 + 7,470 = 44,820');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/8] การคูณจำนวนที่มีศูนย์ลงท้าย', 'easy', 'mcq', 'ผลคูณของ 700 x 500 เท่ากับเท่าใด?', '["3,500","35,000","350,000","3,500,000"]'::jsonb, '2'::jsonb, '7 x 5 = 35 เติมศูนย์ตามหลัง 4 ตัว (00 จาก 700 และ 00 จาก 500) ได้ 350,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/9] การหารที่ตัวหารมีสองหลัก', 'medium', 'mcq', 'ผลลัพธ์ของ 4,680 ÷ 15 คือข้อใด?', '["312","322","310","302"]'::jsonb, '0'::jsonb, '4,680 ÷ 15: 15 x 3 = 45 (เหลือเศษ 1 ดึง 8 เป็น 18), 15 x 1 = 15 (เหลือเศษ 3 ดึง 0 เป็น 30), 15 x 2 = 30 ลงตัว ได้ผลลัพธ์ 312');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/9] การหารมีเศษ', 'medium', 'mcq', '2,579 ÷ 8 ได้ผลหารและเศษตรงกับข้อใด?', '["322 เศษ 3","321 เศษ 5","322 เศษ 5","320 เศษ 7"]'::jsonb, '0'::jsonb, '322 x 8 = 2,576 และ 2,579 - 2,576 = 3 ดังนั้นได้ 322 เศษ 3');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] การบวก ลบ คูณ หารระคน', 'hard', 'mcq', 'หาผลลัพธ์ของ (450 + 150) x (200 - 160)', '["24,000","18,000","12,000","30,000"]'::jsonb, '0'::jsonb, 'คำนวณในวงเล็บก่อน: (450 + 150) = 600 และ (200 - 160) = 40 จากนั้นนำ 600 x 40 = 24,000');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] ลำดับการคำนวณ (Order of Operations)', 'hard', 'mcq', '100 + 50 x 2 - 40 มีค่าเท่ากับเท่าใด?', '["260","160","210","180"]'::jsonb, '1'::jsonb, 'ต้องทำคูณก่อน: 50 x 2 = 100 จากนั้นทำจากซ้ายไปขวา: 100 + 100 = 200 แล้ว 200 - 40 = 160');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/11] โจทย์ปัญหาการบวกและลบ', 'medium', 'mcq', 'โรงสีข้าวมีข้าวสาร 85,400 กิโลกรัม ขายไป 38,950 กิโลกรัม และซื้อเพิ่มอีก 15,000 กิโลกรัม ขณะนี้มีข้าวสารเหลือกี่กิโลกรัม?', '["61,450 กิโลกรัม","59,450 กิโลกรัม","62,550 กิโลกรัม","60,450 กิโลกรัม"]'::jsonb, '0'::jsonb, 'มีข้าวสาร 85,400 - 38,950 = 46,450 แล้วซื้อเพิ่ม 46,450 + 15,000 = 61,450 กิโลกรัม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/11] โจทย์ปัญหาการคูณ', 'medium', 'mcq', 'โรงงานผลิตน้ำดื่มบรรจุลังละ 24 ขวด หากผลิตได้ 1,500 ลัง โรงงานมีน้ำดื่มทั้งหมดกี่ขวด?', '["36,000 ขวด","35,000 ขวด","38,000 ขวด","34,000 ขวด"]'::jsonb, '0'::jsonb, '1,500 x 24 = 36,000 ขวด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาการหาร', 'medium', 'mcq', 'คุณครูมีสมุด 1,200 เล่ม แจกให้นักเรียน 40 คน คนละเท่าๆ กัน นักเรียนจะได้รับคนละกี่เล่ม?', '["25 เล่ม","30 เล่ม","35 เล่ม","40 เล่ม"]'::jsonb, '1'::jsonb, '1,200 ÷ 40 = 30 เล่ม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาการบวก ลบ คูณ หารระคน 2 ขั้นตอน', 'hard', 'mcq', 'แม่ค้าซื้อส้ม 50 กิโลกรัม ราคากิโลกรัมละ 45 บาท นำไปขายกิโลกรัมละ 60 บาท หากขายหมดแม่ค้าจะได้กำไรกี่บาท?', '["650 บาท","750 บาท","800 บาท","950 บาท"]'::jsonb, '1'::jsonb, 'กำไรต่อกิโลกรัม = 60 - 45 = 15 บาท ขายได้ 50 กิโลกรัม ดังนั้นกำไรทั้งหมด = 50 x 15 = 750 บาท');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาเกี่ยวกับเงิน', 'medium', 'mcq', 'ต้นกล้ามีเงิน 1,000 บาท ซื้อหนังสือ 2 เล่ม ราคาเล่มละ 230 บาท และซื้อกระเป๋า 350 บาท ต้นกล้าจะเหลือเงินกี่บาท?', '["190 บาท","210 บาท","240 บาท","180 บาท"]'::jsonb, '0'::jsonb, 'ค่าหนังสือ = 2 x 230 = 460 บาท รวมกับกระเป๋า = 460 + 350 = 810 บาท เงินที่เหลือ = 1,000 - 810 = 190 บาท');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] การหาค่าของตัวไม่ทราบค่าในประโยคสัญลักษณ์', 'hard', 'mcq', 'ถ้า ก x 25 = 1,500 แล้ว ก มีค่าเท่ากับเท่าใด?', '["50","60","70","80"]'::jsonb, '1'::jsonb, 'ก = 1,500 ÷ 25 = 60');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] เศษส่วนแท้ เศษเกิน และจำนวนคละ', 'easy', 'mcq', 'ข้อใดจัดเป็น "เศษเกิน"?', '["3/5","7/9","8/5","1/4"]'::jsonb, '2'::jsonb, 'เศษเกินคือเศษส่วนที่ตัวเศษมากกว่าหรือเท่ากับตัวส่วน ในที่นี้ 8/5 ตัวเศษ (8) มากกว่าตัวส่วน (5)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] การเขียนเศษเกินในรูปจำนวนคละ', 'medium', 'mcq', '17/4 เขียนในรูปจำนวนคละได้ตรงกับข้อใด?', '["3 1/4","4 1/4","4 3/4","5 1/4"]'::jsonb, '1'::jsonb, '17 ÷ 4 ได้ 4 เศษ 1 ดังนั้น 17/4 = 4 1/4');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] การเขียนจำนวนคละในรูปเศษเกิน', 'medium', 'mcq', '3 2/5 เขียนเป็นเศษเกินได้เท่ากับข้อใด?', '["17/5","15/5","11/5","13/5"]'::jsonb, '0'::jsonb, '(3 x 5 + 2) / 5 = (15 + 2) / 5 = 17/5');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] เศษส่วนที่เท่ากัน', 'easy', 'mcq', 'เศษส่วนข้อใดมีค่าเท่ากับ 2/3?', '["4/9","6/9","8/15","4/5"]'::jsonb, '1'::jsonb, 'คูณทั้งตัวเศษและตัวส่วนด้วย 3: (2 x 3) / (3 x 3) = 6/9');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] การเปรียบเทียบเศษส่วน', 'medium', 'mcq', 'ข้อใดเปรียบเทียบเศษส่วนได้ถูกต้อง?', '["3/7 > 5/7","4/9 < 2/9","5/8 > 3/8","1/6 > 4/6"]'::jsonb, '2'::jsonb, 'เมื่อตัวส่วนเท่ากัน ให้ดูที่ตัวเศษ ซึ่ง 5 มากกว่า 3 ดังนั้น 5/8 > 3/8');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] การเปรียบเทียบเศษส่วนที่มีตัวส่วนไม่เท่ากัน', 'hard', 'mcq', 'เปรียบเทียบ 3/4 กับ 5/8 ข้อใดถูกต้อง?', '["3/4 > 5/8","3/4 < 5/8","3/4 = 5/8","เปรียบเทียบกันไม่ได้"]'::jsonb, '0'::jsonb, 'ทำตัวส่วนให้เท่ากัน: 3/4 = (3x2)/(4x2) = 6/8 ซึ่ง 6/8 > 5/8 ดังนั้น 3/4 > 5/8');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/13] การบวกเศษส่วนที่มีตัวส่วนเท่ากัน', 'easy', 'mcq', 'ผลบวกของ 3/11 + 5/11 เท่ากับเท่าใด?', '["8/22","8/11","15/11","2/11"]'::jsonb, '1'::jsonb, 'การบวกเศษส่วนที่ตัวส่วนเท่ากัน ให้นำตัวเศษบวกกัน ตัวส่วนคงเดิม: (3 + 5)/11 = 8/11');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/13] การลบเศษส่วนที่มีตัวส่วนเท่ากัน', 'easy', 'mcq', 'ผลลัพธ์ของ 9/12 - 4/12 คือข้อใด?', '["5/12","5/0","13/12","5/24"]'::jsonb, '0'::jsonb, '(9 - 4)/12 = 5/12');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/14] โจทย์ปัญหาการบวกเศษส่วน', 'medium', 'mcq', 'มานีอ่านหนังสือช่วงเช้าได้ 2/7 เล่ม ช่วงบ่ายอ่านได้อีก 3/7 เล่ม รวมทั้งวันมานีอ่านหนังสือได้คิดเป็นเศษส่วนเท่าใดของเล่ม?', '["5/14 เล่ม","5/7 เล่ม","6/7 เล่ม","1/7 เล่ม"]'::jsonb, '1'::jsonb, '2/7 + 3/7 = 5/7 เล่ม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/14] โจทย์ปัญหาการลบเศษส่วน', 'medium', 'mcq', 'มีน้ำส้มอยู่ในเหยือก 7/8 ลิตร เทดื่มไป 3/8 ลิตร จะเหลือน้ำส้มในเหยือกกี่ลิตร?', '["4/8 ลิตร หรือ 1/2 ลิตร","10/8 ลิตร","4/16 ลิตร","1/8 ลิตร"]'::jsonb, '0'::jsonb, '7/8 - 3/8 = 4/8 ลิตร หรือทอนเป็นเศษส่วนอย่างต่ำได้ 1/2 ลิตร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] การอ่านและการเขียนทศนิยม 1 ตำแหน่ง', 'easy', 'mcq', 'เศษส่วน 7/10 เขียนเป็นทศนิยมได้อย่างไร?', '["0.07","0.7","7.0","7.10"]'::jsonb, '1'::jsonb, 'ตัวส่วนเป็น 10 คือทศนิยม 1 ตำแหน่ง ดังนั้น 7/10 = 0.7');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] การอ่านและการเขียนทศนิยม 2 ตำแหน่ง', 'easy', 'mcq', '"สามจุดห้าสอง" เขียนเป็นตัวเลขทศนิยมได้อย่างไร?', '["3.52","3.25","3.502","35.2"]'::jsonb, '0'::jsonb, 'สามจุดห้าสอง เขียนเป็นตัวเลขอารบิกได้ 3.52');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] ค่าประจำหลักของทศนิยม', 'medium', 'mcq', 'ในทศนิยม 14.86 เลข 6 อยู่ในหลักใด และมีค่าเท่าใด?', '["หลักส่วนสิบ มีค่า 0.6","หลักส่วนร้อย มีค่า 0.06","หลักหน่วย มีค่า 6","หลักสิบ มีค่า 60"]'::jsonb, '1'::jsonb, 'หลังจุดตำแหน่งที่ 1 คือหลักส่วนสิบ (8 มีค่า 0.8), หลังจุดตำแหน่งที่ 2 คือหลักส่วนร้อย (6 มีค่า 0.06)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/6] การเปรียบเทียบทศนิยม', 'medium', 'mcq', 'ข้อใดเปรียบเทียบทศนิยมได้ถูกต้อง?', '["0.4 > 0.45","1.25 < 1.3","3.08 > 3.8","5.6 = 5.06"]'::jsonb, '1'::jsonb, '1.25 เปรียบเทียบกับ 1.30: หลักส่วนสิบ 2 น้อยกว่า 3 ดังนั้น 1.25 < 1.3 ถูกต้อง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/15] การบวกทศนิยมไม่เกินสองตำแหน่ง', 'easy', 'mcq', 'ผลบวกของ 12.35 + 4.8 เท่ากับเท่าใด?', '["17.15","16.43","17.35","16.15"]'::jsonb, '0'::jsonb, 'ตั้งจุดให้ตรงกัน: 12.35 + 4.80 = 17.15');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/15] การลบทศนิยมไม่เกินสองตำแหน่ง', 'medium', 'mcq', '25.00 - 8.65 มีค่าเท่ากับข้อใด?', '["16.35","17.35","16.45","17.45"]'::jsonb, '0'::jsonb, '25.00 - 8.65 = 16.35');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การบอกระยะเวลาเป็นนาทีและชั่วโมง', 'easy', 'mcq', 'เวลา 180 นาที คิดเป็นกี่ชั่วโมง?', '["2 ชั่วโมง","3 ชั่วโมง","4 ชั่วโมง","5 ชั่วโมง"]'::jsonb, '1'::jsonb, '1 ชั่วโมง = 60 นาที ดังนั้น 180 ÷ 60 = 3 ชั่วโมง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การเปลี่ยนหน่วยเวลา', 'medium', 'mcq', '3 สัปดาห์ 4 วัน รวมเป็นเวลากี่วัน?', '["21 วัน","24 วัน","25 วัน","28 วัน"]'::jsonb, '2'::jsonb, '1 สัปดาห์ = 7 วัน ดังนั้น 3 สัปดาห์ = 3 x 7 = 21 วัน บวกอีก 4 วัน = 25 วัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การหาเวลาสิ้นสุดกิจกรรม', 'medium', 'mcq', 'ภาพยนตร์เริ่มฉายเวลา 13.30 น. และฉายต่อเนื่องนาน 1 ชั่วโมง 45 นาที ภาพยนตร์จะฉายจบเวลาใด?', '["15.00 น.","15.15 น.","15.30 น.","14.45 น."]'::jsonb, '1'::jsonb, '13.30 น. + 1 ชั่วโมง = 14.30 น. บวกอีก 45 นาที = 15.15 น.');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การคำนวณระยะเวลาจากบันทึกกิจกรรม', 'hard', 'mcq', 'กานดานั่งรถไฟออกจากสถานีเวลา 08.45 น. ถึงปลายทางเวลา 14.20 น. กานดาใช้เวลาเดินทางนานเท่าใด?', '["5 ชั่วโมง 35 นาที","5 ชั่วโมง 45 นาที","6 ชั่วโมง 25 นาที","6 ชั่วโมง 35 นาที"]'::jsonb, '0'::jsonb, 'จาก 08.45 ถึง 13.45 = 5 ชั่วโมง และจาก 13.45 ถึง 14.20 = 35 นาที รวมเป็น 5 ชั่วโมง 35 นาที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] หน่วยเวลาปี เดือน สัปดาห์', 'easy', 'mcq', 'ระยะเวลา 2 ปี 6 เดือน คิดเป็นกี่เดือน?', '["24 เดือน","26 เดือน","30 เดือน","36 เดือน"]'::jsonb, '2'::jsonb, '1 ปี = 12 เดือน ดังนั้น 2 ปี = 24 เดือน บวกอีก 6 เดือน = 30 เดือน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] ความยาวรอบรูปของรูปสี่เหลี่ยมผืนผ้า', 'medium', 'mcq', 'รูปสี่เหลี่ยมผืนผ้ากว้าง 6 เซนติเมตร ยาว 10 เซนติเมตร จะมีความยาวรอบรูปกี่เซนติเมตร?', '["16 เซนติเมตร","32 เซนติเมตร","60 เซนติเมตร","48 เซนติเมตร"]'::jsonb, '1'::jsonb, 'ความยาวรอบรูปสี่เหลี่ยมผืนผ้า = 2 x (กว้าง + ยาว) = 2 x (6 + 10) = 2 x 16 = 32 เซนติเมตร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] ความยาวรอบรูปของรูปสี่เหลี่ยมจัตุรัส', 'easy', 'mcq', 'รูปสี่เหลี่ยมจัตุรัสมีด้านยาวด้านละ 8 เซนติเมตร มีความยาวรอบรูปเท่าใด?', '["16 เซนติเมตร","24 เซนติเมตร","32 เซนติเมตร","64 เซนติเมตร"]'::jsonb, '2'::jsonb, 'ความยาวรอบรูปสี่เหลี่ยมจัตุรัส = 4 x ความยาวด้าน = 4 x 8 = 32 เซนติเมตร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] พื้นที่ของรูปสี่เหลี่ยมมุมฉาก (สี่เหลี่ยมผืนผ้า)', 'medium', 'mcq', 'ห้องเรียนรูปสี่เหลี่ยมผืนผ้ากว้าง 7 เมตร ยาว 9 เมตร จะมีพื้นที่กี่ตารางเมตร?', '["32 ตารางเมตร","63 ตารางเมตร","16 ตารางเมตร","56 ตารางเมตร"]'::jsonb, '1'::jsonb, 'พื้นที่รูปสี่เหลี่ยมผืนผ้า = กว้าง x ยาว = 7 x 9 = 63 ตารางเมตร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] พื้นที่ของรูปสี่เหลี่ยมจัตุรัส', 'medium', 'mcq', 'กระดาษรูปสี่เหลี่ยมจัตุรัสยาวด้านละ 12 เซนติเมตร มีพื้นที่กี่ตารางเซนติเมตร?', '["48 ตารางเซนติเมตร","120 ตารางเซนติเมตร","144 ตารางเซนติเมตร","24 ตารางเซนติเมตร"]'::jsonb, '2'::jsonb, 'พื้นที่สี่เหลี่ยมจัตุรัส = ด้าน x ด้าน = 12 x 12 = 144 ตารางเซนติเมตร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] โจทย์ปัญหาพื้นที่และการปูพื้น', 'hard', 'mcq', 'สนามหญ้ารูปสี่เหลี่ยมผืนผ้ากว้าง 5 เมตร ยาว 8 เมตร ต้องการปูหญ้าให้เต็มสนามโดยหญ้าราคาตารางเมตรละ 60 บาท จะต้องจ่ายเงินค่าหญ้าทั้งหมดกี่บาท?', '["2,400 บาท","1,800 บาท","1,560 บาท","3,200 บาท"]'::jsonb, '0'::jsonb, 'พื้นที่สนาม = 5 x 8 = 40 ตารางเมตร ราคาหญ้าตารางเมตรละ 60 บาท ดังนั้นต้องจ่ายเงิน = 40 x 60 = 2,400 บาท');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] จุด เส้นตรง รังสี และส่วนของเส้นตรง', 'easy', 'mcq', 'เส้นที่มีจุดปลายเพียงจุดเดียว เรียกว่าอะไร?', '["เส้นตรง","ส่วนของเส้นตรง","รังสี","เส้นขนาน"]'::jsonb, '2'::jsonb, 'รังสี คือเส้นที่มีจุดปลายเพียง 1 จุด และต่อออกไปในทิศทางเดียวได้ไม่สิ้นสุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] ชนิดของมุม: มุมแหลม มุมฉาก มุมป้าน', 'easy', 'mcq', 'มุมที่มีขนาด 90 องศา เรียกว่ามุมอะไร?', '["มุมแหลม","มุมฉาก","มุมป้าน","มุมตรง"]'::jsonb, '1'::jsonb, 'มุมฉากมีขนาด 90 องศาพอดี (มุมแหลม < 90°, มุมป้าน 90° - 180°, มุมตรง = 180°)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] การเปรียบเทียบขนาดของมุม', 'medium', 'mcq', 'มุมที่มีขนาด 125 องศา จัดเป็นมุมชนิดใด?', '["มุมแหลม","มุมฉาก","มุมป้าน","มุมกลับ"]'::jsonb, '2'::jsonb, 'มุมที่มีขนาดมากกว่า 90 องศาแต่น้อยกว่า 180 องศา เรียกว่า "มุมป้าน"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] สมบัติของรูปสี่เหลี่ยมจัตุรัส', 'easy', 'mcq', 'ข้อใดเป็นสมบัติเด่นของ "รูปสี่เหลี่ยมจัตุรัส"?', '["ด้านทั้งสี่ยาวเท่ากัน และมุมทุกมุมเป็นมุมฉาก","ด้านตรงข้ามยาวเท่ากัน และมุมทุกมุมเป็นมุมแหลม","มีด้านขนานกันเพียงคู่เดียว","มุมทุกมุมมีขนาด 60 องศา"]'::jsonb, '0'::jsonb, 'รูปสี่เหลี่ยมจัตุรัสมีด้านทั้งสี่ยาวเท่ากันทุกด้าน และมุมภายในทุกมุมเป็นมุมฉาก (90 องศา)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] สมบัติของรูปสี่เหลี่ยมผืนผ้า', 'easy', 'mcq', 'รูปสี่เหลี่ยมที่มีมุมทุกมุมเป็นมุมฉาก และด้านตรงข้ามยาวเท่ากันแต่ด้านติดกันยาวไม่เท่ากัน คือรูปสี่เหลี่ยมใด?', '["สี่เหลี่ยมขนมเปียกปูน","สี่เหลี่ยมผืนผ้า","สี่เหลี่ยมคางหมู","สี่เหลี่ยมรูปว่าว"]'::jsonb, '1'::jsonb, 'รูปสี่เหลี่ยมผืนผ้ามีมุมทุกมุมเป็นมุมฉาก ด้านตรงข้ามยาวเท่ากันและขนานกัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] แกนสมมาตร', 'medium', 'mcq', 'รูปสี่เหลี่ยมจัตุรัสมีแกนสมมาตรทั้งหมดกี่แกน?', '["2 แกน","3 แกน","4 แกน","8 แกน"]'::jsonb, '2'::jsonb, 'สี่เหลี่ยมจัตุรัสมีแกนสมมาตร 4 แกน (แนวนอน, แนวตั้ง, และเส้นทแยงมุม 2 เส้น)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การอ่านแผนภูมิแท่ง', 'easy', 'mcq', 'จากแผนภูมิแท่งแสดงจำนวนนักเรียนที่ชอบกีฬาต่างๆ: ฟุตบอล 18 คน, ว่ายน้ำ 12 คน, แบดมินตัน 15 คน กีฬาชนิดใดมีนักเรียนชอบมากที่สุด และชอบมากกว่าว่ายน้ำกี่คน?', '["ฟุตบอล มากกว่า 6 คน","แบดมินตัน มากกว่า 3 คน","ฟุตบอล มากกว่า 3 คน","ว่ายน้ำ มากกว่า 6 คน"]'::jsonb, '0'::jsonb, 'ฟุตบอลมีผู้ชอบมากที่สุด 18 คน และมากกว่าว่ายน้ำ (12 คน) อยู่ 18 - 12 = 6 คน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การแปลความหมายแผนภูมิแท่งย่นระยะ', 'medium', 'mcq', 'เส้นหยักบนแกนแสดงจำนวนในแผนภูมิแท่ง มีจุดประสงค์เพื่ออะไร?', '["ตกแต่งให้สวยงาม","ละการแสดงข้อมูลในช่วงที่มีค่าน้อยหรือไม่มีข้อมูล เพื่อประหยัดเนื้อที่","แสดงว่าข้อมูลเกิดข้อผิดพลาด","แสดงข้อมูลที่เพิ่มขึ้นอย่างรวดเร็ว"]'::jsonb, '1'::jsonb, 'การย่นระยะของเส้นแสดงจำนวน ใช้เพื่อละข้อมูลในช่วงเริ่มต้นที่ไม่มีข้อมูล ทำให้แสดงความต่างของข้อมูลได้ชัดเจนขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การอ่านข้อมูลจากตารางสองทาง (Two-way Table)', 'medium', 'mcq', 'ในตารางแสดงจำนวนนักเรียนชาย-หญิง ป.4: ชายชอบคณิตศาสตร์ 14 คน หญิงชอบคณิตศาสตร์ 16 คน, ชายชอบวิทยาศาสตร์ 12 คน หญิงชอบวิทยาศาสตร์ 15 คน มีนักเรียนชอบวิชาคณิตศาสตร์รวมทั้งหมดกี่คน?', '["26 คน","30 คน","27 คน","57 คน"]'::jsonb, '1'::jsonb, 'นักเรียนที่ชอบคณิตศาสตร์รวม = ชาย 14 + หญิง 16 = 30 คน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การใช้ข้อมูลจากตารางสองทางแก้ปัญหา', 'hard', 'mcq', 'จากข้อมูลตารางสองทาง หากมีนักเรียนชั้น ป.4 ทั้งหมด 60 คน เป็นนักเรียนชาย 28 คน และมีนักเรียนหญิงที่มาโรงเรียนด้วยรถโดยสาร 18 คน ถ้ามีนักเรียนหญิงทั้งหมดกี่คน?', '["28 คน","30 คน","32 คน","34 คน"]'::jsonb, '2'::jsonb, 'นักเรียนทั้งหมด 60 คน เป็นชาย 28 คน ดังนั้นเป็นนักเรียนหญิง = 60 - 28 = 32 คน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] หน้าที่ของส่วนต่างๆ ของพืช: รากและลำต้น', 'easy', 'mcq', 'ส่วนใดของพืชทำหน้าที่ดูดน้ำและแร่ธาตุจากดินขึ้นไปเลี้ยงส่วนต่างๆ?', '["ใบ","ดอก","ราก","ผล"]'::jsonb, '2'::jsonb, 'รากทำหน้าที่ยึดลำต้นให้ติดกับดิน และดูดน้ำกับแร่ธาตุขึ้นไปส่งต่อให้ลำต้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ท่อลำเลียงน้ำและท่อลำเลียงอาหาร', 'medium', 'mcq', 'ท่อลำเลียงน้ำ (ไซเลม) และท่อลำเลียงอาหาร (โฟลเอ็ม) ในลำต้นพืช มีทิศทางการลำเลียงอย่างไร?', '["ท่อลำเลียงน้ำลำเลียงจากรากขึ้นสู่ใบ ท่อลำเลียงอาหารลำเลียงจากใบไปส่วนต่างๆ","ท่อลำเลียงน้ำลำเลียงจากใบคงลงสู่รากเท่านั้น","ทั้งสองท่อลำเลียงจากดินขึ้นสู่ยอดพร้อมกัน","ท่อลำเลียงอาหารลำเลียงจากรากขึ้นสู่ดอก"]'::jsonb, '0'::jsonb, 'ท่อลำเลียงน้ำดูดน้ำจากรากขึ้นสู่ใบ ส่วนท่อลำเลียงอาหารลำเลียงน้ำตาลที่สร้างจากใบไปเลี้ยงส่วนต่างๆ ของพืช');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] หน้าที่ของใบและการสังเคราะห์ด้วยแสง', 'easy', 'mcq', 'ปัจจัยสำคัญที่พืชใช้ในกระบวนการสังเคราะห์ด้วยแสงคือข้อใด?', '["แสงแดด, คลอโรฟิลล์, น้ำ, แก๊สคาร์บอนไดออกไซด์","แสงแดด, ดิน, น้ำมัน, แก๊สออกซิเจน","ความมืด, ปุ๋ย, แก๊สไนโตรเจน","น้ำตาล, เกลือ, น้ำ, แก๊สคาร์บอนไดออกไซด์"]'::jsonb, '0'::jsonb, 'พืชใช้คลอโรฟิลล์ดูดกลืนพลังงานแสง รวมกับน้ำและแก๊สคาร์บอนไดออกไซด์ เพื่อสร้างน้ำตาลและแก๊สออกซิเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ผลผลิตจากการสังเคราะห์ด้วยแสง', 'easy', 'mcq', 'แก๊สชนิดใดที่พืชคายออกมาจากกระบวนการสังเคราะห์ด้วยแสง ซึ่งเป็นประโยชน์ต่อการหายใจของสัตว์และมนุษย์?', '["แก๊สคาร์บอนมอนอกไซด์","แก๊สออกซิเจน","แก๊สคาร์บอนไดออกไซด์","แก๊สไฮโดรเจน"]'::jsonb, '1'::jsonb, 'ผลผลิตจากการสังเคราะห์ด้วยแสงคือน้ำตาลกลูโคสและแก๊สออกซิเจน ซึ่งสิ่งมีชีวิตใช้ในการหายใจ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การคายน้ำของพืช', 'medium', 'mcq', 'พืชคายน้ำออกทางโครงสร้างใดเป็นหลัก?', '["ขนราก","ปากใบ (Stomata)","กลีบดอก","เปลือกลำต้น"]'::jsonb, '1'::jsonb, 'พืชคายน้ำในรูปของไอน้ำออกทางปากใบที่อยู่บริเวณใต้ใบเป็นส่วนใหญ่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การจำแนกพืชดอกและพืชไม่มีดอก', 'easy', 'mcq', 'พืชในข้อใดจัดเป็น "พืชไม่มีดอก"?', '["กุหลาบ, ชบา","ทานตะวัน, กล้วยไม้","เฟิร์น, มอส","มะม่วง, มะลิ"]'::jsonb, '2'::jsonb, 'เฟิร์นและมอสเป็นพืชไม่มีดอก โดยสืบพันธุ์โดยการสร้างสปอร์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงเดี่ยว', 'medium', 'mcq', 'ข้อใดเป็นลักษณะเฉพาะของ "พืชใบเลี้ยงเดี่ยว"?', '["เส้นใบเป็นร่างแห, ระบบรากแก้ว","เส้นใบขนาน, ระบบรากฝอย, มีใบเลี้ยง 1 ใบ","ลำต้นไม่มีข้อปล้อง, กลีบดอกมี 4-5 กลีบ","มีเนื้อไม้ขนาดใหญ่ ไม่มีข้อปล้อง"]'::jsonb, '1'::jsonb, 'พืชใบเลี้ยงเดี่ยว เช่น ข้าว ข้าวโพด มะพร้าว มีใบเลี้ยง 1 ใบ เส้นใบเรียงขนาน และมีระบบรากฝอย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงคู่', 'medium', 'mcq', 'พืชในข้อใดจัดเป็น "พืชใบเลี้ยงคู่" ทั้งหมด?', '["ข้าว, ข้าวโพด, หญ้า","มะม่วง, ถั่วเขียว, กุหลาบ","ไผ่, มะพร้าว, อ้อย","กล้วย, หญ้าแพรก, ข่า"]'::jsonb, '1'::jsonb, 'มะม่วง ถั่วเขียว กุหลาบ มีเส้นใบเป็นร่างแห ระบบรากแก้ว และมีใบเลี้ยง 2 ใบ จึงเป็นพืชใบเลี้ยงคู่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] ส่วนประกอบของดอกไม้', 'easy', 'mcq', 'ส่วนประกอบของดอกไม้ที่มีสีสันสวยงามและมีกลิ่นหอมเพื่อล่อแมลงคือส่วนใด?', '["กลีบเลี้ยง","กลีบดอก","เกสรเพศผู้","เกสรเพศเมีย"]'::jsonb, '1'::jsonb, 'กลีบดอกมีหน้าที่ดึงดูดแมลงให้มาช่วยผสมเกสรด้วยสีสันและกลิ่นหอม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.2 ป.4/1] การทดสอบแป้งในใบพืช', 'hard', 'mcq', 'สารละลายใดที่ใช้ทดสอบหาแป้งที่พืชสะสมไว้ โดยจะเปลี่ยนเป็นสีน้ำเงินเข้มหรือสีน้ำเงินแกมม่วง?', '["สารละลายเบเนดิกต์","สารละลายไอโอดีน","แอลกอฮอล์บริสุทธิ์","น้ำเกลือ"]'::jsonb, '1'::jsonb, 'สารละลายไอโอดีนจะทำปฏิกิริยากับแป้งแล้วเปลี่ยนจากสีน้ำตาลอมส้มเป็นสีน้ำเงินเข้มหรือม่วงเข้ม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] การจำแนกสัตว์: สัตว์มีกระดูกสันหลัง', 'easy', 'mcq', 'สัตว์ในข้อใดจัดเป็นสัตว์มีกระดูกสันหลังทั้งหมด?', '["ปลา, สุนัข, กบ, นก","แมงกะพรุน, ดาวทะเล, ปลาหมึก","หอย, กุ้ง, ปู, ไส้เดือน","พยาธิ, แมลงวัน, ยุง, ผึ้ง"]'::jsonb, '0'::jsonb, 'ปลา สุนัข กบ นก มีกระดูกแกนกลางพยุงร่างกาย จัดเป็นสัตว์มีกระดูกสันหลัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มปลา', 'easy', 'mcq', 'ปลาหายใจด้วยอวัยวะใด และออกลูกอย่างไรเป็นส่วนใหญ่?', '["หายใจด้วยปอด, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นไข่","หายใจด้วยผิวหนัง, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นตัว"]'::jsonb, '1'::jsonb, 'ปลาอาศัยในน้ำ ใช้เหงือกในการแลกเปลี่ยนแก๊ส และส่วนใหญ่ออกลูกเป็นไข่ (เป็นสัตว์เลือดเย็น)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์สะเทินน้ำสะเทินบก', 'medium', 'mcq', 'สัตว์กลุ่มสะเทินน้ำสะเทินบก (เช่น กบ คางคก) ในวัยตัวอ่อน (ลูกอ๊อด) หายใจด้วยอวัยวะใด?', '["ปอด","เหงือก","ผิวหนังและปอด","จมูก"]'::jsonb, '1'::jsonb, 'วัยลูกอ๊อดอาศัยอยู่ในน้ำและหายใจด้วยเหงือก เมื่อโตเต็มวัยขึ้นมาอยู่บนบกจะหายใจด้วยปอดและผิวหนัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์เลื้อยคลาน', 'medium', 'mcq', 'ข้อใดเป็นลักษณะสำคัญของ "สัตว์เลื้อยคลาน"?', '["ผิวหนังเปียกชื้น ไม่มีเกล็ด","ผิวหนังแห้ง มีเกล็ดปกคลุม หายใจด้วยปอด","มีขนเป็นแผง มีปีกบินได้","มีต่อมน้ำนมเลี้ยงลูก"]'::jsonb, '1'::jsonb, 'สัตว์เลื้อยคลาน เช่น จระเข้ เต่า งู กิ้งก่า ผิวหนังแห้งมีเกล็ดแข็งปกคลุม วางไข่บนบก และหายใจด้วยปอด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์ปีก', 'easy', 'mcq', 'สัตว์กลุ่มใดจัดเป็นสัตว์เลือดอุ่นและมีกระดูกกลวงเบาช่วยในการบิน?', '["สัตว์เลื้อยคลาน","สัตว์สะเทินน้ำสะเทินบก","สัตว์ปีก","ปลา"]'::jsonb, '2'::jsonb, 'สัตว์ปีก (นก เป็ด ไก่) เป็นสัตว์เลือดอุ่น มีขนเป็นแผง และกระดูกกลวงเบาเพื่อช่วยลดน้ำหนักในการบิน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] กลุ่มสัตว์เลี้ยงลูกด้วยน้ำนม', 'easy', 'mcq', 'สัตว์น้ำในข้อใดจัดเป็น "สัตว์เลี้ยงลูกด้วยน้ำนม" ไม่ใช่ปลา?', '["ฉลาม","ปลากระเบน","วาฬและโลมา","ปลาทู"]'::jsonb, '2'::jsonb, 'วาฬและโลมาหายใจด้วยปอด เลี้ยงลูกด้วยน้ำนม ออกลูกเป็นตัว จัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์เลี้ยงลูกด้วยน้ำนมที่บินได้', 'medium', 'mcq', 'สัตว์ในข้อใดจัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนมที่สามารถบินได้?', '["ค้างคาว","กระรอกบิน","นกเพนกวิน","นกกระจอกเทศ"]'::jsonb, '0'::jsonb, 'ค้างคาวมีต่อมน้ำนม ออกลูกเป็นตัว และเป็นสัตว์เลี้ยงลูกด้วยน้ำนมเพียงชนิดเดียวที่บินได้จริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: กลุ่มขาข้อ', 'medium', 'mcq', 'สัตว์ที่มีขาเป็นข้อและมี 6 ขา จัดเป็นสัตว์จำพวกใด?', '["แมง (เช่น แมงมุม)","แมลง (เช่น ผึ้ง ตั๊กแตน)","สัตว์พวกกุ้งกั้งปู","กิ้งกือ"]'::jsonb, '1'::jsonb, 'แมลงมี 6 ขา ลำตัวแบ่งเป็น 3 ส่วน (หัว อก ท้อง) ส่วนแมงมุมมี 8 ขา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: หอยและหมึก', 'easy', 'mcq', 'สัตว์ในข้อใดเป็นสัตว์ไม่มีกระดูกสันหลังที่มีลำตัวนิ่ม?', '["ปลาทอง","หมึกกล้วย","กบหนอง","จิ้งจก"]'::jsonb, '1'::jsonb, 'หมึกกล้วยและหอยเป็นสัตว์ไม่มีกระดูกสันหลังจำพวกลำตัวนิ่ม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 1.3 ป.4/1] สัตว์เลือดอุ่นและสัตว์เลือดเย็น', 'hard', 'mcq', 'สัตว์กลุ่มใดจัดเป็น "สัตว์เลือดเย็น" (อุณหภูมิร่างกายเปลี่ยนตามสภาพแวดล้อม)?', '["นกและสัตว์เลี้ยงลูกด้วยน้ำนม","ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน","มนุษย์และสุนัข","วาฬและลิง"]'::jsonb, '1'::jsonb, 'ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน เป็นสัตว์เลือดเย็น อุณหภูมิร่างกายปรับเปลี่ยนตามสิ่งแวดล้อม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] สมบัติความแข็งของวัสดุ', 'easy', 'mcq', 'เมื่อนำวัตถุ A มาขูดบนวัตถุ B แล้วพบว่าวัตถุ B เกิดรอย แสดงว่าสมบัติความแข็งของวัตถุทั้งสองเป็นอย่างไร?', '["วัตถุ B แข็งกว่าวัตถุ A","วัตถุ A แข็งกว่าวัตถุ B","วัตถุทั้งสองแข็งเท่ากัน","ไม่สามารถสรุปได้"]'::jsonb, '1'::jsonb, 'วัตถุที่มีความแข็งมากกว่าเมื่อนำไปขูดขีดวัตถุอื่น จะทำให้วัตถุที่แข็งน้อยกว่าเกิดรอย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] สภาพยืดหยุ่นของวัสดุ', 'easy', 'mcq', 'วัสดุในข้อใดมี "สภาพยืดหยุ่น" ดีที่สุด?', '["ดินน้ำมัน","ยางรัดของ","แท่งแก้ว","แผ่นไม้"]'::jsonb, '1'::jsonb, 'ยางรัดของเมื่อถูกดึงยืดออกแล้วปล่อย จะสามารถกลับคืนสู่สภาพเดิมได้ จึงมีสภาพยืดหยุ่นสูง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] การนำความร้อนของวัสดุ', 'medium', 'mcq', 'วัสดุใดนำความร้อนได้ดีที่สุด จึงนิยมนำมาทำก้นกระทะและหม้อหุงต้ม?', '["ไม้","พลาสติก","โลหะ (เช่น อะลูมิเนียม สแตนเลส)","แก้ว"]'::jsonb, '2'::jsonb, 'โลหะเป็นตัวนำความร้อนที่ดี ทำให้อาหารได้รับความร้อนและสุกเร็ว ส่วนด้ามจับมักทำจากฉนวนความร้อน เช่น พลาสติกหรือไม้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] การนำไฟฟ้าของวัสดุ', 'easy', 'mcq', 'วัตถุที่ยอมให้กระแสไฟฟ้าไหลผ่านได้ เรียกว่าอะไร?', '["ฉนวนไฟฟ้า","ตัวนำไฟฟ้า","สารกึ่งตัวนำ","แม่เหล็ก"]'::jsonb, '1'::jsonb, 'ตัวนำไฟฟ้า คือวัตถุที่ยอมให้กระแสไฟฟ้าไหลผ่านได้ เช่น ทองแดง อะลูมิเนียม เงิน เหล็ก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/1] ฉนวนไฟฟ้า', 'easy', 'mcq', 'วัสดุใดนิยมใช้หุ้มสายไฟเพื่อป้องกันไฟฟ้ารั่วและไฟดูด?', '["ทองแดง","เหล็ก","พลาสติกหรือยาง","อะลูมิเนียม"]'::jsonb, '2'::jsonb, 'พลาสติกและยางเป็นฉนวนไฟฟ้า ไม่ยอมให้กระแสไฟฟ้าไหลผ่าน จึงปลอดภัยเมื่อสัมผัส');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของของแข็ง', 'easy', 'mcq', 'ข้อใดเป็นสมบัติที่ถูกต้องของสารในสถานะ "ของแข็ง"?', '["มีมวล รูปร่างและปริมาตรคงที่ ไม่เปลี่ยนตามภาชนะ","รูปร่างเปลี่ยนตามภาชนะ แต่ปริมาตรคงที่","ฟุ้งกระจายเต็มภาชนะเสมอ","ไม่มีมวลและไม่ต้องการที่อยู่"]'::jsonb, '0'::jsonb, 'ของแข็งมีอนุภาคเรียงชิดติดกันแน่น ทำให้มีมวล มีรูปร่างและปริมาตรที่คงที่แน่นอน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของของเหลว', 'medium', 'mcq', 'เมื่อเทน้ำ 100 มิลลิลิตร จากแก้วทรงกระบอกลงในจานแบน สิ่งใดจะเปลี่ยนแปลงไป และสิ่งใดคงเดิม?', '["รูปร่างเปลี่ยนไปตามจาน แต่ปริมาตรคงเดิม 100 มิลลิลิตร","ทั้งรูปร่างและปริมาตรเปลี่ยนไปทั้งหมด","รูปร่างคงเดิม แต่ปริมาตรลดลง","ไม่มีสิ่งใดเปลี่ยนแปลง"]'::jsonb, '0'::jsonb, 'ของเหลวมีปริมาตรคงที่ แต่อนุภาคเลื่อนไหลได้ รูปร่างจึงเปลี่ยนไปตามภาชนะที่บรรจุ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/3] สมบัติของแก๊ส', 'medium', 'mcq', 'ข้อใดเป็นสมบัติเด่นของสารในสถานะ "แก๊ส"?', '["มีรูปร่างแน่นอน","อนุภาคอยู่ห่างกันมาก ฟุ้งกระจายเต็มภาชนะ และอัดให้เล็กลงได้","ปริมาตรคงที่เสมอ","ไม่สามารถชั่งหามวลได้"]'::jsonb, '1'::jsonb, 'แก๊สมีอนุภาคอยู่ห่างกันมาก เคลื่อนที่อิสระ จึงฟุ้งกระจายเต็มภาชนะและสามารถถูกบีบอัดปริมาตรได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/4] การหาปริมาตรของของแข็งที่มีรูปทรงไม่แน่นอน', 'hard', 'mcq', 'การหาปริมาตรของก้อนหินที่มีรูปร่างไม่แน่นอน นิยมใช้วิธีการใด?', '["ใช้ไม้บรรทัดวัดความกว้าง ยาว สูง","การแทนที่น้ำโดยใช้ถ้วยยูเรกาและกระบอกตวง","ใช้เครื่องชั่งดิจิทัล","นำไปต้มจนละลาย"]'::jsonb, '1'::jsonb, 'ใช้วิธีการแทนที่น้ำ ปริมาตรของน้ำที่ล้นออกมาจากถ้วยยูเรกาจะเท่ากับปริมาตรของก้อนหิน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.1 ป.4/4] การพิสูจน์ว่าอากาศมีมวล', 'medium', 'mcq', 'การทดลองใดสามารถพิสูจน์ได้ว่า "อากาศมีมวล"?', '["เปรียบเทียบน้ำหนักของลูกโป่งที่สูบลมเต็มกับลูกโป่งที่แฟบ บนคานไม้แขวน","นำลูกโป่งไปลอยน้ำ","เปิดพัดลมเป่าลูกโป่ง","นำลูกโป่งไปตากแดด"]'::jsonb, '0'::jsonb, 'ลูกโป่งที่สูบลมจะหนักกว่าลูกโป่งที่แฟบ ทำให้คานเอียงไปข้างที่สูบลม พิสูจน์ว่าอากาศมีมวล');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] แรงโน้มถ่วงของโลก', 'easy', 'mcq', 'ผลไม้สุกที่หลุดจากขั้วจะตกลงสู่พื้นดินเสมอ เกิดจากแรงชนิดใด?', '["แรงเสียดทาน","แรงแม่เหล็ก","แรงโน้มถ่วงของโลก","แรงผลักของลม"]'::jsonb, '2'::jsonb, 'แรงโน้มถ่วงของโลกเป็นแรงดึงดูดที่โลกกระทำต่อมวลของวัตถุทุกชนิด โดยดึงดูดเข้าสู่ศูนย์กลางของโลก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] ประโยชน์ของแรงโน้มถ่วง', 'easy', 'mcq', 'ข้อใดเป็นประโยชน์ที่เกิดจาก "แรงโน้มถ่วงของโลก"?', '["ทำให้มนุษย์และสิ่งของไม่ลอยเคว้งคว้างในอากาศ","ทำให้เรายกของหนักได้ง่ายขึ้น","ทำให้ฝนตกย้อนขึ้นสู่ก้อนเมฆ","ทำให้รถยนต์วิ่งเร็วขึ้น"]'::jsonb, '0'::jsonb, 'แรงโน้มถ่วงช่วยยึดเหนี่ยวสิ่งมีชีวิต บรรยากาศ และสิ่งของต่างๆ ให้อยู่บนพื้นผิวโลกได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/2] ความแตกต่างระหว่างมวลและน้ำหนัก', 'medium', 'mcq', 'ข้อใดอธิบายความแตกต่างระหว่าง "มวล" และ "น้ำหนัก" ได้ถูกต้อง?', '["มวลมีหน่วยเป็นนิวตัน ส่วนน้ำหนักมีหน่วยเป็นกิโลกรัม","มวลคือปริมาณเนื้อสารมีค่าคงที่ แต่น้ำหนักคือแรงดึงดูดของโลกมีหน่วยเป็นนิวตัน","ทั้งมวลและน้ำหนักจะเปลี่ยนไปเมื่อไปอยู่ที่ดวงจันทร์","มวลขึ้นอยู่กับแรงโน้มถ่วง แต่น้ำหนักไม่ขึ้นอยู่กับแรงโน้มถ่วง"]'::jsonb, '1'::jsonb, 'มวล (Mass) คือเนื้อของสาร มีค่าคงที่ทุกที่ (หน่วย kg) ส่วนน้ำหนัก (Weight) คือแรงโน้มถ่วงที่กระทำต่อมวล (หน่วย นิวตัน)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/2] น้ำหนักของวัตถุบนดวงจันทร์', 'hard', 'mcq', 'หากนำวัตถุหนัก 60 นิวตันบนโลก ไปชั่งบนดวงจันทร์ วัตถุนี้จะมีน้ำหนักประมาณเท่าใด? (ดวงจันทร์มีแรงโน้มถ่วง 1/6 ของโลก)', '["60 นิวตัน","10 นิวตัน","360 นิวตัน","0 นิวตัน"]'::jsonb, '1'::jsonb, 'แรงโน้มถ่วงของดวงจันทร์มีเพียง 1/6 ของโลก ดังนั้นน้ำหนักจะเหลือ 60 ÷ 6 = 10 นิวตัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/3] เครื่องมือวัดแรงหรือน้ำหนัก', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับวัดแรงหรือน้ำหนักของวัตถุ โดยมีหน่วยเป็นนิวตัน?', '["ไม้บรรทัด","เครื่องชั่งสปริง","เทอร์โมมิเตอร์","กระบอกตวง"]'::jsonb, '1'::jsonb, 'เครื่องชั่งสปริงใช้สปริงที่ยืดออกตามแรงดึงดูดเพื่อวัดน้ำหนักของวัตถุในหน่วยนิวตัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.2 ป.4/1] ข้อจำกัดของแรงโน้มถ่วง', 'medium', 'mcq', 'กิจกรรมใดเป็นกิจกรรมที่ต้อง "ออกแรงต้าน" แรงโน้มถ่วงของโลก?', '["การกระโดดร่มลงสู่พื้น","การปีนหน้าผาขึ้นสู่ยอดเขา","การเดินลงบันได","การปล่อยลูกบอลให้ตก"]'::jsonb, '1'::jsonb, 'การปีนเขาหรือยกของขึ้นที่สูงเป็นการเคลื่อนที่สวนทางกับทิศทางของแรงโน้มถ่วง จึงต้องออกแรงต้าน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การเคลื่อนที่ของแสง', 'easy', 'mcq', 'แสงเดินทางออกจากแหล่งกำเนิดแสงในลักษณะใด?', '["เดินทางเป็นเส้นตรงในทุกทิศทาง","เดินทางเป็นคลื่นโค้งไปมา","เดินทางเฉพาะแนวตั้งเท่านั้น","เดินทางเฉพาะเมื่อมีตัวกลางของแข็ง"]'::jsonb, '0'::jsonb, 'แสงเดินทางเป็นเส้นตรงออกจากแหล่งกำเนิดแสงทุกทิศทางด้วยความเร็วสูงมาก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] ตัวกลางโปร่งใส', 'easy', 'mcq', 'วัตถุที่ยอมให้แสงผ่านได้เกือบทั้งหมด ทำให้มองเห็นวัตถุด้านหลังได้อย่างชัดเจน เรียกว่าอะไร?', '["ตัวกลางโปร่งใส","ตัวกลางโปร่งแสง","วัตถุทึบแสง","กระจกเงา"]'::jsonb, '0'::jsonb, 'ตัวกลางโปร่งใส เช่น กระจกใส อากาศ น้ำใส แสงผ่านได้เกือบ 100% ทำให้มองเห็นวัตถุด้านหลังได้ชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] ตัวกลางโปร่งแสง', 'medium', 'mcq', 'สิ่งของในข้อใดจัดเป็น "ตัวกลางโปร่งแสง" (แสงผ่านได้บางส่วน มองเห็นไม่ชัดเจน)?', '["แผ่นแก้วใส","กระดาษไข, กระจกฝ้า, หมอกควัน","แผ่นไม้, แผ่นเหล็ก","ผ้าม่านหนาทึบ"]'::jsonb, '1'::jsonb, 'กระดาษไขและกระจกฝ้า แสงผ่านได้เพียงบางส่วน ทำให้มองเห็นภาพด้านหลังมัวๆ ไม่ชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] วัตถุทึบแสงและการเกิดเงา', 'easy', 'mcq', 'เมื่อแสงส่องกระทบ "วัตถุทึบแสง" จะเกิดสิ่งใดขึ้นด้านหลังของวัตถุ?', '["ภาพสะท้อนหัวกลับ","เงาของวัตถุ","การหักเหเป็นสีรุ้ง","ความสว่างเพิ่มขึ้น"]'::jsonb, '1'::jsonb, 'วัตถุทึบแสงไม่ยอมให้แสงทะลุผ่าน แสงจึงถูกกั้นไว้ ทำให้เกิดเงามืด/เงามัวที่ฉากด้านหลังวัตถุ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การเกิดเงา', 'medium', 'mcq', 'ถ้าเลื่อนแหล่งกำเนิดแสงให้ "เข้าใกล้วัตถุมากขึ้น" ขนาดของเงาบนฉากจะเป็นอย่างไร?', '["เงามีขนาดเล็กลง","เงามีขนาดใหญ่ขึ้น","เงาหายไป","ขนาดของเงาเท่าเดิม"]'::jsonb, '1'::jsonb, 'เมื่อแหล่งกำเนิดแสงอยู่ใกล้วัตถุมากขึ้น วัตถุจะบดบังแนวลำแสงเป็นมุมกว้างขึ้น ทำให้เงาบนฉากมีขนาดใหญ่ขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 2.3 ป.4/1] การประยุกต์ใช้ตัวกลางในชีวิตประจำวัน', 'medium', 'mcq', 'ในการสร้างห้องน้ำที่ต้องการแสงสว่างธรรมชาติแต่ต้องการความเป็นส่วนตัว ควรเลือกใช้วัสดุใดทำช่องรับแสง?', '["แผ่นกระจกใส","กระจกฝ้า","แผ่นเหล็กทึบ","ไม้อัด"]'::jsonb, '1'::jsonb, 'กระจกฝ้าเป็นตัวกลางโปร่งแสง ยอมให้แสงแดดส่องผ่านเข้ามาได้ แต่คนภายนอกมองไม่เห็นภาพด้านในชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ศูนย์กลางของระบบสุริยะ', 'easy', 'mcq', 'ดาวดวงใดเป็นศูนย์กลางของระบบสุริยะ และมีดาวเคราะห์โคจรรอบๆ?', '["โลก","ดวงอาทิตย์","ดวงจันทร์","ดาวพฤหัสบดี"]'::jsonb, '1'::jsonb, 'ดวงอาทิตย์เป็นดาวฤกษ์ดวงเดียวที่เป็นศูนย์กลางของระบบสุริยะ มีแรงโน้มถ่วงดึงดูดดาวเคราะห์ทั้ง 8 ดวงไว้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์ลำดับต่างๆ ในระบบสุริยะ', 'medium', 'mcq', 'ดาวเคราะห์ที่อยู่ "ใกล้ดวงอาทิตย์มากที่สุด" และ "ขนาดใหญ่ที่สุด" ในระบบสุริยะ คือดาวใดตามลำดับ?', '["ดาวพุธ และ ดาวพฤหัสบดี","ดาวศุกร์ และ ดาวเสาร์","โลก และ ดาวอังคาร","ดาวพุธ และ ดาวเสาร์"]'::jsonb, '0'::jsonb, 'ดาวพุธอยู่ใกล้ดวงอาทิตย์ที่สุด ส่วนดาวพฤหัสบดีเป็นดาวเคราะห์ที่มีขนาดใหญ่ที่สุดในระบบสุริยะ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์วงในและดาวเคราะห์วงนอก', 'medium', 'mcq', 'ดาวเคราะห์ดวงใดที่ได้รับฉายาว่า "ฝาแฝดของโลก" เนื่องจากมีขนาดใกล้เคียงกับโลก?', '["ดาวพุธ","ดาวศุกร์","ดาวอังคาร","ดาวเนปจูน"]'::jsonb, '1'::jsonb, 'ดาวศุกร์มีขนาด มวล และความหนาแน่นใกล้เคียงกับโลกมาก จึงได้ฉายาว่าเป็นฝาแฝดของโลก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์หินและดาวเคราะห์แก๊ส', 'hard', 'mcq', 'ดาวเคราะห์ในข้อใดจัดเป็น "ดาวเคราะห์หิน" ทั้งหมด?', '["ดาวพุธ, ดาวศุกร์, โลก, ดาวอังคาร","ดาวพฤหัสบดี, ดาวเสาร์, ดาวยูเรนัส","ดาวเนปจูน, ดาวเสาร์, โลก","ดาวอังคาร, ดาวพฤหัสบดี, ดาวพุธ"]'::jsonb, '0'::jsonb, 'ดาวเคราะห์ชั้นใน 4 ดวงแรก (พุธ ศุกร์ โลก อังคาร) เป็นดาวเคราะห์หินที่มีพื้นผิวแข็ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/1] ดาวเคราะห์ที่มีวงแหวนโดดเด่น', 'easy', 'mcq', 'ดาวเคราะห์ดวงใดในระบบสุริยะที่มีวงแหวนขนาดใหญ่สวยงาม ชัดเจนที่สุด?', '["ดาวพฤหัสบดี","ดาวเสาร์","ดาวยูเรนัส","ดาวเนปจูน"]'::jsonb, '1'::jsonb, 'ดาวเสาร์มีระบบวงแหวนน้ำแข็งและเศษหินที่กว้างใหญ่ สวยงามและโดดเด่นที่สุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] การเกิดข้างขึ้น-ข้างแรม', 'medium', 'mcq', 'ปรากฏการณ์ข้างขึ้น-ข้างแรม เกิดจากสาเหตุใด?', '["เงาของโลกบังดวงจันทร์","ดวงจันทร์โคจรรอบโลก ทำให้มุมระหว่างดวงอาทิตย์ โลก และดวงจันทร์เปลี่ยนไป","ดวงอาทิตย์ดับเป็นบางช่วง","ดวงจันทร์หมุนรอบตัวเองเร็วเกินไป"]'::jsonb, '1'::jsonb, 'เกิดจากการที่ดวงจันทร์โคจรรอบโลก ทำให้ส่วนสว่างที่ได้รับแสงจากดวงอาทิตย์หันมายังโลกในมุมที่ต่างกันในแต่ละคืน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] คืนเดือนมืดและคืนวันเพ็ญ', 'easy', 'mcq', 'ในคืน "วันเพ็ญขึ้น 15 ค่ำ" เราจะมองเห็นดวงจันทร์ในลักษณะใด?', '["มองไม่เห็นดวงจันทร์เลย (เดือนมืด)","สว่างเต็มดวงกลมโต","สว่างเพียงครึ่งดวง","เป็นรูปเสี้ยวบางๆ"]'::jsonb, '1'::jsonb, 'วันขึ้น 15 ค่ำ ดวงจันทร์อยู่ตรงข้ามกับดวงอาทิตย์โดยมีโลกอยู่ระหว่างกลาง เราจึงเห็นด้านสว่างของดวงจันทร์เต็มดวง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 3.1 ป.4/2] การขึ้นและตกของดวงจันทร์', 'medium', 'mcq', 'ดวงจันทร์ปรากฏขึ้นและตกในทิศทางใดของขอบฟ้า?', '["ขึ้นทางทิศตะวันตก ตกทางทิศตะวันออก","ขึ้นทางทิศตะวันออก ตกทางทิศตะวันตก","ขึ้นทางทิศเหนือ ตกทางทิศใต้","ขึ้นและตกไม่แน่นอน"]'::jsonb, '1'::jsonb, 'เนื่องจากโลกหมุนรอบตัวเองจากทิศตะวันตกไปทิศตะวันออก ทำให้เรามองเห็นดวงจันทร์ขึ้นทางทิศตะวันออกและตกทางทิศตะวันตกเช่นเดียวกับดวงอาทิตย์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/1] การใช้เหตุผลเชิงตรรกะในการแก้ปัญหา', 'easy', 'mcq', 'การแสดงขั้นตอนการแก้ปัญหาโดยการเขียนเป็นข้อความบอกเล่าตามลำดับก่อนหลัง เรียกว่าอะไร?', '["อัลกอริทึม (Algorithm)","การเขียนโปรแกรม","การแก้สมการ","การบักกิ้ง"]'::jsonb, '0'::jsonb, 'อัลกอริทึม คือกระบวนการแก้ปัญหาที่มีลำดับขั้นตอนชัดเจน สามารถปฏิบัติตามได้ผลลัพธ์ที่ถูกต้อง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/1] การหาข้อผิดพลาดของโปรแกรม (Debugging)', 'medium', 'mcq', 'เมื่อโปรแกรมทำงานผิดพลาดไม่ตรงตามที่คาดหวัง ขั้นตอนการตรวจสอบและแก้ไขข้อผิดพลาดเรียกว่าอะไร?', '["Coding","Debugging","Compiling","Downloading"]'::jsonb, '1'::jsonb, 'Debugging คือการตรวจหาและแก้ไขข้อผิดพลาด (Bug) ภายในโปรแกรมคำสั่ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/2] การเขียนโปรแกรมแบบบล็อก (Block Programming / Scratch)', 'easy', 'mcq', 'ในโปรแกรม Scratch หากต้องการให้ตัวละครเดินซ้ำไปเรื่อยๆ ไม่รู้จบ ควรใช้บล็อกคำสั่งใด?', '["if then","forever (วนซ้ำตลอด)","repeat 10","wait 1 sec"]'::jsonb, '1'::jsonb, 'บล็อก "forever" ใช้สำหรับสั่งให้ชุดคำสั่งภายในวนทำงานซ้ำไปเรื่อยๆ อย่างต่อเนื่องไม่มีที่สิ้นสุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/2] การทำงานแบบมีเงื่อนไข (Condition)', 'medium', 'mcq', '"ถ้าฝนตก ให้อยู่ในร่ม ถ้าฝนไม่ตก ให้ออกไปเตะฟุตบอล" ข้อความนี้ตรงกับโครงสร้างคำสั่งใดในทางคอมพิวเตอร์?', '["การทำงานแบบลำดับ (Sequence)","การทำงานแบบมีเงื่อนไข (If-Else)","การวนซ้ำแบบไม่จำกัด","การสุ่มค่า"]'::jsonb, '1'::jsonb, 'โครงสร้าง "ถ้า...แล้ว...มิฉะนั้น..." คือโครงสร้างแบบมีเงื่อนไข (If - Else) เพื่อเลือกทำตามสภาวะที่เกิดขึ้นจริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การใช้อินเทอร์เน็ตค้นหาความรู้', 'easy', 'mcq', 'โปรแกรมประเภทเว็บเบราว์เซอร์ (Web Browser) ข้อใดที่ใช้สำหรับเปิดดูเว็บไซต์บนอินเทอร์เน็ต?', '["Google Chrome, Microsoft Edge","Microsoft Excel","Adobe Photoshop","Scratch Offline"]'::jsonb, '0'::jsonb, 'Google Chrome, Microsoft Edge, Safari เป็นโปรแกรมเว็บเบราว์เซอร์สำหรับเปิดเข้าสู่เว็บไซต์ต่างๆ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การใช้คำสำคัญ (Keywords) ในการค้นหา', 'medium', 'mcq', 'หากต้องการค้นหาข้อมูลเกี่ยวกับ "การสังเคราะห์ด้วยแสงของพืชชั้น ป.4" คำค้นหาในข้อใดตรงประเด็นและได้ผลลัพธ์ดีที่สุด?', '["ต้นไม้สีเขียวทำอะไรได้บ้างในโลก","การสังเคราะห์ด้วยแสง พืช ป.4","ทำไมใบไม้จึงเป็นสีเขียวชอบแดด","วิทยาศาสตร์สนุกจัง"]'::jsonb, '1'::jsonb, 'การใช้คำค้นหาที่สั้น กระชับ และตรงประเด็น (Keyword) จะช่วยให้เครื่องมือค้นหาแสดงผลลัพธ์ที่ตรงตามความต้องการได้เร็วที่สุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/3] การประเมินความน่าเชื่อถือของข้อมูล', 'hard', 'mcq', 'แหล่งข้อมูลบนอินเทอร์เน็ตในข้อใดมีความน่าเชื่อถือสูงที่สุดในการอ้างอิงรายงานทางวิทยาศาสตร์?', '["โพสต์ในเว็บบอร์ดนิรนามที่ไม่มีคนลงชื่อ","เว็บไซต์ของหน่วยงานราชการหรือมหาวิทยาลัย (เช่น .ac.th, .go.th)","ความเห็นบนโซเชียลมีเดียที่แชร์ต่อๆ กันมา","บล็อกส่วนตัวที่ไม่มีการระบุแหล่งที่มา"]'::jsonb, '1'::jsonb, 'เว็บไซต์ของหน่วยงานรัฐหรือสถาบันการศึกษา (.go.th, .ac.th) มีการตรวจทานข้อมูลโดยผู้เชี่ยวชาญ จึงมีความน่าเชื่อถือสูง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] มารยาทและความปลอดภัยในการใช้อินเทอร์เน็ต', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตัวที่ "ปลอดภัย" ในการใช้อินเทอร์เน็ต?', '["บอกรหัสผ่าน (Password) ให้เพื่อนทุกคนในห้องรู้","ตั้งรหัสผ่านที่คาดเดายาก และไม่เปิดเผยข้อมูลส่วนตัวให้คนแปลกหน้า","นัดพบคนแปลกหน้าที่คุยผ่านเกมออนไลน์ตามลำพัง","โพสต์รูปบัตรประชาชนลงบนอินเทอร์เน็ต"]'::jsonb, '1'::jsonb, 'การรักษาความลับของรหัสผ่านและไม่เปิดเผยข้อมูลส่วนตัวแก่คนแปลกหน้า เป็นวิธีป้องกันภัยคุกคามทางไซเบอร์ที่ถูกต้อง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] การเคารพสิทธิ์และลิขสิทธิ์ของผู้อื่น', 'medium', 'mcq', 'เมื่อนำรูปภาพจากอินเทอร์เน็ตมาใช้ประกอบรายงาน ควรปฏิบัติตนอย่างไรจึงจะถูกต้องตามมารยาท?', '["ลบลายน้ำแล้วอ้างว่าเป็นภาพที่ตนเองวาด","ระบุแหล่งที่มาของภาพเพื่อเป็นการให้เกียรติเจ้าของผลงาน","ไม่ต้องทำอะไรเพราะภาพบนอินเทอร์เน็ตเป็นของทุกคน","นำไปพิมพ์ขายหารายได้พิเศษทันที"]'::jsonb, '1'::jsonb, 'การอ้างอิงแหล่งที่มาของข้อมูลและภาพ (Credit) เป็นการเคารพทรัพย์สินทางปัญญาและมีมารยาททางดิจิทัล');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('วิทยาศาสตร์', 'ป.4', '[ว 4.2 ป.4/4] การกลั่นแกล้งบนโลกออนไลน์ (Cyberbullying)', 'easy', 'mcq', 'พฤติกรรมใดจัดเป็นการกลั่นแกล้งบนโลกออนไลน์ (Cyberbullying) ที่ไม่ควรทำ?', '["การส่งสติกเกอร์ให้กำลังใจเพื่อน","การแชร์ภาพล้อเลียนหรือพิมพ์ข้อความด่าทอประจานเพื่อนในโซเชียล","การตั้งกลุ่มทำงานวิชาวิทยาศาสตร์","การชมเชยผลงานของเพื่อน"]'::jsonb, '1'::jsonb, 'การโพสต์ล้อเลียน ด่าทอ หรือประจานผู้อื่นบนสื่อออนไลน์เป็นการกลั่นแกล้งที่ผิดกฎหมายและสร้างความเสียหายต่อจิตใจผู้อื่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] พุทธประวัติ: การประสูติ ตรัสรู้ ปรินิพพาน', 'easy', 'mcq', 'เจ้าชายสิทธัตถะประสูติ ณ สถานที่ใด?', '["ใต้ร่มไม้รัง ลุมพินีวัน","ใต้ต้นพระศรีมหาโพธิ์ พุทธคยา","ป่าอิสิปตนมฤคทายวัน","สาลวโนทยาน เมืองกุสินารา"]'::jsonb, '0'::jsonb, 'เจ้าชายสิทธัตถะประสูติ ณ ลุมพินีวัน (ปัจจุบันอยู่ในประเทศเนปาล) ตรงกับวันขึ้น 15 ค่ำ เดือน 6');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] เทวทูต 4', 'medium', 'mcq', 'เจ้าชายสิทธัตถะทอดพระเนตรเห็น "เทวทูตทั้ง 4" ทำให้เกิดความเบื่อหน่ายในโลกียวิสัย เทวทูตทั้ง 4 คือข้อใด?', '["คนเกิด, คนแก่, คนเจ็บ, คนรวย","คนเกิด, คนรวย, คนจน, สมณะ","คนแก่, คนเจ็บ, คนตาย, สมณะ","คนเจ็บ, คนตาย, พระราชา, สมณะ"]'::jsonb, '2'::jsonb, 'เทวทูตทั้ง 4 ได้แก่ คนแก่ คนเจ็บ คนตาย และสมณะ ซึ่งทำให้พระองค์คิดหาทางหลุดพ้นจากความทุกข์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/1] การตรัสรู้ของพระพุทธเจ้า', 'easy', 'mcq', 'พระพุทธเจ้าตรัสรู้ความจริงอันประเสริฐ 4 ประการ ซึ่งเรียกว่าอะไร?', '["ไตรลักษณ์","อริยสัจ 4","อิทธิบาท 4","พรหมวิหาร 4"]'::jsonb, '1'::jsonb, 'พระองค์ตรัสรู้อริยสัจ 4 ได้แก่ ทุกข์ (ความไม่สบายกายใจ), สมุทัย (สาเหตุแห่งทุกข์), นิโรธ (การดับทุกข์), มรรค (หนทางดับทุกข์)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/2] พระรัตนตรัย: ดวงแก้ว 3 ประการ', 'easy', 'mcq', 'พระรัตนตรัยอันเป็นที่พึ่งสูงสุดของชาวพุทธ ประกอบด้วยสิ่งใดบ้าง?', '["พระมหากษัตริย์, พระสงฆ์, ประชาชน","พระพุทธ, พระธรรม, พระสงฆ์","พระพรหม, พระอิศวร, พระนารายณ์","ศีล, สมาธิ, ปัญญา"]'::jsonb, '1'::jsonb, 'พระรัตนตรัยคือ แก้ว 3 ประการ ได้แก่ พระพุทธ (ผู้ตรัสรู้), พระธรรม (คำสั่งสอน), และพระสงฆ์ (ผู้ปฏิบัติตามและสืบทอด)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/3] หลักธรรม: เบญจศีล (ศีล 5)', 'easy', 'mcq', 'การไม่พูดโกหก หลอกลวง หรือพูดคำหยาบ ตรงกับการปฏิบัติตามศีลข้อใดในเบญจศีล?', '["ศีลข้อที่ 1","ศีลข้อที่ 2","ศีลข้อที่ 3","ศีลข้อที่ 4"]'::jsonb, '3'::jsonb, 'ศีลข้อที่ 4 (มุสาวาทา เวรมณี) คือการงดเว้นจากการพูดเท็จ พูดคำหยาบ พูดส่อเสียด และพูดเพ้อเจ้อ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/3] หลักธรรม: เบญจธรรม 5', 'medium', 'mcq', 'ธรรมะคู่กับศีลข้อที่ 1 (ไม่ฆ่าสัตว์) ที่สอนให้มีความรัก ความปรารถนาดีต่อผู้อื่น คือข้อใด?', '["เมตตากรุณา","สัมมาอาชีวะ","กามสังวร","สัจจะ"]'::jsonb, '0'::jsonb, 'เมตตากรุณา คือความรักความเห็นอกเห็นใจผู้อื่น เป็นธรรมะที่เกื้อหนุนศีลข้อที่ 1');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/4] พุทธสาวก พุทธสาวิกา: พระอุรุเวลกัสสปะ', 'hard', 'mcq', 'พระอุรุเวลกัสสปะ เดิมเคยเป็นผู้นำของนักบวชกลุ่มใดก่อนหันมาบวชในพระพุทธศาสนา?', '["พราหมณ์ผู้บูชาไฟ (ชฎิล 3 พี่น้อง)","ฤๅษีในป่าหิมพานต์","ปริพาชก","โยคีเปลือย"]'::jsonb, '0'::jsonb, 'พระอุรุเวลกัสสปะและน้องๆ เดิมเป็นชฎิลบูชาไฟ มีบริวารรวม 1,000 คน เมื่อฟังธรรมจากพระพุทธเจ้าจึงขอบวช');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/5] ชาดก: กุฏิทูสกชาดก (ลิงกับนกกระจอก)', 'medium', 'mcq', 'ชาดกเรื่อง "กุฏิทูสกชาดก" (ลิงเกเรทำลายรังนกกระจอก) ให้ข้อคิดสำคัญเรื่องใด?', '["ไม่ควรสร้างรังบนต้นไม้สูง","การให้คำแนะนำตักเตือนแก่คนพาล ย่อมนำความเดือดร้อนมาสู่ตน","ลิงเป็นสัตว์ที่ฉลาดกว่านก","ควรพึ่งพาอาศัยผู้อื่นเสมอ"]'::jsonb, '1'::jsonb, 'นกกระจอกหวังดีตักเตือนลิงที่เปียกฝน แต่ลิงพาลโกรธจึงทำลายรังนก สอนว่าไม่ควรสั่งสอนคนพาลที่ไม่ยอมรับฟัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาสากล: ศาสนาอิสลาม', 'easy', 'mcq', 'ศาสดาและคัมภีร์ศักดิ์สิทธิ์ของศาสนาอิสลามคือข้อใด?', '["นบีมุฮัมมัด และ คัมภีร์อัลกุรอาน","พระเยซู และ คัมภีร์ไบเบิล","พระพุทธเจ้า และ พระไตรปิฎก","คุรุนานัก และ คัมภีร์อาทิครันถ์"]'::jsonb, '0'::jsonb, 'ศาสนาอิสลามมีนบีมุฮัมมัดเป็นศาสนทูตผู้นำวิวรณ์จากอัลลอฮ์ และมีคัมภีร์อัลกุรอานเป็นคัมภีร์สูงสุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาคริสต์', 'easy', 'mcq', 'ศาสดาของศาสนาคริสต์คือใคร และหลักธรรมสำคัญที่สุดคือเรื่องใด?', '["พระเยซูคริสต์ สอนเรื่องความรักและความเมตตา","โมเสส สอนเรื่องการสู้รบ","พระนารายณ์ สอนเรื่องการอวตาร","พระอินทร์ สอนเรื่องการบำเพ็ญตบะ"]'::jsonb, '0'::jsonb, 'พระเยซูทรงเป็นศาสดาของศาสนาคริสต์ ทรงเน้นหลักความรัก (ความรักต่อพระเจ้าและความรักต่อเพื่อนมนุษย์)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.1 ป.4/6] ศาสนาพราหมณ์-ฮินดู', 'medium', 'mcq', 'เทพเจ้าสูงสุด 3 พระองค์ (ตรีมูรติ) ในศาสนาพราหมณ์-ฮินดู ประกอบด้วยเทพองค์ใดบ้าง?', '["พระพรหม, พระวิษณุ (พระนารายณ์), พระศิวะ (พระอิศวร)","พระอินทร์, พระอาทิตย์, พระจันทร์","พระราม, พระลักษณ์, พระพรต","พระพิฆเนศ, พระแม่กาลี, พระแม่ลักษมี"]'::jsonb, '0'::jsonb, 'ตรีมูรติคือมหาเทพ 3 พระองค์: พระพรหม (ผู้สร้าง), พระวิษณุ (ผู้ปกป้อง), และพระศิวะ (ผู้ทำลาย)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันมาฆบูชา', 'easy', 'mcq', 'วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3) มีเหตุการณ์สำคัญใดเกิดขึ้น?', '["พระพุทธเจ้าประสูติ ตรัสรู้ ปรินิพพาน","พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย (จาตุรงคสันนิบาต)","พระพุทธเจ้าทรงแสดงปฐมเทศนา","วันถวายพระเพลิงพระพุทธสรีระ"]'::jsonb, '1'::jsonb, 'วันมาฆบูชาเกิดเหตุการณ์จาตุรงคสันนิบาต พระสงฆ์ 1,250 รูปล้วนเป็นพระอรหันต์มาประชุมพร้อมกันโดยมิได้นัดหมาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันวิสาขบูชา', 'easy', 'mcq', 'วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6) ได้รับการยกย่องจากองค์การสหประชาชาติ (UN) ให้เป็นวันสำคัญใดของโลก?', '["วันเยาวชนสากล","วันสันติภาพโลก","วันสากลของสหประชาชาติ (International Day)","วันอนุรักษ์สิ่งแวดล้อมโลก"]'::jsonb, '2'::jsonb, 'สหประชาชาติยกย่องวันวิสาขบูชาเป็นวันสำคัญสากลของโลก เนื่องจากเป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/1] วันอาสาฬหบูชา', 'medium', 'mcq', 'เหตุการณ์สำคัญที่สุดในวันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8) คือข้อใด?', '["เกิดพระสงฆ์รูปแรกในโลก คือ พระอัญญาโกณฑัญญะ และมีพระรัตนตรัยครบองค์ 3","พระพุทธเจ้าแสดงโอวาทปาติโมกข์","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระมหากัสสปะทำสังคายนาครั้งแรก"]'::jsonb, '0'::jsonb, 'พระพุทธเจ้าทรงแสดงปฐมเทศนา "ธัมมจักกัปปวัตตนสูตร" โปรดปัญจวัคคีย์ ทำให้เกิดพระสงฆ์รูปแรกและมีพระรัตนตรัยครบ 3 ประการ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 1.2 ป.4/2] ศาสนพิธีและการเวียนเทียน', 'easy', 'mcq', 'การเวียนเทียนในวันสำคัญทางพระพุทธศาสนา ต้องเดินเวียนรอบพระอุโบสถในทิศทางใดและกี่รอบ?', '["เวียนซ้าย 1 รอบ","เวียนขวา (ทักษิณาวรรต) 3 รอบ","เวียนซ้าย 3 รอบ","เวียนไปกลับกี่รอบก็ได้"]'::jsonb, '1'::jsonb, 'เดินเวียนขวาตามเข็มนาฬิกา (ประทักษิณ) 3 รอบ พร้อมน้อมรำลึกถึงพระพุทธ พระธรรม และพระสงฆ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิเด็ก 4 ประการ: สิทธิที่จะมีชีวิตรอด', 'easy', 'mcq', 'การที่เด็กได้รับการฉีดวัคซีนป้องกันโรคและได้รับอาหารครบ 5 หมู่ จัดอยู่ในสิทธิเด็กด้านใด?', '["สิทธิที่จะมีชีวิตรอด (Survival)","สิทธิที่จะได้รับการปกป้อง (Protection)","สิทธิที่จะได้รับการพัฒนา (Development)","สิทธิที่จะมีส่วนร่วม (Participation)"]'::jsonb, '0'::jsonb, 'สิทธิที่จะมีชีวิตรอด คือสิทธิในการได้รับการเลี้ยงดู ได้รับอาหาร ที่อยู่อาศัย ยารักษาโรค และการดูแลสุขภาพขั้นพื้นฐาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิที่จะได้รับการพัฒนา', 'easy', 'mcq', 'การที่เด็กทุกคนต้องได้รับการศึกษาขั้นพื้นฐาน 12 ปีจากรัฐโดยไม่เสียค่าใช้จ่าย ตรงกับสิทธิเด็กข้อใด?', '["สิทธิที่จะมีส่วนร่วม","สิทธิที่จะได้รับการพัฒนา","สิทธิที่จะมีชีวิตรอด","สิทธิเสรีภาพ"]'::jsonb, '1'::jsonb, 'สิทธิที่จะได้รับการพัฒนา ได้แก่ การศึกษา การเรียนรู้ การเล่นกีฬา และการพัฒนาทางอารมณ์และสติปัญญา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/1] สิทธิที่จะได้รับการปกป้องคุ้มครอง', 'medium', 'mcq', 'การกระทำใดเป็นการ "ละเมิดสิทธิเด็ก"?', '["พ่อแม่พาลูกไปเที่ยวพักผ่อนในวันหยุด","คุณครูสอนให้นักเรียนทำการบ้านด้วยตนเอง","การบังคับใช้แรงงานเด็กหรือทำร้ายร่างกายเด็กอย่างทารุณ","โรงเรียนจัดอาหารกลางวันที่มีประโยชน์ให้เด็กรับประทาน"]'::jsonb, '2'::jsonb, 'การใช้แรงงานเด็ก ทำร้าย ทอดทิ้ง หรือแสวงหาประโยชน์โดยมิชอบ ถือเป็นการละเมิดสิทธิเด็กและผิดกฎหมาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] วัฒนธรรมและประเพณีไทย 4 ภาค', 'medium', 'mcq', 'ประเพณี "บุญบั้งไฟ" และ "แห่ผีตาโขน" เป็นประเพณีท้องถิ่นของภาคใดในประเทศไทย?', '["ภาคเหนือ","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคใต้"]'::jsonb, '2'::jsonb, 'ประเพณีบุญบั้งไฟ (ขอฝนจากพญาแถน) และแห่ผีตาโขน (อ.ด่านซ้าย จ.เลย) เป็นเอกลักษณ์ของภาคอีสาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ประเพณีภาคเหนือ', 'medium', 'mcq', 'ประเพณี "ยี่เป็ง" (ลอยโคมขึ้นสู่ท้องฟ้า) เป็นประเพณีดั้งเดิมของชาวภาคใด?', '["ภาคใต้","ภาคเหนือ (ล้านนา)","ภาคกลาง","ภาคตะวันออก"]'::jsonb, '1'::jsonb, 'ประเพณียี่เป็งเป็นประเพณีลอยกระทงและจุดโคมลอยตามวัฒนธรรมล้านนาในภาคเหนือ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ประเพณีภาคใต้', 'medium', 'mcq', 'ประเพณี "สารทเดือนสิบ" หรือประเพณีชิงเปรต จัดขึ้นเพื่อวัตถุประสงค์ใดในภาคใต้?', '["เพื่อเฉลิมฉลองฤดูเก็บเกี่ยว","เพื่อทำบุญอุทิศส่วนกุศลให้แก่บรรพบุรุษผู้ล่วงลับ","เพื่อขอฝนสำหรับการเกษตร","เพื่อบูชาพระแม่คงคา"]'::jsonb, '1'::jsonb, 'ประเพณีสารทเดือนสิบของภาคใต้เป็นการทำบุญอุทิศส่วนกุศลให้แก่ดวงวิญญาณบรรพบุรุษและเปรต');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/3] บทบาทหน้าที่ของสมาชิกที่ดีในครอบครัวและโรงเรียน', 'easy', 'mcq', 'นักเรียนสามารถปฏิบัติตนเป็นสมาชิกที่ดีของโรงเรียนได้อย่างไร?', '["ปฏิบัติตามกฎระเบียบของโรงเรียนและตั้งใจศึกษาเล่าเรียน","มาโรงเรียนสายทุกวันเพื่อหลีกเลี่ยงเข้าแถว","แอบทิ้งขยะใต้โต๊ะเรียน","ทะเลาะวิวาทกับเพื่อนห้องอื่น"]'::jsonb, '0'::jsonb, 'การเคารพกฎระเบียบ ตั้งใจเรียน และช่วยดูแลรักษาความสะอาดเป็นหน้าที่สำคัญของนักเรียนที่ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/1] อำนาจอธิปไตย 3 ฝ่าย', 'hard', 'mcq', 'อำนาจอธิปไตยตามรัฐธรรมนูญแห่งราชอาณาจักรไทย แบ่งออกเป็น 3 ฝ่าย คือข้อใด?', '["อำนาจนิติบัญญัติ, อำนาจบริหาร, อำนาจตุลาการ","อำนาจทหาร, อำนาจตำรวจ, อำนาจพลเรือน","อำนาจครู, อำนาจหมอ, อำนาจทนาย","อำนาจรัฐบาล, อำนาจประชาชน, อำนาจเอกชน"]'::jsonb, '0'::jsonb, 'อำนาจอธิปไตยของปวงชนชาวไทย แบ่งเป็น นิติบัญญัติ (รัฐสภาออกกฎหมาย), บริหาร (ครม. บริหารประเทศ), และตุลาการ (ศาลพิพากษาคดี)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/1] สถาบันพระมหากษัตริย์ในระบอบประชาธิปไตย', 'medium', 'mcq', 'ประเทศไทยมีการปกครองระบอบใด?', '["ระบอบสมบูรณาญาสิทธิราชย์","ระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข","ระบอบสังคมนิยม","ระบอบเผด็จการทหาร"]'::jsonb, '1'::jsonb, 'ประเทศไทยปกครองด้วยระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข อำนาจอธิปไตยเป็นของปวงชนชาวไทย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/2] การเลือกตั้งผู้นำในระบอบประชาธิปไตย', 'easy', 'mcq', 'การเลือกตั้งหัวหน้าห้องหรือประธานนักเรียน มีประโยชน์อย่างไรต่อนักเรียน?', '["ทำให้นักเรียนไม่ต้องมาโรงเรียน","เป็นการฝึกฝนหลักการประชาธิปไตย การยอมรับเสียงข้างมากและเคารพเสียงข้างน้อย","ทำให้ประธานนักเรียนมีสิทธิ์ทำโทษเพื่อนตามใจชอบ","ช่วยให้นักเรียนมีเงินค่าขนมเพิ่มขึ้น"]'::jsonb, '1'::jsonb, 'การเลือกตั้งในโรงเรียนเป็นการจำลองระบอบประชาธิปไตย สอนให้นักเรียนมีส่วนร่วม ยอมรับเสียงข้างมาก และเคารพความเห็นต่าง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/3] ผู้นำและผู้ตามที่ดี', 'easy', 'mcq', 'คุณสมบัติข้อใดสำคัญที่สุดของ "ผู้นำที่ดี"?', '["สั่งการโดยไม่รับฟังความคิดเห็นของใคร","มีความรับผิดชอบ เสียสละ มีคุณธรรม และรับฟังความคิดเห็นของทุกคน","เอาแต่ใจตนเองเป็นใหญ่","เลือกปฏิบัติเฉพาะเพื่อนสนิทของตนเอง"]'::jsonb, '1'::jsonb, 'ผู้นำที่ดีต้องมีความยุติธรรม มีวิสัยทัศน์ เสียสละเพื่อส่วนรวม และรับฟังความคิดเห็นของสมาชิกทุกคน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.2 ป.4/3] คุณสมบัติของผู้ตามที่ดี', 'easy', 'mcq', 'ข้อใดเป็นลักษณะของ "ผู้ตามที่ดี"?', '["คอยขัดขวางการทำงานของกลุ่ม","ให้ความร่วมมือในการทำงาน ปฏิบัติหน้าที่ที่ได้รับมอบหมายด้วยความตั้งใจ","หลบเลี่ยงไม่ยอมช่วยทำงานกลุ่ม","นินทาผู้นำลับหลัง"]'::jsonb, '1'::jsonb, 'ผู้ตามที่ดีต้องมีความรับผิดชอบต่อหน้าที่ ให้ความร่วมมือ และช่วยเสนอแนะแนวทางแก้ปัญหาอย่างสร้างสรรค์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/4] มารยาทไทย', 'easy', 'mcq', 'การแสดงความเคารพต่อคุณครูหรือผู้ใหญ่ด้วยการไหว้ ควรให้ปลายนิ้วชี้จรดตำแหน่งใด?', '["จรดระหว่างคิ้ว","จรดปลายจมูก","จรดคาง","จรดหน้าผาก"]'::jsonb, '1'::jsonb, 'การไหว้ผู้มีพระคุณและครูอาจารย์ (ระดับที่ 2) ให้ปลายนิ้วชี้จรดระหว่างคิ้ว หรือปลายนิ้วชี้จรดปลายจมูก ปลายนิ้วหัวแม่มือจรดปลายคาง ก้มศีรษะลงพอสมควร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/4] การยืนเคารพธงชาติ', 'easy', 'mcq', 'เมื่อได้ยินเสียงเพลงชาติไทยในเวลา 08.00 น. หรือ 18.00 น. ควรปฏิบัติตนอย่างไร?', '["รีบวิ่งหนีออกจากบริเวณนั้น","หยุดยืนตรงด้วยกิริยาสำรวมเพื่อแสดงความเคารพ","ก้มกราบลงกับพื้นทันที","พูดคุยกับเพื่อนตามปกติ"]'::jsonb, '1'::jsonb, 'การหยุดยืนตรงเมื่อได้ยินเสียงเพลงชาติเป็นการแสดงความเคารพต่อชาติ ศาสนา และพระมหากษัตริย์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 2.1 ป.4/2] ภูมิปัญญาท้องถิ่น', 'medium', 'mcq', 'การนำสมุนไพรฟ้าทะลายโจรมาใช้บรรเทาอาการไข้หวัด จัดเป็นภูมิปัญญาไทยในด้านใด?', '["ด้านเกษตรกรรม","ด้านการแพทย์และสาธารณสุขพื้นบ้าน","ด้านศิลปกรรม","ด้านสถาปัตยกรรม"]'::jsonb, '1'::jsonb, 'การนำสมุนไพรมาใช้รักษาโรคเป็นภูมิปัญญาทางการแพทย์และเภสัชกรรมแผนไทยที่สืบทอดกันมา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] ปัจจัยการผลิตสินค้าและบริการ 4 ประการ', 'medium', 'mcq', 'ปัจจัยการผลิตในทางเศรษฐศาสตร์ ประกอบด้วย 4 สิ่งคือข้อใด?', '["ที่ดิน, แรงงาน, ทุน, ผู้ประกอบการ","เงิน, รถยนต์, บ้าน, ทองคำ","พ่อค้า, ลูกค้า, ตลาด, ห้างสรรพสินค้า","โรงงาน, เครื่องจักร, เงินสด, บัตรเครดิต"]'::jsonb, '0'::jsonb, 'ปัจจัยการผลิต 4 ชนิดได้แก่ ที่ดิน (ทรัพยากรธรรมชาติ), แรงงาน (กำลังคน), ทุน (เครื่องจักร อุปกรณ์), และผู้ประกอบการ (ผู้รวบรวมปัจจัยมาผลิต)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] สินค้าและบริการ', 'easy', 'mcq', 'ข้อใดจัดเป็น "การบริการ" ไม่ใช่สินค้า?', '["สมุดและดินสอ","ขนมปังและนมสด","การตัดผมที่ร้านตัดผม","รองเท้านักเรียน"]'::jsonb, '2'::jsonb, 'สินค้าเป็นสิ่งของที่จับต้องได้ ส่วนการบริการเป็นการอำนวยความสะดวก สร้างความพึงพอใจ เช่น การตัดผม การโดยสารรถประจำทาง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] ความต้องการและความจำเป็นในการดำเนินชีวิต', 'medium', 'mcq', 'สิ่งใดจัดเป็น "ปัจจัย 4" ที่มีความจำเป็นขั้นพื้นฐานต่อการดำรงชีวิตของมนุษย์?', '["โทรศัพท์มือถือราคาแพง","อาหาร, เครื่องนุ่งห่ม, ที่อยู่อาศัย, ยารักษาโรค","รถยนต์หรูหรา","เครื่องประดับเพชรพลอย"]'::jsonb, '1'::jsonb, 'ปัจจัย 4 ได้แก่ อาหาร ที่อยู่อาศัย เครื่องนุ่งห่ม และยารักษาโรค เป็นสิ่งจำเป็นที่มนุษย์ขาดไม่ได้เพื่อความอยู่รอด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] การใช้จ่ายเงินอย่างคุ้มค่า', 'easy', 'mcq', 'พฤติกรรมการใช้จ่ายเงินของใครเหมาะสมและเกิดประโยชน์สูงสุด?', '["แก้วซื้อของเล่นใหม่ทุกครั้งที่เห็นโฆษณา","กล้าทำบัญชีรายรับ-รายจ่าย และแบ่งเงินส่วนหนึ่งไว้หยอดกระปุกออมสิน","ก้อยยืมเงินเพื่อนมาซื้อขนมราคาแพง","กิ่งซื้อของที่ไม่จำเป็นเพราะเห็นว่าลดราคา"]'::jsonb, '1'::jsonb, 'การทำบัญชีรายรับ-รายจ่าย ช่วยควบคุมการใช้จ่าย และการแบ่งเงินออมเป็นพฤติกรรมทางการเงินที่ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] หน้าที่และประโยชน์ของการออมเงิน', 'easy', 'mcq', 'ประโยชน์ที่สำคัญที่สุดของการ "ออมเงิน" คือข้อใด?', '["มีเงินสำรองไว้ใช้ในยามเจ็บป่วยหรือเหตุฉุกเฉิน และใช้เพื่อการศึกษาในอนาคต","เพื่ออวดเพื่อนว่ามีเงินในกระเป๋าเยอะ","เพื่อนำไปซื้อของฟุ่มเฟือยทั้งหมดในวันเดียว","เพื่อไม่ต้องทำงานในอนาคต"]'::jsonb, '0'::jsonb, 'เงินออมช่วยสร้างความมั่นคงในชีวิต มีเงินใช้เมื่อเกิดเหตุจำเป็น และสามารถนำไปต่อยอดอนาคตได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] สถาบันการเงิน: ธนาคาร', 'medium', 'mcq', 'หน้าที่หลักของ "ธนาคารพาณิชย์" คือข้อใด?', '["พิมพ์ธนบัตรออกใช้ในประเทศ","รับฝากเงินและให้กู้ยืมเงิน","ควบคุมราคาสินค้าในตลาด","แจกเงินฟรีให้ประชาชนทุกคน"]'::jsonb, '1'::jsonb, 'ธนาคารมีหน้าที่รับฝากเงิน (จ่ายดอกเบี้ยเงินฝาก) และนำเงินไปให้บุคคลหรือธุรกิจกู้ยืม (คิดดอกเบี้ยเงินกู้)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] ธนาคารแห่งประเทศไทย (ธปท.)', 'hard', 'mcq', 'หน่วยงานใดทำหน้าที่เป็น "ธนาคารกลาง" ของประเทศ มีอำนาจพิมพ์ธนบัตรและดูแลเสถียรภาพทางการเงิน?', '["ธนาคารออมสิน","ธนาคารแห่งประเทศไทย","ธนาคารกรุงไทย","กระทรวงการคลัง"]'::jsonb, '1'::jsonb, 'ธนาคารแห่งประเทศไทย (แบงก์ชาติ) เป็นธนาคารกลาง ทำหน้าที่ออกธนบัตรและกำกับดูแลระบบสถาบันการเงินของประเทศ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/1] ความหมายของสหกรณ์', 'medium', 'mcq', '"สหกรณ์" หมายถึงข้อใดในทางเศรษฐกิจ?', '["องค์กรที่ตั้งขึ้นเพื่อแสวงหากำไรสูงสุดจากสมาชิก","การรวมกลุ่มของบุคคลด้วยความสมัครใจ เพื่อช่วยเหลือเกื้อกูลกันทางเศรษฐกิจและสังคม","ห้างสรรพสินค้าขนาดใหญ่ของรัฐบาล","บริษัทที่ผูกขาดการค้าเพียงรายเดียว"]'::jsonb, '1'::jsonb, 'สหกรณ์คือการรวมกลุ่มกันโดยสมัครใจ ดำเนินงานตามหลักประชาธิปไตย เพื่อช่วยเหลือซึ่งกันและกัน ไม่ได้มุ่งแสวงหากำไรสูงสุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/1] หลักการสำคัญของสหกรณ์', 'hard', 'mcq', 'ข้อใด "ไม่ใช่" หลักการดำเนินงานของสหกรณ์?', '["การเป็นสมาชิกโดยสมัครใจและเปิดกว้าง","การควบคุมตามแนวทางประชาธิปไตย (1 คน 1 เสียง)","สมาชิกที่ถือหุ้นมากที่สุดมีสิทธิ์สั่งการเพียงคนเดียว","การจัดสรรผลประโยชน์หรือเงินปันผลอย่างเป็นธรรม"]'::jsonb, '2'::jsonb, 'ในสหกรณ์ สมาชิกทุกคนมีสิทธิ์ออกเสียงเท่ากันคนละ 1 เสียง ไม่ว่าจะถือหุ้นมากหรือน้อย ต่างจากบริษัทจำกัด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.2 ป.4/2] สหกรณ์ในโรงเรียน', 'easy', 'mcq', 'ร้านค้าสหกรณ์ในโรงเรียนมีประโยชน์ต่อนักเรียนอย่างไร?', '["จำหน่ายอุปกรณ์การเรียนและขนมที่มีคุณภาพในราคายุติธรรม และสมาชิกได้รับเงินปันผล","แจกสิ่งของฟรีให้นักเรียนทุกคนทุกวัน","จำหน่ายสินค้าแพงกว่าร้านค้าทั่วไป","บังคับให้นักเรียนต้องซื้อสินค้าทุกคน"]'::jsonb, '0'::jsonb, 'ร้านสหกรณ์โรงเรียนจำหน่ายอุปกรณ์การศึกษาในราคายุติธรรม และเมื่อสิ้นปีการศึกษาจะมีเงินปันผลตามยอดการซื้อให้สมาชิก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] ผู้ผลิตและผู้บริโภค', 'easy', 'mcq', 'ชาวสวนปลูกส้มแล้วนำส้มไปขายที่ตลาด ชาวสวนทำหน้าที่ใดในระบบเศรษฐกิจ?', '["ผู้ผลิต","ผู้บริโภค","นายธนาคาร","ผู้ตรวจสอบ"]'::jsonb, '0'::jsonb, 'ผู้ผลิตคือผู้นำปัจจัยการผลิตมาแปรรูปเป็นสินค้าหรือบริการ ส่วนผู้ที่ซื้อไปรับประทานคือผู้บริโภค');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] สิทธิของผู้บริโภค', 'medium', 'mcq', 'เมื่อนักเรียนซื้อนมกล่องแล้วพบว่านมบูดก่อนวันหมดอายุ นักเรียนควรทำอย่างไรเป็นอันดับแรก?', '["ดื่มต่อไปเพราะเสียดายเงิน","นำหลักฐานใบเสร็จและกล่องนมไปแจ้งร้านค้าเพื่อขอเปลี่ยนหรือคืนเงิน","โพสต์ด่าทอเจ้าของร้านลงโซเชียลมีเดีย","ทิ้งไปโดยไม่บอกใคร"]'::jsonb, '1'::jsonb, 'ผู้บริโภคมีสิทธิได้รับการชดเชยความเสียหายตามกฎหมายคุ้มครองผู้บริโภค จึงควรติดต่อร้านค้าพร้อมหลักฐานทันที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/1] การแข่งขันทางการค้า', 'medium', 'mcq', 'เมื่อมีผู้ขายสินค้าชนิดเดียวกันหลายๆ ร้านในตลาด จะส่งผลดีต่อผู้บริโภคอย่างไร?', '["สินค้ามีราคาแพงขึ้น","ผู้บริโภคมีตัวเลือกมากขึ้น และได้สินค้าที่มีคุณภาพในราคาที่เหมาะสม","สินค้าในตลาดขาดแคลน","ผู้บริโภคต้องจ่ายภาษีเพิ่ม"]'::jsonb, '1'::jsonb, 'การแข่งขันทำให้ผู้ขายต้องพัฒนาคุณภาพสินค้าและตั้งราคาที่เหมาะสม เป็นธรรมต่อผู้บริโภค');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/2] การบันทึกรายรับ-รายจ่าย', 'easy', 'mcq', 'สิ่งใดจัดเป็น "รายรับ" ของนักเรียน?', '["เงินค่าขนมที่คุณพ่อให้","เงินค่าซื้อสมุดและปากกา","เงินค่าโดยสารรถประจำทาง","เงินบริจาคช่วยงานโรงเรียน"]'::jsonb, '0'::jsonb, 'เงินที่ได้มา เช่น เงินค่าขนม รางวัล เงินช่วยทำงาน จัดเป็นรายรับ ส่วนเงินที่จ่ายออกไปจัดเป็นรายจ่าย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 3.1 ป.4/3] ปรัชญาเศรษฐกิจพอเพียง', 'medium', 'mcq', 'หลัก 3 ห่วง ในปรัชญาเศรษฐกิจพอเพียงของรัชกาลที่ 9 ประกอบด้วยสิ่งใดบ้าง?', '["พอประมาณ, มีเหตุผล, มีภูมิคุ้มกันในตัวที่ดี","ร่ำรวย, ประหยัด, ตระหนี่","มีเงิน, มีทอง, มีที่ดิน","ทำบุญ, รักษาศีล, ภาวนา"]'::jsonb, '0'::jsonb, 'เศรษฐกิจพอเพียงประกอบด้วย 3 ห่วง: ความพอประมาณ, ความมีเหตุผล, การมีภูมิคุ้มกันที่ดี ภายใต้เงื่อนไขความรู้และคุณธรรม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] แผนที่และเครื่องมือทางภูมิศาสตร์', 'easy', 'mcq', 'สัญลักษณ์รูป "สามเหลี่ยมสีดำ" บนแผนที่ภูมิประเทศ มักใช้แทนสิ่งใด?', '["แม่น้ำลำคลอง","ยอดเขาหรือภูเขา","สนามบิน","โรงพยาบาล"]'::jsonb, '1'::jsonb, 'สัญลักษณ์สามเหลี่ยมบนแผนที่ใช้แสดงยอดเขาหรือจุดที่มีระดับความสูงเด่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] ทิศหลักในแผนที่', 'easy', 'mcq', 'โดยทั่วไป ทิศที่อยู่ "ด้านบนสุด" ของแผนที่สากลคือทิศใด?', '["ทิศตะวันออก","ทิศตะวันตก","ทิศใต้","ทิศเหนือ"]'::jsonb, '3'::jsonb, 'ตามมาตรฐานสากล ด้านบนของแผนที่จะกำหนดให้เป็นทิศเหนือเสมอ เว้นแต่จะมีลูกศรบอกทิศกำกับไว้เป็นอย่างอื่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] มาตราส่วนในแผนที่', 'medium', 'mcq', 'มาตราส่วน 1 : 50,000 หมายความว่าอย่างไร?', '["ระยะทางในแผนที่ 1 เซนติเมตร เท่ากับระยะทางจริงบนพื้นโลก 50,000 เซนติเมตร (500 เมตร)","ระยะทางจริง 1 เมตร เท่ากับในแผนที่ 50,000 เมตร","แผนที่นี้ย่อส่วนลง 50 เท่า","ในแผนที่มีภูเขา 50,000 ลูก"]'::jsonb, '0'::jsonb, 'มาตราส่วนแบบสัดส่วน 1 : 50,000 หมายถึง 1 หน่วยในแผนที่ เท่ากับ 50,000 หน่วยในพื้นที่จริงบนโลก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/1] ลูกโลกจำลอง', 'easy', 'mcq', 'เครื่องมือทางภูมิศาสตร์ชนิดใดที่แสดงรูปทรงสัณฐานกลมของโลกและความเอียงของแกนโลกได้สมจริงที่สุด?', '["แผนที่แบน","ลูกโลกจำลอง (Globe)","เข็มทิศ","ภาพถ่ายดาวเทียมแบบสองมิติ"]'::jsonb, '1'::jsonb, 'ลูกโลกจำลองย่อส่วนโลกในลักษณะสามมิติ แสดงความเอียงของแกนโลก 23.5 องศา และสัดส่วนทวีปมหาสมุทรได้ถูกต้องตามจริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะทางกายภาพของประเทศไทย', 'medium', 'mcq', 'ภูมิภาคใดของประเทศไทยที่มีลักษณะภูมิประเทศส่วนใหญ่เป็น "ทิวเขาสูงสลับซับซ้อนและหุบเขา"?', '["ภาคกลาง","ภาคเหนือ","ภาคตะวันออกเฉียงเหนือ","ภาคใต้"]'::jsonb, '1'::jsonb, 'ภาคเหนือของไทยประกอบด้วยเทือกเขาสูงสลับซับซ้อน เป็นต้นกำเนิดของแม่น้ำสายสำคัญ เช่น ปิง วัง ยม น่าน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิประเทศภาคกลาง', 'easy', 'mcq', 'ลักษณะเด่นของภูมิประเทศใน "ภาคกลาง" คือข้อใด?', '["ที่ราบลุ่มแม่น้ำกว้างใหญ่ ดินตะกอนอุดมสมบูรณ์ เหมาะแก่การทำนาปลูกข้าว","ที่ราบสูงดินปนทราย","ภูเขาหินปูนและเกาะแก่งกลางทะเล","ป่าดิบชื้นฝนตกชุกตลอดปี"]'::jsonb, '0'::jsonb, 'ภาคกลางเป็นที่ราบลุ่มดินดอนสามเหลี่ยมปากแม่น้ำ มีแม่น้ำเจ้าพระยาไหลผ่าน เป็นแหล่งปลูกข้าวและเกษตรกรรมสำคัญของประเทศ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิประเทศภาคอีสาน', 'medium', 'mcq', 'ภาคตะวันออกเฉียงเหนือมีลักษณะภูมิประเทศเป็น "ที่ราบสูง" ที่เรียกว่าอะไร?', '["ที่ราบสูงโคราช","ที่ราบสูงทิเบต","ที่ราบสูงเดกกัน","ที่ราบสูงไซบีเรีย"]'::jsonb, '0'::jsonb, 'ภาคอีสานตั้งอยู่บนที่ราบสูงโคราชและแอ่งสกลนคร ลักษณะคล้ายกระทะหงาย ดินส่วนใหญ่เป็นดินทรายเก็บน้ำได้น้อย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.1 ป.4/2] ลักษณะภูมิอากาศและลมมรสุม', 'hard', 'mcq', 'ลมมรสุมที่พัดพาความชื้นจากมหาสมุทรอินเดียเข้ามา ทำให้ประเทศไทยมีฝนตกชุก คือลมมรสุมใด?', '["ลมมรสุมตะวันออกเฉียงเหนือ","ลมมรสุมตะวันตกเฉียงใต้","ลมบก","ลมทะเล"]'::jsonb, '1'::jsonb, 'ลมมรสุมตะวันตกเฉียงใต้พัดผ่านทะเลอันดามันนำความชื้นมาทำให้เกิดฤดูฝนในไทย ส่วนลมมรสุมตะวันออกเฉียงเหนือนำความหนาวเย็นและแห้งแล้งเข้ามา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/1] ทรัพยากรธรรมชาติในท้องถิ่น', 'easy', 'mcq', 'ทรัพยากรธรรมชาติในข้อใดจัดเป็นทรัพยากรที่ "ใช้แล้วไม่หมดสิ้น"?', '["น้ำมันดิบ","ถ่านหิน","แสงอาทิตย์และลม","ก๊าซธรรมชาติ"]'::jsonb, '2'::jsonb, 'แสงอาทิตย์ ลม และน้ำ หมุนเวียนตามธรรมชาติจึงใช้ไม่มีวันหมด ต่างจากเชื้อเพลิงฟอสซิลที่ใช้แล้วหมดไป');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/2] ปัญหาสิ่งแวดล้อม: มลพิษทางอากาศ', 'medium', 'mcq', 'ฝุ่นละอองขนาดเล็ก PM 2.5 ในประเทศไทย มักมีสาเหตุหลักมาจากการกระทำใด?', '["การปลูกต้นไม้ในเมือง","การเผาเศษวัชพืชทางการเกษตร ควันไอเสียรถยนต์ และโรงงานอุตสาหกรรม","การใช้พลังงานแสงอาทิตย์","การคัดแยกขยะในครัวเรือน"]'::jsonb, '1'::jsonb, 'PM 2.5 เกิดจากการเผาในที่โล่ง ควันไอเสียจากเครื่องยนต์ดีเซล และการปล่อยควันจากโรงงานอุตสาหกรรม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/2] การอนุรักษ์ทรัพยากรดินและน้ำ', 'medium', 'mcq', 'การปลูก "หญ้าแฝก" ตามแนวพระราชดำริ มีประโยชน์ต่อดินอย่างไร?', '["ช่วยดูดซับสารพิษทำให้พืชโตเร็ว","รากหญ้าแฝกที่ยาวและหนาแน่นช่วยยึดเกาะดิน ป้องกันการชะล้างพังทลายของหน้าดิน","ช่วยเร่งให้ดินกลายเป็นหิน","ใช้เป็นอาหารสัตว์ทดแทนหญ้าธรรมดา"]'::jsonb, '1'::jsonb, 'หญ้าแฝกมีระบบรากลึกและแน่นหนา ทำหน้าที่เป็นกำแพงธรรมชาติช่วยยึดหน้าดินและกักเก็บความชุ่มชื้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การลดปริมาณขยะตามหลัก 3R', 'easy', 'mcq', 'การนำถุงผ้าไปใส่ของแทนการใช้ถุงพลาสติก ตรงกับหลัก 3R ข้อใด?', '["Reduce (ลดการใช้)","Reuse (นำกลับมาใช้ซ้ำ)","Recycle (แปรรูปนำกลับมาใช้ใหม่)","Repair (ซ่อมแซม)"]'::jsonb, '0'::jsonb, 'Reduce คือการลดการใช้สิ่งของที่สร้างขยะหรือใช้ครั้งเดียวทิ้ง เช่น การปฏิเสธถุงพลาสติกแล้วใช้ถุงผ้าแทน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การคัดแยกขยะ', 'easy', 'mcq', 'ถังขยะ "สีแดง" ตามมาตรฐานสากล ใช้สำหรับทิ้งขยะประเภทใด?', '["ขยะเปียก (เศษอาหาร)","ขยะรีไซเคิล (ขวดแก้ว กระดาษ)","ขยะอันตราย (หลอดไฟ แบตเตอรี่ กระป๋องสเปรย์)","ขยะทั่วไป (ถุงพลาสติก ซองขนม)"]'::jsonb, '2'::jsonb, 'ถังขยะสีแดงใช้สำหรับขยะอันตรายและสารพิษ เช่น ถ่านไฟฉาย หลอดฟลูออเรสเซนต์ แบตเตอรี่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] ภาวะโลกร้อน (Global Warming)', 'medium', 'mcq', 'แก๊สเรือนกระจกที่เกิดจากการเผาไหม้เชื้อเพลิงและตัดไม้ทำลายป่า ซึ่งเป็นสาเหตุสำคัญของภาวะโลกร้อนคือแก๊สใด?', '["แก๊สออกซิเจน","แก๊สคาร์บอนไดออกไซด์","แก๊สไนโตรเจน","แก๊สฮีเลียม"]'::jsonb, '1'::jsonb, 'แก๊สคาร์บอนไดออกไซด์ทำหน้าที่ดักจับความร้อนในชั้นบรรยากาศ เมื่อมีปริมาณมากเกินไปจะทำให้อุณหภูมิเฉลี่ยของโลกสูงขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สังคมศึกษา', 'ป.4', '[ส 5.2 ป.4/3] การมีส่วนร่วมในการอนุรักษ์สิ่งแวดล้อมในโรงเรียน', 'easy', 'mcq', 'นักเรียนสามารถช่วยประหยัดพลังงานในห้องเรียนได้อย่างไร?', '["เปิดแอร์อุณหภูมิ 16 องศาตลอดวัน","ปิดไฟและพัดลมทุกครั้งเมื่อไม่มีคนอยู่ในห้องเรียนหรือก่อนออกจากห้อง","เปิดน้ำทิ้งไว้ในห้องน้ำ","เสียบปลั๊กเครื่องใช้ไฟฟ้าค้างไว้ตลอดทั้งคืน"]'::jsonb, '1'::jsonb, 'การปิดสวิตช์ไฟ พัดลม และแอร์ทุกครั้งเมื่อไม่ใช้งาน ช่วยประหยัดพลังงานไฟฟ้าและลดค่าใช้จ่ายของโรงเรียน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: ทศวรรษ', 'easy', 'mcq', 'ช่วงเวลา "ทศวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["5 ปี","10 ปี","50 ปี","100 ปี"]'::jsonb, '1'::jsonb, 'ทศวรรษ (Decade) หมายถึง ช่วงเวลา 10 ปี โดยเริ่มนับจากปีที่ลงท้ายด้วย 0 ไปจนถึงปีที่ลงท้ายด้วย 9');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: ศตวรรษ', 'easy', 'mcq', 'คำว่า "ศตวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["10 ปี","50 ปี","100 ปี","1,000 ปี"]'::jsonb, '2'::jsonb, 'ศตวรรษ (Century) หมายถึง ช่วงเวลารอบ 100 ปี เริ่มนับจากปีที่ลงท้ายด้วย 1 จนถึงปีที่ลงท้ายด้วย 100 หรือ 00');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การนับช่วงเวลา: สหัสวรรษ', 'easy', 'mcq', 'ช่วงเวลา "สหัสวรรษ" หมายถึงรอบระยะเวลากี่ปี?', '["100 ปี","500 ปี","1,000 ปี","10,000 ปี"]'::jsonb, '2'::jsonb, 'สหัสวรรษ (Millennium) หมายถึง รอบระยะเวลา 1,000 ปี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การคำนวณศตวรรษในพุทธศักราช', 'medium', 'mcq', 'ปี พ.ศ. 2567 จัดอยู่ในพุทธศตวรรษที่เท่าใด?', '["พุทธศตวรรษที่ 24","พุทธศตวรรษที่ 25","พุทธศตวรรษที่ 26","พุทธศตวรรษที่ 27"]'::jsonb, '2'::jsonb, 'พุทธศตวรรษที่ 26 เริ่มนับจาก พ.ศ. 2501 ถึง พ.ศ. 2600 ดังนั้นปี พ.ศ. 2567 จึงอยู่ในพุทธศตวรรษที่ 26');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/1] การคำนวณคริสต์ศตวรรษ', 'hard', 'mcq', 'ปี ค.ศ. 2024 จัดอยู่ในคริสต์ศตวรรษที่เท่าใด?', '["คริสต์ศตวรรษที่ 19","คริสต์ศตวรรษที่ 20","คริสต์ศตวรรษที่ 21","คริสต์ศตวรรษที่ 22"]'::jsonb, '2'::jsonb, 'คริสต์ศตวรรษที่ 21 เริ่มต้นตั้งแต่วันที่ 1 มกราคม ค.ศ. 2001 ถึง ค.ศ. 2100');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การแบ่งยุคสมัย: ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์', 'easy', 'mcq', 'เกณฑ์สำคัญที่สุดที่นักประวัติศาสตร์ใช้แบ่งระหว่าง "ยุคก่อนประวัติศาสตร์" กับ "ยุคประวัติศาสตร์" คือข้อใด?', '["การรู้จักใช้ไฟ","การประดิษฐ์และบันทึกด้วยตัวอักษร","การสร้างบ้านเรือน","การรู้จักเพาะปลูกพืช"]'::jsonb, '1'::jsonb, 'ยุคประวัติศาสตร์เริ่มต้นเมื่อมนุษย์เริ่มรู้จักการประดิษฐ์ตัวอักษรและบันทึกเรื่องราวเป็นลายลักษณ์อักษร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคก่อนประวัติศาสตร์: ยุคหินเก่า', 'medium', 'mcq', 'ลักษณะการดำรงชีวิตของมนุษย์ใน "ยุคหินเก่า" ตรงกับข้อใด?', '["สร้างบ้านแปงเมืองอย่างเป็นระเบียบ","เร่ร่อนเก็บของป่า ล่าสัตว์ อาศัยตามถ้ำหรือเพิงผา ใช้เครื่องมือหินกะเทาะหยาบๆ","รู้จักการทำเกษตรกรรมและเลี้ยงสัตว์ในคอก","รู้จักการถลุงแร่เหล็กสร้างดาบ"]'::jsonb, '1'::jsonb, 'มนุษย์ยุคหินเก่ายังไม่ตั้งถิ่นฐานเป็นหลักแหล่ง อาศัยถ้ำธรรมชาติ ล่าสัตว์ และใช้เครื่องมือหินกะเทาะแบบหยาบ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคหินใหม่', 'medium', 'mcq', 'การเปลี่ยนแปลงสำคัญที่สุดที่ทำให้มนุษย์ก้าวเข้าสู่ "ยุคหินใหม่" คือข้อใด?', '["การเริ่มทำการเพาะปลูก เลี้ยงสัตว์ และสร้างชุมชนถาวร รู้จักขัดเครื่องมือหินจนเรียบคม","การค้นพบเครื่องบิน","การเริ่มใช้เงินตรา","การมีคอมพิวเตอร์"]'::jsonb, '0'::jsonb, 'ยุคหินใหม่เกิดการปฏิวัติเกษตรกรรม มนุษย์เริ่มตั้งถิ่นฐานเป็นหลักแหล่ง ทำเครื่องปั้นดินเผา และใช้เครื่องมือหินขัด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคโลหะ: ยุคสัมฤทธิ์', 'hard', 'mcq', 'โลหะ "สัมฤทธิ์" เกิดจากการหลอมผสมระหว่างแร่ชนิดใดเข้าด้วยกัน?', '["ทองแดง กับ ดีบุก","เหล็ก กับ สังกะสี","ทองคำ กับ เงิน","อะลูมิเนียม กับ ตะกั่ว"]'::jsonb, '0'::jsonb, 'สัมฤทธิ์ (Bronze) เป็นโลหะผสมระหว่างทองแดงกับดีบุก มีความแข็งแรงกว่าทองแดงบริสุทธิ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ยุคโลหะ: ยุคเหล็ก', 'medium', 'mcq', 'ข้อดีของเครื่องมือเครื่องใช้ที่ทำจาก "เหล็ก" เมื่อเทียบกับสัมฤทธิ์คืออะไร?', '["มีสีสันสวยงามกว่า","มีความแข็งแกร่ง ทนทาน และมีแหล่งแร่หาง่ายกว่า จึงนำมาทำอาวุธและคันไถ","มีน้ำหนักเบากว่ามาก","ละลายในน้ำได้"]'::jsonb, '1'::jsonb, 'เหล็กมีความแข็งแรง ทนทาน และคมกว่าสัมฤทธิ์มาก ทำให้การเกษตร (คันไถ) และอาวุธมีประสิทธิภาพสูงขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การนับศักราช: พ.ศ. และ ค.ศ.', 'easy', 'mcq', 'พุทธศักราช (พ.ศ.) เริ่มนับเมื่อเกิดเหตุการณ์ใด?', '["พระพุทธเจ้าประสูติ","พระพุทธเจ้าตรัสรู้","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระพุทธเจ้าทรงแสดงปฐมเทศนา"]'::jsonb, '2'::jsonb, 'ในประเทศไทย พุทธศักราชเริ่มนับ พ.ศ. 1 เมื่อพระพุทธเจ้าเสด็จดับขันธ์ปรินิพพานไปแล้วครบ 1 ปี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] คริสต์ศักราช (ค.ศ.)', 'easy', 'mcq', 'คริสต์ศักราช (ค.ศ.) เริ่มนับเริ่มต้นจากปีที่เกิดเหตุการณ์ใด?', '["ปีที่พระเยซูสิ้นพระชนม์","ปีที่พระเยซูประสูติ","ปีที่สร้างกรุงโรม","ปีที่ค้นพบทวีปอเมริกา"]'::jsonb, '1'::jsonb, 'คริสต์ศักราชเริ่มนับปี ค.ศ. 1 จากปีที่พระเยซูคริสต์ประสูติ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] การเทียบ พ.ศ. และ ค.ศ.', 'medium', 'mcq', 'การแปลง พ.ศ. ให้เป็น ค.ศ. ต้องนำตัวเลขใดมาลบออก?', '["543","621","1181","2324"]'::jsonb, '0'::jsonb, 'พ.ศ. เริ่มก่อน ค.ศ. อยู่ 543 ปี ดังนั้น ค.ศ. = พ.ศ. - 543 (เช่น 2567 - 543 = 2024)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] ฮิจเราะห์ศักราช (ฮ.ศ.)', 'hard', 'mcq', 'ฮิจเราะห์ศักราช (ฮ.ศ.) เป็นศักราชที่ใช้ในศาสนาใด และเริ่มนับจากเหตุการณ์ใด?', '["ศาสนาพุทธ เริ่มนับวันตรัสรู้","ศาสนาคริสต์ เริ่มนับวันล้างบาป","ศาสนาอิสลาม เริ่มนับจากปีที่ท่านนบีมุฮัมมัดอพยพจากเมืองมักกะฮ์ไปยังเมืองมะดีนะฮ์","ศาสนาพราหมณ์ เริ่มนับวันสร้างโลก"]'::jsonb, '2'::jsonb, 'ฮิจเราะห์ศักราชเริ่มนับเมื่อท่านนบีมุฮัมมัดนำชาวมุสลิมอพยพ (ฮิจเราะห์) จากมักกะฮ์ไปมะดีนะฮ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.1 ป.4/2] รัตนโกสินทร์ศก (ร.ศ.)', 'hard', 'mcq', 'รัตนโกสินทร์ศก (ร.ศ.) เริ่มนับ ร.ศ. 1 ตรงกับปีใด?', '["ปีที่สถาปนากรุงสุโขทัย","ปีที่สถาปนากรุงศรีอยุธยา","ปีที่พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช (ร.1) สถาปนากรุงรัตนโกสินทร์ (พ.ศ. 2325)","ปีที่เปลี่ยนแปลงการปกครอง พ.ศ. 2475"]'::jsonb, '2'::jsonb, 'ร.ศ. เริ่มนับ ร.ศ. 1 ในปี พ.ศ. 2325 ซึ่งเป็นปีที่สถาปนากรุงเทพฯ เป็นราชธานี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] ประเภทของหลักฐานทางประวัติศาสตร์: หลักฐานชั้นต้น', 'easy', 'mcq', 'หลักฐานทางประวัติศาสตร์ในข้อใดจัดเป็น "หลักฐานชั้นต้น (ปฐมภูมิ)"?', '["ศิลาจารึกหลักที่ 1 ที่สร้างขึ้นในสมัยสุโขทัย","หนังสือแบบเรียนประวัติศาสตร์ที่เขียนขึ้นเมื่อวาน","ภาพยนตร์ย้อนยุคอิงประวัติศาสตร์","บทความวิเคราะห์ประวัติศาสตร์ในอินเทอร์เน็ต"]'::jsonb, '0'::jsonb, 'หลักฐานชั้นต้นคือหลักฐานที่ถูกบันทึกหรือสร้างขึ้นโดยผู้ที่อยู่ในเหตุการณ์หรือช่วงเวลาที่เกิดเหตุการณ์นั้นจริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานชั้นรอง (ทุติยภูมิ)', 'medium', 'mcq', 'ข้อใดจัดเป็น "หลักฐานชั้นรอง"?', '["โครงกระดูกมนุษย์โบราณ","เครื่องปั้นดินเผาบ้านเชียง","หนังสือประวัติศาสตร์สุโขทัยที่นักวิชาการเรียบเรียงขึ้นในปัจจุบัน","กำแพงเมืองโบราณ"]'::jsonb, '2'::jsonb, 'หลักฐานชั้นรองถูกรวบรวมและเรียบเรียงขึ้นภายหลังจากเหตุการณ์นั้นผ่านพ้นไปแล้ว โดยอาศัยข้อมูลจากหลักฐานชั้นต้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานที่เป็นลายลักษณ์อักษร', 'easy', 'mcq', 'หลักฐานในข้อใดเป็น "หลักฐานที่เป็นลายลักษณ์อักษร"?', '["จดหมายเหตุวันวลิต","ขวานหินขัด","ลูกปัดแก้วโบราณ","ซากเจดีย์เก่า"]'::jsonb, '0'::jsonb, 'หลักฐานที่เป็นลายลักษณ์อักษรคือหลักฐานที่มีการบันทึกด้วยตัวหนังสือ เช่น ศิลาจารึก พงศาวดาร จดหมายเหตุ ใบลาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] หลักฐานที่ไม่เป็นลายลักษณ์อักษร', 'easy', 'mcq', 'ข้อใดเป็นหลักฐานทางประวัติศาสตร์ที่ "ไม่เป็นลายลักษณ์อักษร"?', '["พงศาวดารกรุงศรีอยุธยา","ศิลาจารึกวัดศรีชุม","หม้อดินเผาลายเขียนสีบ้านเชียง","สนธิสัญญาเบาว์ริง"]'::jsonb, '2'::jsonb, 'โบราณวัตถุ โบราณสถาน โครงกระดูก อาวุธ เครื่องประดับ จัดเป็นหลักฐานที่ไม่เป็นลายลักษณ์อักษร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีบ้านเชียง', 'medium', 'mcq', 'แหล่งโบราณคดี "บ้านเชียง" ซึ่งได้รับการขึ้นทะเบียนเป็นมรดกโลกทางวัฒนธรรม ตั้งอยู่ในจังหวัดใด?', '["จังหวัดเชียงใหม่","จังหวัดอุดรธานี","จังหวัดขอนแก่น","จังหวัดนครราชสีมา"]'::jsonb, '1'::jsonb, 'แหล่งโบราณคดีบ้านเชียงตั้งอยู่ที่ อ.หนองหาน จ.อุดรธานี มีชื่อเสียงด้านภาชนะดินเผาลายเขียนสีแดงและเครื่องสำริด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] เอกลักษณ์ของเครื่องปั้นดินเผาบ้านเชียง', 'easy', 'mcq', 'ลักษณะเด่นของภาชนะดินเผาที่พบที่บ้านเชียงยุคปลายคืออะไร?', '["เป็นหม้อเคลือบสีเขียวมรกต","เป็นภาชนะดินเผาลายก้นหอยเขียนด้วยสีแดง","ทำจากทองคำบริสุทธิ์แกะสลัก","มีตัวหนังสือภาษาอังกฤษสลักไว้"]'::jsonb, '1'::jsonb, 'ภาชนะบ้านเชียงยุคปลายมีเอกลักษณ์ที่ลายเขียนสีแดงเป็นลวดลายก้นหอย ลายเส้นโค้งเรขาคณิตสวยงาม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีถ้ำผีแมน', 'hard', 'mcq', 'แหล่งโบราณคดียุคหินเก่าและหินกลาง "ถ้ำผีแมน" พบในจังหวัดใดของประเทศไทย?', '["จังหวัดแม่ฮ่องสอน","จังหวัดกาญจนบุรี","จังหวัดกระบี่","จังหวัดสุราษฎร์ธานี"]'::jsonb, '0'::jsonb, 'ถ้ำผีแมนตั้งอยู่ใน อ.ปางมะผ้า จ.แม่ฮ่องสอน พบหลักฐานโลงไม้รูปเรือและเครื่องมือหินกะเทาะโบราณ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีเมืองอู่ทอง', 'medium', 'mcq', 'เมืองโบราณอู่ทองในจังหวัดสุพรรณบุรี เคยเป็นศูนย์กลางความเจริญของอาณาจักรโบราณใด?', '["อาณาจักรทวารวดี","อาณาจักรล้านนา","อาณาจักรศรีวิชัย","อาณาจักรสุโขทัย"]'::jsonb, '0'::jsonb, 'เมืองโบราณอู่ทองและนครปฐมโบราณเป็นศูนย์กลางวัฒนธรรมทวารวดีที่นับถือพระพุทธศาสนานิกายเถรวาทในลุ่มน้ำเจ้าพระยา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] โบราณวัตถุสัญลักษณ์ธรรมจักรศิลา', 'medium', 'mcq', '"ธรรมจักรศิลาพร้อมกวางหมอบ" เป็นศิลปะโบราณเนื่องในศาสนาพุทธสมัยอาณาจักรใด?', '["ทวารวดี","ศรีวิชัย","อยุธยา","ลพบุรี"]'::jsonb, '0'::jsonb, 'ธรรมจักรศิลาพร้อมกวางหมอบเป็นเอกลักษณ์ของศิลปะทวารวดี แสดงถึงการเผยแผ่พระธรรมจักรในดินแดนไทย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] แหล่งโบราณคดีเมืองโบราณศรีเทพ', 'hard', 'mcq', '"เมืองโบราณศรีเทพ" มรดกโลกทางวัฒนธรรมแห่งใหม่ของไทย ตั้งอยู่ในจังหวัดใด?', '["จังหวัดเพชรบูรณ์","จังหวัดลพบุรี","จังหวัดนครสวรรค์","จังหวัดสระบุรี"]'::jsonb, '0'::jsonb, 'เมืองโบราณศรีเทพตั้งอยู่ใน อ.ศรีเทพ จ.เพชรบูรณ์ ได้รับการขึ้นทะเบียนเป็นมรดกโลกโดยยูเนสโกในปี พ.ศ. 2566');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/2] ภาพเขียนสีก่อนประวัติศาสตร์', 'medium', 'mcq', 'ภาพเขียนสีผาแต้ม ริมแม่น้ำโขง จังหวัดอุบลราชธานี มีลักษณะภาพอย่างไร?', '["ภาพลายไทยกนกเปลว","ภาพคน ช้าง ปลาบึก และลวดลายเรขาคณิตสีแดงทึบ","ภาพตัวอักษรจีนโบราณ","ภาพแผนที่ดาวเทียม"]'::jsonb, '1'::jsonb, 'ผาแต้มมีภาพเขียนสีอายุราว 3,000 ปี แสดงภาพฝ่ามือ ภาพสัตว์ขนาดใหญ่ เช่น ปลาบึก ช้าง และวิถีชีวิตคนโบราณ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] การตรวจสอบความถูกต้องของหลักฐาน', 'hard', 'mcq', 'ก่อนนำหลักฐานทางประวัติศาสตร์มาสรุปเป็นข้อเท็จจริง ต้องผ่านขั้นตอนใดก่อน?', '["นำไปตั้งแสดงในพิพิธภัณฑ์ทันที","การประเมินความน่าเชื่อถือและการวิพากษ์หลักฐาน","การสวดมนต์ขอขมา","การแจกจ่ายให้คนทั่วไปอ่าน"]'::jsonb, '1'::jsonb, 'ขั้นตอนการประเมินคุณค่าหรือวิพากษ์หลักฐาน (ภายนอกและภายใน) ช่วยตรวจสอบว่าเป็นของจริงหรือไม่และมีความน่าเชื่อถือเพียงใด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] ศิลาจารึกหลักที่ 1', 'easy', 'mcq', 'ศิลาจารึกหลักที่ 1 (จารึกพ่อขุนรามคำแหง) สลักด้วยตัวอักษรชนิดใด?', '["อักษรขอมโบราณ","อักษรลายสือไทย","อักษรปัลลวะ","อักษรมอญโบราณ"]'::jsonb, '1'::jsonb, 'พ่อขุนรามคำแหงทรงประดิษฐ์อักษรลายสือไทยขึ้นในปี พ.ศ. 1826 และจารึกลงบนแท่งศิลา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] สถานที่เก็บรักษาหลักฐานทางประวัติศาสตร์', 'easy', 'mcq', 'หน่วยงานใดของทางราชการมีหน้าที่รวบรวม เก็บรักษา และจัดแสดงโบราณวัตถุของชาติ?', '["สำนักหอสมุดแห่งชาติ","พิพิธภัณฑสถานแห่งชาติ กรมศิลปากร","กรมการศาสนา","สำนักงานตำรวจแห่งชาติ"]'::jsonb, '1'::jsonb, 'พิพิธภัณฑสถานแห่งชาติ สังกัดกรมศิลปากร มีหน้าที่อนุรักษ์ จัดแสดง และเผยแพร่ความรู้เกี่ยวกับโบราณวัตถุและศิลปวัตถุ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.2 ป.4/1] การอนุรักษ์โบราณสถาน', 'easy', 'mcq', 'เมื่อไปทัศนศึกษาโบราณสถาน นักเรียนควรปฏิบัติตนอย่างไร?', '["ขีดเขียนชื่อตนเองไว้บนผนังศิลาแลงเป็นที่ระลึก","ปีนป่ายขึ้นไปบนองค์พระพุทธรูปเพื่อถ่ายรูป","ปฏิบัติตามป้ายเตือน ไม่สัมผัสหรือทำลายโบราณสถาน และช่วยกันรักษาความสะอาด","เก็บก้อนหินโบราณกลับมาเป็นของสะสมที่บ้าน"]'::jsonb, '2'::jsonb, 'การปฏิบัติตามกฎ ไม่ปีนป่าย ไม่ขีดเขียน และไม่นำโบราณวัตถุออกจากพื้นที่ เป็นการช่วยอนุรักษ์มรดกทางวัฒนธรรม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] การสถาปนาอาณาจักรสุโขทัย', 'easy', 'mcq', 'ใครคือปฐมกษัตริย์ (กษัตริย์องค์แรก) ผู้สถาปนาอาณาจักรสุโขทัยและราชวงศ์พระร่วง?', '["พ่อขุนรามคำแหงมหาราช","พ่อขุนศรีอินทราทิตย์ (พ่อขุนบางกลางหาว)","พระมหาธรรมราชาที่ 1 (พญาลิไทย)","สมเด็จพระรามาธิบดีที่ 1"]'::jsonb, '1'::jsonb, 'พ่อขุนบางกลางหาวได้รับสถาปนาเป็น "พ่อขุนศรีอินทราทิตย์" ปฐมกษัตริย์แห่งราชวงศ์พระร่วง อาณาจักรสุโขทัย เมื่อประมาณ พ.ศ. 1792');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] พันธมิตรผู้ร่วมกอบกู้อิสรภาพสุโขทัย', 'medium', 'mcq', 'พ่อขุนศรีอินทราทิตย์ได้ร่วมมือกับผู้นำเมืองราดท่านใดในการขับไล่ขอมสบาดโขลญลำพงออกจากสุโขทัย?', '["พ่อขุนผาเมือง","พ่อขุนรามคำแหง","พญางำเมือง","พญามังราย"]'::jsonb, '0'::jsonb, 'พ่อขุนบางกลางหาว (เจ้าเมืองบางยาง) ร่วมมือกับพ่อขุนผาเมือง (เจ้าเมืองราด) รวบรวมกำลังขับไล่ขอมจนสำเร็จ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/1] สาเหตุการเลือกตั้งเมืองสุโขทัยเป็นราชธานี', 'medium', 'mcq', 'ชัยภูมิของกรุงสุโขทัยมีความเหมาะสมในการตั้งราชธานีอย่างไร?', '["มีทางออกสู่ทะเลลึกโดยตรง","ตั้งอยู่บริเวณที่ราบเชิงเขา มีแม่น้ำยมและลำน้ำสาขาไหลผ่าน ดินอุดมสมบูรณ์ และมีแนวเทือกเขาช่วยป้องกันลมมรสุม","เป็นเกาะกลางแม่น้ำขนาดใหญ่","อยู่บนยอดเขาสูงชันข้าศึกเข้าไม่ถึง"]'::jsonb, '1'::jsonb, 'สุโขทัยตั้งอยู่ริมแม่น้ำยม มีทรัพยากรธรรมชาติอุดมสมบูรณ์ เหมาะแก่การเกษตรและการคมนาคมทางบกและทางน้ำ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] รูปแบบการปกครองสมัยสุโขทัยตอนต้น', 'easy', 'mcq', 'การปกครองของสุโขทัยในยุคเริ่มต้นมีลักษณะความสัมพันธ์ระหว่างกษัตริย์กับราษฎรแบบใด?', '["ระบอบสมบูรณาญาสิทธิราชย์แบบเทวราชา","การปกครองแบบพ่อปกครองลูก (ปิตุราชา)","การปกครองแบบประชาธิปไตย","การปกครองแบบขุนนาง"]'::jsonb, '1'::jsonb, 'สุโขทัยตอนต้นปกครองแบบ "พ่อปกครองลูก" กษัตริย์ใช้คำนำหน้าว่า "พ่อขุน" ดูแลราษฎรอย่างใกล้ชิดเสมือนคนในครอบครัว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การรับเรื่องร้องทุกข์ของพ่อขุนรามคำแหง', 'easy', 'mcq', 'ในสมัยพ่อขุนรามคำแหงมหาราช ราษฎรที่มีเรื่องเดือดร้อนใจสามารถร้องทุกข์ต่อพระองค์ได้อย่างไร?', '["ส่งจดหมายอิเล็กทรอนิกส์","ไปสั่นกระดิ่งที่แขวนไว้ที่ประตูเมือง","เขียนป้ายประท้วงหน้าพระราชวัง","ต้องจ่ายเงินว่าจ้างขุนนางให้ไปกราบทูล"]'::jsonb, '1'::jsonb, 'พระองค์โปรดให้แขวนกระดิ่งไว้ที่ซุ้มประตูเมือง เมื่อราษฎรเดือดร้อนก็มาสั่นกระดิ่ง พระองค์จะเสด็จมาชำระความด้วยพระองค์เอง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การปกครองสมัยสุโขทัยตอนปลาย: ธรรมราชา', 'hard', 'mcq', 'ในสมัยพระมหาธรรมราชาที่ 1 (พญาลิไทย) รูปแบบการปกครองเปลี่ยนมาใช้หลักธรรมใดเป็นแนวทาง?', '["ทศพิธราชธรรม (การปกครองแบบธรรมราชา)","กฎหมายโรมัน","หลักนิติธรรมสากล","หลักอำนาจเด็ดขาด"]'::jsonb, '0'::jsonb, 'พระมหาธรรมราชาที่ 1 ทรงนำหลักธรรมทางพุทธศาสนา เช่น ทศพิธราชธรรม มาใช้ในการปกครองบ้านเมือง เรียกว่า "ธรรมราชา"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] เศรษฐกิจสุโขทัย: เสรีภาพทางการค้า', 'easy', 'mcq', 'ข้อความในศิลาจารึก "ใครจักใคร่ค้าช้างค้า ใครจักใคร่ค้าม้าค้า..." แสดงถึงลักษณะทางเศรษฐกิจด้านใดของสุโขทัย?', '["การผูกขาดการค้าโดยกษัตริย์","การค้าขายแบบเสรี โดยไม่มีการเก็บภาษีจังกอบ (ภาษีผ่านด่าน)","การห้ามประชาชนเลี้ยงสัตว์","การค้าขายเฉพาะกับชาวต่างชาติ"]'::jsonb, '1'::jsonb, 'แสดงถึงนโยบายการค้าแบบเสรี รัฐไม่เก็บภาษีผ่านด่าน (จังกอบ) ทำให้พ่อค้าเดินทางมาค้าขายอย่างคึกคัก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] ตลาดในสมัยสุโขทัย', 'medium', 'mcq', 'ตลาดค้าขายสินค้าในสมัยกรุงสุโขทัยมีชื่อเรียกว่าอะไร?', '["ตลาดปสาน","ตลาดน้ำ","ตลาดนัดคลองถม","ตลาดวโรรส"]'::jsonb, '0'::jsonb, 'ตลาดในสมัยสุโขทัยเรียกว่า "ตลาดปสาน" ซึ่งได้รับอิทธิพลมาจากคำว่า บาซาร์ (Bazaar) ในภาษาเปอร์เซีย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] สินค้าส่งออกสำคัญของสุโขทัย', 'easy', 'mcq', 'สินค้าหัตถกรรมเครื่องปั้นดินเผาเคลือบที่ขึ้นชื่อที่สุดของสุโขทัย ซึ่งส่งออกไปขายต่างประเทศคือข้อใด?', '["เครื่องเบญจรงค์","เครื่องสังคโลก","เครื่องลายคราม","เครื่องแก้วเจียระไน"]'::jsonb, '1'::jsonb, 'เครื่องสังคโลกผลิตจากเตาทุเรียงในเมืองสุโขทัยและศรีสัชนาลัย เป็นสินค้าส่งออกสำคัญไปยังดินแดนเอเชียตะวันออกเฉียงใต้และญี่ปุ่น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] การจัดการน้ำในสุโขทัย: สรีดภงส์', 'medium', 'mcq', 'ภูมิปัญญาการชลประทานสร้างเขื่อนหรือทำนบดินกักเก็บน้ำของชาวสุโขทัย เรียกว่าอะไร?', '["สรีดภงส์","บาราย","ฝายแม้ว","คลองชลประทาน"]'::jsonb, '0'::jsonb, 'สรีดภงส์ หรือทำนบพระร่วง เป็นทำนบดินกั้นน้ำระหว่างหุบเขา เพื่อกักเก็บน้ำไว้ใช้และระบายเข้าสู่คูเมืองและตระพังในฤดูแล้ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] สระน้ำหรืออ่างเก็บน้ำในเมืองสุโขทัย', 'medium', 'mcq', 'สระน้ำขนาดใหญ่ที่ขุดขึ้นภายในและรอบตัวเมืองสุโขทัยเพื่อกักเก็บน้ำสะอาดไว้ใช้ เรียกว่าอะไร?', '["หนองน้ำ","ตระพัง","บึง","แอ่ง"]'::jsonb, '1'::jsonb, 'ตระพัง (เช่น ตระพังเงิน ตระพังทอง ตระพังตระกวน) คือสระน้ำที่ขุดขึ้นเพื่อกักเก็บน้ำใช้อุปโภคบริโภคและใช้ในพิธีกรรมทางศาสนา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/2] ศาสนาในสมัยสุโขทัย', 'medium', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงอาราธนาพระสงฆ์จากเมืองใดมาเผยแผ่พระพุทธศาสนานิกายเถรวาท ลัทธิลังกาวงศ์ ที่สุโขทัย?', '["เมืองนครศรีธรรมราช","เมืองเชียงใหม่","เมืองละโว้ (ลพบุรี)","เมืองพุกาม"]'::jsonb, '0'::jsonb, 'ทรงอาราธนาพระมหาเถรสังฆราชจากเมืองนครศรีธรรมราช ผู้มีความเชี่ยวชาญพระไตรปิฎก มาจำพรรษาที่วัดอรัญญิก กรุงสุโขทัย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การประดิษฐ์อักษรไทย', 'easy', 'mcq', 'พ่อขุนรามคำแหงมหาราชทรงประดิษฐ์ "ลายสือไทย" ขึ้นในปี พ.ศ. ใด?', '["พ.ศ. 1792","พ.ศ. 1826","พ.ศ. 1900","พ.ศ. 2000"]'::jsonb, '1'::jsonb, 'ทรงดัดแปลงอักษรขอมและอักษรมอญโบราณมาประดิษฐ์เป็นลายสือไทยขึ้นเมื่อ พ.ศ. 1826 อันเป็นต้นกำเนิดอักษรไทยในปัจจุบัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วรรณกรรมชิ้นเอกสมัยสุโขทัย: ไตรภูมิพระร่วง', 'medium', 'mcq', 'วรรณกรรมเรื่อง "ไตรภูมิพระร่วง" พระราชนิพนธ์โดยกษัตริย์พระองค์ใด และมีเนื้อหาเกี่ยวกับเรื่องใด?', '["พ่อขุนรามคำแหงมหาราช เรื่องการรบ","พระมหาธรรมราชาที่ 1 (พญาลิไทย) เรื่องนรก สวรรค์ กฎแห่งกรรม และการทำความดี","พ่อขุนศรีอินทราทิตย์ เรื่องการค้าขาย","สมเด็จพระนเรศวรมหาราช เรื่องยุทธหัตถี"]'::jsonb, '1'::jsonb, 'พญาลิไทยทรงพระราชนิพนธ์เพื่อสอนศีลธรรม ให้ประชาชนเกรงกลัวต่อบาปและมุ่งทำความดีตามหลักไตรภูมิ (กามภูมิ รูปภูมิ อรูปภูมิ)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ศิลปะสถาปัตยกรรมสุโขทัย: เจดีย์ทรงพุ่มข้าวบิณฑ์', 'medium', 'mcq', 'เจดีย์ทรง "พุ่มข้าวบิณฑ์" (หรือทรงยอดดอกบัวตูม) เป็นเอกลักษณ์เฉพาะของศิลปกรรมในยุคใด?', '["สุโขทัย","อยุธยา","ธนบุรี","รัตนโกสินทร์"]'::jsonb, '0'::jsonb, 'เจดีย์ทรงพุ่มข้าวบิณฑ์หรือดอกบัวตูม (เช่น ที่วัดมหาธาตุ สุโขทัย) เป็นเจดีย์ศิลปะสุโขทัยแท้บริสุทธิ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระพุทธรูปศิลปะสุโขทัย', 'easy', 'mcq', 'พระพุทธรูปปางใดที่ถือว่างดงามอ่อนช้อยและโดดเด่นที่สุดในศิลปะสุโขทัย?', '["พระพุทธรูปปางลีลา","พระพุทธรูปปางป่าเลไลยก์","พระพุทธรูปปางนาคปรก","พระพุทธรูปปางไสยาสน์"]'::jsonb, '0'::jsonb, 'พระพุทธรูปปางลีลาสมัยสุโขทัยได้รับการยกย่องว่ามีความงดงาม อ่อนช้อย พริ้วไหวดั่งมีชีวิตมากที่สุดในประวัติศาสตร์ศิลป์ไทย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระพุทธชินราช', 'easy', 'mcq', 'พระพุทธรูปศักดิ์สิทธิ์คู่บ้านคู่เมืองที่มีพุทธลักษณะงดงามที่สุดในประเทศไทย สร้างขึ้นในสมัยสุโขทัย ประดิษฐาน ณ วัดพระศรีรัตนมหาธาตุ จังหวัดพิษณุโลก คือพระพุทธรูปองค์ใด?', '["พระแก้วมรกต","พระพุทธชินราช","พระพุทธโสธร","หลวงพ่อโต"]'::jsonb, '1'::jsonb, 'พระพุทธชินราชสร้างขึ้นในรัชสมัยพระมหาธรรมราชาที่ 1 (พญาลิไทย) มีพุทธลักษณะงดงามสมบูรณ์แบบที่สุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วีรกรรมของพ่อขุนรามคำแหงในวัยเยาว์', 'medium', 'mcq', 'พระนาม "รามคำแหง" ได้รับพระราชทานจากพระราชบิดาหลังทรงกระทำวีรกรรมใดเมื่อพระชนมายุ 19 พรรษา?', '["ทรงแต่งบทกลอนชนะเลิศ","ทรงชนช้างชนะขุนสามชน เจ้าเมืองฉอด ที่ยกทัพมาตีเมืองตาก","ทรงเดินทางไปค้าขายถึงประเทศจีน","ทรงสร้างเขื่อนสรีดภงส์สำเร็จ"]'::jsonb, '1'::jsonb, 'เมื่อพระชนมายุ 19 พรรษา ทรงไสช้างเข้าช่วยพระราชบิดาและชนช้างชนะขุนสามชนเจ้าเมืองฉอด พระราชบิดาจึงพระราชทานนามว่า "รามคำแหง" (รามผู้กล้าหาญ)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ความสัมพันธ์ระหว่างแว่นแคว้น: สหายสามกษัตริย์', 'hard', 'mcq', '"สามกษัตริย์" ที่ทรงเป็นพระสหายร่วมสาบานและร่วมกันวางผังสร้างเมืองนพบุรีศรีนครพิงค์เชียงใหม่ ประกอบด้วยพระมหากษัตริย์พระองค์ใดบ้าง?', '["พ่อขุนรามคำแหง, พญามังราย, พญางำเมือง","พ่อขุนศรีอินทราทิตย์, พ่อขุนผาเมือง, พระยาลิไทย","สมเด็จพระนเรศวร, สมเด็จพระเอกาทศรถ, พระสุพรรณกัลยา","พ่อขุนรามคำแหง, พระมหาธรรมราชา, ขุนสามชน"]'::jsonb, '0'::jsonb, 'พญามังราย (ล้านนา), พ่อขุนรามคำแหง (สุโขทัย), และพญางำเมือง (พะเยา) ทรงเป็นพระสหายสนิทร่วมกันสร้างเมืองเชียงใหม่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] พระมารดาของพ่อขุนรามคำแหง', 'medium', 'mcq', 'พระมเหสีของพ่อขุนศรีอินทราทิตย์ พระมารดาของพ่อขุนรามคำแหงมหาราช มีพระนามว่าอย่างไร?', '["นางเสือง","พระนางจามเทวี","ท้าวสุรนารี","นางนพมาศ"]'::jsonb, '0'::jsonb, 'ในศิลาจารึกระบุว่า "พ่อกูชื่อศรีอินทราทิตย์ แม่กูชื่อนางเสือง พี่กูชื่อบานเมือง..."');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ประเพณีเผาเทียนเล่นไฟ', 'easy', 'mcq', 'ข้อความในศิลาจารึกกล่าวถึงประเพณีลอยกระทงและจุดประทีปโคมไฟในกรุงสุโขทัยว่าอย่างไร?', '["ประเพณีแห่เทียนพรรษา","ประเพณีเผาเทียนเล่นไฟ","ประเพณีสงกรานต์","ประเพณีตักบาตรเทโว"]'::jsonb, '1'::jsonb, 'ในศิลาจารึกระบุว่าชาวสุโขทัยมักร่วมใจกันทำบุญและ "เผาเทียนเล่นไฟ" ในเทศกาลเดือนสิบสอง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การสิ้นสุดความเป็นราชธานีของสุโขทัย', 'hard', 'mcq', 'ในเวลาต่อมา อาณาจักรสุโขทัยได้ถูกรวมเข้าเป็นส่วนหนึ่งของอาณาจักรไทยใด?', '["อาณาจักรล้านนา","อาณาจักรอยุธยา","อาณาจักรธนบุรี","อาณาจักรขอม"]'::jsonb, '1'::jsonb, 'สุโขทัยค่อยๆ อ่อนแอลงและในที่สุดถูกผนวกรวมเข้าเป็นมณฑลราชธานีฝ่ายเหนือของอาณาจักรอยุธยาในสมัยสมเด็จพระบรมไตรโลกนาถ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การแสดงความกตัญญูกตเวทีของพ่อขุนรามคำแหง', 'easy', 'mcq', 'จากข้อความในจารึก "เมื่อกูขึ้นใหญ่ได้สิบเก้าเข้า... กูไปทวยพ่อกู กูบำเรอแก่พ่อกู กูบำเรอแก่แม่กู..." แสดงถึงคุณธรรมข้อใดของพ่อขุนรามคำแหง?', '["ความกตัญญูกตเวทีต่อบิดามารดา","ความร่ำรวยมั่งคั่ง","ความดุร้ายน่าเกรงขาม","ความสามารถด้านการค้า"]'::jsonb, '0'::jsonb, 'แสดงถึงความกตัญญูและการปรนนิบัติดูแลบิดามารดาด้วยความรักและความเคารพ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การติดต่อทางการทูตกับต่างประเทศ', 'medium', 'mcq', 'ในสมัยสุโขทัยมีการส่งคณะราชทูตและสำเภาไปเจริญสัมพันธไมตรีและการค้ากับประเทศมหาอำนาจใด?', '["ประเทศอังกฤษ","ประเทศจีน (ราชวงศ์หยวน)","ประเทศโปรตุเกส","ประเทศญี่ปุ่น"]'::jsonb, '1'::jsonb, 'สุโขทัยส่งเครื่องราชบรรณาการไปเจริญสัมพันธไมตรีกับจักรพรรดิจีนราชวงศ์หยวน และนำช่างจีนมาช่วยพัฒนาการทำเครื่องเคลือบสังคโลก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] อุทยานประวัติศาสตร์สุโขทัย มรดกโลก', 'easy', 'mcq', 'เมืองประวัติศาสตร์สุโขทัยและเมืองบริวาร (ศรีสัชนาลัย และกำแพงเพชร) ได้รับการยกย่องจากยูเนสโกให้เป็นสิ่งใด?', '["มรดกโลกทางวัฒนธรรม","มรดกโลกทางธรรมชาติ","เมืองหลวงสำรอง","เขตเศรษฐกิจพิเศษ"]'::jsonb, '0'::jsonb, 'ยูเนสโกประกาศให้อุทยานประวัติศาสตร์สุโขทัย ศรีสัชนาลัย และกำแพงเพชร เป็นแหล่งมรดกโลกทางวัฒนธรรมร่วมกันในปี พ.ศ. 2534');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วัดมหาธาตุ สุโขทัย', 'medium', 'mcq', 'วัดสำคัญที่เป็นศูนย์กลางทางศาสนาและการปกครอง ตั้งอยู่กึ่งกลางเมืองสุโขทัยคือวัดใด?', '["วัดพระศรีสรรเพชญ์","วัดมหาธาตุ","วัดพระแก้ว","วัดชนะสงคราม"]'::jsonb, '1'::jsonb, 'วัดมหาธาตุ สุโขทัย เป็นวัดหลวงกลางเมือง มีเจดีย์ประธานทรงพุ่มข้าวบิณฑ์บรรจุพระบรมสารีริกธาตุ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] วัดศรีชุมและอุโมงค์ภาพชาดก', 'hard', 'mcq', 'มณฑปวัดศรีชุม สุโขทัย มีชื่อเสียงโดดเด่นจากสิ่งใด?', '["พระอจนะ (พระพุทธรูปปูนปั้นปางมารวิชัยขนาดใหญ่) และภาพสลักหินชนวนเรื่องชาดกในช่องบันไดเพดาน","พระแก้วมรกตจำลอง","หอระฆังทองคำแท้","เสาหินอโศก"]'::jsonb, '0'::jsonb, 'วัดศรีชุมมี "พระพุทธรูปพูดได้" (พระอจนะ) และช่องทางเดินแคบๆ ในผนังที่มีภาพลายเส้นหินชนวนเล่าเรื่องชาดก 550 ชาติ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] ภูมิปัญญาการทำเครื่องปั้นดินเผา: เตาเผาสุโขทัย', 'medium', 'mcq', 'เตาเผาโบราณที่ใช้เผาเครื่องสังคโลกในสมัยสุโขทัย มีชื่อเรียกว่าอะไร?', '["เตาทุเรียง","เตาหลอมเหล็ก","เตาอบรมยา","เตาถ่านหิน"]'::jsonb, '0'::jsonb, 'เตาทุเรียง (หรือเตาประทุน) เป็นเตาเผาดินเผาโบราณทรงรีคล้ายประทุนเรือ ใช้เผาเครื่องสังคโลกอุณหภูมิสูง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] คุณค่าของการศึกษาประวัติศาสตร์สุโขทัย', 'easy', 'mcq', 'การศึกษาประวัติศาสตร์สมัยสุโขทัยมีประโยชน์ต่อนักเรียนในปัจจุบันอย่างไร?', '["ทำให้ทราบรากเหง้า ตัวอักษรไทย วัฒนธรรม และเกิดความภาคภูมิใจในความเป็นชาติไทย","ทำให้สามารถสร้างเครื่องสังคโลกขายได้รวย","เพื่อให้ท่องจำชื่อพระมหากษัตริย์ไปสอบเท่านั้น","ทำให้เดินทางไปท่องเที่ยวได้โดยไม่ต้องซื้อตั๋ว"]'::jsonb, '0'::jsonb, 'ช่วยให้เข้าใจความเป็นมาของชาติ ภาษา ตัวอักษรไทย ศิลปวัฒนธรรม และเกิดความหวงแหนภูมิปัญญาบรรพบุรุษ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ประวัติศาสตร์', 'ป.4', '[ส 4.3 ป.4/3] การสืบทอดมรดกทางวัฒนธรรม', 'easy', 'mcq', 'หน้าที่สำคัญที่สุดของเยาวชนไทยต่อประวัติศาสตร์และโบราณสถานของชาติคือข้อใด?', '["ช่วยกันอนุรักษ์ ดูแลรักษา ไม่ทำลาย และเผยแพร่ความรู้แก่ผู้อื่นอย่างถูกต้อง","ปล่อยให้เจ้าหน้าที่รัฐดูแลเพียงฝ่ายเดียว","นำสีสเปรย์ไปพ่นตกแต่งโบราณสถานให้ทันสมัย","ย้ายโบราณสถานมาไว้ที่โรงเรียน"]'::jsonb, '0'::jsonb, 'เยาวชนมีหน้าที่ศึกษาให้เข้าใจ ช่วยดูแลรักษา และไม่ทำลายโบราณสถานเพื่อให้คงอยู่สืบไปสู่อนุชนรุ่นหลัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/1] Classroom Instructions and Commands', 'easy', 'mcq', 'When the teacher says, "Open your book to page 25," what should you do?', '["ปิดหนังสือหน้าที่ 25","เปิดหนังสือหน้าที่ 25","เขียนชื่อในหน้าที่ 25","ส่งหนังสือคืนครู"]'::jsonb, '1'::jsonb, '"Open your book to page 25" แปลว่า ให้เปิดหนังสือไปที่หน้าที่ 25');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/1] Classroom Commands', 'easy', 'mcq', 'What is the opposite of the command "Stand up"?', '["Sit down","Turn around","Look at the board","Be quiet"]'::jsonb, '0'::jsonb, '"Stand up" แปลว่า ยืนขึ้น คำตรงข้ามคือ "Sit down" ซึ่งแปลว่า นั่งลง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Phonics: Short and Long Vowels', 'medium', 'mcq', 'Which word has the same vowel sound as "cake" /eɪ/?', '["cat","lake","car","ball"]'::jsonb, '1'::jsonb, 'คำว่า "lake" ออกเสียงสระเอ (long a sound: /eɪ/) เหมือนกับคำว่า "cake"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Phonics: Consonant Blends', 'easy', 'mcq', 'Which word begins with the blend sound /fl/?', '["frog","flag","drum","clock"]'::jsonb, '1'::jsonb, '"flag" ขึ้นต้นด้วยพยัญชนะควบกล้ำ fl- (ฟล)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Signs and Public Symbols', 'easy', 'mcq', 'You see a sign with a cigarette and a red cross over it. What does it mean?', '["No parking","No smoking","No food or drink","No taking photos"]'::jsonb, '1'::jsonb, 'ป้ายรูปบุหรี่มีแถบกากบาทสีแดง หมายถึง "No smoking" (ห้ามสูบบุหรี่)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Library Signs', 'easy', 'mcq', 'Which sign is most suitable for a school library?', '["Please be quiet","Danger! Do not enter","Turn right","Drive fast"]'::jsonb, '0'::jsonb, 'ในห้องสมุดควรมีป้าย "Please be quiet" (กรุณาเงียบ / งดใช้เสียง)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Reading Short Comprehension', 'medium', 'mcq', 'Read the text: "Anna has a brown puppy named Lucky. Lucky likes to run in the park and fetch a small red ball." What is Lucky?', '["A kitten","A puppy","A bird","A rabbit"]'::jsonb, '1'::jsonb, 'ในเนื้อเรื่องระบุชัดเจนว่า "Anna has a brown puppy named Lucky."');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Reading Details', 'medium', 'mcq', 'From the text about Lucky: What color is the ball that Lucky likes to fetch?', '["Yellow","Green","Red","Blue"]'::jsonb, '2'::jsonb, 'ในเนื้อเรื่องระบุว่า "...and fetch a small red ball." ดังนั้นลูกบอลเป็นสีแดง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Rhyming Words', 'easy', 'mcq', 'Which word rhymes with "sun"?', '["fun","sit","top","hot"]'::jsonb, '0'::jsonb, '"sun" (/sʌn/) มีเสียงสัมผัสสระและตัวสะกดตรงกับคำว่า "fun" (/fʌn/)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/3] Traffic Signs', 'easy', 'mcq', 'What does a red octagonal sign with the word "STOP" instruct drivers to do?', '["Go faster","Turn around","Stop the vehicle completely","Park here"]'::jsonb, '2'::jsonb, 'ป้าย STOP สั่งให้ผู้ขับขี่หยุดรถโดยสมบูรณ์ก่อนเพื่อความปลอดภัย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/2] Digraph Sounds: /sh/ and /ch/', 'medium', 'mcq', 'Which word contains the /tʃ/ sound as in "chair"?', '["ship","chocolate","shoe","fish"]'::jsonb, '1'::jsonb, '"chocolate" ออกเสียงพยัญชนะต้น ch- (/tʃ/) เหมือนคำว่า "chair"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.1 ป.4/4] Understanding Timetables', 'medium', 'mcq', 'Look at Tom''s timetable: "09:00 - English, 10:00 - Math, 11:00 - Science, 12:00 - Lunch." What subject does Tom study at 10:00?', '["English","Math","Science","Art"]'::jsonb, '1'::jsonb, 'จากตารางเรียน เวลา 10:00 น. ทอมเรียนวิชาคณิตศาสตร์ (Math)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Greetings and How Are You', 'easy', 'mcq', 'A: "Good morning, Tom! How are you today?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Introductions', 'easy', 'mcq', 'A: "Nice to meet you, Lisa."
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Asking for Permission', 'medium', 'mcq', 'Student: "May I go to the restroom, please?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Offering Help', 'medium', 'mcq', 'A: "Can I help you carry these heavy books?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Expressing Likes and Dislikes', 'easy', 'mcq', 'A: "Do you like apples?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Asking About Food Preferences', 'medium', 'mcq', 'A: "What is your favorite fruit?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/4] Asking Feelings and Emotions', 'easy', 'mcq', 'Look at the picture of a boy drinking water after playing sports. How does he feel?', '["He is thirsty.","He is cold.","He is sleepy.","He is angry."]'::jsonb, '0'::jsonb, 'คนที่ดื่มน้ำหลังเล่นกีฬา คือรู้สึกกระหายน้ำ หรือ "thirsty"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/4] Expressing Feelings', 'easy', 'mcq', 'A: "Why are you smiling?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/1] Saying Goodbye', 'easy', 'mcq', 'A: "See you tomorrow, Jack!"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Polite Responses (You''re welcome)', 'easy', 'mcq', 'A: "Thank you for lending me your pencil."
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/2] Apologizing (Sorry)', 'easy', 'mcq', 'When you accidentally step on someone''s foot, what should you say?', '["Congratulations!","I am so sorry.","Thank you!","Excuse me, where is the toilet?"]'::jsonb, '1'::jsonb, 'เมื่อเผลอเหยียบเท้าผู้อื่นโดยไม่ได้ตั้งใจ ควรกล่าวขอโทษว่า "I am so sorry."');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.2 ป.4/3] Asking for Prices', 'medium', 'mcq', 'Customer: "________ is this school bag?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Telling Time', 'easy', 'mcq', 'The clock shows the short hand at 3 and the long hand at 12. What time is it?', '["It is three o''clock.","It is twelve o''clock.","It is half past three.","It is three thirty."]'::jsonb, '0'::jsonb, 'เข็มสั้นชี้เลข 3 เข็มยาวชี้เลข 12 คือเวลา 3 นาฬิกาตรง ("It is three o''clock.")');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Telling Time (Half past)', 'medium', 'mcq', 'What time is 08:30 in words?', '["It is eight o''clock.","It is half past eight.","It is eight fifteen.","It is half past nine."]'::jsonb, '1'::jsonb, 'เวลา 08:30 คือ "half past eight" (ผ่านแปดโมงมาครึ่งชั่วโมง)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Appearance', 'medium', 'mcq', 'Mary has long black hair and big brown eyes. Which sentence describes Mary correctly?', '["She has short blonde hair.","She has long black hair.","She is short and fat.","Her eyes are blue."]'::jsonb, '1'::jsonb, 'จากข้อความระบุชัดเจนว่า "She has long black hair..."');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Animals', 'easy', 'mcq', 'It is a large animal. It has a long trunk and big ears. What animal is it?', '["A giraffe","A tiger","An elephant","A monkey"]'::jsonb, '2'::jsonb, 'สัตว์ที่มีงวงยาว (trunk) และใบหูใหญ่ คือช้าง (an elephant)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Daily Routines', 'easy', 'mcq', 'What do you do right after you wake up in the morning?', '["I go to bed.","I brush my teeth and wash my face.","I do my homework at night.","I play football in the rain."]'::jsonb, '1'::jsonb, 'หลังตื่นนอนตอนเช้า กิจวัตรปกติคือการแปรงฟันและล้างหน้า ("brush my teeth and wash my face")');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] School Subjects', 'easy', 'mcq', 'In which subject do you learn about numbers, addition, and shapes?', '["English","Music","Mathematics (Math)","Physical Education (PE)"]'::jsonb, '2'::jsonb, 'วิชาที่เรียนเกี่ยวกับตัวเลข การบวก และรูปทรง คือคณิตศาสตร์ (Math / Mathematics)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Days of the Week', 'easy', 'mcq', 'Which day comes right after Tuesday?', '["Monday","Wednesday","Thursday","Friday"]'::jsonb, '1'::jsonb, 'วันพุธ (Wednesday) มาต่อจากวันอังคาร (Tuesday) เสมอ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Months of the Year', 'medium', 'mcq', 'Which is the twelfth (12th) month of the year?', '["October","November","December","January"]'::jsonb, '2'::jsonb, 'เดือนที่ 12 ของปีคือเดือนธันวาคม (December)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Describing Weather', 'easy', 'mcq', 'The sun is shining brightly and the sky is clear. What is the weather like?', '["It is rainy.","It is snowy.","It is sunny.","It is stormy."]'::jsonb, '2'::jsonb, 'แดดออกจ้า ท้องฟ้าแจ่มใส คือสภาพอากาศ "sunny"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/1] Rooms in a House', 'easy', 'mcq', 'Where do people usually cook food and prepare meals in a house?', '["In the bedroom","In the kitchen","In the bathroom","In the garage"]'::jsonb, '1'::jsonb, 'ห้องครัว (kitchen) คือห้องสำหรับปรุงอาหาร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Occupations and Jobs', 'easy', 'mcq', 'A person who cures sick people and works in a hospital is a ________.', '["teacher","doctor","cook","farmer"]'::jsonb, '1'::jsonb, 'ผู้ที่รักษาคนป่วยในโรงพยาบาลคือคุณหมอ (doctor)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 1.3 ป.4/2] Occupations: Teacher', 'easy', 'mcq', 'A person who teaches students at school is a ________.', '["pilot","police officer","teacher","firefighter"]'::jsonb, '2'::jsonb, 'ผู้สอนหนังสือนักเรียนในโรงเรียนคือคุณครู (teacher)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Festivals: Christmas Day', 'easy', 'mcq', 'On Christmas Day (December 25th), who brings presents to children down the chimney?', '["Santa Claus","The Easter Bunny","A snowman","Peter Pan"]'::jsonb, '0'::jsonb, 'ซานตาคลอส (Santa Claus) เป็นสัญลักษณ์ของเทศกาลคริสต์มาสที่นำของขวัญมามอบให้เด็กๆ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Festivals: Halloween', 'easy', 'mcq', 'On October 31st (Halloween), children dress up in costumes and say: "________ or treat!"', '["Play","Trick","Sing","Dance"]'::jsonb, '1'::jsonb, 'ในเทศกาลฮาโลวีน เด็กๆ จะแต่งกายแฟนซีไปเคาะประตูบ้านเพื่อขอขนมด้วยคำพูดว่า "Trick or treat!"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] Symbols of Halloween', 'medium', 'mcq', 'What vegetable is carved into a Jack-o''-lantern for Halloween?', '["A carrot","A pumpkin","A tomato","A potato"]'::jsonb, '1'::jsonb, 'ฟักทอง (pumpkin) ถูกนำมาแกะสลักเป็นตะเกียงหน้าผีที่เรียกว่า Jack-o''-lantern');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/1] New Year Celebrations', 'easy', 'mcq', 'What do people say to greet each other on January 1st?', '["Merry Christmas!","Happy New Year!","Happy Halloween!","Happy Birthday!"]'::jsonb, '1'::jsonb, 'ในวันที่ 1 มกราคม (วันปีใหม่สากล) ผู้คนจะทักทายอวยพรกันว่า "Happy New Year!"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/2] Western Etiquette and Politeness', 'medium', 'mcq', 'In English culture, which word is used to show politeness when asking for something?', '["Please","Now","Quickly","Give"]'::jsonb, '0'::jsonb, 'คำว่า "Please" ใช้กำกับเมื่อขอร้องหรือสั่งซื้อสิ่งใดเพื่อให้สุภาพ นอบน้อม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 2.1 ป.4/2] Table Manners', 'easy', 'mcq', 'What should you do while chewing food at the dining table?', '["Talk loudly with your mouth open","Keep your mouth closed and do not speak with food in your mouth","Sing a song","Spit food on the floor"]'::jsonb, '1'::jsonb, 'มารยาทบนโต๊ะอาหารสากลคือการเคี้ยวอาหารโดยปิดปากและไม่พูดคุยขณะยังมีอาหารเต็มปาก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Pronouns: Subject Pronouns', 'easy', 'mcq', 'Peter is playing football. ________ is very fast.', '["She","He","They","It"]'::jsonb, '1'::jsonb, 'Peter เป็นผู้ชาย สรรพนามบุรุษที่ 3 เอกพจน์เพศชายคือ "He"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Pronouns: Plural Subject Pronouns', 'easy', 'mcq', 'Tom and I are in Grade 4. ________ are classmates.', '["He","We","They","You"]'::jsonb, '1'::jsonb, 'Tom and I (ทอมและฉัน) มีผู้พูดรวมอยู่ด้วย จัดเป็นสรรพนามพหูพจน์ "We" (พวกเรา)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Possessive Adjectives', 'medium', 'mcq', 'I have a new bicycle. ________ bicycle is red.', '["My","His","Her","Your"]'::jsonb, '0'::jsonb, 'สรรพนามแสดงความเป็นเจ้าของของ "I" คือ "My" (จักรยานของฉัน)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to be: Present Simple', 'easy', 'mcq', 'She ________ a student at Kampai School.', '["am","is","are","be"]'::jsonb, '1'::jsonb, 'ประธานเอกพจน์บุรุษที่ 3 (He, She, It) ใช้กริยา "is"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to be: Plural', 'easy', 'mcq', 'They ________ good friends.', '["is","are","am","was"]'::jsonb, '1'::jsonb, 'ประธานพหูพจน์ (They, We, You) ใช้กับกริยา "are"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to have: have / has', 'medium', 'mcq', 'A bird ________ two wings.', '["have","has","having","is"]'::jsonb, '1'::jsonb, 'ประธานเอกพจน์ "A bird" 1 ตัว ใช้ "has" ส่วนพหูพจน์หรือ I/You ใช้ "have"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Verb to have: Plural', 'easy', 'mcq', 'We ________ five pencils in the pencil case.', '["has","have","is","are"]'::jsonb, '1'::jsonb, 'ประธาน "We" ใช้ "have"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Simple Tense: Subject-Verb Agreement', 'medium', 'mcq', 'He ________ to school by bus every day.', '["go","goes","going","went"]'::jsonb, '1'::jsonb, 'ใน Present Simple Tense เมื่อประธานเป็น He, She, It กริยาต้องเติม -s หรือ -es (go -> goes)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Simple Tense: Plural Subject', 'easy', 'mcq', 'The students ________ milk every morning.', '["drinks","drink","drinking","drank"]'::jsonb, '1'::jsonb, 'ประธานพหูพจน์ "The students" กริยาใช้รูปเดิม ไม่ต้องเติม -s (drink)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Continuous Tense', 'medium', 'mcq', 'Look! The cat is ________ on the sofa right now.', '["sleep","sleeping","sleeps","slept"]'::jsonb, '1'::jsonb, 'Present Continuous (is/am/are + V-ing) ใช้บรรยายเหตุการณ์ที่กำลังดำเนินอยู่ขณะนี้ ("is sleeping")');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Present Continuous Tense: Plural', 'medium', 'mcq', 'The children ________ a song in the music room now.', '["is singing","are singing","sing","sings"]'::jsonb, '1'::jsonb, 'ประธาน "The children" เป็นพหูพจน์ จึงใช้โครงสร้าง "are singing"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Prepositions of Place: in / on / under', 'easy', 'mcq', 'The ball is ________ the table on the floor.', '["under","in","on","above"]'::jsonb, '0'::jsonb, 'ลูกบอลวางอยู่ใต้โต๊ะบนพื้น ใช้คำบุพบท "under" (ใต้)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Prepositions of Place: next to / behind', 'medium', 'mcq', 'The cat is hiding ________ the door so no one can see it.', '["behind","on","between","under"]'::jsonb, '0'::jsonb, 'แอบอยู่ "หลังประตู" เพื่อไม่ให้ใครมองเห็น ใช้ "behind" (ด้านหลัง)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: Where', 'easy', 'mcq', 'A: "________ do you live?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: When', 'easy', 'mcq', 'A: "________ is your birthday?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] WH-Question Words: Who', 'easy', 'mcq', 'A: "________ is that tall man?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] How many (Countable Nouns)', 'medium', 'mcq', 'A: "________ apples are there in the basket?"
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ภาษาอังกฤษ', 'ป.4', '[ต 4.1 ป.4/1] Singular and Plural Nouns', 'easy', 'mcq', 'What is the correct plural form of "box"?', '["boxs","boxes","boxies","boxen"]'::jsonb, '1'::jsonb, 'คำนามที่ลงท้ายด้วย -x เมื่อเปลี่ยนเป็นพหูพจน์ต้องเติม -es (box -> boxes)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/1] การเจริญเติบโตและพัฒนาการของร่างกายตามวัย', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับประเมินการเจริญเติบโตทางร่างกายของนักเรียนว่าสมวัยหรือไม่?', '["เครื่องวัดความดันโลหิต","เครื่องชั่งน้ำหนักและที่วัดส่วนสูง","เทอร์โมมิเตอร์วัดไข้","สายวัดรอบอก"]'::jsonb, '1'::jsonb, 'การชั่งน้ำหนักและวัดส่วนสูงตามเกณฑ์มาตรฐานของกรมอนามัย ใช้ประเมินการเจริญเติบโตของเด็กตามวัย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อลาย', 'medium', 'mcq', 'กล้ามเนื้อชนิดใดที่ยึดติดกับกระดูก ทำงานภายใต้อำนาจจิตใจ (เราสั่งให้ขยับได้ เช่น กล้ามแขน ขา)?', '["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อกระเพาะอาหาร"]'::jsonb, '0'::jsonb, 'กล้ามเนื้อลาย (Skeletal muscle) ยึดติดกับกระดูกและทำงานภายใต้การควบคุมของจิตใจ เช่น กล้ามเนื้อแขน ขา ลำตัว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อเรียบ', 'medium', 'mcq', 'กล้ามเนื้อที่พบในอวัยวะภายใน เช่น ผนังกระเพาะอาหาร ลำไส้ หลอดเลือด จัดเป็นกล้ามเนื้อชนิดใด?', '["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อโครงร่าง"]'::jsonb, '1'::jsonb, 'กล้ามเนื้อเรียบ (Smooth muscle) อยู่ตามอวัยวะภายในและทำงานอยู่นอกอำนาจจิตใจโดยอัตโนมัติ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] กล้ามเนื้อหัวใจ', 'easy', 'mcq', 'กล้ามเนื้อหัวใจมีลักษณะการทำงานอย่างไร?', '["ทำงานเฉพาะตอนที่เราตื่นนอน","ทำงานบีบตัวและคลายตัวตลอดชีวิตอยู่นอกอำนาจจิตใจ","เราสามารถสั่งให้หยุดเต้นได้ตามต้องการ","ทำงานเฉพาะเวลาออกกำลังกาย"]'::jsonb, '1'::jsonb, 'กล้ามเนื้อหัวใจทำงานบีบคลายตัวสูบฉีดเลือดโดยอัตโนมัติตลอดเวลา ไม่สามารถสั่งให้หยุดเต้นได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] การดูแลรักษาระบบกล้ามเนื้อ', 'easy', 'mcq', 'สารอาหารประเภทใดจำเป็นที่สุดในการเสริมสร้างและซ่อมแซมกล้ามเนื้อ?', '["คาร์โบไฮเดรต","โปรตีน (เช่น เนื้อสัตว์ ไข่ นม ถั่ว)","ไขมัน","วิตามินซี"]'::jsonb, '1'::jsonb, 'โปรตีนมีกรดอะมิโนที่ช่วยสร้างและซ่อมแซมเส้นใยกล้ามเนื้อที่สึกหรอ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] ระบบกระดูกและข้อต่อ: หน้าที่ของโครงกระดูก', 'easy', 'mcq', 'หน้าที่สำคัญของโครงกระดูกในร่างกายมนุษย์คือข้อใด?', '["เป็นโครงร่างพยุงร่างกาย ปกป้องอวัยวะภายใน และเป็นที่เกาะของกล้ามเนื้อ","สร้างน้ำย่อยอาหาร","ลำเลียงออกซิเจนในเลือด","ขับเหงื่อระบายความร้อน"]'::jsonb, '0'::jsonb, 'กระดูกช่วยค้ำจุนร่างกาย ป้องกันอวัยวะสำคัญ (เช่น กะโหลกป้องกันสมอง ซี่โครงป้องกันหัวใจและปอด) และช่วยในการเคลื่อนไหว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] กระดูกซี่โครง', 'easy', 'mcq', 'กระดูกซี่โครงทำหน้าที่สำคัญในการปกป้องอวัยวะภายในใดเป็นหลัก?', '["สมองและตา","หัวใจและปอด","กระเพาะอาหารและลำไส้ใหญ่","ตับและไต"]'::jsonb, '1'::jsonb, 'กรงกระดูกซี่โครงทำหน้าที่เหมือนเกราะป้องกันหัวใจและปอดจากการกระแทกภายนอก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] แร่ธาตุบำรุงกระดูกและฟัน', 'easy', 'mcq', 'แร่ธาตุชนิดใดมีความสำคัญที่สุดในการเสริมสร้างความแข็งแรงของกระดูกและฟัน?', '["ธาตุเหล็ก","แคลเซียมและฟอสฟอรัส","โซเดียม","ไอโอดีน"]'::jsonb, '1'::jsonb, 'แคลเซียมและฟอสฟอรัส (พบมากในนม ปลาเล็กปลาน้อย ผักใบเขียว) ช่วยให้กระดูกและฟันแข็งแรง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] การดูแลรักษาข้อต่อและกระดูก', 'medium', 'mcq', 'พฤติกรรมในข้อใดช่วยป้องกันปัญหากระดูกสันหลังคดงอได้ดีที่สุด?', '["นั่งหลังค่อมทำการบ้าน","สะพายกระเป๋าหนักๆ เพียงข้างเดียวตลอดเวลา","นั่งและยืนตัวตรง และสะพายกระเป๋านักเรียนแบบเป้สองสายน้ำหนักพอเหมาะ","นอนคว่ำอ่านหนังสือ"]'::jsonb, '2'::jsonb, 'การจัดบุคลิกภาพนั่งยืนหลังตรง และการกระจายน้ำหนักกระเป๋าเป้สองข้าง ช่วยรักษาสมดุลของแนวกระดูกสันหลัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/2] การอบอุ่นร่างกาย (Warm-up)', 'easy', 'mcq', 'การอบอุ่นร่างกาย (Warm-up) และยืดเหยียดกล้ามเนื้อก่อนเล่นกีฬามีประโยชน์อย่างไร?', '["ช่วยเพิ่มความอบอุ่นของร่างกายและป้องกันการบาดเจ็บของกล้ามเนื้อและข้อต่อ","ทำให้เหนื่อยล้าเร็วกว่าปกติ","ทำให้ไม่ต้องฝึกซ้อมกีฬา","ช่วยให้นอนหลับได้ทันที"]'::jsonb, '0'::jsonb, 'การวอร์มอัพช่วยเพิ่มอุณหภูมิร่างกาย กระตุ้นการไหลเวียนเลือด และเตรียมความพร้อมของกล้ามเนื้อเพื่อลดการบาดเจ็บ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/3] ข้อต่อในร่างกาย', 'medium', 'mcq', 'ข้อต่อบริเวณ "หัวไหล่และสะโพก" เป็นข้อต่อชนิดใดที่หมุนได้รอบทิศทาง?', '["ข้อต่อแบบบานพับ","ข้อต่อแบบลูกกลมในเบ้า (Ball and socket)","ข้อต่อแบบเดือย","ข้อต่อที่เคลื่อนไหวไม่ได้"]'::jsonb, '1'::jsonb, 'ข้อต่อแบบลูกกลมในเบ้าที่หัวไหล่และข้อสะโพกช่วยให้แขนและขาสามารถหมุนได้รอบทิศทาง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 1.1 ป.4/1] วิตามินดีกับกระดูก', 'medium', 'mcq', 'ร่างกายของเราสามารถสร้างวิตามินดีได้เองเมื่อผิวหนังสัมผัสกับสิ่งใดในปริมาณที่เหมาะสมในยามเช้า?', '["สายฝน","แสงแดดอ่อนๆ ยามเช้า","ลมหนาว","ไอหมอก"]'::jsonb, '1'::jsonb, 'แสงแดดยามเช้ามีรังสี UVB ที่ช่วยกระตุ้นให้ผิวหนังสังเคราะห์วิตามินดี ซึ่งช่วยในการดูดซึมแคลเซียมเข้าสู่กระดูก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] คุณลักษณะของครอบครัวที่อบอุ่น', 'easy', 'mcq', 'ข้อใดเป็นลักษณะสำคัญของ "ครอบครัวที่อบอุ่น"?', '["สมาชิกต่างคนต่างอยู่ ไม่พูดคุยกัน","สมาชิกในครอบครัวมีความรัก ความเข้าใจ และพูดคุยปรึกษากันด้วยเหตุผล","พ่อแม่ซื้อของขวัญราคาแพงให้ลูกตลอดเวลาแต่ไม่มีเวลาให้","ใช้อารมณ์และความรุนแรงตัดสินปัญหา"]'::jsonb, '1'::jsonb, 'ครอบครัวที่อบอุ่นเกิดจากความรัก ความเอาใจใส่ การให้เกียรติ และการสื่อสารที่ดีระหว่างกัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] บทบาทหน้าที่ของลูกในครอบครัว', 'easy', 'mcq', 'นักเรียนสามารถแสดงความกตัญญูและช่วยเหลือครอบครัวได้อย่างไร?', '["ช่วยทำงานบ้านตามกำลังความสามารถ และตั้งใจเรียนหนังสือ","ขอเงินไปเล่นเกมออนไลน์","เกี่ยงงานบ้านกับพี่น้อง","ออกไปเที่ยวนอกบ้านโดยไม่บอกผู้ปกครอง"]'::jsonb, '0'::jsonb, 'การตั้งใจเรียนหนังสือและช่วยเหลืองานบ้านเล็กๆ น้อยๆ เช่น กวาดบ้าน ล้างจาน ช่วยแบ่งเบาภาระของพ่อแม่ได้ดีที่สุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การสร้างและรักษาสัมพันธภาพกับเพื่อน', 'easy', 'mcq', 'การปฏิบัติตนข้อใดช่วยให้เป็นที่รักและมีสัมพันธภาพที่ดีกับเพื่อนๆ?', '["ชอบล้อเลียนปมด้อยของเพื่อน","มีน้ำใจ เอื้อเฟื้อเผื่อแผ่ และช่วยเหลือเพื่อนด้วยความจริงใจ","เอาแต่ใจตนเองเป็นหลัก","ยุยงให้เพื่อนทะเลาะกัน"]'::jsonb, '1'::jsonb, 'ความเอื้อเฟื้อ มีน้ำใจ ช่วยเหลือ และรับฟังความคิดเห็นของเพื่อนช่วยสร้างมิตรภาพที่ยั่งยืน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การแก้ปัญหาความขัดแย้งกับเพื่อน', 'medium', 'mcq', 'เมื่อเกิดความเข้าใจผิดหรือไม่เข้าใจกันกับเพื่อน ควรแก้ไขปัญหาอย่างไร?', '["ใช้กำลังชกต่อยตัดสิน","เปิดใจพูดคุยกันด้วยเหตุผลและรับฟังอีกฝ่ายอย่างใจเย็น","โพสต์ประจานเพื่อนลงบนอินเทอร์เน็ต","เลิกคบเพื่อนทุกคนในห้อง"]'::jsonb, '1'::jsonb, 'การเจรจาด้วยเหตุผลและความใจเย็นเป็นวิธีแก้ปัญหาความขัดแย้งที่ถูกต้องและสร้างสรรค์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] พฤติกรรมที่เหมาะสมกับเพศสภาพ', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตนที่สุภาพและให้เกียรติซึ่งกันและกันระหว่างเพศ?', '["การใช้คำพูดที่สุภาพ ไม่ล้อเลียนหรือรังแกผู้อื่น","การแตะเนื้อต้องตัวผู้อื่นโดยที่เขาไม่ยินยอม","การดูถูกผู้ที่มีเพศสภาพแตกต่างจากตน","การแย่งชิงสิ่งของของผู้อื่น"]'::jsonb, '0'::jsonb, 'การให้เกียรติซึ่งกันและกัน ไม่ว่าจะเพศใด การใช้คำพูดสุภาพและเคารพสิทธิส่วนบุคคลเป็นสิ่งสำคัญ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] การป้องกันตนเองจากการล่วงละเมิดทางเพศ', 'medium', 'mcq', 'หากมีคนแปลกหน้ามาขอกอด สัมผัสอวัยวะส่วนตัว หรือชวนไปในที่ลับตาคน ควรทำอย่างไร?', '["ยอมตามใจเพราะเขาให้อมยิ้ม","พูดปฏิเสธเสียงดังว่า \"อย่าทำ!\" แล้วรีบวิ่งหนีไปหาผู้ใหญ่หรือครูทันที","เก็บไว้เป็นความลับคนเดียว","ยืนเฉยๆ ไม่ตอบโต้"]'::jsonb, '1'::jsonb, 'ต้องปฏิเสธอย่างหนักแน่น รีบหนีออกจากสถานการณ์เสี่ยง และแจ้งพ่อแม่หรือคุณครูทันที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] ร่างกายของเรา สิทธิของเรา (Body Safety)', 'easy', 'mcq', 'ส่วนใดของร่างกายที่ถือเป็น "พื้นที่ส่วนตัว (Private Parts)" ที่ผู้อื่นไม่มีสิทธิ์มาสัมผัสหรือขอดู?', '["มือและแขน","บริเวณที่ปกคลุมด้วยชุดชั้นใน (หน้าอก อวัยวะเพศ และก้น)","เส้นผม","ฝ่าเท้า"]'::jsonb, '1'::jsonb, 'อวัยวะภายใต้ชุดชั้นในเป็นพื้นที่ส่วนตัวที่ห้ามมิให้ใครมาสัมผัสหรือขอดูโดยเด็ดขาด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/1] ความหลากหลายทางครอบครัว', 'medium', 'mcq', 'ครอบครัวที่ประกอบด้วย ปู่ ย่า พ่อ แม่ ลูก หลาน อาศัยอยู่ร่วมกันในบ้านหลังเดียวกัน เรียกว่าครอบครัวแบบใด?', '["ครอบครัวเดี่ยว","ครอบครัวขยาย","ครอบครัวข้ามรุ่น","ครอบครัวเลี้ยงเดี่ยว"]'::jsonb, '1'::jsonb, 'ครอบครัวขยาย (Extended family) คือครอบครัวที่มีญาติหลายรุ่นอาศัยอยู่ร่วมชายคาเดียวกัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/2] การเลือกคบเพื่อน', 'easy', 'mcq', 'การเลือกคบเพื่อนควรพิจารณาจากสิ่งใดเป็นสำคัญ?', '["มีฐานะร่ำรวยและมีของเล่นแพงๆ","มีความประพฤติดี ชักชวนกันเรียนและทำกิจกรรมที่มีประโยชน์","ชอบพากันโดดเรียนไปเล่นเกม","พูดจาหยาบคาย"]'::jsonb, '1'::jsonb, 'เพื่อนที่ดี (กัลยาณมิตร) คือผู้ที่มีความประพฤติดี ชวนกันไปในทางที่สร้างสรรค์และตั้งใจเรียน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 2.1 ป.4/3] การเคารพสิทธิความแตกต่างทางเพศ', 'easy', 'mcq', 'ข้อใดเป็นการปฏิบัติตนที่ถูกต้องต่อเพื่อนที่มีอัตลักษณ์ทางเพศหลากหลาย?', '["ตั้งชื่อล้อเลียนเพื่อความสนุกสนาน","ยอมรับ ให้เกียรติ และปฏิบัติต่อเพื่อนทุกคนอย่างเท่าเทียม","กีดกันไม่ให้ร่วมกิจกรรมกลุ่ม","ชักชวนให้คนอื่นรังเกียจ"]'::jsonb, '1'::jsonb, 'ในสังคมประชาธิปไตย เราต้องเคารพและยอมรับความหลากหลายทางเพศของทุกคนอย่างเท่าเทียม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายแบบอยู่กับที่', 'easy', 'mcq', 'กิจกรรมข้อใดจัดเป็น "การเคลื่อนไหวแบบอยู่กับที่ (Non-locomotor)"?', '["การวิ่งรอบสนาม","การกระโดดกบไปข้างหน้า","การก้มแตะปลายเท้าและบิดลำตัว","การว่ายน้ำข้ามสระ"]'::jsonb, '2'::jsonb, 'การเคลื่อนไหวแบบอยู่กับที่ คือการเคลื่อนไหวร่างกายโดยฐานรองรับน้ำหนักตัวไม่เปลี่ยนจุด เช่น บิดเอว ก้มแตะ ยืนเขย่ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายแบบเคลื่อนที่', 'easy', 'mcq', 'ข้อใดเป็น "การเคลื่อนไหวแบบเคลื่อนที่ (Locomotor)"?', '["การยืนกระต่ายขาเดียว","การวิ่งเหยาะๆ และการกระโดดเขย่งไปข้างหน้า","การหมุนคอ","การเหวี่ยงแขน"]'::jsonb, '1'::jsonb, 'การเคลื่อนไหวแบบเคลื่อนที่ คือการทำให้ร่างกายเคลื่อนจากจุดหนึ่งไปยังอีกจุดหนึ่ง เช่น เดิน วิ่ง กระโดด กลิ้ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การเคลื่อนไหวร่างกายโดยใช้อุปกรณ์ประกอบ', 'easy', 'mcq', 'กิจกรรมข้อใดเป็นการเคลื่อนไหวร่างกายที่ "ใช้อุปกรณ์ประกอบ (Manipulative)"?', '["การเลี้ยงลูกฟุตบอลและการโยน-รับลูกบอล","การวิ่งแข่ง 50 เมตร","การนอนหงายชันเข่า","การกระโดดตบ"]'::jsonb, '0'::jsonb, 'การใช้อุปกรณ์ประกอบ เช่น ลูกบอล ห่วงฮูลาฮูป เชือกกระโดด ไม้แบดมินตัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/2] ทักษะกายบริหารและการยืดหยุ่นขั้นพื้นฐาน', 'medium', 'mcq', 'ท่า "ม้วนหน้า" บนเบาะยางยืดหยุ่น จุดใดของร่างกายควรสัมผัสเบาะเป็นจุดแรกหลังจากมือแตะเบาะ?', '["หน้าผาก","ท้ายทอย (บริเวณคอด้านหลัง)","กลางหลัง","ก้น"]'::jsonb, '1'::jsonb, 'การม้วนหน้าที่ถูกต้องคือก้มคางชิดอก เพื่อให้ "ท้ายทอย" แตะเบาะอย่างปลอดภัย ป้องกันการบาดเจ็บที่คอและหน้าผาก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/3] เกมเบ็ดเตล็ดและการละเล่นพื้นบ้าน', 'easy', 'mcq', 'การละเล่น "วิ่งเปี้ยว" ช่วยพัฒนาสมรรถภาพทางกายด้านใดมากที่สุด?', '["ความยืดหยุ่นของกล้ามเนื้อ","ความเร็วและความคล่องแคล่วว่องไว","ความอดทนของปอดและหัวใจ","ความแม่นยำ"]'::jsonb, '1'::jsonb, 'วิ่งเปี้ยวเน้นการวิ่งสปีดระยะสั้น การกลับตัว และการรับส่งผ้า จึงช่วยพัฒนาความเร็วและความคล่องตัว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/4] ทักษะกีฬาแชร์บอลเบื้องต้น', 'medium', 'mcq', 'ในกีฬาแชร์บอล ผู้ถือตะกร้าต้องยืนบนเก้าอี้ มีสิทธิ์ทำสิ่งใดได้?', '["กระโดดลงจากเก้าอี้ไปแย่งบอล","ยืนทรงตัวบนเก้าอี้และขยับตะกร้ารับลูกบอลที่เพื่อนร่วมทีมโยนมา","วิ่งไปรอบๆ สนาม","ผลักผู้เล่นฝ่ายตรงข้าม"]'::jsonb, '1'::jsonb, 'ผู้ถือตะกร้าต้องยืนทรงตัวบนเก้าอี้ ห้ามก้าวเท้าลงมา และสามารถเอียงหรือขยับตะกร้าเพื่อรับลูกบอลได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/1] กฎและกติกาการเล่นกีฬาแฮนด์บอล/แชร์บอล', 'medium', 'mcq', 'ในกีฬาแชร์บอล ผู้เล่นที่ถือลูกบอลสามารถถือลูกบอลไว้ในมือได้ไม่เกินกี่วินาทีโดยไม่ส่งหรือยิง?', '["3 วินาที","5 วินาที","10 วินาที","ไม่จำกัดเวลา"]'::jsonb, '0'::jsonb, 'ตามกติกาแชร์บอลสากล ผู้เล่นสามารถถือลูกบอลไว้ในมือได้ไม่เกิน 3 วินาที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/2] น้ำใจนักกีฬา (Sportsmanship)', 'easy', 'mcq', 'ข้อความว่า "รู้แพ้ รู้ชนะ รู้อภัย" มีความหมายตรงกับคุณธรรมข้อใด?', '["ความมีวินัย","ความมีน้ำใจนักกีฬา","ความประหยัด","ความซื่อสัตย์"]'::jsonb, '1'::jsonb, 'น้ำใจนักกีฬาคือการยอมรับความพ่ายแพ้อย่างสง่างาม ชนะอย่างถ่อมตน และให้อภัยเมื่อเกิดอุบัติเหตุในการแข่งขัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.2 ป.4/2] การเคารพคำตัดสินของกรรมการ', 'easy', 'mcq', 'เมื่อกรรมการเป่านกหวีดตัดสินว่าลูกออกข้าง แต่เราคิดว่ายังไม่ออก เราควรทำอย่างไร?', '["วิ่งเข้าไปผลักกรรมการ","ยอมรับการตัดสินของกรรมการและเล่นต่อไปตามกติกา","ขว้างลูกบอลทิ้งและไม่ยอมเล่นต่อ","ชวนเพื่อนทั้งทีมเดินออกจากสนาม"]'::jsonb, '1'::jsonb, 'นักกีฬาที่ดีต้องเคารพการตัดสินของผู้ตัดสินและควบคุมอารมณ์ของตนเองตามกติกาการแข่งขัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/2] การผ่อนคลายกล้ามเนื้อ (Cool-down)', 'easy', 'mcq', 'หลังจากการออกกำลังกายอย่างหนัก ควรทำสิ่งใดเพื่อปรับอัตราการเต้นของหัวใจให้เข้าสู่ภาวะปกติ?', '["นั่งดื่มน้ำเย็นจัดแก้วใหญ่ทันที","การคลายอุ่นร่างกาย (Cool-down) ด้วยการเดินช้าๆ และยืดกล้ามเนื้อเบาๆ","นอนหลับลงบนพื้นทันที","ไปอาบน้ำเย็นทันที"]'::jsonb, '1'::jsonb, 'Cool-down ช่วยให้เลือดไหลเวียนกลับสู่หัวใจอย่างนุ่มนวลและลดการสะสมของกรดแลกติกในกล้ามเนื้อ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/3] การแต่งกายที่เหมาะสมกับการเล่นกีฬา', 'easy', 'mcq', 'การแต่งกายไปเล่นกีฬาข้อใดถูกต้องและปลอดภัยที่สุด?', '["สวมกางเกงยีนส์รัดรูปและรองเท้าแตะ","สวมชุดพละที่ระบายอากาศได้ดีและสวมรองเท้าผ้าใบผูกเชือกแน่นหนา","สวมรองเท้าคัทชูหนัง","ใส่เครื่องประดับสร้อยคอทองคำเส้นใหญ่"]'::jsonb, '1'::jsonb, 'ชุดพละและรองเท้าผ้าใบช่วยให้เคลื่อนไหวสะดวกและช่วยดูดซับแรงกระแทก ป้องกันอุบัติเหตุข้อเท้าพลิก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 3.1 ป.4/1] การทรงตัว (Balance)', 'medium', 'mcq', 'การฝึกเดินบนสันไม้ทรงตัว (Balance beam) ช่วยส่งเสริมสมรรถภาพทางกายด้านใดเป็นหลัก?', '["ความยืดหยุ่น","การทรงตัว (Balance)","พลังกล้ามเนื้อ","ความเร็ว"]'::jsonb, '1'::jsonb, 'การเดินบนสะพานไม้แคบๆ ช่วยฝึกระบบประสาทและการทำงานประสานกันของกล้ามเนื้อเพื่อรักษาสมดุลของร่างกาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] อาหารหลัก 5 หมู่: หมู่ที่ 1 โปรตีน', 'easy', 'mcq', 'อาหารในข้อใดจัดอยู่ในอาหารหลักหมู่ที่ 1 (โปรตีน)?', '["ข้าว, แป้ง, เผือก, มัน","เนื้อหมู, ไข่ไก่, นม, ปลา","ผักบุ้ง, แตงกวา, ผักกาดขาว","กล้วยหอม, ส้ม, แตงโม"]'::jsonb, '1'::jsonb, 'อาหารหมู่ที่ 1 ได้แก่ เนื้อสัตว์ นม ไข่ และถั่วเมล็ดแห้ง ให้สารอาหารประเภทโปรตีน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] อาหารหลักหมู่ที่ 2: คาร์โบไฮเดรต', 'easy', 'mcq', 'สารอาหารประเภทคาร์โบไฮเดรตให้ประโยชน์หลักต่อร่างกายอย่างไร?', '["ให้พลังงานและความอบอุ่นแก่ร่างกายในการทำกิจกรรม","ช่วยรักษาแผลให้หายเร็ว","ช่วยบำรุงสายตา","ช่วยสร้างกระดูกและฟัน"]'::jsonb, '0'::jsonb, 'คาร์โบไฮเดรต (ข้าว แป้ง น้ำตาล เผือก มัน) เป็นแหล่งพลังงานหลักที่ร่างกายนำไปใช้ในการเคลื่อนไหวและทำงาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] วิตามินและเกลือแร่ (หมู่ที่ 3 และ 4)', 'easy', 'mcq', 'ผักและผลไม้เป็นแหล่งสำคัญของสารอาหารประเภทใดที่ช่วยให้ระบบขับถ่ายทำงานเป็นปกติ?', '["โปรตีนและไขมัน","วิตามิน แร่ธาตุ และใยอาหาร (Fiber)","คาร์โบไฮเดรตเข้มข้น","คอเลสเตอรอล"]'::jsonb, '1'::jsonb, 'ผักผลไม้อุดมด้วยวิตามิน แร่ธาตุ และกากใยอาหารที่ช่วยกระตุ้นการบีบตัวของลำไส้ ป้องกันอาการท้องผูก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] วิตามินเอและการบำรุงสายตา', 'medium', 'mcq', 'หากมีอาการมองเห็นไม่ชัดในที่สลัว (โรคตาฟางตอนกลางคืน) ควรรับประทานอาหารที่อุดมด้วยวิตามินใด?', '["วิตามินเอ (เช่น แครอท ฟักทอง ตับ)","วิตามินซี (เช่น ส้ม มะนาว)","วิตามินดี","วิตามินเค"]'::jsonb, '0'::jsonb, 'วิตามินเอช่วยบำรุงสายตาและการมองเห็น พบมากในผักผลไม้สีเหลืองส้มและเครื่องในสัตว์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] โรคเลือดออกตามไรฟันและวิตามินซี', 'easy', 'mcq', 'การขาดวิตามินซีเป็นเวลานานจะส่งผลให้เกิดโรคใด?', '["โรคเหน็บชา","โรคเลือดออกตามไรฟัน (ลักปิดลักเปิด)","โรคคอพอก","โรคกระดูกอ่อน"]'::jsonb, '1'::jsonb, 'วิตามินซีช่วยให้ผนังหลอดเลือดแข็งแรง หากขาดจะทำให้เกิดเลือดออกตามไรฟันได้ง่าย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/2] ธงโภชนาการ', 'medium', 'mcq', 'ตามหลัก "ธงโภชนาการ" ของไทย กลุ่มอาหารที่อยู่บริเวณ "ปลายยอดแหลมล่างสุด" คือกลุ่มที่ควรรับประทานน้อยที่สุด ได้แก่อะไร?', '["ข้าวและแป้ง","ผักและผลไม้","น้ำมัน น้ำตาล และเกลือ","นมและเนื้อสัตว์"]'::jsonb, '2'::jsonb, 'ปลายยอดล่างสุดของธงโภชนาการคือน้ำมัน น้ำตาล และเกลือ ซึ่งควรรับประทานในปริมาณน้อยที่สุดเพื่อป้องกันโรคเรื้อรัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] การเลือกซื้ออาหารสำเร็จรูปและอาหารกระป๋อง', 'easy', 'mcq', 'ข้อใดเป็นลักษณะของปลากระป๋องที่ "ไม่ควรซื้อ" มารับประทานอย่างเด็ดขาด?', '["มีฉลากและวันหมดอายุระบุชัดเจน","กระป๋องบวม บุบ เป็นสนิม หรือมีรอยรั่วซึม","มีเครื่องหมาย อย. รับรอง","กระป๋องปิดผนึกสนิท"]'::jsonb, '1'::jsonb, 'กระป๋องที่บวมหรือบุบอาจมีการเจริญเติบโตของเชื้อแบคทีเรียคลอสทริเดียม โบทูลินัม ซึ่งสร้างสารพิษอันตรายถึงชีวิต');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] เครื่องหมาย อย.', 'easy', 'mcq', 'เครื่องหมาย อย. รับรองความปลอดภัยของผลิตภัณฑ์อาหารและยา ออกโดยหน่วยงานใด?', '["สำนักงานคณะกรรมการคุ้มครองผู้บริโภค (สคบ.)","สำนักงานคณะกรรมการอาหารและยา กระทรวงสาธารณสุข","กรมการค้าภายใน","กระทรวงศึกษาธิการ"]'::jsonb, '1'::jsonb, 'อย. คือสำนักงานคณะกรรมการอาหารและยา สังกัดกระทรวงสาธารณสุข ตรวจสอบมาตรฐานความปลอดภัยของอาหาร ยา และเครื่องสำอาง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] การดูวันหมดอายุบนฉลาก (EXP / BBD)', 'easy', 'mcq', 'ข้อความว่า "EXP 15/10/2026" บนกล่องนม หมายความว่าอย่างไร?', '["ผลิตในวันที่ 15 ตุลาคม 2026","หมดอายุในวันที่ 15 ตุลาคม 2026 (ไม่ควรดื่มหลังจากนี้)","ราคา 15 บาท 10 สตางค์","ควรดื่มให้หมดภายใน 15 นาที"]'::jsonb, '1'::jsonb, 'EXP ย่อมาจาก Expiry Date หมายถึง วันที่อาหารหมดอายุ ไม่ควรบริโภคหลังวันดังกล่าว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/4] สุขภาพจิตและอารมณ์', 'easy', 'mcq', 'เมื่อนักเรียนรู้สึกเครียดจากการเรียนหรือมีเรื่องไม่สบายใจ วิธีปฏิบัติตนข้อใดช่วยคลายเครียดได้อย่างเหมาะสม?', '["ขังตัวเองไว้ในห้องมืดคนเดียว","พูดคุยปรึกษาพ่อแม่ ฟังเพลง หรือออกไปออกกำลังกายกลางแจ้ง","ทุบทำลายข้าวของในบ้าน","อดอาหารประชด"]'::jsonb, '1'::jsonb, 'การพูดคุยกับคนที่ไว้ใจ การฟังเพลง ทำงานอดิเรก หรือเล่นกีฬาช่วยหลั่งสารเอนดอร์ฟินลดความเครียดได้ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] โทษของอาหารขยะ (Junk Food)', 'medium', 'mcq', 'การดื่มน้ำอัดลมและรับประทานขนมกรุบกรอบเป็นประจำทุกวัน จะส่งผลเสียต่อร่างกายอย่างไร?', '["ทำให้กล้ามเนื้อแข็งแรงขึ้น","เสี่ยงต่อการเกิดโรคอ้วน ฟันผุ และได้รับโซเดียมมากเกินไปจนไตทำงานหนัก","ทำให้สายตาดีขึ้น","ช่วยให้กระดูกยาวเร็วขึ้น"]'::jsonb, '1'::jsonb, 'น้ำอัดลมมีน้ำตาลและกรดคาร์บอนิกทำให้ฟันผุ ส่วนขนมกรุบกรอบมีโซเดียมและไขมันอิ่มตัวสูง เสี่ยงต่อโรคอ้วนและโรคไต');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/4] การนอนหลับพักผ่อน', 'easy', 'mcq', 'เด็กในวัยประถมศึกษาตอนปลาย (ป.4) ควรนอนหลับพักผ่อนวันละกี่ชั่วโมงจึงจะเพียงพอต่อการเจริญเติบโต?', '["3-4 ชั่วโมง","5-6 ชั่วโมง","8-10 ชั่วโมง","14-16 ชั่วโมง"]'::jsonb, '2'::jsonb, 'เด็กวัย 9-12 ปี ต้องการการนอนหลับ 8-10 ชั่วโมง เพื่อให้ Growth Hormone หลั่งออกมาช่วยซ่อมแซมร่างกายและเสริมความสูง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/1] การดื่มน้ำสะอาด', 'easy', 'mcq', 'ในแต่ละวัน เราควรดื่มน้ำสะอาดอย่างน้อยวันละเท่าใด?', '["1-2 แก้ว","3-4 แก้ว","6-8 แก้ว","15-20 แก้ว"]'::jsonb, '2'::jsonb, 'การดื่มน้ำสะอาดวันละ 6-8 แก้ว ช่วยระบบไหลเวียนโลหิต การขับถ่ายของเสีย และควบคุมอุณหภูมิร่างกาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 4.1 ป.4/3] สารปนเปื้อนในอาหาร: สารบอแรกซ์', 'hard', 'mcq', 'สารเคมีอันตราย "บอแรกซ์" มักถูกลักลอบใส่ในอาหารประเภทใดเพื่อให้เนื้อสัมผัสกรอบเด้ง?', '["ลูกชิ้น, หมูยอ, ทับทิมกรอบ","น้ำส้มคั้น","ข้าวหอมมะลิ","นมสดพาสเจอร์ไรส์"]'::jsonb, '0'::jsonb, 'บอแรกซ์ (น้ำประสานทอง) นิยมลักลอบใส่ในลูกชิ้น หมูยอ ไส้กรอก เพื่อให้กรอบเด้ง เป็นอันตรายต่อไตและระบบทางเดินอาหาร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] การป้องกันอุบัติเหตุในโรงเรียน', 'easy', 'mcq', 'พฤติกรรมใดเสี่ยงต่อการเกิดอุบัติเหตุตกจากที่สูงในโรงเรียน?', '["เดินชิดขวาขึ้นลงบันไดอย่างมีสติ","ปีนป่ายราวระเบียงหรือโหนตัวบนราวบันไดอาคารเรียน","นั่งรับประทานอาหารที่โรงอาหาร","อ่านหนังสือในห้องสมุด"]'::jsonb, '1'::jsonb, 'การปีนป่ายราวระเบียงและโหนราวบันไดเสี่ยงต่อการพลัดตกรุนแรง เกิดการบาดเจ็บที่กระดูกหรือสมองได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] ความปลอดภัยจากการจราจร', 'easy', 'mcq', 'เมื่อต้องการข้ามถนนในบริเวณที่มีการจราจรหนาแน่น ควรเลือกข้ามที่ใดจึงปลอดภัยที่สุด?', '["วิ่งตัดหน้ารถที่กำลังแล่น","ข้ามบนสะพานลอยคนข้าม หรือทางม้าลายที่มีสัญญาณไฟคนข้าม","มุดใต้ที่กั้นเกาะกลางถนน","ข้ามตรงทางโค้งอับสายตา"]'::jsonb, '1'::jsonb, 'สะพานลอยคนข้ามและทางม้าลายเป็นจุดที่ปลอดภัยที่สุดในการข้ามถนน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/1] ความปลอดภัยในการโดยสารรถจักรยานยนต์', 'easy', 'mcq', 'อุปกรณ์ความปลอดภัยที่ผู้ขับขี่และผู้ซ้อนท้ายรถจักรยานยนต์ต้องสวมใส่เสมอตามกฎหมายคือข้อใด?', '["หมวกนิรภัย (หมวกกันน็อก)","แว่นตากันแดด","ถุงมือผ้า","เสื้อกันฝน"]'::jsonb, '0'::jsonb, 'หมวกนิรภัยช่วยปกป้องศีรษะและสมองจากการกระแทกเมื่อเกิดอุบัติเหตุทางถนน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: แผลถลอก', 'medium', 'mcq', 'ขั้นตอนแรกในการปฐมพยาบาลเมื่อมี "แผลถลอก" คือข้อใด?', '["ใช้ผ้าพันแผลพันทับทันที","ล้างแผลด้วยน้ำสะอาดหรือน้ำเกลือล้างแผลและสบู่เพื่อชะล้างสิ่งสกปรก","เอาผงกาแฟมาโรยแผล","ใช้มีดขูดคราบเลือดออก"]'::jsonb, '1'::jsonb, 'ต้องล้างทำความสะอาดแผลด้วยน้ำสะอาดหรือน้ำเกลือเพื่อกำจัดเชื้อโรคและเศษดินก่อนใส่ยาฆ่าเชื้อ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: เลือดกำเดาไหล', 'medium', 'mcq', 'เมื่อมีเลือดกำเดาไหล วิธีการปฐมพยาบาลที่ถูกต้องที่สุดคือข้อใด?', '["แหงนหน้าขึ้นฟ้าสูงๆ เพื่อไม่ให้เลือดไหล","ก้มหน้าลงเล็กน้อย ใช้นิ้วบีบปีกจมูกทั้งสองข้าง 5-10 นาที และหายใจทางปาก","สั่งน้ำมูกแรงๆ ออกมาทันที","เอาน้ำร้อนราดศีรษะ"]'::jsonb, '1'::jsonb, 'ควรก้มหน้าลงเล็กน้อย (เพื่อไม่ให้เลือดไหลลงคอและสำลัก) แล้วบีบปีกจมูกกดจุดเลือดออกไว้ 5-10 นาที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: แมลงสัตว์กัดต่อย (ผึ้ง/ต่อ)', 'medium', 'mcq', 'เมื่อถูกผึ้งต่อย สิ่งแรกที่ควรทำคือข้อใด?', '["ใช้วัตถุปลายทื่อ เช่น ขอบบัตรพลาสติกหรือปากกาค่อยๆ ขูดเอาเหล็กในออก แล้วประคบเย็น","ใช้เล็บมือบีบเค้นเหล็กในแรงๆ","นำโคลนมาพอกแผล","เอาไฟมารนบริเวณที่ถูกต่อย"]'::jsonb, '0'::jsonb, 'ใช้บัตรพลาสติกปาดเอาเหล็กในออก ไม่ควรใช้มือบีบเพราะจะทำให้ถุงพิษแตกซึมเข้าสู่ผิวหนังมากขึ้น แล้วประคบเย็นลดปวด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/2] การปฐมพยาบาล: ข้อเท้าแพลง (RICE)', 'hard', 'mcq', 'เมื่อข้อเท้าแพลงในช่วง 24-48 ชั่วโมงแรก ควรใช้สิ่งใดประคบเพื่อลดอาการบวมและอักเสบ?', '["กระเป๋าน้ำร้อน","ผ้าห่อน้ำแข็งหรือแผ่นเจลเย็น (Cold pack)","ยานวดน้ำมันมวยร้อน","ใบตองชุบเหล้าขาว"]'::jsonb, '1'::jsonb, 'ในระยะ 48 ชั่วโมงแรกต้องประคบเย็น (Ice) เพื่อให้หลอดเลือดหดตัวลดอาการบวม ห้ามประคบร้อนเด็ดขาด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] โทษของบุหรี่', 'easy', 'mcq', 'สารเสพติดที่เป็นอันตรายในควันบุหรี่ ซึ่งทำให้เกิดการเสพติดและโรคหัวใจคือสารใด?', '["นิโคตินและทาร์ (น้ำมันดิน)","วิตามินบี","เกลือแร่","ออกซิเจนบริสุทธิ์"]'::jsonb, '0'::jsonb, 'นิโคตินทำให้หัวใจเต้นเร็ว ความดันโลหิตสูงและเสพติด ส่วนทาร์เป็นสารก่อมะเร็งปอดและโรคถุงลมโป่งพอง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] โทษของเครื่องดื่มแอลกอฮอล์ (สุรา)', 'easy', 'mcq', 'การดื่มสุราหรือเครื่องดื่มแอลกอฮอล์ส่งผลเสียโดยตรงต่ออวัยวะภายในใดจนอาจเกิดโรคตับแข็ง?', '["ตับ","ปอด","หัวใจ","กระเพาะปัสสาวะ"]'::jsonb, '0'::jsonb, 'แอลกอฮอล์ถูกทำลายที่ตับ การดื่มต่อเนื่องทำให้ตับอักเสบ ไขมันพอกตับ และกลายเป็นโรคตับแข็งในที่สุด');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] ยาบ้า (แอมเฟตามีน)', 'medium', 'mcq', 'ยาบ้าออกฤทธิ์ต่อระบบประสาทอย่างไร และส่งผลร้ายแรงอย่างไรต่อผู้เสพ?', '["ทำให้รู้สึกสงบสุข","กระตุ้นประสาท ทำให้ประสาทหลอน หวาดระแวง คุ้มคลั่ง และทำร้ายผู้อื่น","ช่วยให้ความจำดีขึ้น","รักษาโรคเบาหวาน"]'::jsonb, '1'::jsonb, 'ยาบ้าออกฤทธิ์กระตุ้นประสาทอย่างรุนแรง ทำให้เกิดภาพหลอน คุ้มคลั่ง ขาดสติ และอาจก่อความรุนแรงในสังคม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] สารระเหย (กาว ทินเนอร์)', 'medium', 'mcq', 'การสูดดมสารระเหย (เช่น กาว ทินเนอร์) ส่งผลทำลายอวัยวะสำคัญใดอย่างถาวร?', '["เซลล์สมองเสื่อม ความจำเสื่อม กล้ามเนื้อลีบ","ทำให้ฟันขาวขึ้น","ทำให้ผมยาวเร็ว","ช่วยบำรุงสายตา"]'::jsonb, '0'::jsonb, 'สารระเหยมีสารพิษทำลายเซลล์สมองโดยตรง ทำให้สมองฝ่อ ความจำเสื่อม และระบบประสาทพิการถาวร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('สุขศึกษา', 'ป.4', '[พ 5.1 ป.4/3] ทักษะการปฏิเสธสารเสพติด', 'easy', 'mcq', 'หากมีเพื่อนชักชวนให้ทดลองสูบบุหรี่หรือยาเสพติด ควรใช้หลักการใดในการปฏิเสธ?', '["ลองเพียงครั้งเดียวเพื่อไม่ให้เพื่อนเสียน้ำใจ","ปฏิเสธอย่างหนักแน่นว่า \"ไม่ ไม่ลองเด็ดขาด\" และรีบเดินเลี่ยงออกไปทันที","ขอเก็บไว้ก่อนแล้วค่อยนำไปแจกคนอื่น","เงียบไม่พูดอะไร"]'::jsonb, '1'::jsonb, 'ต้องปฏิเสธอย่างจริงจัง มั่นคง ชัดเจน และออกจากสถานการณ์เสี่ยงทันทีโดยไม่ต้องลังเล');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/1] รูปร่างและรูปทรงในธรรมชาติและสิ่งแวดล้อม', 'easy', 'mcq', 'ข้อใดอธิบายความแตกต่างระหว่าง "รูปร่าง" (Shape) และ "รูปทรง" (Form) ได้ถูกต้อง?', '["รูปร่างมี 2 มิติ (กว้างและยาว) ส่วนรูปทรงมี 3 มิติ (มีความหนาหรือความลึกเพิ่มขึ้น)","รูปร่างมี 3 มิติ ส่วนรูปทรงมี 2 มิติ","รูปร่างมีเฉพาะทรงกลมเท่านั้น","รูปร่างและรูปทรงเหมือนกันทุกประการ"]'::jsonb, '0'::jsonb, 'รูปร่างมี 2 มิติคือความกว้างและความยาวแบนๆ ส่วนรูปทรงมี 3 มิติคือมีมวล ปริมาตร ความหนา และความลึก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/1] รูปทรงเรขาคณิต', 'easy', 'mcq', 'กล่องของขวัญและลูกเต๋า จัดเป็นรูปทรงชนิดใด?', '["รูปทรงกระบอก","รูปทรงลูกบาศก์ (สี่เหลี่ยมลูกบาศก์)","รูปทรงกรวย","รูปทรงกลม"]'::jsonb, '1'::jsonb, 'ลูกเต๋าและกล่องทรงสี่เหลี่ยมจัตุรัส มีด้านทั้ง 6 ด้านเป็นสี่เหลี่ยม เรียกว่า รูปทรงลูกบาศก์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/2] ทัศนธาตุ: อิทธิพลของเส้น', 'medium', 'mcq', 'การวาดภาพโดยใช้ "เส้นซิกแซกหรือเส้นหยัก (Zigzag line)" ให้ความรู้สึกอย่างไรแก่ผู้ชม?', '["สงบนิ่ง ราบเรียบ","รุนแรง ตื่นเต้น เคลื่อนไหว ขัดแย้ง และน่ากลัว","นุ่มนวล อ่อนช้อย","มั่นคง แข็งแรง"]'::jsonb, '1'::jsonb, 'เส้นหยักหรือเส้นซิกแซก ให้ความรู้สึกตื่นเต้น อันตราย รุนแรง และการเคลื่อนไหวฉับพลัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/2] ทัศนธาตุ: เส้นตรงแนวนอน', 'easy', 'mcq', '"เส้นตรงแนวนอน" เช่น เส้นขอบฟ้าหรือพื้นน้ำนิ่ง ให้ความรู้สึกทางจิตวิทยาอย่างไร?', '["สงบนิ่ง ราบเรียบ กว้างขวาง และผ่อนคลาย","ตื่นเต้น หวาดเสียว","รวดเร็ว ดั่งสายฟ้า","กำลังล้มลง"]'::jsonb, '0'::jsonb, 'เส้นแนวนอนให้ความรู้สึกสงบ นิ่ง มั่นคง ราบเรียบ และกว้างใหญ่ ดั่งผืนน้ำและเส้นขอบฟ้า');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีอุ่น (Warm Tone)', 'easy', 'mcq', 'สีในกลุ่มใดจัดเป็นสีใน "วรรณะอุ่น" ทั้งหมด?', '["สีน้ำเงิน, สีฟ้า, สีเขียว","สีแดง, สีส้ม, สีเหลือง, สีม่วงแดง","สีขาว, สีดำ, สีเทา","สีเขียวแก่, สีคราม, สีม่วงน้ำเงิน"]'::jsonb, '1'::jsonb, 'วรรณะสีอุ่นให้ความรู้สึกร้อน ร่าเริง อบอุ่น ได้แก่ สีเหลือง ส้มเหลือง ส้ม แดง ม่วงแดง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีเย็น (Cool Tone)', 'easy', 'mcq', 'สีในกลุ่มใดจัดเป็นสีใน "วรรณะเย็น" ทั้งหมด?', '["สีเขียว, สีเขียวตองอ่อน, สีน้ำเงิน, สีคราม","สีแดง, สีส้ม, สีชมพู","สีทอง, สีเงิน, สีทองแดง","สีแสด, สีน้ำตาลไหม้, สีแดงเลือดหมู"]'::jsonb, '0'::jsonb, 'วรรณะสีเย็นให้ความรู้สึกสงบ สดชื่น ร่มเย็น ได้แก่ สีเขียวเหลือง เขียว น้ำเงิน ม่วงน้ำเงิน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] สีที่อยู่ได้ทั้งสองวรรณะ', 'hard', 'mcq', 'สี 2 สีใดในวงจรสี ที่สามารถอยู่ได้ทั้ง "วรรณะอุ่น" และ "วรรณะเย็น" ขึ้นอยู่กับสีที่อยู่แวดล้อม?', '["สีแดงและสีเขียว","สีเหลืองและสีม่วง","สีส้มและสีน้ำเงิน","สีดำและสีขาว"]'::jsonb, '1'::jsonb, 'สีเหลืองและสีม่วง เป็นสีคนกลางที่สามารถปรับเข้ากับวรรณะอุ่นหรือเย็นได้ตามสีข้างเคียงในภาพ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] การผสมแม่สี: สีขั้นที่ 2', 'easy', 'mcq', 'เมื่อนำแม่สี "สีแดง" ผสมกับ "สีเหลือง" ในสัดส่วนเท่ากัน จะได้สีใหม่คือสีใด?', '["สีเขียว","สีส้ม","สีม่วง","สีน้ำตาล"]'::jsonb, '1'::jsonb, 'แม่สีขั้นที่ 1 (แดง + เหลือง) ผสมกันได้ สีส้ม (สีขั้นที่ 2)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/3] แม่สีขั้นที่ 2: สีเขียว', 'easy', 'mcq', 'สีเขียวเกิดจากการผสมกันของแม่สีคู่ใด?', '["สีน้ำเงิน + สีเหลือง","สีแดง + สีน้ำเงิน","สีขาว + สีดำ","สีส้ม + สีม่วง"]'::jsonb, '0'::jsonb, 'สีน้ำเงินผสมกับสีเหลือง จะได้สีเขียว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/4] แสงและเงาในภาพวาด', 'medium', 'mcq', 'เมื่อมีแสงส่องมายังวัตถุจากทางด้านบนซ้าย เงาตกทอด (Cast shadow) ของวัตถุจะปรากฏอยู่ที่ทิศทางใด?', '["ด้านบนซ้าย","ด้านล่างขวา","ด้านบนขวา","ตรงกลางวัตถุพอดี"]'::jsonb, '1'::jsonb, 'เงาตกทอดจะทอดยาวไปในทิศทางตรงกันข้ามกับทิศทางที่แสงส่องมาเสมอ (ตรงข้ามบนซ้ายคือล่างขวา)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/4] พื้นผิว (Texture)', 'easy', 'mcq', 'สิ่งใดในธรรมชาติที่มีพื้นผิวสัมผัสแบบ "ขรุขระ"?', '["เปลือกหอยสังข์และเปลือกต้นไม้ใหญ่","ผิวผลแอปเปิล","กระจกเงา","ผิวน้ำนิ่ง"]'::jsonb, '0'::jsonb, 'เปลือกต้นไม้ใหญ่หรือเปลือกผลทุเรียน มีลักษณะพื้นผิวขรุขระอย่างชัดเจน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/5] เทคนิคการพิมพ์ภาพ (Printmaking)', 'easy', 'mcq', 'การนำก้านกล้วย ผักบุ้ง หรือใบไม้ มาจุ่มสีแล้วกดทับลงบนกระดาษ เรียกว่าเทคนิคใด?', '["การวาดเส้น","การพิมพ์ภาพจากวัสดุธรรมชาติ","การปั้นดินน้ำมัน","การแกะสลักหิน"]'::jsonb, '1'::jsonb, 'เป็นการพิมพ์ภาพจากแม่พิมพ์ธรรมชาติ เช่น ก้านกล้วย ใบไม้ เปลือกหอย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ นูนสูง และลอยตัว', 'medium', 'mcq', 'รูปปั้นอนุสาวรีย์หรือตุ๊กตาดินเผาที่สามารถเดินมองดูได้รอบทิศทาง 360 องศา จัดเป็นงานปั้นประเภทใด?', '["งานปั้นนูนต่ำ","งานปั้นนูนสูง","งานปั้นลอยตัว (Round-relief)","งานแกะสลักแบน"]'::jsonb, '2'::jsonb, 'งานปั้นลอยตัวเป็นงานประติมากรรมสามมิติแท้จริงที่สามารถมองเห็นได้ครบทุกด้านรอบทิศทาง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ', 'easy', 'mcq', 'ลวดลายพระบรมรูปบน "เหรียญกษาปณ์ (เหรียญบาท, เหรียญสิบ)" จัดเป็นงานปั้นประเภทใด?', '["งานปั้นนูนต่ำ (Bas-relief)","งานปั้นนูนสูง","งานปั้นลอยตัว","งานวาดเขียน"]'::jsonb, '0'::jsonb, 'เหรียญกษาปณ์มีลวดลายนูนขึ้นมาจากแผ่นพื้นหลังเพียงเล็กน้อย มองเห็นด้านหน้าด้านเดียว จัดเป็นงานปั้นนูนต่ำ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/7] การจัดองค์ประกอบภาพ: จุดเด่น (Center of Interest)', 'medium', 'mcq', 'การทำให้สิ่งสำคัญในภาพวาดมีความโดดเด่นสะดุดตาเป็นจุดแรกที่คนมอง เรียกว่าอะไร?', '["ความกลมกลืน","การสร้างจุดเด่นหรือจุดสนใจ","การระบายสีให้มืดที่สุด","การเว้นช่องว่าง"]'::jsonb, '1'::jsonb, 'จุดเด่นคือส่วนที่ต้องการเน้นให้ผู้ชมมองเห็นเป็นจุดแรก โดยอาจเน้นด้วยขนาด สีสัน หรือตำแหน่งในภาพ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.1 ป.4/7] ความสมดุลในงานศิลปะ (Balance)', 'medium', 'mcq', 'ภาพวาดที่มีน้ำหนัก ซ้ายและขวาเท่ากันเหมือนส่องกระจกเงา เรียกว่าความสมดุลแบบใด?', '["ความสมดุลแบบสองข้างเท่ากัน (Symmetrical Balance)","ความสมดุลแบบสองข้างไม่เท่ากัน","ความขัดแย้ง","ความกลมกลืน"]'::jsonb, '0'::jsonb, 'ความสมดุลแบบซ้ายขวาเหมือนกันทุกประการ (สมมาตร) ให้ความรู้สึกมั่นคง เป็นทางการ สงบ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/1] ศิลปะและภูมิปัญญาท้องถิ่น: ผ้ามัดหมี่', 'medium', 'mcq', '"ผ้าไหมมัดหมี่" เป็นงานหัตถกรรมทัศนศิลป์พื้นบ้านที่มีชื่อเสียงโดดเด่นของภาคใด?', '["ภาคใต้","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคตะวันออก"]'::jsonb, '2'::jsonb, 'การมัดหมี่ทอผ้าไหมลายโบราณ (เช่น ลายหมี่ขอนารี ลายนาค) เป็นเอกลักษณ์อันวิจิตรงดงามของภาคอีสาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/1] เครื่องปั้นดินเผาเกาะเกร็ด', 'medium', 'mcq', 'เครื่องปั้นดินเผาดินเผาเนื้อละเอียดแกะสลักลวดลายวิจิตรที่ "เกาะเกร็ด" จังหวัดนนทบุรี เป็นภูมิปัญญาของชาวไทยเชื้อสายใด?', '["ไทยวน","ไทยรามัญ (มอญ)","ไทยพวน","ไทยลื้อ"]'::jsonb, '1'::jsonb, 'เกาะเกร็ดมีชื่อเสียงด้านเครื่องปั้นดินเผาดินแดงแกะสลักลวดลายประณีต สืบทอดจากชาวไทยรามัญ (มอญ)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/2] จิตรกรรมฝาผนังวัดไทย', 'easy', 'mcq', 'ภาพจิตรกรรมฝาผนังภายในพระอุโบสถวัดไทย นิยมเขียนเล่าเรื่องราวเกี่ยวกับสิ่งใดเป็นส่วนใหญ่?', '["ประวัติศาสตร์สงครามโลก","พุทธประวัติและทศชาติชาดก","ภาพสัตว์ประหลาดแฟนตาซี","ภาพธรรมชาติเมืองหนาว"]'::jsonb, '1'::jsonb, 'จิตรกรรมฝาผนังวัดไทยเน้นบอกเล่าเรื่องพุทธประวัติ ชาดก และนรกสวรรค์เพื่อสอนศีลธรรมแก่พุทธศาสนิกชน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 1.2 ป.4/2] การดูแลและทำความสะอาดอุปกรณ์ศิลปะ', 'easy', 'mcq', 'หลังจากใช้ "พู่กันระบายสีน้ำ" เสร็จแล้ว ควรทำความสะอาดและเก็บรักษาอย่างไร?', '["แช่พู่กันทิ้งไว้ในแก้วน้ำข้ามคืน","ล้างขนพู่กันในน้ำสะอาดจนหมดคราบสี ลูบปลายขนให้แหลมมน แล้ววางผึ่งลมให้แห้ง","ใช้ไฟรนขนพู่กันให้แห้งเร็ว","ทิ้งถังขยะแล้วซื้อใหม่ทุกครั้ง"]'::jsonb, '1'::jsonb, 'การล้างคราบสีออกให้หมด ลูบปลายขนให้เข้าทรง แล้วผึ่งให้แห้ง ช่วยยืดอายุการใช้งานของพู่กัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/1] คุณสมบัติของเสียงดนตรี', 'easy', 'mcq', 'คุณสมบัติของเสียงในข้อใดหมายถึง "ความถี่ของเสียงที่มีระดับเสียงสูงหรือต่ำ"?', '["ระดับเสียง (Pitch)","ความดัง-เบา (Dynamic)","ความสั้น-ยาว (Duration)","สีสันของเสียง (Timbre)"]'::jsonb, '0'::jsonb, 'ระดับเสียง (Pitch) คือความสูง-ต่ำของเสียงดนตรี เกิดจากความถี่ในการสั่นสะเทือนของแหล่งกำเนิดเสียง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] สัญลักษณ์ทางดนตรี: บรรทัด 5 เส้น', 'easy', 'mcq', 'บรรทัด 5 เส้น (Staff) ที่ใช้บันทึกโน้ตดนตรีสากล ประกอบด้วยเส้นกี่เส้นและช่องกี่ช่อง?', '["4 เส้น 3 ช่อง","5 เส้น 4 ช่อง","6 เส้น 5 ช่อง","5 เส้น 5 ช่อง"]'::jsonb, '1'::jsonb, 'บรรทัด 5 เส้น มีเส้นแนวนอนขนานกัน 5 เส้น และเกิดช่องว่างระหว่างเส้น 4 ช่อง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] กุญแจประจำหลัก: กุญแจซอล (G Clef)', 'medium', 'mcq', 'หัวของ "กุญแจซอล (Treble Clef)" เริ่มต้นเขียนวนคาบอยู่บนเส้นใดของบรรทัด 5 เส้น?', '["เส้นที่ 1","เส้นที่ 2","เส้นที่ 3","เส้นที่ 4"]'::jsonb, '1'::jsonb, 'กุญแจซอลเริ่มเขียนวนที่เส้นที่ 2 นับจากล่างขึ้นบน ทำให้โน้ตที่คาบเส้นที่ 2 มีเสียงเป็นเสียง "ซอล (G)" เสมอ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/2] อัตราความยาวของตัวโน้ตสากล', 'medium', 'mcq', 'ในจังหวะ 4/4 "โน้ตตัวกลม (Whole note)" มีอัตราความยาวเท่ากับกี่จังหวะ?', '["1 จังหวะ","2 จังหวะ","3 จังหวะ","4 จังหวะ"]'::jsonb, '3'::jsonb, 'โน้ตตัวกลมมีค่ายาวที่สุดเท่ากับ 4 จังหวะ (ตัวขาว = 2 จังหวะ, ตัวดำ = 1 จังหวะ, ตัวเขบ็ต 1 ชั้น = ครึ่งจังหวะ)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องดีด', 'easy', 'mcq', 'เครื่องดนตรีไทยในข้อใดจัดเป็น "เครื่องดีด"?', '["จะเข้ และ ซึง","ซอด้วง และ ซออู้","ระนาดเอก และ ฆ้องวง","ขลุ่ยเพียงออ และ ปี่ใน"]'::jsonb, '0'::jsonb, 'จะเข้และซึงเป็นเครื่องสายที่บรรเลงโดยใช้นิ้วหรือไม้ดีดสายให้เกิดเสียง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องสี', 'easy', 'mcq', 'เครื่องดนตรีไทยที่ใช้คันชักถูกับสายให้เกิดเสียง จัดเป็นเครื่องดนตรีประเภทใด?', '["เครื่องดีด","เครื่องสี (เช่น ซอด้วง ซออู้ ซอสามสาย)","เครื่องตี","เครื่องเป่า"]'::jsonb, '1'::jsonb, 'เครื่องสีใช้คันชักที่มีหางม้าสีเสียดสีกับสาย เกิดการสั่นสะเทือนเป็นเสียงกังวาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีไทย: เครื่องตี', 'easy', 'mcq', 'เครื่องดนตรีไทยข้อใดเป็นเครื่องตีที่ทำด้วยไม้เนื้อแข็ง มีผืนระนาดแขวนบนราง?', '["ระนาดเอก","ฆ้องวงใหญ่","กลองแขก","ฉิ่ง"]'::jsonb, '0'::jsonb, 'ระนาดเอกมีลูกระนาดทำจากไม้ไผ่บงหรือไม้ชิงชันร้อยเป็นผืนแขวนไว้บนรางไม้รูปทรงคล้ายเรือสำเภา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] เครื่องดนตรีกำกับจังหวะสำคัญ', 'easy', 'mcq', 'เครื่องดนตรีไทยชิ้นใดมีหน้าที่สำคัญที่สุดในการ "กำกับจังหวะหน้าทับและจังหวะหลัก" ของวงดนตรีไทย?', '["ฉิ่ง","ขลุ่ย","ซออู้","ระนาดเอก"]'::jsonb, '0'::jsonb, 'ฉิ่งทำหน้าที่ควบคุมจังหวะช้า-เร็ว (เสียงฉิ่ง-ฉับ) ถือเป็นหัวใจในการกำกับจังหวะของวงดนตรีไทย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] ประเภทเครื่องดนตรีสากล: เครื่องสาย (Strings)', 'easy', 'mcq', 'เครื่องดนตรีสากลในข้อใดจัดเป็นเครื่องดนตรีประเภทเครื่องสายทั้งหมด?', '["ไวโอลิน, กีตาร์, เชลโล, ฮาร์ป","ทรัมเป็ต, แซกโซโฟน, ฟลูต","กลองชุด, ไซโลโฟน","เปียโน, คีย์บอร์ด"]'::jsonb, '0'::jsonb, 'ไวโอลิน กีตาร์ เชลโล ฮาร์ป มีสายขึงตึงและทำให้เกิดเสียงด้วยการดีดหรือสี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/3] เครื่องเป่าลมทองเหลือง (Brass)', 'medium', 'mcq', 'เครื่องดนตรีสากลข้อใดจัดเป็น "เครื่องเป่าลมทองเหลือง"?', '["ฟลูต (Flute)","คลาริเน็ต (Clarinet)","ทรัมเป็ต (Trumpet)","โอโบ (Oboe)"]'::jsonb, '2'::jsonb, 'ทรัมเป็ต ทรอมโบน ทูบา ทำจากโลหะทองเหลือง เป่าผ่านปากเป่ารูปถ้วย จัดเป็นกลุ่ม Brass Instruments');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/4] การขับร้องเพลงและการหายใจ', 'easy', 'mcq', 'การหายใจที่ถูกต้องสำหรับการขับร้องเพลงเพื่อให้มีพลังเสียงกังวานและร้องได้ยาว ควรใช้การหายใจแบบใด?', '["หายใจเข้าทางปากตื้นๆ ที่หน้าอก","หายใจเข้าลึกๆ โดยใช้กล้ามเนื้อกระบังลม (ท้องขยายเมื่อหายใจเข้า)","กลั้นหายใจตลอดเวลา","หายใจหอบเร็วๆ"]'::jsonb, '1'::jsonb, 'การหายใจด้วยกระบังลม (Diaphragmatic breathing) ช่วยให้กักเก็บลมได้มากและควบคุมลมหายใจออกขณะร้องเพลงได้อย่างสม่ำเสมอ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/4] การขับร้องเพลงไทย: การเอื้อน', 'medium', 'mcq', 'การเปล่งเสียงทำนองโดยไม่เปล่งเสียงพยัญชนะหรือคำร้อง ออกเป็นเสียง เออ... เอย... ในเพลงไทย เรียกว่าอะไร?', '["การเอื้อน","การแร็ป","การประสานเสียง","การหวีดเสียง"]'::jsonb, '0'::jsonb, 'การเอื้อนเสียงเป็นเอกลักษณ์เฉพาะของเพลงไทยเดิม เพื่อทอดทำนองให้ไพเราะนุ่มนวลตามเสียงดนตรี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีไทย: วงปี่พาทย์', 'medium', 'mcq', 'วงดนตรีไทยที่ประกอบด้วยเครื่องตีเป็นหลัก (ระนาดเอก ระนาดทุ้ม ฆ้องวง กลองทัด ตะโพน) และเครื่องเป่า (ปี่ใน) เรียกว่าวงอะไร?', '["วงเครื่องสาย","วงปี่พาทย์","วงมโหรี","วงสะล้อซอซึง"]'::jsonb, '1'::jsonb, 'วงปี่พาทย์เป็นวงที่เน้นเครื่องตีประเภทไม้ โลหะ หนัง ร่วมกับปี่ มีเสียงดังกังวาน นิยมบรรเลงในพิธีกรรมและโขนละคร');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีพื้นบ้านภาคอีสาน: วงโปงลาง', 'easy', 'mcq', 'เครื่องดนตรีที่ทำจากท่อนไม้เนื้อแข็งแขวนเรียงเป็นผืน ตีด้วยไม้ ให้เสียงไพเราะสนุกสนานในภาคอีสานคือข้อใด?', '["โปงลาง","แคน","พิณ","โหวต"]'::jsonb, '0'::jsonb, 'โปงลางทำจากท่อนไม้มะหาดหรือไม้หมากเหลื่อม เป็นเครื่องดนตรีเอกลักษณ์ของดนตรีพื้นบ้านอีสาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] เครื่องดนตรีพื้นบ้าน: แคน', 'easy', 'mcq', '"แคน" ทำมาจากวัสดุธรรมชาติใดเป็นหลัก?', '["ลำไม้ไผ่ (ไม้กู่แคน)","กระบอกกะลามะพร้าว","เขาสัตว์","ดินเหนียวตากแห้ง"]'::jsonb, '0'::jsonb, 'แคนทำจากไม้ซางหรือไม้กู่แคน มีลิ้นโลหะอยู่ภายใน เป่าได้ทั้งดูดลมเข้าและเป่าลมออก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/1] วงดนตรีพื้นเมืองภาคเหนือ: สะล้อ ซอ ซึง', 'medium', 'mcq', 'เครื่องดนตรีพื้นเมืองภาคเหนือชนิดใดจัดเป็น "เครื่องสี"?', '["ซึง","สะล้อ","กลองสะบัดชัย","ปี่จุม"]'::jsonb, '1'::jsonb, 'สะล้อเป็นเครื่องสี 2 สายหรือ 3 สาย กะโหลกทำด้วยกะลามะพร้าว ให้เสียงหวานซึ้งตามแบบวัฒนธรรมล้านนา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] เพลงพระราชนิพนธ์', 'easy', 'mcq', 'เพลงพระราชนิพนธ์ในรัชกาลที่ 9 ที่พระราชทานให้เป็นเพลงประจำวันขึ้นปีใหม่ คือเพลงใด?', '["เพลงสายฝน","เพลงพรปีใหม่","เพลงใกล้รุ่ง","เพลงชะตาชีวิต"]'::jsonb, '1'::jsonb, 'เพลงพระราชนิพนธ์ "พรปีใหม่" ทรงพระราชนิพนธ์ขึ้นใน พ.ศ. 2494 เพื่อพระราชทานความสุขแก่ปวงชนชาวไทยในวันปีใหม่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] มารยาทในการฟังดนตรี', 'easy', 'mcq', 'มารยาทที่ถูกต้องในการชมการแสดงดนตรีในโรงละครคือข้อใด?', '["ส่งเสียงตะโกนคุยโทรศัพท์ตลอดเวลา","ปรบมือเมื่อจบแต่ละบทเพลง และไม่ลุกเดินไปมาขณะนักดนตรีกำลังบรรเลง","นำอาหารกลิ่นแรงเข้าไปรับประทาน","ใช้นกหวีดเป่าแข่งกับดนตรี"]'::jsonb, '1'::jsonb, 'การปรบมือให้เกียรตินักแสดงเมื่อเพลงจบ และการรักษาความเงียบระหว่างการแสดง เป็นมารยาทสากลของการฟังดนตรี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.1 ป.4/1] สัญลักษณ์ไดนามิก (Dynamic): เปียโน และ ฟอร์เต', 'hard', 'mcq', 'สัญลักษณ์ตัวย่อ "p" (piano) และ "f" (forte) ในโน้ตเพลง หมายถึงระดับความดัง-เบาอย่างไรตามลำดับ?', '["ดังมาก และ เบามาก","เบา (Soft) และ ดัง (Loud)","เร็ว และ ช้า","หยุดเสียง และ เริ่มเสียง"]'::jsonb, '1'::jsonb, 'p (piano) หมายถึงให้เล่นเสียงเบา ส่วน f (forte) หมายถึงให้เล่นเสียงดัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 2.2 ป.4/2] การอนุรักษ์ดนตรีไทย', 'easy', 'mcq', 'เยาวชนไทยสามารถมีส่วนร่วมในการอนุรักษ์ดนตรีไทยได้อย่างไร?', '["ฝึกหัดเล่นเครื่องดนตรีไทยและสนับสนุนชื่นชมบทเพลงไทยเดิม","ช่วยกันเก็บเครื่องดนตรีไทยไว้ในตู้กระจกห้ามใครแตะต้อง","ยกเลิกการสอนดนตรีไทยในโรงเรียน","ดัดแปลงให้เปลี่ยนเป็นดนตรีร็อกทั้งหมด"]'::jsonb, '0'::jsonb, 'การเรียนรู้ ฝึกฝน และร่วมสืบสานการแสดงดนตรีไทยในชีวิตประจำวัน ช่วยให้มรดกทางดนตรีไทยคงอยู่สืบไป');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์: การจีบ', 'easy', 'mcq', 'การปฏิบัติท่า "จีบ" ในนาฏศิลป์ไทย ใช้นิ้วใดจรดกับนิ้วใด?', '["นิ้วชี้จรดกับนิ้วกลาง","ปลายนิ้วหัวแม่มือจรดกับข้อแรกของปลายนิ้วชี้ แล้วกรีดนิ้วที่เหลือออก","นิ้วก้อยจรดกับนิ้วโป้ง","กำนิ้วทั้ง 5 เข้าหาฝ่ามือ"]'::jsonb, '1'::jsonb, 'การจีบ ใช้นิ้วหัวแม่มือจรดข้อแรกของนิ้วชี้ นิ้วกลาง นาง ก้อย กรีดเหยียดตึงออกเป็นรูปพัด และหักข้อมือเข้าหาแขน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] จีบหงาย และ จีบคว่ำ', 'easy', 'mcq', 'การทำท่าจีบโดย "หงายฝ่ามือขึ้น ให้ปลายนิ้วชี้ชี้ขึ้นด้านบน และหักข้อมือเข้าหาลำแขน" เรียกว่าท่าใด?', '["จีบคว่ำ","จีบหงาย","จีบส่งหลัง","จีบปรกหน้า"]'::jsonb, '1'::jsonb, 'จีบหงาย คือการหงายฝ่ามือขึ้น ปลายนิ้วที่จีบชี้ขึ้นข้างบน หักข้อมือเข้าหาลำแขน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์: การตั้งวงบน', 'medium', 'mcq', 'การ "ตั้งวงบน" ของตัวพระ (ชาย) และตัวนาง (หญิง) ปลายนิ้วมือจะอยู่ในระดับใดตามลำดับ?', '["ตัวพระระดับแง่ศีรษะ, ตัวนางระดับหางคิ้ว","ตัวพระระดับอก, ตัวนางระดับปาก","ตัวพระระดับเอว, ตัวนางระดับหัวเข่า","ตัวพระระดับปลายคาง, ตัวนางระดับหน้าผาก"]'::jsonb, '0'::jsonb, 'ตัวพระตั้งวงบนปลายนิ้วอยู่ระดับแง่ศีรษะ (กันวงออกกว้าง) ส่วนตัวนางปลายนิ้วอยู่ระดับหางคิ้ว (วงแคบกว่า)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] การตั้งวงกลางและวงล่าง', 'easy', 'mcq', 'การ "ตั้งวงล่าง" ปลายนิ้วมือทั้งสี่จะทอดโค้งอยู่ระดับใดของร่างกาย?', '["ระดับสายตา","ระดับอก","ระดับหัวเข็มขัดหรือสะดือ","ระดับปลายเท้า"]'::jsonb, '2'::jsonb, 'ตั้งวงล่าง ทอดลำแขนลงข้างล่าง โค้งลำแขน ปลายนิ้วอยู่ระดับหัวเข็มขัดหรือสะดือ หักข้อมือขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/1] นาฏยศัพท์ส่วนเท้า: การก้าวหน้า', 'medium', 'mcq', 'การปฏิบัติท่า "ก้าวหน้า" เท้าที่ก้าวไปข้างหน้าต้องวางส้นเท้าและปลายเท้าอย่างไร?', '["วางปลายเท้าลงก่อน","ก้าวเท้าเฉียงไปข้างหน้า วางส้นเท้าลงก่อน ปลายเท้ายกเชิดขึ้น แล้วถ่ายน้ำหนักตัวไปเท้าหน้า","กระโดดลงด้วยเท้าคู่","ลากปลายเท้าไปข้างหลัง"]'::jsonb, '1'::jsonb, 'การก้าวหน้าในนาฏศิลป์ไทย ต้องเปิดปลายเท้า วางส้นเท้าลงก่อน ปลายเท้าเชิดขึ้น จากนั้นจึงวางเต็มฝ่าเท้าถ่ายน้ำหนัก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่าทางนาฏศิลป์: ภาษาท่าเลียนแบบอารมณ์', 'easy', 'mcq', 'การใช้มือซ้ายทาบที่บริเวณหน้าอก (ระดับหัวใจ) หมายถึงภาษาท่าสื่อความรู้สึกใด?', '["ท่ารัก หรือ ท่าดีใจ","ท่าโกรธ","ท่าร้องไห้เสียใจ","ท่ากลัว"]'::jsonb, '0'::jsonb, 'การทาบมือที่หน้าอก เป็นภาษาท่าสื่อความหมายถึง ความรัก ความปลื้มใจ หรือความจริงใจในใจ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าปฏิเสธ', 'easy', 'mcq', 'การตั้งมือข้างหนึ่งระดับอกแล้วส่ายข้อมือไปมาเล็กน้อย เป็นภาษาท่าสื่อความหมายว่าอะไร?', '["ท่าเรียกมาหา","ท่าปฏิเสธ (ไม่เอา/ไม่ใช่)","ท่ายินดีต้อนรับ","ท่าหลับนอน"]'::jsonb, '1'::jsonb, 'การตั้งมือระดับอกแล้วส่ายปลายนิ้วไปมาเบาๆ สื่อความหมายถึงการปฏิเสธ หรือคำว่า "ไม่"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าอาย', 'medium', 'mcq', 'ภาษาท่า "อาย" ในนาฏศิลป์ไทย มีลักษณะการปฏิบัติอย่างไร?', '["ใช้ฝ่ามือแตะข้างแก้มใกล้ขมับ เอียงศีรษะ หลบสายตา","กระทืบเท้าเสียงดัง","เอามือปิดตาสองข้าง","อ้าปากหัวเราะกว้าง"]'::jsonb, '0'::jsonb, 'ท่าอาย ใช้ฝ่ามือแตะข้างแก้มใกล้ขมับ เอียงศีรษะไปข้างตรงข้ามกับมือ ชายตาลงเล็กน้อยเพื่อแสดงความเขินอาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/2] ภาษาท่า: ท่าโกรธ', 'medium', 'mcq', 'การใช้ฝ่ามือถูกระทบหลังใบหูแล้วกระชากมือลง พร้อมกระทืบเท้า เป็นภาษาท่าใด?', '["ท่าโกรธ","ท่าเสียใจ","ท่ากราบไหว้","ท่ารักใคร่"]'::jsonb, '0'::jsonb, 'ใช้ฝ่ามือถูใต้ใบหูแล้วกระชากมือลง สื่อถึงอารมณ์โกรธจัดหรือแค้นเคือง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] รำวงมาตรฐาน: เพลงงามแสงเดือน', 'easy', 'mcq', 'เพลงรำวงมาตรฐานเพลงแรก "เพลงงามแสงเดือน" ใช้ท่ารำมาตรฐานท่าใด?', '["ท่าสอดสร้อยมาลา","ท่าชักแป้งผัดหน้า","ท่าแขกเต้าเข้ารัง","ท่ายั่ว"]'::jsonb, '0'::jsonb, 'เพลงงามแสงเดือนใช้ท่ารำ "สอดสร้อยมาลา"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] รำวงมาตรฐาน: เพลงชาวไทย', 'medium', 'mcq', 'เพลงรำวงมาตรฐาน "เพลงชาวไทย" ใช้ท่ารำใดในการแสดง?', '["ท่าชักแป้งผัดหน้า","ท่าสอดสร้อยมาลาแปลง","ท่าพวงมาลัย","ท่าจันทร์ทรงกลด"]'::jsonb, '0'::jsonb, 'เพลงชาวไทยใช้ท่ารำ "ชักแป้งผัดหน้า"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/3] กำเนิดรำวงมาตรฐาน', 'hard', 'mcq', 'รำวงมาตรฐานได้รับการปรับปรุงและพัฒนามาจากการละเล่นพื้นบ้านชนิดใด?', '["รำโทน","เพลงเรือ","เต้นกำรำเคียว","ลำตัด"]'::jsonb, '0'::jsonb, 'รำวงมาตรฐานพัฒนามาจาก "รำโทน" ในช่วงสงครามโลกครั้งที่ 2 โดยกรมศิลปากรปรับปรุงท่ารำและบทเพลงให้เป็นแบบแผนสากล');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง 4 ภาค: ภาคเหนือ', 'easy', 'mcq', 'การแสดงนาฏศิลป์พื้นเมืองภาคเหนือที่มีท่วงท่านุ่มนวล อ่อนช้อย อิงวัฒนธรรมล้านนา คือข้อใด?', '["ฟ้อนเล็บ, ฟ้อนเทียน","เซิ้งกระติบข้าว","ระบำรองเง็ง","เต้นกำรำเคียว"]'::jsonb, '0'::jsonb, 'ฟ้อนเล็บและฟ้อนเทียนเป็นการแสดงพื้นเมืองภาคเหนือที่ผู้แสดงสวมเล็บยาวสีทอง ร่ายรำอย่างอ่อนช้อยงดงาม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคอีสาน', 'easy', 'mcq', 'การแสดงพื้นเมืองภาคอีสานที่มีลีลากระฉับกระเฉง สนุกสนาน คล่องแคล่ว เช่น "เซิ้งกระติบข้าว" สื่อถึงวิถีชีวิตใด?', '["การเดินทางออกไปหาปลาในทะเล","การนำข้าวเหนียวใส่กระติบไปส่งให้คนในครอบครัวที่ทำนา","การรบกับข้าศึก","การขึ้นเขาเก็บใบชา"]'::jsonb, '1'::jsonb, 'เซิ้งกระติบข้าวสะท้อนวิถีชีวิตของหญิงสาวอีสานที่สะพายกระติบข้าวเหนียวไปส่งให้สามีหรือญาติที่ทำงานในท้องนา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคใต้', 'medium', 'mcq', 'การแสดงพื้นเมืองภาคใต้ที่มีการแต่งกายด้วยชุดลูกปัดหลากสี สวมเทริดบนศีรษะ ดัดนิ้วมืออ่อนช้อย คือการแสดงใด?', '["โนรา (มโนราห์)","เซิ้งสวิง","รำเถิดเทิง","ฟ้อนสาวไหม"]'::jsonb, '0'::jsonb, 'โนราเป็นการแสดงนาฏศิลป์ชั้นสูงของภาคใต้ที่ได้รับการขึ้นทะเบียนเป็นมรดกภูมิปัญญาทางวัฒนธรรมที่จับต้องไม่ได้ของยูเนสโก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.1 ป.4/4] การแสดงพื้นเมือง: ภาคกลาง', 'easy', 'mcq', 'การแสดง "เต้นกำรำเคียว" ของภาคกลาง สะท้อนถึงวิถีชีวิตอาชีพใด?', '["ชาวสวนผลไม้","ชาวนาในฤดูเกี่ยวข้าว","ชาวประมง","ช่างปั้นหม้อ"]'::jsonb, '1'::jsonb, 'เต้นกำรำเคียวเป็นการละเล่นร้องรำแก้กันระหว่างหนุ่มสาวชาวนาในฤดูกาลลงแขกเกี่ยวข้าว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/1] โขนไทยและวรรณคดี', 'medium', 'mcq', 'การแสดง "โขน" ของไทย นิยมแสดงเรื่องราวจากวรรณคดีเรื่องใดเรื่องเดียวเท่านั้น?', '["ขุนช้างขุนแผน","รามเกียรติ์","อิเหนา","พระอภัยมณี"]'::jsonb, '1'::jsonb, 'โขนเป็นการแสดงนาฏศิลป์ชั้นสูงที่สวมหน้าโขนหัวโขน บรรเลงด้วยวงปี่พาทย์ และแสดงเฉพาะเรื่อง "รามเกียรติ์"');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/1] ตัวละครในโขน: ตัวยักษ์', 'easy', 'mcq', 'ตัวละครยักษ์เอกในเรื่องรามเกียรติ์ที่มี 10 หน้า 20 มือ และมีกายสีเขียว คือตัวละครใด?', '["หนุมาน","ทศกัณฐ์","พระราม","สุครีพ"]'::jsonb, '1'::jsonb, 'ทศกัณฐ์ พญายักษ์แห่งกรุงลงกา มีกายสีเขียว 10 หน้า 20 มือ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/2] มารยาทในการชมการแสดงนาฏศิลป์', 'easy', 'mcq', 'ข้อใดเป็นข้อปฏิบัติที่ดีในการชมการแสดงรำไทยหรือโขน?', '["ลุกขึ้นเต้นเลียนแบบนักแสดงหน้าเวที","แต่งกายสุภาพ ให้เกียรติสถานที่ และปรบมือเมื่อเปิดม่านและหลังจบการแสดง","ใช้แฟลชถ่ายรูปใส่หน้านักแสดงตลอดเวลา","ส่งเสียงตะโกนคุยกับเพื่อนข้างๆ"]'::jsonb, '1'::jsonb, 'การแต่งกายสุภาพ สำรวมกิริยา และปรบมือให้กำลังใจนักแสดงหลังจบการแสดง ถือเป็นมารยาทที่ดีของผู้เข้าชม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('ศิลปะ', 'ป.4', '[ศ 3.2 ป.4/2] คุณค่าของนาฏศิลป์ไทย', 'easy', 'mcq', 'นาฏศิลป์ไทยมีคุณค่าและสะท้อนเอกลักษณ์ของชาติไทยอย่างไร?', '["เป็นเพียงการออกกำลังกายยามว่าง","สะท้อนถึงขนบธรรมเนียม ความประณีตงดงามของภาษา วรรณคดี และภูมิปัญญาไทยที่สั่งสมมาอย่างยาวนาน","ช่วยให้มีชื่อเสียงทางธุรกิจ","ทำให้ต่างชาติเกรงกลัวอำนาจ"]'::jsonb, '1'::jsonb, 'นาฏศิลป์ไทยเป็นมรดกทางวัฒนธรรมอันทรงคุณค่า ผสมผสานดนตรี วรรณคดี เครื่องแต่งกายวิจิตร และกิริยามารยาทอันงดงามของไทย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การดูแลรักษาของใช้ส่วนตัว', 'easy', 'mcq', 'สิ่งของในข้อใดเป็น "ของใช้ส่วนตัว" ที่ไม่ควรใช้ร่วมกับผู้อื่นเพื่อป้องกันโรคติดต่อ?', '["โต๊ะอาหาร","แปรงสีฟัน, ผ้าเช็ดหน้า, ผ้าเช็ดตัว","โทรทัศน์","พัดลมเพดาน"]'::jsonb, '1'::jsonb, 'แปรงสีฟัน ผ้าเช็ดตัว ผ้าเช็ดหน้า หวี เป็นของใช้ส่วนตัวที่ไม่ควรใช้ปะปนกับผู้อื่นเพราะอาจแพร่กระจายเชื้อโรค');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดกระเป๋านักเรียน', 'easy', 'mcq', 'หลักการสำคัญที่สุดในการจัดกระเป๋านักเรียนให้ถูกสุขอนามัยและไม่ปวดหลังคือข้อใด?', '["ใส่หนังสือเรียนทุกเล่มตั้งแต่ ป.1 ถึง ป.6 ลงในกระเป๋า","จัดสมุดและหนังสือตามตารางสอนในแต่ละวัน และเก็บของชิ้นหนักไว้ชิดแผ่นหลัง","ใส่ของเล่นและขนมให้เต็มกระเป๋า","ถือกระเป๋าด้วยมือข้างเดียวตลอดเวลา"]'::jsonb, '1'::jsonb, 'จัดหนังสือตามตารางเรียนทุกวันเพื่อไม่ให้กระเป๋าหนักเกินไป และวางของหนักแนบชิดหลังเพื่อรักษาสมดุลกระดูกสันหลัง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดโต๊ะเขียนหนังสือ', 'easy', 'mcq', 'การจัดวางหนังสือบนโต๊ะเขียนหนังสือควรจัดวางอย่างไรให้หยิบใช้สะดวกและเป็นระเบียบ?', '["วางกองซ้อนทับกันโดยไม่แยกประเภท","จัดเรียงหนังสือจากเล่มสูงไปเล่มต่ำ หันสันหนังสือออกด้านนอก และแยกประเภทสมุด-หนังสือ","วางหนังสือกระจัดกระจายบนเก้าอี้","คว่ำหน้าหนังสือเปิดทิ้งไว้"]'::jsonb, '1'::jsonb, 'การวางเรียงความสูงและหันสันหนังสือออกด้านนอกช่วยให้มองเห็นชื่อหนังสือและหยิบใช้งานได้สะดวก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การจัดตู้เสื้อผ้า', 'medium', 'mcq', 'เสื้อผ้าประเภทใดควร "พับเก็บ" ใส่ลิ้นชัก แทนการแขวนด้วยไม้แขวนเสื้อ?', '["เสื้อเชิ้ตและชุดนักเรียน","เสื้อยืด, กางเกงขาสั้น, ชุดชั้นใน และถุงเท้า","เสื้อสูท","กระโปรงพลีทจีบ"]'::jsonb, '1'::jsonb, 'เสื้อยืดและชุดชั้นในควรพับเก็บเพื่อประหยัดเนื้อที่ตู้ ส่วนชุดนักเรียนและเสื้อเชิ้ตที่รีดแล้วควรแขวนเพื่อไม่ให้ยับ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกวาดบ้านและถูบ้าน', 'easy', 'mcq', 'ขั้นตอนการกวาดบ้านที่ถูกต้องตามหลักสุขาภิบาลควรเริ่มจากบริเวณใดก่อน?', '["กวาดจากชั้นล่างขึ้นชั้นบน","กวาดจากที่สูงลงที่ต่ำ (เช่น ปัดฝุ่นบนตู้ เพดาน แล้วจึงกวาดพื้น) และกวาดจากมุมห้องออกสู่ประตู","กวาดกระจายไปทั่วทุกทิศทางพร้อมกัน","ถูพื้นก่อนแล้วจึงค่อยกวาดขยะ"]'::jsonb, '1'::jsonb, 'ต้องปัดฝุ่นจากที่สูงลงสู่พื้นก่อน จากนั้นกวาดจากซอกมุมห้องมารวมกันตรงกลางหรือหน้าประตูเพื่อตักใส่ที่โกยขยะ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ไม้กวาดชนิดต่างๆ: ไม้กวาดดอกหญ้า', 'easy', 'mcq', '"ไม้กวาดดอกหญ้า" เหมาะสำหรับใช้กวาดพื้นผิวประเภทใด?', '["พื้นซีเมนต์หยาบนอกบ้านที่มีน้ำขัง","พื้นไม้, พื้นกระเบื้อง, พื้นหินขัดที่แห้งและเรียบภายในบ้าน","พื้นสนามหญ้าที่มีใบไม้ร่วง","พื้นดินเลน"]'::jsonb, '1'::jsonb, 'ไม้กวาดดอกหญ้ามีขนอ่อนนุ่ม เหมาะสำหรับกวาดฝุ่นละอองบนพื้นแห้งและเรียบภายในบ้าน ห้ามนำไปกวาดพื้นเปียกน้ำ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ไม้กวาดทางมะพร้าว', 'easy', 'mcq', 'หากต้องการกวาดใบไม้แห้งในสนามหญ้าหรือกวาดน้ำขังบนพื้นซีเมนต์ ควรเลือกใช้ไม้กวาดชนิดใด?', '["ไม้กวาดดอกหญ้า","ไม้กวาดทางมะพร้าว","ไม้กวาดขนไก่","ไม้ปัดหยากไย่"]'::jsonb, '1'::jsonb, 'ไม้กวาดทางมะพร้าวมีความแข็งและทนทาน เหมาะสำหรับกวาดพื้นซีเมนต์หยาบ พื้นดิน สนามหญ้า และพื้นเปียกน้ำ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การล้างจานชาม', 'easy', 'mcq', 'ก่อนนำจานชามไปล้างด้วยน้ำยาล้างจาน ขั้นตอนแรกที่ต้องทำคือข้อใด?', '["แช่น้ำร้อนทันที","กวาดเศษอาหารทิ้งลงในถังขยะ และล้างคราบสกปรกหยาบด้วยน้ำสะอาด 1 ครั้ง","ใช้น้ำยาล้างจานเทราดลงไปขณะมีเศษอาหาร","นำไปผึ่งแดดก่อน"]'::jsonb, '1'::jsonb, 'ต้องแยกกวาดเศษอาหารออกให้หมดก่อน แล้วล้างน้ำเปล่ารอบหนึ่ง จะช่วยให้ล้างคราบมันได้ง่ายขึ้นและท่อไม่อุดตัน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซักรองเท้าผ้าใบนักเรียน', 'medium', 'mcq', 'การตากรองเท้าผ้าใบสีขาวหลังจากซักเสร็จ ควรปฏิบัติตามข้อใดเพื่อป้องกันรองเท้าเกิดคราบเหลือง?', '["ตากแดดจัดโดยไม่ต้องหุ้มอะไร","นำกระดาษทิชชูสีขาวมาพันหุ้มให้ทั่วรองเท้าก่อนนำไปตากแดด","อบในเตาไมโครเวฟ","แช่น้ำยาฟอกขาวทิ้งไว้ข้ามคืน"]'::jsonb, '1'::jsonb, 'การใช้กระดาษทิชชูสีขาวพันหุ้มรองเท้าผ้าใบ กระดาษทิชชูจะช่วยดูดซับคราบด่างของผงซักฟอก ป้องกันการเกิดคราบเหลือง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] สัญลักษณ์การดูแลรักษาเสื้อผ้า', 'hard', 'mcq', 'สัญลักษณ์รูป "เตารีดที่มีจุด 1 จุด (•)" บนป้ายฉลากเสื้อผ้า หมายความว่าอย่างไร?', '["ห้ามรีดเด็ดขาด","รีดด้วยอุณหภูมิต่ำ (ความร้อนต่ำ)","รีดด้วยอุณหภูมิปานกลาง","รีดด้วยอุณหภูมิสูงสุด"]'::jsonb, '1'::jsonb, 'จุด 1 จุด หมายถึง อุณหภูมิต่ำ (สำหรับผ้าใยสังเคราะห์ ไนลอน), 2 จุด = ปานกลาง (ผ้าขนสัตว์ ผ้าไหม), 3 จุด = สูง (ผ้าฝ้าย ลินิน)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การจัดห้องนอน', 'easy', 'mcq', 'หลังจากตื่นนอนในตอนเช้า สิ่งที่นักเรียนควรทำทันทีคือข้อใด?', '["วิ่งไปเปิดโทรทัศน์","พับผ้าห่ม จัดหมอนและดึงผ้าปูที่นอนให้ตึงเรียบร้อย","กระโดดลงจากเตียงแล้วออกจากบ้านทันที","โยนหมอนลงบนพื้น"]'::jsonb, '1'::jsonb, 'การเก็บที่นอน พับผ้าห่ม และจัดหมอนให้เรียบร้อยหลังตื่นนอน เป็นการสร้างวินัยและความเป็นระเบียบของตนเอง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การทำความสะอาดตู้เย็น', 'medium', 'mcq', 'ข้อใดเป็นการดูแลรักษาตู้เย็นที่ถูกต้องและประหยัดพลังงาน?', '["นำอาหารที่ยังร้อนจัดใส่ตู้เย็นทันที","เปิดประตูตู้เย็นทิ้งไว้เพื่อระบายความร้อน","ตรวจสอบอาหารหมดอายุทิ้งสม่ำเสมอ และละลายน้ำแข็งในช่องแช่แข็งเมื่อหนาเกินกำหนด","ตั้งตู้เย็นติดชิดผนังห้องโดยไม่เว้นช่องว่าง"]'::jsonb, '2'::jsonb, 'การละลายน้ำแข็งสม่ำเสมอและไม่ตั้งตู้เย็นชิดผนังเกินไปช่วยให้คอมเพรสเซอร์ระบายความร้อนได้ดีและประหยัดไฟ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การตากผ้า', 'easy', 'mcq', 'ก่อนนำเสื้อผ้าไปตากแดด ควรทำสิ่งใดเพื่อให้ผ้ายับน้อยลงและสีไม่ซีดจาง?', '["กลับเอาด้านในออกด้านนอก แล้วสะบัดผ้าก่อนพาดบนไม้แขวนเสื้อ","ขยำผ้าให้เป็นก้อนกลม","ตากในที่มืดสนิท","นำผ้าไปแช่น้ำมัน"]'::jsonb, '0'::jsonb, 'การกลับด้านในออกด้านนอกช่วยป้องกันแดดเลียสีผ้าให้ซีดจาง และการสะบัดผ้าช่วยคลายรอยยับทำให้รีดง่าย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกำจัดกลิ่นอับในตู้เสื้อผ้า', 'medium', 'mcq', 'วัสดุธรรมชาติในข้อใดสามารถนำมาใส่ในตู้เสื้อผ้าเพื่อช่วยดูดซับกลิ่นอับชื้นได้ดี?', '["ถ่านหุงต้มหรือผงเบกกิ้งโซดา","เศษดินทราย","ใบไม้สดเปียกน้ำ","น้ำส้มคั้น"]'::jsonb, '0'::jsonb, 'ถ่านไม้มีรูพรุนขนาดเล็กจำนวนมาก ช่วยดูดซับกลิ่นอับชื้นและความชื้นในตู้เสื้อผ้าได้อย่างปลอดภัย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การล้างห้องน้ำอย่างปลอดภัย', 'medium', 'mcq', 'ในการใช้น้ำยาล้างห้องน้ำที่มีฤทธิ์เป็นกรด ควรสวมใส่อุปกรณ์ป้องกันใดเพื่อความปลอดภัย?', '["ถุงมือยาง, รองเท้าบูทยาง และหน้ากากอนามัย","ถุงมือผ้าบางๆ","แว่นตากันแดด","ชุดนอน"]'::jsonb, '0'::jsonb, 'กรดในน้ำยาล้างห้องน้ำกัดกร่อนผิวหนังและไอระเหยเป็นอันตรายต่อระบบทางเดินหายใจ จึงต้องสวมถุงมือและรองเท้ายาง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การดูแลรักษากล่องดินสอ', 'easy', 'mcq', 'เพื่อป้องกันไม่ให้กระเป๋าหรือกล่องดินสอเปรอะเปื้อนคราบหมึก ควรทำอย่างไร?', '["เปิดปลอกปากกาทิ้งไว้เสมอ","ปิดฝาปลอกปากกาและสวมปลอกดินสอให้เรียบร้อยทุกครั้งหลังใช้งาน","เหลาดินสอจนแหลมทิ่มทะลุกล่อง","ทิ้งไส้ดินสอกดไว้ในกล่อง"]'::jsonb, '1'::jsonb, 'การสวมปลอกดินสอและปิดปลอกปากกาช่วยป้องกันไส้ดินสอหักและป้องกันน้ำหมึกเลอะสิ่งของ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การประหยัดน้ำในงานบ้าน', 'easy', 'mcq', 'น้ำสุดท้ายจากการล้างจานหรือซักผ้า สามารถนำไปใช้ประโยชน์ต่อได้อย่างไร?', '["เททิ้งลงบนถนน","นำไปรดน้ำต้นไม้หรือล้างพื้นบริเวณรอบบ้าน","นำมาใช้ดื่ม","นำมาใช้ทำอาหาร"]'::jsonb, '1'::jsonb, 'น้ำซักล้างที่ไม่ปนเปื้อนสารเคมีอันตรายสามารถนำมารดน้ำต้นไม้หรือล้างลานซีเมนต์เพื่อประหยัดน้ำได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การแยกขยะในบ้าน', 'easy', 'mcq', 'เปลือกผลไม้และเศษอาหารจากห้องครัวควรคัดแยกไว้ในถังขยะประเภทใดเพื่อนำไปทำปุ๋ยหมัก?', '["ขยะเปียกหรือขยะอินทรีย์","ขยะรีไซเคิล","ขยะอันตราย","ขยะติดเชื้อ"]'::jsonb, '0'::jsonb, 'ขยะเปียกหรือขยะอินทรีย์ย่อยสลายได้ง่าย เหมาะสำหรับนำไปทำปุ๋ยหมักบำรุงดิน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ไม้ดอกและไม้ประดับ', 'easy', 'mcq', 'ข้อใดเป็น "ไม้ดอก" (พืชที่ปลูกเพื่อชื่นชมความสวยงามของดอก)?', '["ดาวเรือง, กุหลาบ, มะลิ, กล้วยไม้","พลูด่าง, สาวน้อยปะแป้ง, ลิ้นมังกร","ผักบุ้ง, คะน้า","ต้นยางพารา, ต้นปาล์ม"]'::jsonb, '0'::jsonb, 'ดาวเรือง กุหลาบ มะลิ มีดอกสวยงามมีกลิ่นหอม จัดเป็นไม้ดอก ส่วนพลูด่าง ลิ้นมังกร เน้นใบสวยงามจัดเป็นไม้ประดับ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ไม้ประดับ (Foliage plants)', 'easy', 'mcq', 'พืชในข้อใดจัดเป็น "ไม้ประดับ" ที่นิยมปลูกเพื่อชมความสวยงามของใบและลำต้น?', '["ดอกบัว","พลูด่าง และ เฟิร์นข้าหลวง","ดอกชบา","มะลิซ้อน"]'::jsonb, '1'::jsonb, 'พลูด่างและเฟิร์นข้าหลวงมีใบและทรงพุ่มที่สวยงาม จึงนิยมปลูกประดับตกแต่งอาคารสถานที่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: ช้อนปลูก', 'easy', 'mcq', '"ช้อนปลูก" มีหน้าที่ในการใช้งานตรงกับข้อใด?', '["ตัดแต่งกิ่งไม้ขนาดใหญ่","ใช้ขุดหลุมปลูก ย้ายต้นกล้า และตักดินใส่กระถาง","รดน้ำต้นกล้าขนาดเล็ก","ดายหญ้าในแปลงกว้าง"]'::jsonb, '1'::jsonb, 'ช้อนปลูกมีใบมีดโค้งมน ใช้ขุดย้ายต้นกล้าและคลุกเคล้าดินปลูกในแปลงหรือกระถางขนาดเล็ก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: ส้อมพรวน', 'easy', 'mcq', '"ส้อมพรวน" ใช้สำหรับทำงานเกษตรในด้านใด?', '["พรวนดินรอบโคนต้นพืชให้ร่วนซุย","ตัดกิ่งไม้ที่แห้งตาย","ตักน้ำรดต้นไม้","ขุดบ่อปลาขนาดใหญ่"]'::jsonb, '0'::jsonb, 'ส้อมพรวนมีซี่เหล็ก 3 ซี่ ใช้สำหรับพรวนดินรอบๆ โคนต้นพืชให้ดินโปร่ง ร่วนซุย ระบายน้ำและอากาศได้ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: บัวรดน้ำ', 'easy', 'mcq', 'เครื่องมือใดเหมาะที่สุดสำหรับรดน้ำ "ต้นกล้าอ่อน" เพื่อไม่ให้ลำต้นหักโค่นและดินกระจาย?', '["สายยางฉีดน้ำแรงดันสูง","บัวรดน้ำที่มีฝักบัวกระจายน้ำเป็นฝอยนุ่มนวล","ขันตักน้ำสาด","เครื่องสูบน้ำ"]'::jsonb, '1'::jsonb, 'บัวรดน้ำกระจายสายน้ำเป็นเม็ดฝอยละเอียด ช่วยให้ต้นกล้าอ่อนไม่ช้ำและดินไม่กระเด็น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] เครื่องมือเกษตร: กรรไกรตัดกิ่ง', 'easy', 'mcq', 'เมื่อต้องการตัดแต่งกิ่งไม้ที่มีขนาดเล็กหรือตัดดอกไม้แห้งทิ้ง ควรเลือกใช้เครื่องมือใด?', '["มีดดายหญ้า","กรรไกรตัดกิ่ง","ขวาน","เลื่อยลันดา"]'::jsonb, '1'::jsonb, 'กรรไกรตัดกิ่งมีสปริงช่วยผ่อนแรง ใช้สำหรับตัดแต่งกิ่งไม้ที่มีเส้นผ่านศูนย์กลางไม่เกิน 1 นิ้ว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การดูแลรักษาเครื่องมือเกษตรที่มีคม', 'medium', 'mcq', 'หลังใช้งานจอบ เสียม และช้อนปลูกเสร็จแล้ว ควรทำความสะอาดและบำรุงรักษาอย่างไรก่อนจัดเก็บ?', '["ล้างคราบดินออก เช็ดให้แห้ง ทาน้ำมันกันสนิม และแขวนเก็บเข้าที่","วางทิ้งไว้บนพื้นดินกลางแจ้ง","แช่น้ำไว้ในถัง","ล้างด้วยน้ำยาล้างห้องน้ำ"]'::jsonb, '0'::jsonb, 'ต้องล้างดินออก เช็ดให้แห้งสนิท ชโลมน้ำมันหล่อลื่นกันสนิม เพื่อยืดอายุการใช้งานและป้องกันอุบัติเหตุ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเตรียมดินปลูกต้นไม้ในกระถาง', 'medium', 'mcq', 'ก่อนใส่ดินลงในกระถางปลูก ควรใช้วัสดุใดรองก้นกระถางเพื่อป้องกันดินไหลออกและช่วยระบายน้ำ?', '["เศษกระเบื้องแตกหรือกาบมะพร้าวสับ","ถุงพลาสติกทึบ","แผ่นเหล็ก","กระดาษหนังสือพิมพ์"]'::jsonb, '0'::jsonb, 'เศษกระถางแตกหรือกาบมะพร้าวสับช่วยปิดรูก้นกระถางไม่ให้ดินร่วง แต่ยอมให้น้ำส่วนเกินระบายออกได้ดี');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ดินที่เหมาะแก่การปลูกพืช', 'easy', 'mcq', 'ดินชนิดใดมีความเหมาะสมที่สุดสำหรับการปลูกไม้ดอกไม้ประดับทั่วไป?', '["ดินร่วนที่มีอินทรียวัตถุ (ซากพืชซากสัตว์) ผสม","ดินทรายล้วนๆ","ดินเหนียวจัดแข็งตัว","ดินลูกรัง"]'::jsonb, '0'::jsonb, 'ดินร่วนมีความโปร่ง อุ้มน้ำและระบายน้ำได้พอเหมาะ และมีธาตุอาหารสมบูรณ์ที่สุดสำหรับพืช');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การรดน้ำต้นไม้', 'easy', 'mcq', 'ช่วงเวลาใดเหมาะสมที่สุดสำหรับการรดน้ำต้นไม้ในแต่ละวัน?', '["เวลากลางคืนดึกสงัด","เวลาเช้าตรู่ (06.00-08.00 น.) และเวลาบ่ายแก่ๆ (16.00-17.00 น.)","เวลาเที่ยงวันแดดจัด","รดน้ำทุกๆ 1 ชั่วโมง"]'::jsonb, '1'::jsonb, 'ควรรดน้ำตอนเช้าและตอนเย็น แดดไม่แรง ทำให้น้ำไม่ระเหยเร็วและใบพืชไม่ไหม้เหี่ยวเฉา');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การใส่ปุ๋ยบำรุงต้นไม้', 'medium', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการใส่ปุ๋ยให้แก่ต้นไม้คือข้อใด?', '["ไม่ควรโรยปุ๋ยชิดโคนต้นไม้โดยตรง เพราะจะทำให้โคนต้นไหม้และตายได้","ต้องใส่ปุ๋ยวันละ 3 เวลา","ห้ามรดน้ำตามหลังใส่ปุ๋ย","ต้องใส่ปุ๋ยเฉพาะตอนกลางคืน"]'::jsonb, '0'::jsonb, 'ควรโรยปุ๋ยรอบๆ ชายพุ่มของต้นไม้ ไม่ควรใส่ชิดโคนต้นโดยตรงเพราะความเข้มข้นของปุ๋ยอาจทำให้รากและโคนเน่าไหม้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การกำจัดวัชพืช', 'easy', 'mcq', '"วัชพืช" หมายถึงอะไร และส่งผลเสียต่อพืชที่เราปลูกอย่างไร?', '["แมลงที่มากินใบพืช","พืชที่เราไม่ต้องการ (เช่น หญ้า) ที่แย่งน้ำ แสงแดด และธาตุอาหารจากต้นไม้หลัก","ปุ๋ยชนิดหนึ่ง","เชื้อราในดิน"]'::jsonb, '1'::jsonb, 'วัชพืชคือพืชที่ขึ้นเองโดยไม่ได้เพาะปลูก เช่น หญ้าแห้วหมู หญ้าคา คอยแย่งน้ำและอาหารของพืชปลูก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การขยายพันธุ์พืช: การปักชำ', 'medium', 'mcq', 'พืชในข้อใดสามารถขยายพันธุ์ได้ง่ายด้วยวิธี "การตัดกิ่งปักชำ"?', '["ต้นคุณนายตื่นสาย, ต้นพลูด่าง, ชบา","ต้นมะพร้าว","ต้นข้าวโพด","ต้นทุเรียน"]'::jsonb, '0'::jsonb, 'คุณนายตื่นสาย พลูด่าง ชบา สามารถตัดกิ่งสมบูรณ์มาปักลงในดินร่วนหรือแช่น้ำแล้วออกรากใหม่ได้ง่าย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ปุ๋ยอินทรีย์', 'easy', 'mcq', 'ปุ๋ยชนิดใดจัดเป็น "ปุ๋ยคอก"?', '["ปุ๋ยเคมีสูตร 15-15-15","มูลสัตว์ต่างๆ เช่น ขี้วัว ขี้ไก่ ขี้ค้างคาว","เศษใบไม้หมัก","ปุ๋ยยูเรียเม็ดสีขาว"]'::jsonb, '1'::jsonb, 'ปุ๋ยคอกได้จากมูลสัตว์ต่างๆ เช่น มูลวัว มูลไก่ มูลสุกร ช่วยปรับปรุงโครงสร้างดินให้ร่วนซุย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ประโยชน์ของไม้ดอกไม้ประดับ', 'easy', 'mcq', 'ข้อใดเป็นประโยชน์ของไม้ดอกไม้ประดับต่อสุขภาพจิตของมนุษย์?', '["ช่วยให้สถานที่ดูสดชื่น สวยงาม สบายตา และผ่อนคลายความตึงเครียด","ทำให้บ้านมีราคาแพงขึ้นพันเท่า","ช่วยป้องกันน้ำท่วมโลก","ทำให้ไม่ต้องทำความสะอาดบ้าน"]'::jsonb, '0'::jsonb, 'สีสันและความเขียวขจีของต้นไม้ช่วยฟอกอากาศ สร้างความร่มรื่น และช่วยให้จิตใจผ่อนคลาย');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การพรวนดิน', 'easy', 'mcq', 'เหตุใดเราจึงต้อง "พรวนดิน" รอบโคนต้นพืชอย่างสม่ำเสมอ?', '["เพื่อให้ดินร่วนซุย อากาศและน้ำซึมผ่านไปยังรากพืชได้สะดวก","เพื่อตัดรากพืชทิ้งทั้งหมด","เพื่อทำให้ดินแข็งตัวดั่งหิน","เพื่อเปลี่ยนสีของดิน"]'::jsonb, '0'::jsonb, 'การพรวนดินช่วยทำลายหน้าดินที่แน่นทึบ ทำให้ออกซิเจนและน้ำซึมลงสู่รากพืชได้ง่ายขึ้น');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] น้ำหมักชีวภาพ (EM)', 'medium', 'mcq', 'น้ำหมักชีวภาพทำมาจากสิ่งใด และมีประโยชน์อย่างไร?', '["ทำจากเศษพืช ผัก ผลไม้ หมักร่วมกับกากน้ำตาล ช่วยย่อยสลายอินทรียวัตถุและบำรุงดินอย่างปลอดภัย","ทำจากสารเคมีสังเคราะห์เข้มข้น","ทำจากน้ำมันเบนซิน","ทำจากผงซักฟอก"]'::jsonb, '0'::jsonb, 'น้ำหมักชีวภาพเกิดจากการหมักเศษพืชผักกับกากน้ำตาล มีจุลินทรีย์ที่มีประโยชน์ช่วยปรับปรุงดินและขับไล่แมลงศัตรูพืช');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การเก็บเกี่ยวผลผลิตดอกไม้', 'easy', 'mcq', 'การตัดดอกไม้เพื่อนำไปปักแจกัน ควรตัดในลักษณะใดเพื่อให้ดูดน้ำได้ดีและอยู่ได้นาน?', '["ตัดกิ่งในแนวเฉียง 45 องศาในน้ำสะอาด","หักกิ่งด้วยมือแรงๆ","ทุบก้านดอกให้แหลกละเอียด","ใช้ไฟลนปลายก้านดอก"]'::jsonb, '0'::jsonb, 'การตัดก้านดอกในแนวเฉียงช่วยเพิ่มพื้นที่ผิวในการดูดน้ำของท่อลำเลียง และตัดในน้ำเพื่อป้องกันฟองอากาศอุดตันท่อ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่างพื้นฐาน: ค้อนหงอน', 'easy', 'mcq', '"ค้อนหงอน" มีประโยชน์หลักตรงกับข้อใด?', '["ใช้ตัดแผ่นไม้","ใช้ตอกตะปูและใช้หงอนค้อนสำหรับถอนตะปู","ใช้ขันนอตหัวแฉก","ใช้วัดความยาว"]'::jsonb, '1'::jsonb, 'ด้านหน้าของค้อนหงอนใช้สำหรับตอกตะปู ส่วนด้านหลังที่เป็นง่ามงอโค้ง (หงอน) ใช้สำหรับถอนตะปู');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่าง: ไขควงปากแบนและปากแฉก', 'easy', 'mcq', 'เครื่องมือใดใช้สำหรับขันหรือคลายสกรูที่มีรอยผ่าบนหัวสกรูเป็นรูปเครื่องหมายบวก (+)?', '["ไขควงปากแบน","ไขควงปากแฉก (Phillips screwdriver)","คีมปากจิ้งจก","ประแจเลื่อน"]'::jsonb, '1'::jsonb, 'ไขควงปากแฉกมีปลายแฉก 4 แฉก ใช้สำหรับขันหรือคลายสกรูหัวแฉก (+)');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือช่าง: คีมรวม (คีมปากจิ้งจก)', 'medium', 'mcq', '"คีมปากจิ้งจก" นิยมใช้ในงานช่างลักษณะใด?', '["ใช้จับ ยึด ดัด บิด และตัดเส้นลวดขนาดเล็ก","ใช้ทุบทำลายกำแพงปูน","ใช้ไถปรับหน้าไม้","ใช้วัดระดับน้ำ"]'::jsonb, '0'::jsonb, 'คีมปากจิ้งจกเป็นคีมอเนกประสงค์ ใช้คีบจับชิ้นงาน ดัดสายไฟ และมีรอยตัดสำหรับตัดลวดขนาดเล็ก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] เครื่องมือวัด: ตลับเมตร', 'easy', 'mcq', 'เมื่อต้องการวัดความยาวของโต๊ะเรียนหรือความกว้างของห้องเรียน ควรเลือกใช้เครื่องมือวัดใด?', '["ไม้บรรทัดพลาสติกสั้น 15 ซม.","ตลับเมตร (Tape measure)","วงเวียน","สายวัดรอบเอว"]'::jsonb, '1'::jsonb, 'ตลับเมตรมีความยาว 3-5 เมตรขึ้นไป แถบวัดทำจากเหล็กสปริงม้วนเก็บได้ เหมาะสำหรับวัดงานก่อสร้างและชิ้นงานขนาดใหญ่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซ่อมแซมสันหนังสือที่ชำรุด', 'easy', 'mcq', 'หากพบว่าปกสมุดหรือสันหนังสือเรียนฉีกขาด ควรซ่อมแซมด้วยวัสดุอุปกรณ์ใด?', '["ใช้เชือกฟางมัดรอบเล่ม","ใช้เทปกาวใสหรือเทปผ้าติดสัน และกรรไกรตัดแต่งให้เรียบร้อย","ใช้ตะปูตอกตรึง","ใช้กาวตราช้างหยอดจนเปียกโชก"]'::jsonb, '1'::jsonb, 'การใช้เทปกาวใสหรือเทปแลคซีนติดยึดสันหนังสือที่ขาดช่วยให้หนังสือกลับมาแข็งแรงและเปิดอ่านได้ตามเดิม');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] การซ่อมแซมขาเก้าอี้ไม้ที่โยกคลอน', 'medium', 'mcq', 'เมื่อขาโต๊ะหรือเก้าอี้ไม้ที่บ้านมีสกรูหลวมจนโยกคลอน ควรทำอย่างไรเป็นอันดับแรก?', '["ใช้ค้อนทุบขาเก้าอี้ทิ้ง","ใช้ไขควงที่ขนาดพอดีกับหัวสกรู ขันให้แน่นเข้าที่เดิม","นำเทปกาวกระดาษมาพันรอบขาเก้าอี้","ทิ้งเก้าอี้แล้วซื้อใหม่ทันที"]'::jsonb, '1'::jsonb, 'การใช้ไขควงขันสกรูที่คลายตัวให้แน่นขึ้นเป็นทักษะงานช่างพื้นฐานที่ช่วยยืดอายุการใช้งานเฟอร์นิเจอร์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากวัสดุเหลือใช้', 'easy', 'mcq', 'การนำ "ขวดน้ำพลาสติกที่ไม่ใช้แล้ว" มาตัดทำเป็นกระถางต้นไม้แขวน จัดเป็นกิจกรรมที่ตรงกับข้อใด?', '["การทำลายทรัพยากร","การประดิษฐ์ของใช้จากวัสดุเหลือใช้ (Upcycling / Reuse)","การสร้างมลพิษ","การสิ้นเปลืองเวลา"]'::jsonb, '1'::jsonb, 'การนำขวดพลาสติกเหลือใช้มาประดิษฐ์เป็นกระถางต้นไม้ ช่วยลดปริมาณขยะ ประหยัดค่าใช้จ่าย และส่งเสริมความคิดสร้างสรรค์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากวัสดุธรรมชาติ: ใบตอง', 'easy', 'mcq', 'งานประดิษฐ์ใบตองในข้อใดนิยมใช้ในวันลอยกระทง?', '["กระทงลอยจากหยวกกล้วยและกลีบใบตอง","พานพุ่ม","บายศรีสู่ขวัญ","มาลัยคล้องคอ"]'::jsonb, '0'::jsonb, 'กระทงใบตองใช้วัสดุธรรมชาติย่อยสลายได้ง่าย เช่น หยวกกล้วยและใบตองพับเป็นกลีบผกาหรือกลีบกุหลาบ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] งานประดิษฐ์จากกะลามะพร้าว', 'medium', 'mcq', 'ผลิตภัณฑ์ของใช้ในข้อใดที่นิยมนำ "กะลามะพร้าวขัดมัน" มาประดิษฐ์?', '["กระบวยตักน้ำ, โคมไฟ, กระปุกออมสิน","เสื้อกันฝน","รองเท้าผ้าใบ","กระจกมองหลัง"]'::jsonb, '0'::jsonb, 'กะลามะพร้าวมีความแข็ง เหนียว ทนทาน เมื่อขูดขัดผิวให้เรียบมันจะสวยงาม นิยมทำกระบวยตักน้ำ ถ้วย และโคมไฟ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] กาวชนิดต่างๆ: กาวลาเท็กซ์', 'easy', 'mcq', '"กาวลาเท็กซ์ (กาวสีขาว)" เหมาะสำหรับใช้ติดวัสดุประเภทใดในงานประดิษฐ์?', '["กระดาษ, ผ้า, และไม้","แผ่นเหล็กหนา","แผ่นกระจกเงา","ท่อน้ำพีวีซี"]'::jsonb, '0'::jsonb, 'กาวลาเท็กซ์เป็นกาวน้ำสูตรน้ำ เหมาะสำหรับติดวัสดุที่มีรูพรุน เช่น กระดาษ ไม้ ผ้า และติดแน่นเมื่อแห้ง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] ปืนกาวร้อน (Hot Glue Gun)', 'medium', 'mcq', 'ข้อควรระวังสำคัญที่สุดในการใช้ "ปืนกาวร้อน" ในการทำงานประดิษฐ์คือข้อใด?', '["ห้ามสัมผัสปลายโลหะและกาวร้อนที่ไหลออกมาเพราะอาจทำให้ผิวหนังพุพองไหม้ได้","ห้ามเสียบปลั๊กไฟ","ห้ามใช้กับริบบิ้นผ้า","ห้ามวางบนแท่นวาง"]'::jsonb, '0'::jsonb, 'ปลายปืนกาวและแท่งกาวที่ละลายมีความร้อนสูงมาก หากสัมผัสจะทำให้เกิดแผลไหม้พุพองได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/2] ขั้นตอนการทำงานประดิษฐ์', 'medium', 'mcq', 'ขั้นตอนแรกสุดในกระบวนการทำงานประดิษฐ์ของใช้คือข้อใด?', '["ลงมือตัดวัสดุทันที","การกำหนดปัญหา ความต้องการ และวางแผนออกแบบร่างแบบชิ้นงาน","การประเมินราคาขาย","การนำไปจัดแสดง"]'::jsonb, '1'::jsonb, 'ต้องเริ่มจากการคิดวิเคราะห์ความต้องการ ออกแบบร่างแบบ (Sketch) และวางแผนเตรียมวัสดุก่อนลงมือทำจริง');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความปลอดภัยในการใช้เครื่องมือช่าง', 'easy', 'mcq', 'การส่งมีดคัตเตอร์หรือกรรไกรให้เพื่อนอย่างปลอดภัย ควรส่งอย่างไร?', '["หันปลายแหลมคมไปทางเพื่อน","โยนข้ามโต๊ะไปให้เพื่อน","หันด้านด้ามจับไปให้เพื่อนรับ และเก็บใบมีดเข้าฝักให้สนิทก่อนส่ง","ถือวิ่งไปส่งอย่างรวดเร็ว"]'::jsonb, '2'::jsonb, 'ต้องเก็บคมมีดเข้าฝัก และหันด้านด้ามจับไปให้เพื่อนเสมอ เพื่อป้องกันของมีคมบาดมือ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความปลอดภัยจากเครื่องใช้ไฟฟ้า', 'easy', 'mcq', 'พฤติกรรมในข้อใดเสี่ยงต่อการถูก "กระแสไฟฟ้าดูด" เสียชีวิต?', '["ใช้ผ้าแห้งเช็ดปลั๊กไฟ","ใช้มือที่เปียกน้ำจับเต้าเสียบหรือกดสวิตช์ไฟ","ดึงที่ตัวปลั๊กเมื่อต้องการถอดสายไฟ","ปิดสวิตช์ก่อนถอดปลั๊ก"]'::jsonb, '1'::jsonb, 'น้ำเป็นตัวนำไฟฟ้าที่ดีมาก การใช้มือเปียกสัมผัสอุปกรณ์ไฟฟ้าอาจทำให้กระแสไฟฟ้ารั่วไหลเข้าสู่ร่างกายได้ทันที');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การจัดเก็บเครื่องมือช่าง', 'easy', 'mcq', 'หลังจากใช้งานเครื่องมือช่างเสร็จแล้ว ควรจัดเก็บอย่างไรจึงจะถูกต้องและปลอดภัย?', '["วางเกลื่อนกลาดไว้บนพื้นทางเดิน","ทำความสะอาด เช็ดน้ำมันกันสนิม และจัดเก็บเข้ากล่องเครื่องมือหรือแขวนบนแผงเครื่องมืออย่างเป็นระเบียบ","โยนรวมกันไว้ในถังขยะ","เก็บไว้ใต้เตียงนอน"]'::jsonb, '1'::jsonb, 'การเก็บเข้ากล่องหรือแขวนบนแผงเป็นระเบียบ ช่วยป้องกันอุบัติเหตุสะดุดหกล้ม และทำให้หยิบใช้งานได้สะดวกในครั้งต่อไป');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] มารยาทในการทำงานร่วมกับผู้อื่น', 'easy', 'mcq', 'เมื่อทำงานกลุ่มร่วมกับเพื่อนในวิชาการงานอาชีพ ข้อใดเป็นมารยาทการทำงานที่ดีที่สุด?', '["รับผิดชอบหน้าที่ของตนเอง รับฟังความคิดเห็นของเพื่อน และช่วยเหลือซึ่งกันและกัน","ปล่อยให้เพื่อนสนิททำคนเดียว","สั่งการเพื่อนโดยไม่ช่วยลงมือทำ","แย่งผลงานเพื่อนมาเป็นของตนเอง"]'::jsonb, '0'::jsonb, 'การมีความรับผิดชอบต่อหน้าที่ที่ได้รับมอบหมาย มีน้ำใจ และรับฟังความคิดเห็นของเพื่อนร่วมกลุ่มคือกุญแจสู่ความสำเร็จ');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การตรงต่อเวลาในการทำงาน', 'easy', 'mcq', 'การส่งงานประดิษฐ์ตรงตามกำหนดเวลา มีประโยชน์ต่อนักเรียนอย่างไร?', '["แสดงถึงความรับผิดชอบ การมีวินัยในตนเอง และฝึกนิสัยการทำงานอย่างมืออาชีพ","ทำให้ได้รางวัลใหญ่จากรัฐบาล","ทำให้ไม่ต้องสอบปลายภาค","ทำให้คุณครูเกรงใจ"]'::jsonb, '0'::jsonb, 'การตรงต่อเวลาสะท้อนถึงการบริหารเวลาที่ดี ความซื่อสัตย์ และความรับผิดชอบต่อภาระหน้าที่');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การใช้วัสดุอย่างคุ้มค่าและประหยัด', 'easy', 'mcq', 'ในการตัดกระดาษสีเพื่อทำงานประดิษฐ์ ควรตัดอย่างไรจึงจะประหยัดและเหลือเศษทิ้งน้อยที่สุด?', '["ตัดตรงกลางแผ่นกระดาษใหญ่ทันที","วาดแบบร่างชิดมุมหรือขอบกระดาษก่อนตัด เพื่อให้เหลือก้นกระดาษผืนใหญ่ไว้ใช้ต่อ","ฉีกกระดาษเป็นชิ้นเล็กๆ ทั้งแผ่น","ใช้กระดาษแผ่นละ 1 ชิ้นงาน"]'::jsonb, '1'::jsonb, 'การร่างแบบชิดขอบหรือมุมกระดาษช่วยลดการสิ้นเปลือง และทำให้เหลือพื้นที่กระดาษส่วนที่เหลือไปทำงานชิ้นอื่นต่อได้');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] การประเมินผลงาน', 'medium', 'mcq', 'หลังจากประดิษฐ์ชิ้นงานเสร็จสิ้นแล้ว การทดลองใช้งานจริงมีประโยชน์อย่างไร?', '["เพื่อตรวจหาข้อบกพร่องและนำไปปรับปรุงแก้ไขให้ชิ้นงานมีความแข็งแรงทนทานใช้งานได้จริง","เพื่อถ่ายรูปลงโซเชียลเท่านั้น","เพื่อให้พังแล้วจะได้ทำใหม่","ไม่มีประโยชน์ใดๆ"]'::jsonb, '0'::jsonb, 'การทดสอบประสิทธิภาพจริงทำให้ทราบจุดอ่อนของชิ้นงาน เช่น รอยต่อไม่แน่น กาวหลุด เพื่อนำไปปรับปรุงให้สมบูรณ์');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเย็บผ้าพื้นฐาน: การสอยผ้า', 'hard', 'mcq', 'การซ่อมแซมชายกระโปรงหรือชายกางเกงนักเรียนที่ด้ายหลุดลุ่ย โดยไม่ต้องการให้เห็นรอยด้ายที่ด้านหน้า นิยมใช้วิธีการเย็บแบบใด?', '["การด้นถอยหลัง","การสอยซ่อนด้าย","การเนาเท่ากัน","การปักทึบ"]'::jsonb, '1'::jsonb, 'การสอยซ่อนด้าย (Blind stitch) ใช้สำหรับเก็บริมผ้า ชายกระโปรง ชายกางเกง โดยรอยด้ายจะซ่อนอยู่ด้านใน ไม่เห็นที่ด้านนอก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] การเย็บผ้าพื้นฐาน: การเนา', 'medium', 'mcq', 'การ "เนาผ้า" มีจุดประสงค์เพื่ออะไรก่อนการเย็บจริง?', '["เพื่อยึดผ้าสองชิ้นให้อยู่ติดกันชั่วคราว ป้องกันผ้าเลื่อนหลุดก่อนเย็บถาวร","เพื่อให้ผ้ามีสีสันสวยงาม","เพื่อให้ผ้าหนาขึ้น","เพื่อกันน้ำซึม"]'::jsonb, '0'::jsonb, 'การเนาคือการเย็บตะเข็บห่างๆ ชั่วคราวเพื่อตรึงผ้าให้อยู่ในแนวที่ต้องการ เมื่อเย็บจริงเสร็จแล้วจะเลาะด้ายเนาออก');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/1] อุปกรณ์ตัดเย็บ: ปลอกนิ้ว', 'medium', 'mcq', '"ปลอกนิ้ว (Thimble)" ที่สวมที่ปลายนิ้วขณะเย็บผ้าด้วยมือ มีประโยชน์อย่างไร?', '["ป้องกันไม่ให้ก้นเข็มแทงปลายนิ้วขณะดันเข็มผ่านผ้าหนา","ช่วยให้ตัดด้ายได้เร็ว","ช่วยสนเข็มได้ง่ายขึ้น","เป็นเครื่องประดับสวยงาม"]'::jsonb, '0'::jsonb, 'ปลอกนิ้วทำจากโลหะหรือพลาสติก ใช้สวมนิ้วกลางเพื่อดันก้นเข็มผ่านเนื้อผ้าหนาโดยไม่เจ็บนิ้ว');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ความสะอาดของสถานที่ทำงาน', 'easy', 'mcq', 'เมื่อทำงานประดิษฐ์หรืองานช่างเสร็จสิ้น สิ่งสุดท้ายที่ทุกคนในห้องต้องร่วมมือกันทำคือข้อใด?', '["วิ่งไปโรงอาหารทันที","ช่วยกันเก็บเศษขยะ ทำความสะอาดโต๊ะทำงานและกวาดถูห้องให้เรียบร้อย","โยนอุปกรณ์ไว้บนโต๊ะครู","ปิดไฟและขังเพื่อนไว้ในห้อง"]'::jsonb, '1'::jsonb, 'การทำความสะอาดพื้นที่ทำงาน คัดแยกขยะ และเก็บอุปกรณ์ให้เรียบร้อยหลังทำงานเสร็จเป็นสุขนิสัยที่ดีในการทำงาน');
INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation) VALUES ('การงานอาชีพ', 'ป.4', '[ง 1.1 ป.4/3] ประโยชน์ของการมีทักษะการทำงานอาชีพ', 'easy', 'mcq', 'การฝึกทักษะวิชาการงานอาชีพตั้งแต่ระดับประถมศึกษา มีคุณค่าต่อนักเรียนอย่างไรมากที่สุด?', '["ช่วยให้พึ่งพาตนเองได้ ช่วยเหลืองานครอบครัว มีทักษะชีวิต และสามารถนำไปต่อยอดอาชีพในอนาคต","ทำให้ไม่ต้องอ่านหนังสือวิชาอื่น","ทำให้สอบเข้ามหาวิทยาลัยได้โดยไม่ต้องเรียน","ช่วยให้มีชื่อเสียงเป็นดารา"]'::jsonb, '0'::jsonb, 'ช่วยปลูกฝังนิสัยรักการทำงาน การพึ่งพาตนเอง ความคิดริเริ่มสร้างสรรค์ และทักษะการแก้ปัญหาในชีวิตประจำวัน');
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาภาษาไทย ป.4 (20 ข้อ)', 'ภาษาไทย', 'ป.4', '[{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/1] การอ่านออกเสียงบทร้อยแก้วและบทร้อยกรอง","difficulty":"easy","question_type":"mcq","question_text":"คำในข้อใดอ่านออกเสียงอักษรนำถูกต้อง?","options":["ผลิต อ่านว่า ผะ-ลิด","ปรารถนา อ่านว่า ปราด-ถะ-หนา","ตลาด อ่านว่า ตะ-หลาด","สมาคม อ่านว่า สะ-มา-คม"],"answer":2,"explanation":"\"ตลาด\" เป็นคำที่มีอักษรนำ (ต นำ ล) อ่านออกเสียงสองพยางค์ พยางค์หลังออกเสียงเหมือนมี ห นำ คือ ตะ-หลาด"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/1] การอ่านออกเสียงคำที่มี ร ล ว ควบกล้ำ","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดมีคำควบกล้ำแท้ทุกคำ?","options":["สร้างเสริม, จริงจัง","กราบพระ, กว้างขวาง","เศรษฐี, ทรงทราบ","เสร็จสิ้น, ปราศจาก"],"answer":1,"explanation":"กราบพระ (กร), กว้างขวาง (กว) เป็นคำควบกล้ำแท้ที่ออกเสียงพยัญชนะต้นสองตัวพร้อมกัน ส่วนข้ออื่นมีคำควบไม่แท้ปนอยู่"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/2] การอธิบายความหมายของคำ ประโยค และสำนวน","difficulty":"medium","question_type":"mcq","question_text":"สำนวน \"ขี่ช้างจับตั๊กแตน\" มีความหมายตรงกับข้อใด?","options":["ทำงานใหญ่แต่ได้ผลประโยชน์น้อย","ทำสิ่งที่เป็นไปไม่ได้ให้สำเร็จ","มีความพยายามอย่างยิ่งยวด","ทำลายสิ่งของเพื่อประโยชน์ส่วนตัว"],"answer":0,"explanation":"\"ขี่ช้างจับตั๊กแตน\" หมายถึง การลงทุนหรือลงแรงทำสิ่งใหญ่โตแต่ได้ผลตอบแทนเพียงเล็กน้อย ไม่คุ้มค่า"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/2] การเข้าใจความหมายของคำศัพท์ในบริบท","difficulty":"medium","question_type":"mcq","question_text":"คำว่า \"มัธยัสถ์\" มีความหมายตรงข้ามกับคำในข้อใด?","options":["ตระหนี่","ฟุ่มเฟือย","รอบคอบ","ประหยัด"],"answer":1,"explanation":"มัธยัสถ์ หมายถึง การใช้จ่ายอย่างประหยัดพอเหมาะ จึงมีความหมายตรงข้ามกับคำว่า \"ฟุ่มเฟือย\""},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/3] การอ่านจับใจความจากสื่อต่างๆ","difficulty":"medium","question_type":"mcq","question_text":"\"ต้นไม้ช่วยดูดซับก๊าซคาร์บอนไดออกไซด์และคายก๊าซออกซิเจนให้สิ่งมีชีวิตใช้หายใจ นอกจากนี้รากยังช่วยยึดดินไม่ให้พังทลาย\" ใจความสำคัญของข้อความนี้คืออะไร?","options":["รากของต้นไม้ยึดดินได้ดี","ต้นไม้มีประโยชน์ต่อสิ่งมีชีวิตและสิ่งแวดล้อม","สิ่งมีชีวิตทุกชนิดต้องหายใจ","ก๊าซออกซิเจนเกิดจากต้นไม้เท่านั้น"],"answer":1,"explanation":"ใจความสำคัญสรุปรวมถึงประโยชน์ของต้นไม้ทั้งในด้านการให้อากาศหายใจและการช่วยยึดหน้าดิน"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น","difficulty":"medium","question_type":"mcq","question_text":"ข้อความใดต่อไปนี้เป็น \"ข้อคิดเห็น\"?","options":["ประเทศไทยตั้งอยู่ในทวีปเอเชีย","น้ำจะเดือดที่อุณหภูมิ 100 องศาเซลเซียส","ดอกกุหลาบสีแดงเป็นดอกไม้ที่สวยงามที่สุดในโลก","ดวงอาทิตย์ขึ้นทางทิศตะวันออก"],"answer":2,"explanation":"ความสวยงามเป็นความรู้สึกส่วนบุคคล ไม่สามารถพิสูจน์ให้ทุกคนยอมรับตรงกันได้ จึงเป็นข้อคิดเห็น"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/4] การแยกข้อเท็จจริงและข้อคิดเห็น","difficulty":"easy","question_type":"mcq","question_text":"ข้อความใดเป็น \"ข้อเท็จจริง\"?","options":["วันนี้อากาศร้อนจนน่าหงุดหงิด","เด็กที่เล่นกีฬาเป็นคนมีน้ำใจทุกคน","จังหวัดขอนแก่นตั้งอยู่ในภาคตะวันออกเฉียงเหนือ","วิชาคณิตศาสตร์ยากกว่าวิชาภาษาไทย"],"answer":2,"explanation":"ที่ตั้งของจังหวัดขอนแก่นเป็นความจริงทางภูมิศาสตร์ที่มีหลักฐานยืนยันชัดเจน"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/5] การคาดคะเนเหตุการณ์จากเรื่องที่อ่าน","difficulty":"medium","question_type":"mcq","question_text":"\"เมฆดำทมิฬลอยปกคลุมทั่วท้องฟ้า ลมพัดกรรโชกแรง ฟ้าแลบแปลบปลาบ\" จากข้อความนี้จะเกิดเหตุการณ์ใดตามมา?","options":["อากาศหนาวจัดจนเกิดหิมะ","ฝนกำลังจะตกหนักและอาจมีพายุ","เกิดแผ่นดินไหวรุนแรง","เกิดน้ำท่วมฉับพลันในทันที"],"answer":1,"explanation":"สัญญาณเมฆดำ ลมแรง และฟ้าแลบ เป็นสัญญาณบ่งบอกว่าฝนและพายุกำลังจะตก"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/6] การสรุปความรู้และข้อคิดจากการอ่านเพื่อนำไปใช้","difficulty":"hard","question_type":"mcq","question_text":"นิทานเรื่อง \"กระต่ายกับเต่า\" ให้ข้อคิดเตือนใจเรื่องใดมากที่สุด?","options":["ความคล่องแคล่วว่องไวทำให้ชนะเสมอ","ความประมาทเป็นหนทางสู่ความล้มเหลว","การเดินช้าช่วยรักษาสุขภาพ","ควรแข่งขันกับคนที่อ่อนแอกว่า"],"answer":1,"explanation":"กระต่ายแพ้เพราะประมาทและชะล่าใจ นอนหลับระหว่างทาง ส่วนเต่าชนะเพราะความเพียรพยายาม"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/7] การอ่านหนังสือที่มีคุณค่าตามความสนใจ","difficulty":"easy","question_type":"mcq","question_text":"มารยาทในการอ่านหนังสือในห้องสมุดข้อใดถูกต้องที่สุด?","options":["พูดคุยปรึกษาการบ้านกับเพื่อนเสียงดัง","นำขนมและน้ำหวานเข้าไปรับประทานขณะอ่าน","พับมุมหนังสือเพื่อทำเครื่องหมายหน้าคั่น","รักษาความเงียบและเก็บหนังสือเข้าที่ให้เรียบร้อย"],"answer":3,"explanation":"การรักษาความเงียบและการเก็บหนังสือเข้าที่เดิมเป็นมารยาทสำคัญของการใช้ห้องสมุด"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/8] การมีมารยาทในการอ่าน","difficulty":"easy","question_type":"mcq","question_text":"หากต้องการอ่านหนังสือพิมพ์ที่ผู้อื่นกำลังอ่านอยู่ ควรทำอย่างไร?","options":["ดึงมาอ่านทันทีเพราะอยากอ่านมาก","ชะโงกหน้าเข้าไปอ่านใกล้ๆ","รอให้ผู้อื่นอ่านเสร็จก่อนแล้วจึงขออ่านต่อ","หยิบหน้าอื่นที่เขายังไม่ได้เปิดมาอ่าน"],"answer":2,"explanation":"การรอให้ผู้อื่นอ่านเสร็จอย่างสุภาพเป็นมารยาทที่ดีในการอ่านร่วมกับผู้อื่น"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 1.1 ป.4/2] การเข้าใจความหมายของสำนวนไทย","difficulty":"medium","question_type":"mcq","question_text":"คนที่ไม่ยอมลงมือทำงานแต่วิพากษ์วิจารณ์คนอื่น ตรงกับสำนวนใด?","options":["มือไม่พายเอาเท้าราน้ำ","น้ำขึ้นให้รีบตัก","จับปลาสองมือ","ชี้โพรงให้กระรอก"],"answer":0,"explanation":"\"มือไม่พายเอาเท้าราน้ำ\" หมายถึง คนที่ไม่ช่วยเหลืองานแล้วยังทำตัวเกะกะขัดขวางการทำงานของผู้อื่น"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/1] การคัดลายมือตัวบรรจงเต็มบรรทัดและครึ่งบรรทัด","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นหลักการคัดลายมือตัวบรรจงที่ถูกต้อง?","options":["เขียนตัวเอียงมากๆ เพื่อความสวยงาม","เขียนหัวพยัญชนะให้ชัดเจน วางสระวรรณยุกต์ตรงตำแหน่ง","เว้นวรรคช่องไฟให้ห่างมากที่สุด","ลากเส้นตวัดหางให้ยาวทับบรรทัดอื่น"],"answer":1,"explanation":"การคัดลายมือที่ถูกต้องต้องเขียนหัวตัวอักษรกลมชัดเจน วางสระและวรรณยุกต์ตรงตำแหน่งตามหลักเกณฑ์"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/2] การเขียนสื่อความโดยใช้คำได้ถูกต้องชัดเจน","difficulty":"medium","question_type":"mcq","question_text":"ประโยคใดใช้คำลักษณนามถูกต้อง?","options":["คุณพ่อซื้อช้อนมา 2 อัน","คุณแม่ซื้อแหวนทอง 1 วง","คุณครูมีดินสอ 3 ด้าม","พี่ชายกางร่ม 1 อัน"],"answer":1,"explanation":"แหวนใช้ลักษณนามว่า \"วง\" (ช้อนใช้ \"คัน\", ดินสอใช้ \"แท่ง\", ร่มใช้ \"คัน\")"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/3] การเขียนแผนภาพโครงเรื่องและแผนภาพความคิด","difficulty":"medium","question_type":"mcq","question_text":"องค์ประกอบใด \"ไม่จำเป็น\" ต้องมีในแผนภาพโครงเรื่องของนิทาน?","options":["ตัวละคร","สถานที่และเวลา","เหตุการณ์และผลของเหตุการณ์","ราคาจำหน่ายของหนังสือนิทาน"],"answer":3,"explanation":"แผนภาพโครงเรื่องประกอบด้วย ใคร (ตัวละคร), ที่ไหน (ฉาก/เวลา), ทำอะไร (เหตุการณ์), และผลเป็นอย่างไร ข้อคิดที่ได้ ไม่เกี่ยวกับราคาหนังสือ"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/4] การเขียนย่อความจากเรื่องสั้นๆ","difficulty":"hard","question_type":"mcq","question_text":"ข้อใดเป็นข้อปฏิบัติที่ถูกต้องในการเขียนย่อความ?","options":["คัดลอกข้อความเดิมทั้งหมดมาตัดต่อใหม่","เปลี่ยนสรรพนามบุรุษที่ 1 และ 2 เป็นบุรุษที่ 3","ใส่เครื่องหมายอัญประกาศแสดงคำพูดเดิมเสมอ","เติมความรู้สึกส่วนตัวของผู้เขียนลงไปด้วย"],"answer":1,"explanation":"การเขียนย่อความต้องเรียบเรียงด้วยสำนวนตนเอง และเปลี่ยนสรรพนามบุรุษที่ 1 และ 2 ให้เป็นบุรุษที่ 3 เสมอ"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/5] การเขียนจดหมายถึงเพื่อนและบิดามารดา","difficulty":"medium","question_type":"mcq","question_text":"คำขึ้นต้นในการเขียนจดหมายถึงบิดามารดาที่ถูกต้องคือข้อใด?","options":["สวัสดีคุณพ่อคุณแม่ที่รัก","กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง","ถึงคุณพ่อคุณแม่","เรียนคุณพ่อคุณแม่ที่นับถือ"],"answer":1,"explanation":"คำขึ้นต้นจดหมายถึงบิดามารดาตามแบบแผนคือ \"กราบเท้าคุณพ่อคุณแม่ที่เคารพอย่างสูง\" และคำลงท้ายคือ \"ด้วยความเคารพรักอย่างสูง\""},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/6] การเขียนบันทึกและการเขียนรายงานความรู้","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นข้อมูลสำคัญที่ต้องระบุในการเขียนบันทึกประจำวัน?","options":["ชื่อสำนักพิมพ์","วัน เดือน ปี และเวลาที่เกิดเหตุการณ์","ราคาของสมุดบันทึก","เลขบัตรประจำตัวประชาชน"],"answer":1,"explanation":"การบันทึกประจำวันต้องระบุ วัน เดือน ปี และเวลาเพื่อบันทึกลำดับเหตุการณ์ที่เกิดขึ้นจริง"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/7] การเขียนเรื่องตามจินตนาการ","difficulty":"medium","question_type":"mcq","question_text":"สิ่งสำคัญที่สุดในการเขียนเรื่องตามจินตนาการคือข้อใด?","options":["การคัดลอกเนื้อเรื่องจากภาพยนตร์ชื่อดัง","ความคิดริเริ่มสร้างสรรค์และข้อคิดที่เป็นประโยชน์","การใช้คำศัพท์ภาษาต่างประเทศให้มากที่สุด","การเขียนเรื่องที่ยาวเกิน 10 หน้ากระดาษ"],"answer":1,"explanation":"การเขียนเรื่องตามจินตนาการต้องอาศัยความคิดริเริ่มสร้างสรรค์ ความสมเหตุสมผล และมีข้อคิดสอนใจที่ดี"},{"subject":"ภาษาไทย","grade":"ป.4","topic":"[ท 2.1 ป.4/8] การมีมารยาทในการเขียน","difficulty":"easy","question_type":"mcq","question_text":"การกระทำใดถือว่า \"ไม่มีมารยาท\" ในการเขียน?","options":["ใช้น้ำยาลบคำผิดลบให้สะอาดเรียบร้อย","เขียนข้อความขีดเขียนบนโต๊ะเรียนและผนังห้องน้ำ","ใช้ภาษาที่สุภาพ เหมาะสมกับกาลเทศะ","ตรวจสอบความถูกต้องของตัวสะกดก่อนส่ง"],"answer":1,"explanation":"การขีดเขียนในที่สาธารณะ เช่น โต๊ะเรียน ผนังห้องน้ำ ถือเป็นการทำลายทรัพย์สินและขาดมารยาทอย่างยิ่ง"}]'::jsonb, 30, 50, 'THAI401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาคณิตศาสตร์ ป.4 (20 ข้อ)', 'คณิตศาสตร์', 'ป.4', '[{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/1] การอ่านและการเขียนตัวเลขฮินดูอารบิก ตัวเลขไทย และตัวหนังสือ","difficulty":"easy","question_type":"mcq","question_text":"ตัวเลข \"๔๘๕,๒๐๙\" เขียนเป็นตัวหนังสือได้อย่างไร?","options":["สี่แสนแปดหมื่นห้าพันสองร้อยเก้า","สี่หมื่นแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดหมื่นห้าพันยี่สิบเก้า"],"answer":0,"explanation":"4 ในหลักแสน, 8 ในหลักหมื่น, 5 ในหลักพัน, 2 ในหลักร้อย, 0 ในหลักสิบ, 9 ในหลักหน่วย อ่านว่า สี่แสนแปดหมื่นห้าพันสองร้อยเก้า"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/1] ค่าประจำหลักและค่าของเลขโดด","difficulty":"easy","question_type":"mcq","question_text":"ในจำนวน 3,745,820 เลขโดด 4 อยู่ในหลักใด และมีค่าเท่าใด?","options":["หลักแสน มีค่า 400,000","หลักหมื่น มีค่า 40,000","หลักพัน มีค่า 4,000","หลักร้อย มีค่า 400"],"answer":1,"explanation":"3 (ล้าน), 7 (แสน), 4 (หมื่น) ดังนั้นเลข 4 อยู่ในหลักหมื่น มีค่าเท่ากับ 40,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/1] การเขียนในรูปกระจาย","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นการเขียน 609,450 ในรูปกระจายที่ถูกต้อง?","options":["600,000 + 9,000 + 400 + 50","60,000 + 9,000 + 400 + 5","600,000 + 90,000 + 400 + 50","6,000,000 + 9,000 + 450"],"answer":0,"explanation":"609,450 = 600,000 + 0 + 9,000 + 400 + 50 + 0 ซึ่งเขียนแบบย่อคือ 600,000 + 9,000 + 400 + 50"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การเปรียบเทียบและเรียงลำดับจำนวน","difficulty":"medium","question_type":"mcq","question_text":"ข้อใดเรียงลำดับจำนวนจาก \"มากไปน้อย\" ได้ถูกต้อง?","options":["785,100  792,400  810,000","950,210  948,990  948,750","523,000  532,000  519,000","405,600  406,500  404,900"],"answer":1,"explanation":"950,210 > 948,990 > 948,750 เรียงลำดับจากค่ามากที่สุดไปหาค่าน้อยที่สุดถูกต้อง"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มสิบ","difficulty":"easy","question_type":"mcq","question_text":"ค่าประมาณเป็นจำนวนเต็มสิบของ 4,876 คือเท่าใด?","options":["4,870","4,880","4,900","5,000"],"answer":1,"explanation":"พิจารณาหลักหน่วยคือ 6 (มากกว่าหรือเท่ากับ 5) จึงปัดขึ้นจาก 70 เป็น 80 ได้ 4,880"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มร้อยและเต็มพัน","difficulty":"medium","question_type":"mcq","question_text":"ค่าประมาณเป็นจำนวนเต็มร้อยของ 52,438 คือจำนวนใด?","options":["52,400","52,500","52,000","53,000"],"answer":0,"explanation":"พิจารณาหลักสิบคือ 3 (น้อยกว่า 5) จึงปัดลง ได้ค่าประมาณเป็นจำนวนเต็มร้อยคือ 52,400"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มหมื่น","difficulty":"medium","question_type":"mcq","question_text":"ค่าประมาณเป็นจำนวนเต็มหมื่นของ 768,490 คือข้อใด?","options":["760,000","770,000","800,000","768,000"],"answer":1,"explanation":"พิจารณาหลักพันคือ 8 (มากกว่าหรือเท่ากับ 5) ปัดขึ้นในหลักหมื่นจาก 60,000 เป็น 70,000 ได้ 770,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มแสน","difficulty":"medium","question_type":"mcq","question_text":"จำนวนในข้อใดมีค่าประมาณเป็นจำนวนเต็มแสนเท่ากับ 500,000?","options":["429,999","551,000","478,500","580,200"],"answer":2,"explanation":"478,500 พิจารณาหลักหมื่นคือ 7 (ปัดขึ้น) จะได้ 500,000 ส่วน 429,999 ปัดลงได้ 400,000 และ 551,000 ปัดขึ้นได้ 600,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/1] แบบรูปและความสัมพันธ์ของจำนวน","difficulty":"medium","question_type":"mcq","question_text":"จากแบบรูป 125, 250, 500, 1,000, ... จำนวนถัดไปคือจำนวนใด?","options":["1,250","1,500","2,000","2,500"],"answer":2,"explanation":"เป็นแบบรูปที่มีความสัมพันธ์แบบเพิ่มขึ้นโดยการคูณด้วย 2 ทีละเท่าตัว ดังนั้น 1,000 x 2 = 2,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/2] การประมาณผลลัพธ์","difficulty":"hard","question_type":"mcq","question_text":"ผลบวกโดยประมาณของ 39,850 + 20,400 มีค่าใกล้เคียงข้อใดมากที่สุด?","options":["50,000","60,000","70,000","80,000"],"answer":1,"explanation":"39,850 ประมาณเป็น 40,000 และ 20,400 ประมาณเป็น 20,000 รวมกันได้ประมาณ 40,000 + 20,000 = 60,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/7] การบวกจำนวนนับที่มากกว่า 100,000","difficulty":"easy","question_type":"mcq","question_text":"ผลลัพธ์ของ 458,920 + 324,159 คือเท่าใด?","options":["783,079","782,079","773,079","883,079"],"answer":0,"explanation":"458,920 + 324,159 = 783,079"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/7] การลบจำนวนนับที่มากกว่า 100,000","difficulty":"easy","question_type":"mcq","question_text":"ผลลัพธ์ของ 800,000 - 347,650 มีค่าเท่าใด?","options":["452,350","552,350","462,350","453,350"],"answer":0,"explanation":"800,000 - 347,650 = 452,350"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/8] การคูณจำนวนที่มีหลายหลัก","difficulty":"medium","question_type":"mcq","question_text":"ผลคูณของ 1,245 x 36 มีค่าเท่ากับเท่าใด?","options":["44,820","43,820","44,720","45,820"],"answer":0,"explanation":"1,245 x 30 = 37,350 และ 1,245 x 6 = 7,470 นำมารวมกันได้ 37,350 + 7,470 = 44,820"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/8] การคูณจำนวนที่มีศูนย์ลงท้าย","difficulty":"easy","question_type":"mcq","question_text":"ผลคูณของ 700 x 500 เท่ากับเท่าใด?","options":["3,500","35,000","350,000","3,500,000"],"answer":2,"explanation":"7 x 5 = 35 เติมศูนย์ตามหลัง 4 ตัว (00 จาก 700 และ 00 จาก 500) ได้ 350,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/9] การหารที่ตัวหารมีสองหลัก","difficulty":"medium","question_type":"mcq","question_text":"ผลลัพธ์ของ 4,680 ÷ 15 คือข้อใด?","options":["312","322","310","302"],"answer":0,"explanation":"4,680 ÷ 15: 15 x 3 = 45 (เหลือเศษ 1 ดึง 8 เป็น 18), 15 x 1 = 15 (เหลือเศษ 3 ดึง 0 เป็น 30), 15 x 2 = 30 ลงตัว ได้ผลลัพธ์ 312"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/9] การหารมีเศษ","difficulty":"medium","question_type":"mcq","question_text":"2,579 ÷ 8 ได้ผลหารและเศษตรงกับข้อใด?","options":["322 เศษ 3","321 เศษ 5","322 เศษ 5","320 เศษ 7"],"answer":0,"explanation":"322 x 8 = 2,576 และ 2,579 - 2,576 = 3 ดังนั้นได้ 322 เศษ 3"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/10] การบวก ลบ คูณ หารระคน","difficulty":"hard","question_type":"mcq","question_text":"หาผลลัพธ์ของ (450 + 150) x (200 - 160)","options":["24,000","18,000","12,000","30,000"],"answer":0,"explanation":"คำนวณในวงเล็บก่อน: (450 + 150) = 600 และ (200 - 160) = 40 จากนั้นนำ 600 x 40 = 24,000"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/10] ลำดับการคำนวณ (Order of Operations)","difficulty":"hard","question_type":"mcq","question_text":"100 + 50 x 2 - 40 มีค่าเท่ากับเท่าใด?","options":["260","160","210","180"],"answer":1,"explanation":"ต้องทำคูณก่อน: 50 x 2 = 100 จากนั้นทำจากซ้ายไปขวา: 100 + 100 = 200 แล้ว 200 - 40 = 160"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/11] โจทย์ปัญหาการบวกและลบ","difficulty":"medium","question_type":"mcq","question_text":"โรงสีข้าวมีข้าวสาร 85,400 กิโลกรัม ขายไป 38,950 กิโลกรัม และซื้อเพิ่มอีก 15,000 กิโลกรัม ขณะนี้มีข้าวสารเหลือกี่กิโลกรัม?","options":["61,450 กิโลกรัม","59,450 กิโลกรัม","62,550 กิโลกรัม","60,450 กิโลกรัม"],"answer":0,"explanation":"มีข้าวสาร 85,400 - 38,950 = 46,450 แล้วซื้อเพิ่ม 46,450 + 15,000 = 61,450 กิโลกรัม"},{"subject":"คณิตศาสตร์","grade":"ป.4","topic":"[ค 1.1 ป.4/11] โจทย์ปัญหาการคูณ","difficulty":"medium","question_type":"mcq","question_text":"โรงงานผลิตน้ำดื่มบรรจุลังละ 24 ขวด หากผลิตได้ 1,500 ลัง โรงงานมีน้ำดื่มทั้งหมดกี่ขวด?","options":["36,000 ขวด","35,000 ขวด","38,000 ขวด","34,000 ขวด"],"answer":0,"explanation":"1,500 x 24 = 36,000 ขวด"}]'::jsonb, 30, 50, 'MATH401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาวิทยาศาสตร์ ป.4 (20 ข้อ)', 'วิทยาศาสตร์', 'ป.4', '[{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] หน้าที่ของส่วนต่างๆ ของพืช: รากและลำต้น","difficulty":"easy","question_type":"mcq","question_text":"ส่วนใดของพืชทำหน้าที่ดูดน้ำและแร่ธาตุจากดินขึ้นไปเลี้ยงส่วนต่างๆ?","options":["ใบ","ดอก","ราก","ผล"],"answer":2,"explanation":"รากทำหน้าที่ยึดลำต้นให้ติดกับดิน และดูดน้ำกับแร่ธาตุขึ้นไปส่งต่อให้ลำต้น"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] ท่อลำเลียงน้ำและท่อลำเลียงอาหาร","difficulty":"medium","question_type":"mcq","question_text":"ท่อลำเลียงน้ำ (ไซเลม) และท่อลำเลียงอาหาร (โฟลเอ็ม) ในลำต้นพืช มีทิศทางการลำเลียงอย่างไร?","options":["ท่อลำเลียงน้ำลำเลียงจากรากขึ้นสู่ใบ ท่อลำเลียงอาหารลำเลียงจากใบไปส่วนต่างๆ","ท่อลำเลียงน้ำลำเลียงจากใบคงลงสู่รากเท่านั้น","ทั้งสองท่อลำเลียงจากดินขึ้นสู่ยอดพร้อมกัน","ท่อลำเลียงอาหารลำเลียงจากรากขึ้นสู่ดอก"],"answer":0,"explanation":"ท่อลำเลียงน้ำดูดน้ำจากรากขึ้นสู่ใบ ส่วนท่อลำเลียงอาหารลำเลียงน้ำตาลที่สร้างจากใบไปเลี้ยงส่วนต่างๆ ของพืช"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] หน้าที่ของใบและการสังเคราะห์ด้วยแสง","difficulty":"easy","question_type":"mcq","question_text":"ปัจจัยสำคัญที่พืชใช้ในกระบวนการสังเคราะห์ด้วยแสงคือข้อใด?","options":["แสงแดด, คลอโรฟิลล์, น้ำ, แก๊สคาร์บอนไดออกไซด์","แสงแดด, ดิน, น้ำมัน, แก๊สออกซิเจน","ความมืด, ปุ๋ย, แก๊สไนโตรเจน","น้ำตาล, เกลือ, น้ำ, แก๊สคาร์บอนไดออกไซด์"],"answer":0,"explanation":"พืชใช้คลอโรฟิลล์ดูดกลืนพลังงานแสง รวมกับน้ำและแก๊สคาร์บอนไดออกไซด์ เพื่อสร้างน้ำตาลและแก๊สออกซิเจน"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] ผลผลิตจากการสังเคราะห์ด้วยแสง","difficulty":"easy","question_type":"mcq","question_text":"แก๊สชนิดใดที่พืชคายออกมาจากกระบวนการสังเคราะห์ด้วยแสง ซึ่งเป็นประโยชน์ต่อการหายใจของสัตว์และมนุษย์?","options":["แก๊สคาร์บอนมอนอกไซด์","แก๊สออกซิเจน","แก๊สคาร์บอนไดออกไซด์","แก๊สไฮโดรเจน"],"answer":1,"explanation":"ผลผลิตจากการสังเคราะห์ด้วยแสงคือน้ำตาลกลูโคสและแก๊สออกซิเจน ซึ่งสิ่งมีชีวิตใช้ในการหายใจ"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] การคายน้ำของพืช","difficulty":"medium","question_type":"mcq","question_text":"พืชคายน้ำออกทางโครงสร้างใดเป็นหลัก?","options":["ขนราก","ปากใบ (Stomata)","กลีบดอก","เปลือกลำต้น"],"answer":1,"explanation":"พืชคายน้ำในรูปของไอน้ำออกทางปากใบที่อยู่บริเวณใต้ใบเป็นส่วนใหญ่"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] การจำแนกพืชดอกและพืชไม่มีดอก","difficulty":"easy","question_type":"mcq","question_text":"พืชในข้อใดจัดเป็น \"พืชไม่มีดอก\"?","options":["กุหลาบ, ชบา","ทานตะวัน, กล้วยไม้","เฟิร์น, มอส","มะม่วง, มะลิ"],"answer":2,"explanation":"เฟิร์นและมอสเป็นพืชไม่มีดอก โดยสืบพันธุ์โดยการสร้างสปอร์"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงเดี่ยว","difficulty":"medium","question_type":"mcq","question_text":"ข้อใดเป็นลักษณะเฉพาะของ \"พืชใบเลี้ยงเดี่ยว\"?","options":["เส้นใบเป็นร่างแห, ระบบรากแก้ว","เส้นใบขนาน, ระบบรากฝอย, มีใบเลี้ยง 1 ใบ","ลำต้นไม่มีข้อปล้อง, กลีบดอกมี 4-5 กลีบ","มีเนื้อไม้ขนาดใหญ่ ไม่มีข้อปล้อง"],"answer":1,"explanation":"พืชใบเลี้ยงเดี่ยว เช่น ข้าว ข้าวโพด มะพร้าว มีใบเลี้ยง 1 ใบ เส้นใบเรียงขนาน และมีระบบรากฝอย"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] ลักษณะของพืชใบเลี้ยงคู่","difficulty":"medium","question_type":"mcq","question_text":"พืชในข้อใดจัดเป็น \"พืชใบเลี้ยงคู่\" ทั้งหมด?","options":["ข้าว, ข้าวโพด, หญ้า","มะม่วง, ถั่วเขียว, กุหลาบ","ไผ่, มะพร้าว, อ้อย","กล้วย, หญ้าแพรก, ข่า"],"answer":1,"explanation":"มะม่วง ถั่วเขียว กุหลาบ มีเส้นใบเป็นร่างแห ระบบรากแก้ว และมีใบเลี้ยง 2 ใบ จึงเป็นพืชใบเลี้ยงคู่"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] ส่วนประกอบของดอกไม้","difficulty":"easy","question_type":"mcq","question_text":"ส่วนประกอบของดอกไม้ที่มีสีสันสวยงามและมีกลิ่นหอมเพื่อล่อแมลงคือส่วนใด?","options":["กลีบเลี้ยง","กลีบดอก","เกสรเพศผู้","เกสรเพศเมีย"],"answer":1,"explanation":"กลีบดอกมีหน้าที่ดึงดูดแมลงให้มาช่วยผสมเกสรด้วยสีสันและกลิ่นหอม"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.2 ป.4/1] การทดสอบแป้งในใบพืช","difficulty":"hard","question_type":"mcq","question_text":"สารละลายใดที่ใช้ทดสอบหาแป้งที่พืชสะสมไว้ โดยจะเปลี่ยนเป็นสีน้ำเงินเข้มหรือสีน้ำเงินแกมม่วง?","options":["สารละลายเบเนดิกต์","สารละลายไอโอดีน","แอลกอฮอล์บริสุทธิ์","น้ำเกลือ"],"answer":1,"explanation":"สารละลายไอโอดีนจะทำปฏิกิริยากับแป้งแล้วเปลี่ยนจากสีน้ำตาลอมส้มเป็นสีน้ำเงินเข้มหรือม่วงเข้ม"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] การจำแนกสัตว์: สัตว์มีกระดูกสันหลัง","difficulty":"easy","question_type":"mcq","question_text":"สัตว์ในข้อใดจัดเป็นสัตว์มีกระดูกสันหลังทั้งหมด?","options":["ปลา, สุนัข, กบ, นก","แมงกะพรุน, ดาวทะเล, ปลาหมึก","หอย, กุ้ง, ปู, ไส้เดือน","พยาธิ, แมลงวัน, ยุง, ผึ้ง"],"answer":0,"explanation":"ปลา สุนัข กบ นก มีกระดูกแกนกลางพยุงร่างกาย จัดเป็นสัตว์มีกระดูกสันหลัง"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] กลุ่มปลา","difficulty":"easy","question_type":"mcq","question_text":"ปลาหายใจด้วยอวัยวะใด และออกลูกอย่างไรเป็นส่วนใหญ่?","options":["หายใจด้วยปอด, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นไข่","หายใจด้วยผิวหนัง, ออกลูกเป็นตัว","หายใจด้วยเหงือก, ออกลูกเป็นตัว"],"answer":1,"explanation":"ปลาอาศัยในน้ำ ใช้เหงือกในการแลกเปลี่ยนแก๊ส และส่วนใหญ่ออกลูกเป็นไข่ (เป็นสัตว์เลือดเย็น)"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] กลุ่มสัตว์สะเทินน้ำสะเทินบก","difficulty":"medium","question_type":"mcq","question_text":"สัตว์กลุ่มสะเทินน้ำสะเทินบก (เช่น กบ คางคก) ในวัยตัวอ่อน (ลูกอ๊อด) หายใจด้วยอวัยวะใด?","options":["ปอด","เหงือก","ผิวหนังและปอด","จมูก"],"answer":1,"explanation":"วัยลูกอ๊อดอาศัยอยู่ในน้ำและหายใจด้วยเหงือก เมื่อโตเต็มวัยขึ้นมาอยู่บนบกจะหายใจด้วยปอดและผิวหนัง"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] กลุ่มสัตว์เลื้อยคลาน","difficulty":"medium","question_type":"mcq","question_text":"ข้อใดเป็นลักษณะสำคัญของ \"สัตว์เลื้อยคลาน\"?","options":["ผิวหนังเปียกชื้น ไม่มีเกล็ด","ผิวหนังแห้ง มีเกล็ดปกคลุม หายใจด้วยปอด","มีขนเป็นแผง มีปีกบินได้","มีต่อมน้ำนมเลี้ยงลูก"],"answer":1,"explanation":"สัตว์เลื้อยคลาน เช่น จระเข้ เต่า งู กิ้งก่า ผิวหนังแห้งมีเกล็ดแข็งปกคลุม วางไข่บนบก และหายใจด้วยปอด"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] กลุ่มสัตว์ปีก","difficulty":"easy","question_type":"mcq","question_text":"สัตว์กลุ่มใดจัดเป็นสัตว์เลือดอุ่นและมีกระดูกกลวงเบาช่วยในการบิน?","options":["สัตว์เลื้อยคลาน","สัตว์สะเทินน้ำสะเทินบก","สัตว์ปีก","ปลา"],"answer":2,"explanation":"สัตว์ปีก (นก เป็ด ไก่) เป็นสัตว์เลือดอุ่น มีขนเป็นแผง และกระดูกกลวงเบาเพื่อช่วยลดน้ำหนักในการบิน"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] กลุ่มสัตว์เลี้ยงลูกด้วยน้ำนม","difficulty":"easy","question_type":"mcq","question_text":"สัตว์น้ำในข้อใดจัดเป็น \"สัตว์เลี้ยงลูกด้วยน้ำนม\" ไม่ใช่ปลา?","options":["ฉลาม","ปลากระเบน","วาฬและโลมา","ปลาทู"],"answer":2,"explanation":"วาฬและโลมาหายใจด้วยปอด เลี้ยงลูกด้วยน้ำนม ออกลูกเป็นตัว จัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนม"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] สัตว์เลี้ยงลูกด้วยน้ำนมที่บินได้","difficulty":"medium","question_type":"mcq","question_text":"สัตว์ในข้อใดจัดเป็นสัตว์เลี้ยงลูกด้วยน้ำนมที่สามารถบินได้?","options":["ค้างคาว","กระรอกบิน","นกเพนกวิน","นกกระจอกเทศ"],"answer":0,"explanation":"ค้างคาวมีต่อมน้ำนม ออกลูกเป็นตัว และเป็นสัตว์เลี้ยงลูกด้วยน้ำนมเพียงชนิดเดียวที่บินได้จริง"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: กลุ่มขาข้อ","difficulty":"medium","question_type":"mcq","question_text":"สัตว์ที่มีขาเป็นข้อและมี 6 ขา จัดเป็นสัตว์จำพวกใด?","options":["แมง (เช่น แมงมุม)","แมลง (เช่น ผึ้ง ตั๊กแตน)","สัตว์พวกกุ้งกั้งปู","กิ้งกือ"],"answer":1,"explanation":"แมลงมี 6 ขา ลำตัวแบ่งเป็น 3 ส่วน (หัว อก ท้อง) ส่วนแมงมุมมี 8 ขา"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] สัตว์ไม่มีกระดูกสันหลัง: หอยและหมึก","difficulty":"easy","question_type":"mcq","question_text":"สัตว์ในข้อใดเป็นสัตว์ไม่มีกระดูกสันหลังที่มีลำตัวนิ่ม?","options":["ปลาทอง","หมึกกล้วย","กบหนอง","จิ้งจก"],"answer":1,"explanation":"หมึกกล้วยและหอยเป็นสัตว์ไม่มีกระดูกสันหลังจำพวกลำตัวนิ่ม"},{"subject":"วิทยาศาสตร์","grade":"ป.4","topic":"[ว 1.3 ป.4/1] สัตว์เลือดอุ่นและสัตว์เลือดเย็น","difficulty":"hard","question_type":"mcq","question_text":"สัตว์กลุ่มใดจัดเป็น \"สัตว์เลือดเย็น\" (อุณหภูมิร่างกายเปลี่ยนตามสภาพแวดล้อม)?","options":["นกและสัตว์เลี้ยงลูกด้วยน้ำนม","ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน","มนุษย์และสุนัข","วาฬและลิง"],"answer":1,"explanation":"ปลา สัตว์สะเทินน้ำสะเทินบก และสัตว์เลื้อยคลาน เป็นสัตว์เลือดเย็น อุณหภูมิร่างกายปรับเปลี่ยนตามสิ่งแวดล้อม"}]'::jsonb, 30, 50, 'SCI401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาสังคมศึกษา ป.4 (20 ข้อ)', 'สังคมศึกษา', 'ป.4', '[{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/1] พุทธประวัติ: การประสูติ ตรัสรู้ ปรินิพพาน","difficulty":"easy","question_type":"mcq","question_text":"เจ้าชายสิทธัตถะประสูติ ณ สถานที่ใด?","options":["ใต้ร่มไม้รัง ลุมพินีวัน","ใต้ต้นพระศรีมหาโพธิ์ พุทธคยา","ป่าอิสิปตนมฤคทายวัน","สาลวโนทยาน เมืองกุสินารา"],"answer":0,"explanation":"เจ้าชายสิทธัตถะประสูติ ณ ลุมพินีวัน (ปัจจุบันอยู่ในประเทศเนปาล) ตรงกับวันขึ้น 15 ค่ำ เดือน 6"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/1] เทวทูต 4","difficulty":"medium","question_type":"mcq","question_text":"เจ้าชายสิทธัตถะทอดพระเนตรเห็น \"เทวทูตทั้ง 4\" ทำให้เกิดความเบื่อหน่ายในโลกียวิสัย เทวทูตทั้ง 4 คือข้อใด?","options":["คนเกิด, คนแก่, คนเจ็บ, คนรวย","คนเกิด, คนรวย, คนจน, สมณะ","คนแก่, คนเจ็บ, คนตาย, สมณะ","คนเจ็บ, คนตาย, พระราชา, สมณะ"],"answer":2,"explanation":"เทวทูตทั้ง 4 ได้แก่ คนแก่ คนเจ็บ คนตาย และสมณะ ซึ่งทำให้พระองค์คิดหาทางหลุดพ้นจากความทุกข์"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/1] การตรัสรู้ของพระพุทธเจ้า","difficulty":"easy","question_type":"mcq","question_text":"พระพุทธเจ้าตรัสรู้ความจริงอันประเสริฐ 4 ประการ ซึ่งเรียกว่าอะไร?","options":["ไตรลักษณ์","อริยสัจ 4","อิทธิบาท 4","พรหมวิหาร 4"],"answer":1,"explanation":"พระองค์ตรัสรู้อริยสัจ 4 ได้แก่ ทุกข์ (ความไม่สบายกายใจ), สมุทัย (สาเหตุแห่งทุกข์), นิโรธ (การดับทุกข์), มรรค (หนทางดับทุกข์)"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/2] พระรัตนตรัย: ดวงแก้ว 3 ประการ","difficulty":"easy","question_type":"mcq","question_text":"พระรัตนตรัยอันเป็นที่พึ่งสูงสุดของชาวพุทธ ประกอบด้วยสิ่งใดบ้าง?","options":["พระมหากษัตริย์, พระสงฆ์, ประชาชน","พระพุทธ, พระธรรม, พระสงฆ์","พระพรหม, พระอิศวร, พระนารายณ์","ศีล, สมาธิ, ปัญญา"],"answer":1,"explanation":"พระรัตนตรัยคือ แก้ว 3 ประการ ได้แก่ พระพุทธ (ผู้ตรัสรู้), พระธรรม (คำสั่งสอน), และพระสงฆ์ (ผู้ปฏิบัติตามและสืบทอด)"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/3] หลักธรรม: เบญจศีล (ศีล 5)","difficulty":"easy","question_type":"mcq","question_text":"การไม่พูดโกหก หลอกลวง หรือพูดคำหยาบ ตรงกับการปฏิบัติตามศีลข้อใดในเบญจศีล?","options":["ศีลข้อที่ 1","ศีลข้อที่ 2","ศีลข้อที่ 3","ศีลข้อที่ 4"],"answer":3,"explanation":"ศีลข้อที่ 4 (มุสาวาทา เวรมณี) คือการงดเว้นจากการพูดเท็จ พูดคำหยาบ พูดส่อเสียด และพูดเพ้อเจ้อ"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/3] หลักธรรม: เบญจธรรม 5","difficulty":"medium","question_type":"mcq","question_text":"ธรรมะคู่กับศีลข้อที่ 1 (ไม่ฆ่าสัตว์) ที่สอนให้มีความรัก ความปรารถนาดีต่อผู้อื่น คือข้อใด?","options":["เมตตากรุณา","สัมมาอาชีวะ","กามสังวร","สัจจะ"],"answer":0,"explanation":"เมตตากรุณา คือความรักความเห็นอกเห็นใจผู้อื่น เป็นธรรมะที่เกื้อหนุนศีลข้อที่ 1"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/4] พุทธสาวก พุทธสาวิกา: พระอุรุเวลกัสสปะ","difficulty":"hard","question_type":"mcq","question_text":"พระอุรุเวลกัสสปะ เดิมเคยเป็นผู้นำของนักบวชกลุ่มใดก่อนหันมาบวชในพระพุทธศาสนา?","options":["พราหมณ์ผู้บูชาไฟ (ชฎิล 3 พี่น้อง)","ฤๅษีในป่าหิมพานต์","ปริพาชก","โยคีเปลือย"],"answer":0,"explanation":"พระอุรุเวลกัสสปะและน้องๆ เดิมเป็นชฎิลบูชาไฟ มีบริวารรวม 1,000 คน เมื่อฟังธรรมจากพระพุทธเจ้าจึงขอบวช"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/5] ชาดก: กุฏิทูสกชาดก (ลิงกับนกกระจอก)","difficulty":"medium","question_type":"mcq","question_text":"ชาดกเรื่อง \"กุฏิทูสกชาดก\" (ลิงเกเรทำลายรังนกกระจอก) ให้ข้อคิดสำคัญเรื่องใด?","options":["ไม่ควรสร้างรังบนต้นไม้สูง","การให้คำแนะนำตักเตือนแก่คนพาล ย่อมนำความเดือดร้อนมาสู่ตน","ลิงเป็นสัตว์ที่ฉลาดกว่านก","ควรพึ่งพาอาศัยผู้อื่นเสมอ"],"answer":1,"explanation":"นกกระจอกหวังดีตักเตือนลิงที่เปียกฝน แต่ลิงพาลโกรธจึงทำลายรังนก สอนว่าไม่ควรสั่งสอนคนพาลที่ไม่ยอมรับฟัง"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/6] ศาสนาสากล: ศาสนาอิสลาม","difficulty":"easy","question_type":"mcq","question_text":"ศาสดาและคัมภีร์ศักดิ์สิทธิ์ของศาสนาอิสลามคือข้อใด?","options":["นบีมุฮัมมัด และ คัมภีร์อัลกุรอาน","พระเยซู และ คัมภีร์ไบเบิล","พระพุทธเจ้า และ พระไตรปิฎก","คุรุนานัก และ คัมภีร์อาทิครันถ์"],"answer":0,"explanation":"ศาสนาอิสลามมีนบีมุฮัมมัดเป็นศาสนทูตผู้นำวิวรณ์จากอัลลอฮ์ และมีคัมภีร์อัลกุรอานเป็นคัมภีร์สูงสุด"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/6] ศาสนาคริสต์","difficulty":"easy","question_type":"mcq","question_text":"ศาสดาของศาสนาคริสต์คือใคร และหลักธรรมสำคัญที่สุดคือเรื่องใด?","options":["พระเยซูคริสต์ สอนเรื่องความรักและความเมตตา","โมเสส สอนเรื่องการสู้รบ","พระนารายณ์ สอนเรื่องการอวตาร","พระอินทร์ สอนเรื่องการบำเพ็ญตบะ"],"answer":0,"explanation":"พระเยซูทรงเป็นศาสดาของศาสนาคริสต์ ทรงเน้นหลักความรัก (ความรักต่อพระเจ้าและความรักต่อเพื่อนมนุษย์)"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.1 ป.4/6] ศาสนาพราหมณ์-ฮินดู","difficulty":"medium","question_type":"mcq","question_text":"เทพเจ้าสูงสุด 3 พระองค์ (ตรีมูรติ) ในศาสนาพราหมณ์-ฮินดู ประกอบด้วยเทพองค์ใดบ้าง?","options":["พระพรหม, พระวิษณุ (พระนารายณ์), พระศิวะ (พระอิศวร)","พระอินทร์, พระอาทิตย์, พระจันทร์","พระราม, พระลักษณ์, พระพรต","พระพิฆเนศ, พระแม่กาลี, พระแม่ลักษมี"],"answer":0,"explanation":"ตรีมูรติคือมหาเทพ 3 พระองค์: พระพรหม (ผู้สร้าง), พระวิษณุ (ผู้ปกป้อง), และพระศิวะ (ผู้ทำลาย)"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันมาฆบูชา","difficulty":"easy","question_type":"mcq","question_text":"วันมาฆบูชา (ขึ้น 15 ค่ำ เดือน 3) มีเหตุการณ์สำคัญใดเกิดขึ้น?","options":["พระพุทธเจ้าประสูติ ตรัสรู้ ปรินิพพาน","พระสงฆ์ 1,250 รูปมาประชุมพร้อมกันโดยมิได้นัดหมาย (จาตุรงคสันนิบาต)","พระพุทธเจ้าทรงแสดงปฐมเทศนา","วันถวายพระเพลิงพระพุทธสรีระ"],"answer":1,"explanation":"วันมาฆบูชาเกิดเหตุการณ์จาตุรงคสันนิบาต พระสงฆ์ 1,250 รูปล้วนเป็นพระอรหันต์มาประชุมพร้อมกันโดยมิได้นัดหมาย"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.2 ป.4/1] วันสำคัญทางศาสนา: วันวิสาขบูชา","difficulty":"easy","question_type":"mcq","question_text":"วันวิสาขบูชา (ขึ้น 15 ค่ำ เดือน 6) ได้รับการยกย่องจากองค์การสหประชาชาติ (UN) ให้เป็นวันสำคัญใดของโลก?","options":["วันเยาวชนสากล","วันสันติภาพโลก","วันสากลของสหประชาชาติ (International Day)","วันอนุรักษ์สิ่งแวดล้อมโลก"],"answer":2,"explanation":"สหประชาชาติยกย่องวันวิสาขบูชาเป็นวันสำคัญสากลของโลก เนื่องจากเป็นวันคล้ายวันประสูติ ตรัสรู้ และปรินิพพาน"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.2 ป.4/1] วันอาสาฬหบูชา","difficulty":"medium","question_type":"mcq","question_text":"เหตุการณ์สำคัญที่สุดในวันอาสาฬหบูชา (ขึ้น 15 ค่ำ เดือน 8) คือข้อใด?","options":["เกิดพระสงฆ์รูปแรกในโลก คือ พระอัญญาโกณฑัญญะ และมีพระรัตนตรัยครบองค์ 3","พระพุทธเจ้าแสดงโอวาทปาติโมกข์","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระมหากัสสปะทำสังคายนาครั้งแรก"],"answer":0,"explanation":"พระพุทธเจ้าทรงแสดงปฐมเทศนา \"ธัมมจักกัปปวัตตนสูตร\" โปรดปัญจวัคคีย์ ทำให้เกิดพระสงฆ์รูปแรกและมีพระรัตนตรัยครบ 3 ประการ"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 1.2 ป.4/2] ศาสนพิธีและการเวียนเทียน","difficulty":"easy","question_type":"mcq","question_text":"การเวียนเทียนในวันสำคัญทางพระพุทธศาสนา ต้องเดินเวียนรอบพระอุโบสถในทิศทางใดและกี่รอบ?","options":["เวียนซ้าย 1 รอบ","เวียนขวา (ทักษิณาวรรต) 3 รอบ","เวียนซ้าย 3 รอบ","เวียนไปกลับกี่รอบก็ได้"],"answer":1,"explanation":"เดินเวียนขวาตามเข็มนาฬิกา (ประทักษิณ) 3 รอบ พร้อมน้อมรำลึกถึงพระพุทธ พระธรรม และพระสงฆ์"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 2.1 ป.4/1] สิทธิเด็ก 4 ประการ: สิทธิที่จะมีชีวิตรอด","difficulty":"easy","question_type":"mcq","question_text":"การที่เด็กได้รับการฉีดวัคซีนป้องกันโรคและได้รับอาหารครบ 5 หมู่ จัดอยู่ในสิทธิเด็กด้านใด?","options":["สิทธิที่จะมีชีวิตรอด (Survival)","สิทธิที่จะได้รับการปกป้อง (Protection)","สิทธิที่จะได้รับการพัฒนา (Development)","สิทธิที่จะมีส่วนร่วม (Participation)"],"answer":0,"explanation":"สิทธิที่จะมีชีวิตรอด คือสิทธิในการได้รับการเลี้ยงดู ได้รับอาหาร ที่อยู่อาศัย ยารักษาโรค และการดูแลสุขภาพขั้นพื้นฐาน"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 2.1 ป.4/1] สิทธิที่จะได้รับการพัฒนา","difficulty":"easy","question_type":"mcq","question_text":"การที่เด็กทุกคนต้องได้รับการศึกษาขั้นพื้นฐาน 12 ปีจากรัฐโดยไม่เสียค่าใช้จ่าย ตรงกับสิทธิเด็กข้อใด?","options":["สิทธิที่จะมีส่วนร่วม","สิทธิที่จะได้รับการพัฒนา","สิทธิที่จะมีชีวิตรอด","สิทธิเสรีภาพ"],"answer":1,"explanation":"สิทธิที่จะได้รับการพัฒนา ได้แก่ การศึกษา การเรียนรู้ การเล่นกีฬา และการพัฒนาทางอารมณ์และสติปัญญา"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 2.1 ป.4/1] สิทธิที่จะได้รับการปกป้องคุ้มครอง","difficulty":"medium","question_type":"mcq","question_text":"การกระทำใดเป็นการ \"ละเมิดสิทธิเด็ก\"?","options":["พ่อแม่พาลูกไปเที่ยวพักผ่อนในวันหยุด","คุณครูสอนให้นักเรียนทำการบ้านด้วยตนเอง","การบังคับใช้แรงงานเด็กหรือทำร้ายร่างกายเด็กอย่างทารุณ","โรงเรียนจัดอาหารกลางวันที่มีประโยชน์ให้เด็กรับประทาน"],"answer":2,"explanation":"การใช้แรงงานเด็ก ทำร้าย ทอดทิ้ง หรือแสวงหาประโยชน์โดยมิชอบ ถือเป็นการละเมิดสิทธิเด็กและผิดกฎหมาย"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 2.1 ป.4/2] วัฒนธรรมและประเพณีไทย 4 ภาค","difficulty":"medium","question_type":"mcq","question_text":"ประเพณี \"บุญบั้งไฟ\" และ \"แห่ผีตาโขน\" เป็นประเพณีท้องถิ่นของภาคใดในประเทศไทย?","options":["ภาคเหนือ","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคใต้"],"answer":2,"explanation":"ประเพณีบุญบั้งไฟ (ขอฝนจากพญาแถน) และแห่ผีตาโขน (อ.ด่านซ้าย จ.เลย) เป็นเอกลักษณ์ของภาคอีสาน"},{"subject":"สังคมศึกษา","grade":"ป.4","topic":"[ส 2.1 ป.4/2] ประเพณีภาคเหนือ","difficulty":"medium","question_type":"mcq","question_text":"ประเพณี \"ยี่เป็ง\" (ลอยโคมขึ้นสู่ท้องฟ้า) เป็นประเพณีดั้งเดิมของชาวภาคใด?","options":["ภาคใต้","ภาคเหนือ (ล้านนา)","ภาคกลาง","ภาคตะวันออก"],"answer":1,"explanation":"ประเพณียี่เป็งเป็นประเพณีลอยกระทงและจุดโคมลอยตามวัฒนธรรมล้านนาในภาคเหนือ"}]'::jsonb, 30, 50, 'SOC401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาประวัติศาสตร์ ป.4 (20 ข้อ)', 'ประวัติศาสตร์', 'ป.4', '[{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/1] การนับช่วงเวลา: ทศวรรษ","difficulty":"easy","question_type":"mcq","question_text":"ช่วงเวลา \"ทศวรรษ\" หมายถึงรอบระยะเวลากี่ปี?","options":["5 ปี","10 ปี","50 ปี","100 ปี"],"answer":1,"explanation":"ทศวรรษ (Decade) หมายถึง ช่วงเวลา 10 ปี โดยเริ่มนับจากปีที่ลงท้ายด้วย 0 ไปจนถึงปีที่ลงท้ายด้วย 9"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/1] การนับช่วงเวลา: ศตวรรษ","difficulty":"easy","question_type":"mcq","question_text":"คำว่า \"ศตวรรษ\" หมายถึงรอบระยะเวลากี่ปี?","options":["10 ปี","50 ปี","100 ปี","1,000 ปี"],"answer":2,"explanation":"ศตวรรษ (Century) หมายถึง ช่วงเวลารอบ 100 ปี เริ่มนับจากปีที่ลงท้ายด้วย 1 จนถึงปีที่ลงท้ายด้วย 100 หรือ 00"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/1] การนับช่วงเวลา: สหัสวรรษ","difficulty":"easy","question_type":"mcq","question_text":"ช่วงเวลา \"สหัสวรรษ\" หมายถึงรอบระยะเวลากี่ปี?","options":["100 ปี","500 ปี","1,000 ปี","10,000 ปี"],"answer":2,"explanation":"สหัสวรรษ (Millennium) หมายถึง รอบระยะเวลา 1,000 ปี"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/1] การคำนวณศตวรรษในพุทธศักราช","difficulty":"medium","question_type":"mcq","question_text":"ปี พ.ศ. 2567 จัดอยู่ในพุทธศตวรรษที่เท่าใด?","options":["พุทธศตวรรษที่ 24","พุทธศตวรรษที่ 25","พุทธศตวรรษที่ 26","พุทธศตวรรษที่ 27"],"answer":2,"explanation":"พุทธศตวรรษที่ 26 เริ่มนับจาก พ.ศ. 2501 ถึง พ.ศ. 2600 ดังนั้นปี พ.ศ. 2567 จึงอยู่ในพุทธศตวรรษที่ 26"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/1] การคำนวณคริสต์ศตวรรษ","difficulty":"hard","question_type":"mcq","question_text":"ปี ค.ศ. 2024 จัดอยู่ในคริสต์ศตวรรษที่เท่าใด?","options":["คริสต์ศตวรรษที่ 19","คริสต์ศตวรรษที่ 20","คริสต์ศตวรรษที่ 21","คริสต์ศตวรรษที่ 22"],"answer":2,"explanation":"คริสต์ศตวรรษที่ 21 เริ่มต้นตั้งแต่วันที่ 1 มกราคม ค.ศ. 2001 ถึง ค.ศ. 2100"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] การแบ่งยุคสมัย: ยุคก่อนประวัติศาสตร์และยุคประวัติศาสตร์","difficulty":"easy","question_type":"mcq","question_text":"เกณฑ์สำคัญที่สุดที่นักประวัติศาสตร์ใช้แบ่งระหว่าง \"ยุคก่อนประวัติศาสตร์\" กับ \"ยุคประวัติศาสตร์\" คือข้อใด?","options":["การรู้จักใช้ไฟ","การประดิษฐ์และบันทึกด้วยตัวอักษร","การสร้างบ้านเรือน","การรู้จักเพาะปลูกพืช"],"answer":1,"explanation":"ยุคประวัติศาสตร์เริ่มต้นเมื่อมนุษย์เริ่มรู้จักการประดิษฐ์ตัวอักษรและบันทึกเรื่องราวเป็นลายลักษณ์อักษร"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] ยุคก่อนประวัติศาสตร์: ยุคหินเก่า","difficulty":"medium","question_type":"mcq","question_text":"ลักษณะการดำรงชีวิตของมนุษย์ใน \"ยุคหินเก่า\" ตรงกับข้อใด?","options":["สร้างบ้านแปงเมืองอย่างเป็นระเบียบ","เร่ร่อนเก็บของป่า ล่าสัตว์ อาศัยตามถ้ำหรือเพิงผา ใช้เครื่องมือหินกะเทาะหยาบๆ","รู้จักการทำเกษตรกรรมและเลี้ยงสัตว์ในคอก","รู้จักการถลุงแร่เหล็กสร้างดาบ"],"answer":1,"explanation":"มนุษย์ยุคหินเก่ายังไม่ตั้งถิ่นฐานเป็นหลักแหล่ง อาศัยถ้ำธรรมชาติ ล่าสัตว์ และใช้เครื่องมือหินกะเทาะแบบหยาบ"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] ยุคหินใหม่","difficulty":"medium","question_type":"mcq","question_text":"การเปลี่ยนแปลงสำคัญที่สุดที่ทำให้มนุษย์ก้าวเข้าสู่ \"ยุคหินใหม่\" คือข้อใด?","options":["การเริ่มทำการเพาะปลูก เลี้ยงสัตว์ และสร้างชุมชนถาวร รู้จักขัดเครื่องมือหินจนเรียบคม","การค้นพบเครื่องบิน","การเริ่มใช้เงินตรา","การมีคอมพิวเตอร์"],"answer":0,"explanation":"ยุคหินใหม่เกิดการปฏิวัติเกษตรกรรม มนุษย์เริ่มตั้งถิ่นฐานเป็นหลักแหล่ง ทำเครื่องปั้นดินเผา และใช้เครื่องมือหินขัด"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] ยุคโลหะ: ยุคสัมฤทธิ์","difficulty":"hard","question_type":"mcq","question_text":"โลหะ \"สัมฤทธิ์\" เกิดจากการหลอมผสมระหว่างแร่ชนิดใดเข้าด้วยกัน?","options":["ทองแดง กับ ดีบุก","เหล็ก กับ สังกะสี","ทองคำ กับ เงิน","อะลูมิเนียม กับ ตะกั่ว"],"answer":0,"explanation":"สัมฤทธิ์ (Bronze) เป็นโลหะผสมระหว่างทองแดงกับดีบุก มีความแข็งแรงกว่าทองแดงบริสุทธิ์"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] ยุคโลหะ: ยุคเหล็ก","difficulty":"medium","question_type":"mcq","question_text":"ข้อดีของเครื่องมือเครื่องใช้ที่ทำจาก \"เหล็ก\" เมื่อเทียบกับสัมฤทธิ์คืออะไร?","options":["มีสีสันสวยงามกว่า","มีความแข็งแกร่ง ทนทาน และมีแหล่งแร่หาง่ายกว่า จึงนำมาทำอาวุธและคันไถ","มีน้ำหนักเบากว่ามาก","ละลายในน้ำได้"],"answer":1,"explanation":"เหล็กมีความแข็งแรง ทนทาน และคมกว่าสัมฤทธิ์มาก ทำให้การเกษตร (คันไถ) และอาวุธมีประสิทธิภาพสูงขึ้น"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] การนับศักราช: พ.ศ. และ ค.ศ.","difficulty":"easy","question_type":"mcq","question_text":"พุทธศักราช (พ.ศ.) เริ่มนับเมื่อเกิดเหตุการณ์ใด?","options":["พระพุทธเจ้าประสูติ","พระพุทธเจ้าตรัสรู้","พระพุทธเจ้าเสด็จดับขันธ์ปรินิพพาน","พระพุทธเจ้าทรงแสดงปฐมเทศนา"],"answer":2,"explanation":"ในประเทศไทย พุทธศักราชเริ่มนับ พ.ศ. 1 เมื่อพระพุทธเจ้าเสด็จดับขันธ์ปรินิพพานไปแล้วครบ 1 ปี"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] คริสต์ศักราช (ค.ศ.)","difficulty":"easy","question_type":"mcq","question_text":"คริสต์ศักราช (ค.ศ.) เริ่มนับเริ่มต้นจากปีที่เกิดเหตุการณ์ใด?","options":["ปีที่พระเยซูสิ้นพระชนม์","ปีที่พระเยซูประสูติ","ปีที่สร้างกรุงโรม","ปีที่ค้นพบทวีปอเมริกา"],"answer":1,"explanation":"คริสต์ศักราชเริ่มนับปี ค.ศ. 1 จากปีที่พระเยซูคริสต์ประสูติ"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] การเทียบ พ.ศ. และ ค.ศ.","difficulty":"medium","question_type":"mcq","question_text":"การแปลง พ.ศ. ให้เป็น ค.ศ. ต้องนำตัวเลขใดมาลบออก?","options":["543","621","1181","2324"],"answer":0,"explanation":"พ.ศ. เริ่มก่อน ค.ศ. อยู่ 543 ปี ดังนั้น ค.ศ. = พ.ศ. - 543 (เช่น 2567 - 543 = 2024)"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] ฮิจเราะห์ศักราช (ฮ.ศ.)","difficulty":"hard","question_type":"mcq","question_text":"ฮิจเราะห์ศักราช (ฮ.ศ.) เป็นศักราชที่ใช้ในศาสนาใด และเริ่มนับจากเหตุการณ์ใด?","options":["ศาสนาพุทธ เริ่มนับวันตรัสรู้","ศาสนาคริสต์ เริ่มนับวันล้างบาป","ศาสนาอิสลาม เริ่มนับจากปีที่ท่านนบีมุฮัมมัดอพยพจากเมืองมักกะฮ์ไปยังเมืองมะดีนะฮ์","ศาสนาพราหมณ์ เริ่มนับวันสร้างโลก"],"answer":2,"explanation":"ฮิจเราะห์ศักราชเริ่มนับเมื่อท่านนบีมุฮัมมัดนำชาวมุสลิมอพยพ (ฮิจเราะห์) จากมักกะฮ์ไปมะดีนะฮ์"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.1 ป.4/2] รัตนโกสินทร์ศก (ร.ศ.)","difficulty":"hard","question_type":"mcq","question_text":"รัตนโกสินทร์ศก (ร.ศ.) เริ่มนับ ร.ศ. 1 ตรงกับปีใด?","options":["ปีที่สถาปนากรุงสุโขทัย","ปีที่สถาปนากรุงศรีอยุธยา","ปีที่พระบาทสมเด็จพระพุทธยอดฟ้าจุฬาโลกมหาราช (ร.1) สถาปนากรุงรัตนโกสินทร์ (พ.ศ. 2325)","ปีที่เปลี่ยนแปลงการปกครอง พ.ศ. 2475"],"answer":2,"explanation":"ร.ศ. เริ่มนับ ร.ศ. 1 ในปี พ.ศ. 2325 ซึ่งเป็นปีที่สถาปนากรุงเทพฯ เป็นราชธานี"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.2 ป.4/1] ประเภทของหลักฐานทางประวัติศาสตร์: หลักฐานชั้นต้น","difficulty":"easy","question_type":"mcq","question_text":"หลักฐานทางประวัติศาสตร์ในข้อใดจัดเป็น \"หลักฐานชั้นต้น (ปฐมภูมิ)\"?","options":["ศิลาจารึกหลักที่ 1 ที่สร้างขึ้นในสมัยสุโขทัย","หนังสือแบบเรียนประวัติศาสตร์ที่เขียนขึ้นเมื่อวาน","ภาพยนตร์ย้อนยุคอิงประวัติศาสตร์","บทความวิเคราะห์ประวัติศาสตร์ในอินเทอร์เน็ต"],"answer":0,"explanation":"หลักฐานชั้นต้นคือหลักฐานที่ถูกบันทึกหรือสร้างขึ้นโดยผู้ที่อยู่ในเหตุการณ์หรือช่วงเวลาที่เกิดเหตุการณ์นั้นจริง"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.2 ป.4/1] หลักฐานชั้นรอง (ทุติยภูมิ)","difficulty":"medium","question_type":"mcq","question_text":"ข้อใดจัดเป็น \"หลักฐานชั้นรอง\"?","options":["โครงกระดูกมนุษย์โบราณ","เครื่องปั้นดินเผาบ้านเชียง","หนังสือประวัติศาสตร์สุโขทัยที่นักวิชาการเรียบเรียงขึ้นในปัจจุบัน","กำแพงเมืองโบราณ"],"answer":2,"explanation":"หลักฐานชั้นรองถูกรวบรวมและเรียบเรียงขึ้นภายหลังจากเหตุการณ์นั้นผ่านพ้นไปแล้ว โดยอาศัยข้อมูลจากหลักฐานชั้นต้น"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.2 ป.4/1] หลักฐานที่เป็นลายลักษณ์อักษร","difficulty":"easy","question_type":"mcq","question_text":"หลักฐานในข้อใดเป็น \"หลักฐานที่เป็นลายลักษณ์อักษร\"?","options":["จดหมายเหตุวันวลิต","ขวานหินขัด","ลูกปัดแก้วโบราณ","ซากเจดีย์เก่า"],"answer":0,"explanation":"หลักฐานที่เป็นลายลักษณ์อักษรคือหลักฐานที่มีการบันทึกด้วยตัวหนังสือ เช่น ศิลาจารึก พงศาวดาร จดหมายเหตุ ใบลาน"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.2 ป.4/1] หลักฐานที่ไม่เป็นลายลักษณ์อักษร","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นหลักฐานทางประวัติศาสตร์ที่ \"ไม่เป็นลายลักษณ์อักษร\"?","options":["พงศาวดารกรุงศรีอยุธยา","ศิลาจารึกวัดศรีชุม","หม้อดินเผาลายเขียนสีบ้านเชียง","สนธิสัญญาเบาว์ริง"],"answer":2,"explanation":"โบราณวัตถุ โบราณสถาน โครงกระดูก อาวุธ เครื่องประดับ จัดเป็นหลักฐานที่ไม่เป็นลายลักษณ์อักษร"},{"subject":"ประวัติศาสตร์","grade":"ป.4","topic":"[ส 4.2 ป.4/2] แหล่งโบราณคดีบ้านเชียง","difficulty":"medium","question_type":"mcq","question_text":"แหล่งโบราณคดี \"บ้านเชียง\" ซึ่งได้รับการขึ้นทะเบียนเป็นมรดกโลกทางวัฒนธรรม ตั้งอยู่ในจังหวัดใด?","options":["จังหวัดเชียงใหม่","จังหวัดอุดรธานี","จังหวัดขอนแก่น","จังหวัดนครราชสีมา"],"answer":1,"explanation":"แหล่งโบราณคดีบ้านเชียงตั้งอยู่ที่ อ.หนองหาน จ.อุดรธานี มีชื่อเสียงด้านภาชนะดินเผาลายเขียนสีแดงและเครื่องสำริด"}]'::jsonb, 30, 50, 'HIST401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาภาษาอังกฤษ ป.4 (20 ข้อ)', 'ภาษาอังกฤษ', 'ป.4', '[{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/1] Classroom Instructions and Commands","difficulty":"easy","question_type":"mcq","question_text":"When the teacher says, \"Open your book to page 25,\" what should you do?","options":["ปิดหนังสือหน้าที่ 25","เปิดหนังสือหน้าที่ 25","เขียนชื่อในหน้าที่ 25","ส่งหนังสือคืนครู"],"answer":1,"explanation":"\"Open your book to page 25\" แปลว่า ให้เปิดหนังสือไปที่หน้าที่ 25"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/1] Classroom Commands","difficulty":"easy","question_type":"mcq","question_text":"What is the opposite of the command \"Stand up\"?","options":["Sit down","Turn around","Look at the board","Be quiet"],"answer":0,"explanation":"\"Stand up\" แปลว่า ยืนขึ้น คำตรงข้ามคือ \"Sit down\" ซึ่งแปลว่า นั่งลง"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Phonics: Short and Long Vowels","difficulty":"medium","question_type":"mcq","question_text":"Which word has the same vowel sound as \"cake\" /eɪ/?","options":["cat","lake","car","ball"],"answer":1,"explanation":"คำว่า \"lake\" ออกเสียงสระเอ (long a sound: /eɪ/) เหมือนกับคำว่า \"cake\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Phonics: Consonant Blends","difficulty":"easy","question_type":"mcq","question_text":"Which word begins with the blend sound /fl/?","options":["frog","flag","drum","clock"],"answer":1,"explanation":"\"flag\" ขึ้นต้นด้วยพยัญชนะควบกล้ำ fl- (ฟล)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Signs and Public Symbols","difficulty":"easy","question_type":"mcq","question_text":"You see a sign with a cigarette and a red cross over it. What does it mean?","options":["No parking","No smoking","No food or drink","No taking photos"],"answer":1,"explanation":"ป้ายรูปบุหรี่มีแถบกากบาทสีแดง หมายถึง \"No smoking\" (ห้ามสูบบุหรี่)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Library Signs","difficulty":"easy","question_type":"mcq","question_text":"Which sign is most suitable for a school library?","options":["Please be quiet","Danger! Do not enter","Turn right","Drive fast"],"answer":0,"explanation":"ในห้องสมุดควรมีป้าย \"Please be quiet\" (กรุณาเงียบ / งดใช้เสียง)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Reading Short Comprehension","difficulty":"medium","question_type":"mcq","question_text":"Read the text: \"Anna has a brown puppy named Lucky. Lucky likes to run in the park and fetch a small red ball.\" What is Lucky?","options":["A kitten","A puppy","A bird","A rabbit"],"answer":1,"explanation":"ในเนื้อเรื่องระบุชัดเจนว่า \"Anna has a brown puppy named Lucky.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Reading Details","difficulty":"medium","question_type":"mcq","question_text":"From the text about Lucky: What color is the ball that Lucky likes to fetch?","options":["Yellow","Green","Red","Blue"],"answer":2,"explanation":"ในเนื้อเรื่องระบุว่า \"...and fetch a small red ball.\" ดังนั้นลูกบอลเป็นสีแดง"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Rhyming Words","difficulty":"easy","question_type":"mcq","question_text":"Which word rhymes with \"sun\"?","options":["fun","sit","top","hot"],"answer":0,"explanation":"\"sun\" (/sʌn/) มีเสียงสัมผัสสระและตัวสะกดตรงกับคำว่า \"fun\" (/fʌn/)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/3] Traffic Signs","difficulty":"easy","question_type":"mcq","question_text":"What does a red octagonal sign with the word \"STOP\" instruct drivers to do?","options":["Go faster","Turn around","Stop the vehicle completely","Park here"],"answer":2,"explanation":"ป้าย STOP สั่งให้ผู้ขับขี่หยุดรถโดยสมบูรณ์ก่อนเพื่อความปลอดภัย"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/2] Digraph Sounds: /sh/ and /ch/","difficulty":"medium","question_type":"mcq","question_text":"Which word contains the /tʃ/ sound as in \"chair\"?","options":["ship","chocolate","shoe","fish"],"answer":1,"explanation":"\"chocolate\" ออกเสียงพยัญชนะต้น ch- (/tʃ/) เหมือนคำว่า \"chair\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.1 ป.4/4] Understanding Timetables","difficulty":"medium","question_type":"mcq","question_text":"Look at Tom''s timetable: \"09:00 - English, 10:00 - Math, 11:00 - Science, 12:00 - Lunch.\" What subject does Tom study at 10:00?","options":["English","Math","Science","Art"],"answer":1,"explanation":"จากตารางเรียน เวลา 10:00 น. ทอมเรียนวิชาคณิตศาสตร์ (Math)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/1] Greetings and How Are You","difficulty":"easy","question_type":"mcq","question_text":"A: \"Good morning, Tom! How are you today?\"\nB: \"________, thank you. And you?\"","options":["I am 10 years old","I am fine","My name is Tom","I am from Thailand"],"answer":1,"explanation":"เมื่อมีคนถามว่า \"How are you today?\" คำตอบมาตรฐานคือ \"I am fine / I am good, thank you.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/1] Introductions","difficulty":"easy","question_type":"mcq","question_text":"A: \"Nice to meet you, Lisa.\"\nB: \"____________________\"","options":["Good night","Nice to meet you, too","Goodbye","You are welcome"],"answer":1,"explanation":"เมื่อผู้อื่นพูดว่า \"Nice to meet you.\" ควรตอบกลับว่า \"Nice to meet you, too.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/2] Asking for Permission","difficulty":"medium","question_type":"mcq","question_text":"Student: \"May I go to the restroom, please?\"\nTeacher: \"________\"","options":["Yes, you may.","No, thank you.","I am sorry.","You are tall."],"answer":0,"explanation":"เมื่อขออนุญาตด้วย \"May I...?\" คุณครูอนุญาตจะตอบว่า \"Yes, you may.\" หรือ \"Sure.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/2] Offering Help","difficulty":"medium","question_type":"mcq","question_text":"A: \"Can I help you carry these heavy books?\"\nB: \"____________________\"","options":["No, I am not.","Thank you very much. That is very kind of you.","I am hungry.","It is 5 o''clock."],"answer":1,"explanation":"เมื่อมีผู้เสนอความช่วยเหลือและเราต้องการรับ ควรตอบขอบคุณอย่างสุภาพว่า \"Thank you very much.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/3] Expressing Likes and Dislikes","difficulty":"easy","question_type":"mcq","question_text":"A: \"Do you like apples?\"\nB: \"Yes, ________. They are delicious.\"","options":["I do","I am","I can","I like not"],"answer":0,"explanation":"คำถามที่ขึ้นต้นด้วย \"Do you...?\" เวลาตอบรับแบบสั้นจะใช้ \"Yes, I do.\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/3] Asking About Food Preferences","difficulty":"medium","question_type":"mcq","question_text":"A: \"What is your favorite fruit?\"\nB: \"My favorite fruit is ________.\"","options":["pizza","mango","fried rice","milk"],"answer":1,"explanation":"ผลไม้ (fruit) ในตัวเลือกมีเพียงอย่างเดียวคือ \"mango\" (มะม่วง)"},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/4] Asking Feelings and Emotions","difficulty":"easy","question_type":"mcq","question_text":"Look at the picture of a boy drinking water after playing sports. How does he feel?","options":["He is thirsty.","He is cold.","He is sleepy.","He is angry."],"answer":0,"explanation":"คนที่ดื่มน้ำหลังเล่นกีฬา คือรู้สึกกระหายน้ำ หรือ \"thirsty\""},{"subject":"ภาษาอังกฤษ","grade":"ป.4","topic":"[ต 1.2 ป.4/4] Expressing Feelings","difficulty":"easy","question_type":"mcq","question_text":"A: \"Why are you smiling?\"\nB: \"Because I am very ________ today. It is my birthday!\"","options":["sad","happy","tired","sick"],"answer":1,"explanation":"ในวันเกิดและกำลังยิ้ม แสดงถึงความรู้สึกมีความสุข หรือ \"happy\""}]'::jsonb, 30, 50, 'ENG401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาสุขศึกษา ป.4 (20 ข้อ)', 'สุขศึกษา', 'ป.4', '[{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/1] การเจริญเติบโตและพัฒนาการของร่างกายตามวัย","difficulty":"easy","question_type":"mcq","question_text":"เครื่องมือใดใช้สำหรับประเมินการเจริญเติบโตทางร่างกายของนักเรียนว่าสมวัยหรือไม่?","options":["เครื่องวัดความดันโลหิต","เครื่องชั่งน้ำหนักและที่วัดส่วนสูง","เทอร์โมมิเตอร์วัดไข้","สายวัดรอบอก"],"answer":1,"explanation":"การชั่งน้ำหนักและวัดส่วนสูงตามเกณฑ์มาตรฐานของกรมอนามัย ใช้ประเมินการเจริญเติบโตของเด็กตามวัย"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อลาย","difficulty":"medium","question_type":"mcq","question_text":"กล้ามเนื้อชนิดใดที่ยึดติดกับกระดูก ทำงานภายใต้อำนาจจิตใจ (เราสั่งให้ขยับได้ เช่น กล้ามแขน ขา)?","options":["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อกระเพาะอาหาร"],"answer":0,"explanation":"กล้ามเนื้อลาย (Skeletal muscle) ยึดติดกับกระดูกและทำงานภายใต้การควบคุมของจิตใจ เช่น กล้ามเนื้อแขน ขา ลำตัว"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/2] ระบบกล้ามเนื้อ: กล้ามเนื้อเรียบ","difficulty":"medium","question_type":"mcq","question_text":"กล้ามเนื้อที่พบในอวัยวะภายใน เช่น ผนังกระเพาะอาหาร ลำไส้ หลอดเลือด จัดเป็นกล้ามเนื้อชนิดใด?","options":["กล้ามเนื้อลาย","กล้ามเนื้อเรียบ","กล้ามเนื้อหัวใจ","กล้ามเนื้อโครงร่าง"],"answer":1,"explanation":"กล้ามเนื้อเรียบ (Smooth muscle) อยู่ตามอวัยวะภายในและทำงานอยู่นอกอำนาจจิตใจโดยอัตโนมัติ"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/2] กล้ามเนื้อหัวใจ","difficulty":"easy","question_type":"mcq","question_text":"กล้ามเนื้อหัวใจมีลักษณะการทำงานอย่างไร?","options":["ทำงานเฉพาะตอนที่เราตื่นนอน","ทำงานบีบตัวและคลายตัวตลอดชีวิตอยู่นอกอำนาจจิตใจ","เราสามารถสั่งให้หยุดเต้นได้ตามต้องการ","ทำงานเฉพาะเวลาออกกำลังกาย"],"answer":1,"explanation":"กล้ามเนื้อหัวใจทำงานบีบคลายตัวสูบฉีดเลือดโดยอัตโนมัติตลอดเวลา ไม่สามารถสั่งให้หยุดเต้นได้"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/2] การดูแลรักษาระบบกล้ามเนื้อ","difficulty":"easy","question_type":"mcq","question_text":"สารอาหารประเภทใดจำเป็นที่สุดในการเสริมสร้างและซ่อมแซมกล้ามเนื้อ?","options":["คาร์โบไฮเดรต","โปรตีน (เช่น เนื้อสัตว์ ไข่ นม ถั่ว)","ไขมัน","วิตามินซี"],"answer":1,"explanation":"โปรตีนมีกรดอะมิโนที่ช่วยสร้างและซ่อมแซมเส้นใยกล้ามเนื้อที่สึกหรอ"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/3] ระบบกระดูกและข้อต่อ: หน้าที่ของโครงกระดูก","difficulty":"easy","question_type":"mcq","question_text":"หน้าที่สำคัญของโครงกระดูกในร่างกายมนุษย์คือข้อใด?","options":["เป็นโครงร่างพยุงร่างกาย ปกป้องอวัยวะภายใน และเป็นที่เกาะของกล้ามเนื้อ","สร้างน้ำย่อยอาหาร","ลำเลียงออกซิเจนในเลือด","ขับเหงื่อระบายความร้อน"],"answer":0,"explanation":"กระดูกช่วยค้ำจุนร่างกาย ป้องกันอวัยวะสำคัญ (เช่น กะโหลกป้องกันสมอง ซี่โครงป้องกันหัวใจและปอด) และช่วยในการเคลื่อนไหว"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/3] กระดูกซี่โครง","difficulty":"easy","question_type":"mcq","question_text":"กระดูกซี่โครงทำหน้าที่สำคัญในการปกป้องอวัยวะภายในใดเป็นหลัก?","options":["สมองและตา","หัวใจและปอด","กระเพาะอาหารและลำไส้ใหญ่","ตับและไต"],"answer":1,"explanation":"กรงกระดูกซี่โครงทำหน้าที่เหมือนเกราะป้องกันหัวใจและปอดจากการกระแทกภายนอก"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/3] แร่ธาตุบำรุงกระดูกและฟัน","difficulty":"easy","question_type":"mcq","question_text":"แร่ธาตุชนิดใดมีความสำคัญที่สุดในการเสริมสร้างความแข็งแรงของกระดูกและฟัน?","options":["ธาตุเหล็ก","แคลเซียมและฟอสฟอรัส","โซเดียม","ไอโอดีน"],"answer":1,"explanation":"แคลเซียมและฟอสฟอรัส (พบมากในนม ปลาเล็กปลาน้อย ผักใบเขียว) ช่วยให้กระดูกและฟันแข็งแรง"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/3] การดูแลรักษาข้อต่อและกระดูก","difficulty":"medium","question_type":"mcq","question_text":"พฤติกรรมในข้อใดช่วยป้องกันปัญหากระดูกสันหลังคดงอได้ดีที่สุด?","options":["นั่งหลังค่อมทำการบ้าน","สะพายกระเป๋าหนักๆ เพียงข้างเดียวตลอดเวลา","นั่งและยืนตัวตรง และสะพายกระเป๋านักเรียนแบบเป้สองสายน้ำหนักพอเหมาะ","นอนคว่ำอ่านหนังสือ"],"answer":2,"explanation":"การจัดบุคลิกภาพนั่งยืนหลังตรง และการกระจายน้ำหนักกระเป๋าเป้สองข้าง ช่วยรักษาสมดุลของแนวกระดูกสันหลัง"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/2] การอบอุ่นร่างกาย (Warm-up)","difficulty":"easy","question_type":"mcq","question_text":"การอบอุ่นร่างกาย (Warm-up) และยืดเหยียดกล้ามเนื้อก่อนเล่นกีฬามีประโยชน์อย่างไร?","options":["ช่วยเพิ่มความอบอุ่นของร่างกายและป้องกันการบาดเจ็บของกล้ามเนื้อและข้อต่อ","ทำให้เหนื่อยล้าเร็วกว่าปกติ","ทำให้ไม่ต้องฝึกซ้อมกีฬา","ช่วยให้นอนหลับได้ทันที"],"answer":0,"explanation":"การวอร์มอัพช่วยเพิ่มอุณหภูมิร่างกาย กระตุ้นการไหลเวียนเลือด และเตรียมความพร้อมของกล้ามเนื้อเพื่อลดการบาดเจ็บ"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/3] ข้อต่อในร่างกาย","difficulty":"medium","question_type":"mcq","question_text":"ข้อต่อบริเวณ \"หัวไหล่และสะโพก\" เป็นข้อต่อชนิดใดที่หมุนได้รอบทิศทาง?","options":["ข้อต่อแบบบานพับ","ข้อต่อแบบลูกกลมในเบ้า (Ball and socket)","ข้อต่อแบบเดือย","ข้อต่อที่เคลื่อนไหวไม่ได้"],"answer":1,"explanation":"ข้อต่อแบบลูกกลมในเบ้าที่หัวไหล่และข้อสะโพกช่วยให้แขนและขาสามารถหมุนได้รอบทิศทาง"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 1.1 ป.4/1] วิตามินดีกับกระดูก","difficulty":"medium","question_type":"mcq","question_text":"ร่างกายของเราสามารถสร้างวิตามินดีได้เองเมื่อผิวหนังสัมผัสกับสิ่งใดในปริมาณที่เหมาะสมในยามเช้า?","options":["สายฝน","แสงแดดอ่อนๆ ยามเช้า","ลมหนาว","ไอหมอก"],"answer":1,"explanation":"แสงแดดยามเช้ามีรังสี UVB ที่ช่วยกระตุ้นให้ผิวหนังสังเคราะห์วิตามินดี ซึ่งช่วยในการดูดซึมแคลเซียมเข้าสู่กระดูก"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/1] คุณลักษณะของครอบครัวที่อบอุ่น","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นลักษณะสำคัญของ \"ครอบครัวที่อบอุ่น\"?","options":["สมาชิกต่างคนต่างอยู่ ไม่พูดคุยกัน","สมาชิกในครอบครัวมีความรัก ความเข้าใจ และพูดคุยปรึกษากันด้วยเหตุผล","พ่อแม่ซื้อของขวัญราคาแพงให้ลูกตลอดเวลาแต่ไม่มีเวลาให้","ใช้อารมณ์และความรุนแรงตัดสินปัญหา"],"answer":1,"explanation":"ครอบครัวที่อบอุ่นเกิดจากความรัก ความเอาใจใส่ การให้เกียรติ และการสื่อสารที่ดีระหว่างกัน"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/1] บทบาทหน้าที่ของลูกในครอบครัว","difficulty":"easy","question_type":"mcq","question_text":"นักเรียนสามารถแสดงความกตัญญูและช่วยเหลือครอบครัวได้อย่างไร?","options":["ช่วยทำงานบ้านตามกำลังความสามารถ และตั้งใจเรียนหนังสือ","ขอเงินไปเล่นเกมออนไลน์","เกี่ยงงานบ้านกับพี่น้อง","ออกไปเที่ยวนอกบ้านโดยไม่บอกผู้ปกครอง"],"answer":0,"explanation":"การตั้งใจเรียนหนังสือและช่วยเหลืองานบ้านเล็กๆ น้อยๆ เช่น กวาดบ้าน ล้างจาน ช่วยแบ่งเบาภาระของพ่อแม่ได้ดีที่สุด"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/2] การสร้างและรักษาสัมพันธภาพกับเพื่อน","difficulty":"easy","question_type":"mcq","question_text":"การปฏิบัติตนข้อใดช่วยให้เป็นที่รักและมีสัมพันธภาพที่ดีกับเพื่อนๆ?","options":["ชอบล้อเลียนปมด้อยของเพื่อน","มีน้ำใจ เอื้อเฟื้อเผื่อแผ่ และช่วยเหลือเพื่อนด้วยความจริงใจ","เอาแต่ใจตนเองเป็นหลัก","ยุยงให้เพื่อนทะเลาะกัน"],"answer":1,"explanation":"ความเอื้อเฟื้อ มีน้ำใจ ช่วยเหลือ และรับฟังความคิดเห็นของเพื่อนช่วยสร้างมิตรภาพที่ยั่งยืน"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/2] การแก้ปัญหาความขัดแย้งกับเพื่อน","difficulty":"medium","question_type":"mcq","question_text":"เมื่อเกิดความเข้าใจผิดหรือไม่เข้าใจกันกับเพื่อน ควรแก้ไขปัญหาอย่างไร?","options":["ใช้กำลังชกต่อยตัดสิน","เปิดใจพูดคุยกันด้วยเหตุผลและรับฟังอีกฝ่ายอย่างใจเย็น","โพสต์ประจานเพื่อนลงบนอินเทอร์เน็ต","เลิกคบเพื่อนทุกคนในห้อง"],"answer":1,"explanation":"การเจรจาด้วยเหตุผลและความใจเย็นเป็นวิธีแก้ปัญหาความขัดแย้งที่ถูกต้องและสร้างสรรค์"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/3] พฤติกรรมที่เหมาะสมกับเพศสภาพ","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็นการปฏิบัติตนที่สุภาพและให้เกียรติซึ่งกันและกันระหว่างเพศ?","options":["การใช้คำพูดที่สุภาพ ไม่ล้อเลียนหรือรังแกผู้อื่น","การแตะเนื้อต้องตัวผู้อื่นโดยที่เขาไม่ยินยอม","การดูถูกผู้ที่มีเพศสภาพแตกต่างจากตน","การแย่งชิงสิ่งของของผู้อื่น"],"answer":0,"explanation":"การให้เกียรติซึ่งกันและกัน ไม่ว่าจะเพศใด การใช้คำพูดสุภาพและเคารพสิทธิส่วนบุคคลเป็นสิ่งสำคัญ"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/3] การป้องกันตนเองจากการล่วงละเมิดทางเพศ","difficulty":"medium","question_type":"mcq","question_text":"หากมีคนแปลกหน้ามาขอกอด สัมผัสอวัยวะส่วนตัว หรือชวนไปในที่ลับตาคน ควรทำอย่างไร?","options":["ยอมตามใจเพราะเขาให้อมยิ้ม","พูดปฏิเสธเสียงดังว่า \"อย่าทำ!\" แล้วรีบวิ่งหนีไปหาผู้ใหญ่หรือครูทันที","เก็บไว้เป็นความลับคนเดียว","ยืนเฉยๆ ไม่ตอบโต้"],"answer":1,"explanation":"ต้องปฏิเสธอย่างหนักแน่น รีบหนีออกจากสถานการณ์เสี่ยง และแจ้งพ่อแม่หรือคุณครูทันที"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/3] ร่างกายของเรา สิทธิของเรา (Body Safety)","difficulty":"easy","question_type":"mcq","question_text":"ส่วนใดของร่างกายที่ถือเป็น \"พื้นที่ส่วนตัว (Private Parts)\" ที่ผู้อื่นไม่มีสิทธิ์มาสัมผัสหรือขอดู?","options":["มือและแขน","บริเวณที่ปกคลุมด้วยชุดชั้นใน (หน้าอก อวัยวะเพศ และก้น)","เส้นผม","ฝ่าเท้า"],"answer":1,"explanation":"อวัยวะภายใต้ชุดชั้นในเป็นพื้นที่ส่วนตัวที่ห้ามมิให้ใครมาสัมผัสหรือขอดูโดยเด็ดขาด"},{"subject":"สุขศึกษา","grade":"ป.4","topic":"[พ 2.1 ป.4/1] ความหลากหลายทางครอบครัว","difficulty":"medium","question_type":"mcq","question_text":"ครอบครัวที่ประกอบด้วย ปู่ ย่า พ่อ แม่ ลูก หลาน อาศัยอยู่ร่วมกันในบ้านหลังเดียวกัน เรียกว่าครอบครัวแบบใด?","options":["ครอบครัวเดี่ยว","ครอบครัวขยาย","ครอบครัวข้ามรุ่น","ครอบครัวเลี้ยงเดี่ยว"],"answer":1,"explanation":"ครอบครัวขยาย (Extended family) คือครอบครัวที่มีญาติหลายรุ่นอาศัยอยู่ร่วมชายคาเดียวกัน"}]'::jsonb, 30, 50, 'HEA401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาศิลปะ ป.4 (20 ข้อ)', 'ศิลปะ', 'ป.4', '[{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/1] รูปร่างและรูปทรงในธรรมชาติและสิ่งแวดล้อม","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดอธิบายความแตกต่างระหว่าง \"รูปร่าง\" (Shape) และ \"รูปทรง\" (Form) ได้ถูกต้อง?","options":["รูปร่างมี 2 มิติ (กว้างและยาว) ส่วนรูปทรงมี 3 มิติ (มีความหนาหรือความลึกเพิ่มขึ้น)","รูปร่างมี 3 มิติ ส่วนรูปทรงมี 2 มิติ","รูปร่างมีเฉพาะทรงกลมเท่านั้น","รูปร่างและรูปทรงเหมือนกันทุกประการ"],"answer":0,"explanation":"รูปร่างมี 2 มิติคือความกว้างและความยาวแบนๆ ส่วนรูปทรงมี 3 มิติคือมีมวล ปริมาตร ความหนา และความลึก"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/1] รูปทรงเรขาคณิต","difficulty":"easy","question_type":"mcq","question_text":"กล่องของขวัญและลูกเต๋า จัดเป็นรูปทรงชนิดใด?","options":["รูปทรงกระบอก","รูปทรงลูกบาศก์ (สี่เหลี่ยมลูกบาศก์)","รูปทรงกรวย","รูปทรงกลม"],"answer":1,"explanation":"ลูกเต๋าและกล่องทรงสี่เหลี่ยมจัตุรัส มีด้านทั้ง 6 ด้านเป็นสี่เหลี่ยม เรียกว่า รูปทรงลูกบาศก์"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/2] ทัศนธาตุ: อิทธิพลของเส้น","difficulty":"medium","question_type":"mcq","question_text":"การวาดภาพโดยใช้ \"เส้นซิกแซกหรือเส้นหยัก (Zigzag line)\" ให้ความรู้สึกอย่างไรแก่ผู้ชม?","options":["สงบนิ่ง ราบเรียบ","รุนแรง ตื่นเต้น เคลื่อนไหว ขัดแย้ง และน่ากลัว","นุ่มนวล อ่อนช้อย","มั่นคง แข็งแรง"],"answer":1,"explanation":"เส้นหยักหรือเส้นซิกแซก ให้ความรู้สึกตื่นเต้น อันตราย รุนแรง และการเคลื่อนไหวฉับพลัน"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/2] ทัศนธาตุ: เส้นตรงแนวนอน","difficulty":"easy","question_type":"mcq","question_text":"\"เส้นตรงแนวนอน\" เช่น เส้นขอบฟ้าหรือพื้นน้ำนิ่ง ให้ความรู้สึกทางจิตวิทยาอย่างไร?","options":["สงบนิ่ง ราบเรียบ กว้างขวาง และผ่อนคลาย","ตื่นเต้น หวาดเสียว","รวดเร็ว ดั่งสายฟ้า","กำลังล้มลง"],"answer":0,"explanation":"เส้นแนวนอนให้ความรู้สึกสงบ นิ่ง มั่นคง ราบเรียบ และกว้างใหญ่ ดั่งผืนน้ำและเส้นขอบฟ้า"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีอุ่น (Warm Tone)","difficulty":"easy","question_type":"mcq","question_text":"สีในกลุ่มใดจัดเป็นสีใน \"วรรณะอุ่น\" ทั้งหมด?","options":["สีน้ำเงิน, สีฟ้า, สีเขียว","สีแดง, สีส้ม, สีเหลือง, สีม่วงแดง","สีขาว, สีดำ, สีเทา","สีเขียวแก่, สีคราม, สีม่วงน้ำเงิน"],"answer":1,"explanation":"วรรณะสีอุ่นให้ความรู้สึกร้อน ร่าเริง อบอุ่น ได้แก่ สีเหลือง ส้มเหลือง ส้ม แดง ม่วงแดง"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/3] วรรณะของสี: วรรณะสีเย็น (Cool Tone)","difficulty":"easy","question_type":"mcq","question_text":"สีในกลุ่มใดจัดเป็นสีใน \"วรรณะเย็น\" ทั้งหมด?","options":["สีเขียว, สีเขียวตองอ่อน, สีน้ำเงิน, สีคราม","สีแดง, สีส้ม, สีชมพู","สีทอง, สีเงิน, สีทองแดง","สีแสด, สีน้ำตาลไหม้, สีแดงเลือดหมู"],"answer":0,"explanation":"วรรณะสีเย็นให้ความรู้สึกสงบ สดชื่น ร่มเย็น ได้แก่ สีเขียวเหลือง เขียว น้ำเงิน ม่วงน้ำเงิน"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/3] สีที่อยู่ได้ทั้งสองวรรณะ","difficulty":"hard","question_type":"mcq","question_text":"สี 2 สีใดในวงจรสี ที่สามารถอยู่ได้ทั้ง \"วรรณะอุ่น\" และ \"วรรณะเย็น\" ขึ้นอยู่กับสีที่อยู่แวดล้อม?","options":["สีแดงและสีเขียว","สีเหลืองและสีม่วง","สีส้มและสีน้ำเงิน","สีดำและสีขาว"],"answer":1,"explanation":"สีเหลืองและสีม่วง เป็นสีคนกลางที่สามารถปรับเข้ากับวรรณะอุ่นหรือเย็นได้ตามสีข้างเคียงในภาพ"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/3] การผสมแม่สี: สีขั้นที่ 2","difficulty":"easy","question_type":"mcq","question_text":"เมื่อนำแม่สี \"สีแดง\" ผสมกับ \"สีเหลือง\" ในสัดส่วนเท่ากัน จะได้สีใหม่คือสีใด?","options":["สีเขียว","สีส้ม","สีม่วง","สีน้ำตาล"],"answer":1,"explanation":"แม่สีขั้นที่ 1 (แดง + เหลือง) ผสมกันได้ สีส้ม (สีขั้นที่ 2)"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/3] แม่สีขั้นที่ 2: สีเขียว","difficulty":"easy","question_type":"mcq","question_text":"สีเขียวเกิดจากการผสมกันของแม่สีคู่ใด?","options":["สีน้ำเงิน + สีเหลือง","สีแดง + สีน้ำเงิน","สีขาว + สีดำ","สีส้ม + สีม่วง"],"answer":0,"explanation":"สีน้ำเงินผสมกับสีเหลือง จะได้สีเขียว"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/4] แสงและเงาในภาพวาด","difficulty":"medium","question_type":"mcq","question_text":"เมื่อมีแสงส่องมายังวัตถุจากทางด้านบนซ้าย เงาตกทอด (Cast shadow) ของวัตถุจะปรากฏอยู่ที่ทิศทางใด?","options":["ด้านบนซ้าย","ด้านล่างขวา","ด้านบนขวา","ตรงกลางวัตถุพอดี"],"answer":1,"explanation":"เงาตกทอดจะทอดยาวไปในทิศทางตรงกันข้ามกับทิศทางที่แสงส่องมาเสมอ (ตรงข้ามบนซ้ายคือล่างขวา)"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/4] พื้นผิว (Texture)","difficulty":"easy","question_type":"mcq","question_text":"สิ่งใดในธรรมชาติที่มีพื้นผิวสัมผัสแบบ \"ขรุขระ\"?","options":["เปลือกหอยสังข์และเปลือกต้นไม้ใหญ่","ผิวผลแอปเปิล","กระจกเงา","ผิวน้ำนิ่ง"],"answer":0,"explanation":"เปลือกต้นไม้ใหญ่หรือเปลือกผลทุเรียน มีลักษณะพื้นผิวขรุขระอย่างชัดเจน"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/5] เทคนิคการพิมพ์ภาพ (Printmaking)","difficulty":"easy","question_type":"mcq","question_text":"การนำก้านกล้วย ผักบุ้ง หรือใบไม้ มาจุ่มสีแล้วกดทับลงบนกระดาษ เรียกว่าเทคนิคใด?","options":["การวาดเส้น","การพิมพ์ภาพจากวัสดุธรรมชาติ","การปั้นดินน้ำมัน","การแกะสลักหิน"],"answer":1,"explanation":"เป็นการพิมพ์ภาพจากแม่พิมพ์ธรรมชาติ เช่น ก้านกล้วย ใบไม้ เปลือกหอย"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ นูนสูง และลอยตัว","difficulty":"medium","question_type":"mcq","question_text":"รูปปั้นอนุสาวรีย์หรือตุ๊กตาดินเผาที่สามารถเดินมองดูได้รอบทิศทาง 360 องศา จัดเป็นงานปั้นประเภทใด?","options":["งานปั้นนูนต่ำ","งานปั้นนูนสูง","งานปั้นลอยตัว (Round-relief)","งานแกะสลักแบน"],"answer":2,"explanation":"งานปั้นลอยตัวเป็นงานประติมากรรมสามมิติแท้จริงที่สามารถมองเห็นได้ครบทุกด้านรอบทิศทาง"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/6] งานปั้นนูนต่ำ","difficulty":"easy","question_type":"mcq","question_text":"ลวดลายพระบรมรูปบน \"เหรียญกษาปณ์ (เหรียญบาท, เหรียญสิบ)\" จัดเป็นงานปั้นประเภทใด?","options":["งานปั้นนูนต่ำ (Bas-relief)","งานปั้นนูนสูง","งานปั้นลอยตัว","งานวาดเขียน"],"answer":0,"explanation":"เหรียญกษาปณ์มีลวดลายนูนขึ้นมาจากแผ่นพื้นหลังเพียงเล็กน้อย มองเห็นด้านหน้าด้านเดียว จัดเป็นงานปั้นนูนต่ำ"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/7] การจัดองค์ประกอบภาพ: จุดเด่น (Center of Interest)","difficulty":"medium","question_type":"mcq","question_text":"การทำให้สิ่งสำคัญในภาพวาดมีความโดดเด่นสะดุดตาเป็นจุดแรกที่คนมอง เรียกว่าอะไร?","options":["ความกลมกลืน","การสร้างจุดเด่นหรือจุดสนใจ","การระบายสีให้มืดที่สุด","การเว้นช่องว่าง"],"answer":1,"explanation":"จุดเด่นคือส่วนที่ต้องการเน้นให้ผู้ชมมองเห็นเป็นจุดแรก โดยอาจเน้นด้วยขนาด สีสัน หรือตำแหน่งในภาพ"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.1 ป.4/7] ความสมดุลในงานศิลปะ (Balance)","difficulty":"medium","question_type":"mcq","question_text":"ภาพวาดที่มีน้ำหนัก ซ้ายและขวาเท่ากันเหมือนส่องกระจกเงา เรียกว่าความสมดุลแบบใด?","options":["ความสมดุลแบบสองข้างเท่ากัน (Symmetrical Balance)","ความสมดุลแบบสองข้างไม่เท่ากัน","ความขัดแย้ง","ความกลมกลืน"],"answer":0,"explanation":"ความสมดุลแบบซ้ายขวาเหมือนกันทุกประการ (สมมาตร) ให้ความรู้สึกมั่นคง เป็นทางการ สงบ"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.2 ป.4/1] ศิลปะและภูมิปัญญาท้องถิ่น: ผ้ามัดหมี่","difficulty":"medium","question_type":"mcq","question_text":"\"ผ้าไหมมัดหมี่\" เป็นงานหัตถกรรมทัศนศิลป์พื้นบ้านที่มีชื่อเสียงโดดเด่นของภาคใด?","options":["ภาคใต้","ภาคกลาง","ภาคตะวันออกเฉียงเหนือ (อีสาน)","ภาคตะวันออก"],"answer":2,"explanation":"การมัดหมี่ทอผ้าไหมลายโบราณ (เช่น ลายหมี่ขอนารี ลายนาค) เป็นเอกลักษณ์อันวิจิตรงดงามของภาคอีสาน"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.2 ป.4/1] เครื่องปั้นดินเผาเกาะเกร็ด","difficulty":"medium","question_type":"mcq","question_text":"เครื่องปั้นดินเผาดินเผาเนื้อละเอียดแกะสลักลวดลายวิจิตรที่ \"เกาะเกร็ด\" จังหวัดนนทบุรี เป็นภูมิปัญญาของชาวไทยเชื้อสายใด?","options":["ไทยวน","ไทยรามัญ (มอญ)","ไทยพวน","ไทยลื้อ"],"answer":1,"explanation":"เกาะเกร็ดมีชื่อเสียงด้านเครื่องปั้นดินเผาดินแดงแกะสลักลวดลายประณีต สืบทอดจากชาวไทยรามัญ (มอญ)"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.2 ป.4/2] จิตรกรรมฝาผนังวัดไทย","difficulty":"easy","question_type":"mcq","question_text":"ภาพจิตรกรรมฝาผนังภายในพระอุโบสถวัดไทย นิยมเขียนเล่าเรื่องราวเกี่ยวกับสิ่งใดเป็นส่วนใหญ่?","options":["ประวัติศาสตร์สงครามโลก","พุทธประวัติและทศชาติชาดก","ภาพสัตว์ประหลาดแฟนตาซี","ภาพธรรมชาติเมืองหนาว"],"answer":1,"explanation":"จิตรกรรมฝาผนังวัดไทยเน้นบอกเล่าเรื่องพุทธประวัติ ชาดก และนรกสวรรค์เพื่อสอนศีลธรรมแก่พุทธศาสนิกชน"},{"subject":"ศิลปะ","grade":"ป.4","topic":"[ศ 1.2 ป.4/2] การดูแลและทำความสะอาดอุปกรณ์ศิลปะ","difficulty":"easy","question_type":"mcq","question_text":"หลังจากใช้ \"พู่กันระบายสีน้ำ\" เสร็จแล้ว ควรทำความสะอาดและเก็บรักษาอย่างไร?","options":["แช่พู่กันทิ้งไว้ในแก้วน้ำข้ามคืน","ล้างขนพู่กันในน้ำสะอาดจนหมดคราบสี ลูบปลายขนให้แหลมมน แล้ววางผึ่งลมให้แห้ง","ใช้ไฟรนขนพู่กันให้แห้งเร็ว","ทิ้งถังขยะแล้วซื้อใหม่ทุกครั้ง"],"answer":1,"explanation":"การล้างคราบสีออกให้หมด ลูบปลายขนให้เข้าทรง แล้วผึ่งให้แห้ง ช่วยยืดอายุการใช้งานของพู่กัน"}]'::jsonb, 30, 50, 'ART401', true);
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active) VALUES ('แบบทดสอบมาตรฐาน วิชาการงานอาชีพ ป.4 (20 ข้อ)', 'การงานอาชีพ', 'ป.4', '[{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] การดูแลรักษาของใช้ส่วนตัว","difficulty":"easy","question_type":"mcq","question_text":"สิ่งของในข้อใดเป็น \"ของใช้ส่วนตัว\" ที่ไม่ควรใช้ร่วมกับผู้อื่นเพื่อป้องกันโรคติดต่อ?","options":["โต๊ะอาหาร","แปรงสีฟัน, ผ้าเช็ดหน้า, ผ้าเช็ดตัว","โทรทัศน์","พัดลมเพดาน"],"answer":1,"explanation":"แปรงสีฟัน ผ้าเช็ดตัว ผ้าเช็ดหน้า หวี เป็นของใช้ส่วนตัวที่ไม่ควรใช้ปะปนกับผู้อื่นเพราะอาจแพร่กระจายเชื้อโรค"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] การจัดกระเป๋านักเรียน","difficulty":"easy","question_type":"mcq","question_text":"หลักการสำคัญที่สุดในการจัดกระเป๋านักเรียนให้ถูกสุขอนามัยและไม่ปวดหลังคือข้อใด?","options":["ใส่หนังสือเรียนทุกเล่มตั้งแต่ ป.1 ถึง ป.6 ลงในกระเป๋า","จัดสมุดและหนังสือตามตารางสอนในแต่ละวัน และเก็บของชิ้นหนักไว้ชิดแผ่นหลัง","ใส่ของเล่นและขนมให้เต็มกระเป๋า","ถือกระเป๋าด้วยมือข้างเดียวตลอดเวลา"],"answer":1,"explanation":"จัดหนังสือตามตารางเรียนทุกวันเพื่อไม่ให้กระเป๋าหนักเกินไป และวางของหนักแนบชิดหลังเพื่อรักษาสมดุลกระดูกสันหลัง"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] การจัดโต๊ะเขียนหนังสือ","difficulty":"easy","question_type":"mcq","question_text":"การจัดวางหนังสือบนโต๊ะเขียนหนังสือควรจัดวางอย่างไรให้หยิบใช้สะดวกและเป็นระเบียบ?","options":["วางกองซ้อนทับกันโดยไม่แยกประเภท","จัดเรียงหนังสือจากเล่มสูงไปเล่มต่ำ หันสันหนังสือออกด้านนอก และแยกประเภทสมุด-หนังสือ","วางหนังสือกระจัดกระจายบนเก้าอี้","คว่ำหน้าหนังสือเปิดทิ้งไว้"],"answer":1,"explanation":"การวางเรียงความสูงและหันสันหนังสือออกด้านนอกช่วยให้มองเห็นชื่อหนังสือและหยิบใช้งานได้สะดวก"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] การจัดตู้เสื้อผ้า","difficulty":"medium","question_type":"mcq","question_text":"เสื้อผ้าประเภทใดควร \"พับเก็บ\" ใส่ลิ้นชัก แทนการแขวนด้วยไม้แขวนเสื้อ?","options":["เสื้อเชิ้ตและชุดนักเรียน","เสื้อยืด, กางเกงขาสั้น, ชุดชั้นใน และถุงเท้า","เสื้อสูท","กระโปรงพลีทจีบ"],"answer":1,"explanation":"เสื้อยืดและชุดชั้นในควรพับเก็บเพื่อประหยัดเนื้อที่ตู้ ส่วนชุดนักเรียนและเสื้อเชิ้ตที่รีดแล้วควรแขวนเพื่อไม่ให้ยับ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การกวาดบ้านและถูบ้าน","difficulty":"easy","question_type":"mcq","question_text":"ขั้นตอนการกวาดบ้านที่ถูกต้องตามหลักสุขาภิบาลควรเริ่มจากบริเวณใดก่อน?","options":["กวาดจากชั้นล่างขึ้นชั้นบน","กวาดจากที่สูงลงที่ต่ำ (เช่น ปัดฝุ่นบนตู้ เพดาน แล้วจึงกวาดพื้น) และกวาดจากมุมห้องออกสู่ประตู","กวาดกระจายไปทั่วทุกทิศทางพร้อมกัน","ถูพื้นก่อนแล้วจึงค่อยกวาดขยะ"],"answer":1,"explanation":"ต้องปัดฝุ่นจากที่สูงลงสู่พื้นก่อน จากนั้นกวาดจากซอกมุมห้องมารวมกันตรงกลางหรือหน้าประตูเพื่อตักใส่ที่โกยขยะ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] ไม้กวาดชนิดต่างๆ: ไม้กวาดดอกหญ้า","difficulty":"easy","question_type":"mcq","question_text":"\"ไม้กวาดดอกหญ้า\" เหมาะสำหรับใช้กวาดพื้นผิวประเภทใด?","options":["พื้นซีเมนต์หยาบนอกบ้านที่มีน้ำขัง","พื้นไม้, พื้นกระเบื้อง, พื้นหินขัดที่แห้งและเรียบภายในบ้าน","พื้นสนามหญ้าที่มีใบไม้ร่วง","พื้นดินเลน"],"answer":1,"explanation":"ไม้กวาดดอกหญ้ามีขนอ่อนนุ่ม เหมาะสำหรับกวาดฝุ่นละอองบนพื้นแห้งและเรียบภายในบ้าน ห้ามนำไปกวาดพื้นเปียกน้ำ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] ไม้กวาดทางมะพร้าว","difficulty":"easy","question_type":"mcq","question_text":"หากต้องการกวาดใบไม้แห้งในสนามหญ้าหรือกวาดน้ำขังบนพื้นซีเมนต์ ควรเลือกใช้ไม้กวาดชนิดใด?","options":["ไม้กวาดดอกหญ้า","ไม้กวาดทางมะพร้าว","ไม้กวาดขนไก่","ไม้ปัดหยากไย่"],"answer":1,"explanation":"ไม้กวาดทางมะพร้าวมีความแข็งและทนทาน เหมาะสำหรับกวาดพื้นซีเมนต์หยาบ พื้นดิน สนามหญ้า และพื้นเปียกน้ำ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การล้างจานชาม","difficulty":"easy","question_type":"mcq","question_text":"ก่อนนำจานชามไปล้างด้วยน้ำยาล้างจาน ขั้นตอนแรกที่ต้องทำคือข้อใด?","options":["แช่น้ำร้อนทันที","กวาดเศษอาหารทิ้งลงในถังขยะ และล้างคราบสกปรกหยาบด้วยน้ำสะอาด 1 ครั้ง","ใช้น้ำยาล้างจานเทราดลงไปขณะมีเศษอาหาร","นำไปผึ่งแดดก่อน"],"answer":1,"explanation":"ต้องแยกกวาดเศษอาหารออกให้หมดก่อน แล้วล้างน้ำเปล่ารอบหนึ่ง จะช่วยให้ล้างคราบมันได้ง่ายขึ้นและท่อไม่อุดตัน"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การซักรองเท้าผ้าใบนักเรียน","difficulty":"medium","question_type":"mcq","question_text":"การตากรองเท้าผ้าใบสีขาวหลังจากซักเสร็จ ควรปฏิบัติตามข้อใดเพื่อป้องกันรองเท้าเกิดคราบเหลือง?","options":["ตากแดดจัดโดยไม่ต้องหุ้มอะไร","นำกระดาษทิชชูสีขาวมาพันหุ้มให้ทั่วรองเท้าก่อนนำไปตากแดด","อบในเตาไมโครเวฟ","แช่น้ำยาฟอกขาวทิ้งไว้ข้ามคืน"],"answer":1,"explanation":"การใช้กระดาษทิชชูสีขาวพันหุ้มรองเท้าผ้าใบ กระดาษทิชชูจะช่วยดูดซับคราบด่างของผงซักฟอก ป้องกันการเกิดคราบเหลือง"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] สัญลักษณ์การดูแลรักษาเสื้อผ้า","difficulty":"hard","question_type":"mcq","question_text":"สัญลักษณ์รูป \"เตารีดที่มีจุด 1 จุด (•)\" บนป้ายฉลากเสื้อผ้า หมายความว่าอย่างไร?","options":["ห้ามรีดเด็ดขาด","รีดด้วยอุณหภูมิต่ำ (ความร้อนต่ำ)","รีดด้วยอุณหภูมิปานกลาง","รีดด้วยอุณหภูมิสูงสุด"],"answer":1,"explanation":"จุด 1 จุด หมายถึง อุณหภูมิต่ำ (สำหรับผ้าใยสังเคราะห์ ไนลอน), 2 จุด = ปานกลาง (ผ้าขนสัตว์ ผ้าไหม), 3 จุด = สูง (ผ้าฝ้าย ลินิน)"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การจัดห้องนอน","difficulty":"easy","question_type":"mcq","question_text":"หลังจากตื่นนอนในตอนเช้า สิ่งที่นักเรียนควรทำทันทีคือข้อใด?","options":["วิ่งไปเปิดโทรทัศน์","พับผ้าห่ม จัดหมอนและดึงผ้าปูที่นอนให้ตึงเรียบร้อย","กระโดดลงจากเตียงแล้วออกจากบ้านทันที","โยนหมอนลงบนพื้น"],"answer":1,"explanation":"การเก็บที่นอน พับผ้าห่ม และจัดหมอนให้เรียบร้อยหลังตื่นนอน เป็นการสร้างวินัยและความเป็นระเบียบของตนเอง"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การทำความสะอาดตู้เย็น","difficulty":"medium","question_type":"mcq","question_text":"ข้อใดเป็นการดูแลรักษาตู้เย็นที่ถูกต้องและประหยัดพลังงาน?","options":["นำอาหารที่ยังร้อนจัดใส่ตู้เย็นทันที","เปิดประตูตู้เย็นทิ้งไว้เพื่อระบายความร้อน","ตรวจสอบอาหารหมดอายุทิ้งสม่ำเสมอ และละลายน้ำแข็งในช่องแช่แข็งเมื่อหนาเกินกำหนด","ตั้งตู้เย็นติดชิดผนังห้องโดยไม่เว้นช่องว่าง"],"answer":2,"explanation":"การละลายน้ำแข็งสม่ำเสมอและไม่ตั้งตู้เย็นชิดผนังเกินไปช่วยให้คอมเพรสเซอร์ระบายความร้อนได้ดีและประหยัดไฟ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การตากผ้า","difficulty":"easy","question_type":"mcq","question_text":"ก่อนนำเสื้อผ้าไปตากแดด ควรทำสิ่งใดเพื่อให้ผ้ายับน้อยลงและสีไม่ซีดจาง?","options":["กลับเอาด้านในออกด้านนอก แล้วสะบัดผ้าก่อนพาดบนไม้แขวนเสื้อ","ขยำผ้าให้เป็นก้อนกลม","ตากในที่มืดสนิท","นำผ้าไปแช่น้ำมัน"],"answer":0,"explanation":"การกลับด้านในออกด้านนอกช่วยป้องกันแดดเลียสีผ้าให้ซีดจาง และการสะบัดผ้าช่วยคลายรอยยับทำให้รีดง่าย"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การกำจัดกลิ่นอับในตู้เสื้อผ้า","difficulty":"medium","question_type":"mcq","question_text":"วัสดุธรรมชาติในข้อใดสามารถนำมาใส่ในตู้เสื้อผ้าเพื่อช่วยดูดซับกลิ่นอับชื้นได้ดี?","options":["ถ่านหุงต้มหรือผงเบกกิ้งโซดา","เศษดินทราย","ใบไม้สดเปียกน้ำ","น้ำส้มคั้น"],"answer":0,"explanation":"ถ่านไม้มีรูพรุนขนาดเล็กจำนวนมาก ช่วยดูดซับกลิ่นอับชื้นและความชื้นในตู้เสื้อผ้าได้อย่างปลอดภัย"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การล้างห้องน้ำอย่างปลอดภัย","difficulty":"medium","question_type":"mcq","question_text":"ในการใช้น้ำยาล้างห้องน้ำที่มีฤทธิ์เป็นกรด ควรสวมใส่อุปกรณ์ป้องกันใดเพื่อความปลอดภัย?","options":["ถุงมือยาง, รองเท้าบูทยาง และหน้ากากอนามัย","ถุงมือผ้าบางๆ","แว่นตากันแดด","ชุดนอน"],"answer":0,"explanation":"กรดในน้ำยาล้างห้องน้ำกัดกร่อนผิวหนังและไอระเหยเป็นอันตรายต่อระบบทางเดินหายใจ จึงต้องสวมถุงมือและรองเท้ายาง"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] การดูแลรักษากล่องดินสอ","difficulty":"easy","question_type":"mcq","question_text":"เพื่อป้องกันไม่ให้กระเป๋าหรือกล่องดินสอเปรอะเปื้อนคราบหมึก ควรทำอย่างไร?","options":["เปิดปลอกปากกาทิ้งไว้เสมอ","ปิดฝาปลอกปากกาและสวมปลอกดินสอให้เรียบร้อยทุกครั้งหลังใช้งาน","เหลาดินสอจนแหลมทิ่มทะลุกล่อง","ทิ้งไส้ดินสอกดไว้ในกล่อง"],"answer":1,"explanation":"การสวมปลอกดินสอและปิดปลอกปากกาช่วยป้องกันไส้ดินสอหักและป้องกันน้ำหมึกเลอะสิ่งของ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การประหยัดน้ำในงานบ้าน","difficulty":"easy","question_type":"mcq","question_text":"น้ำสุดท้ายจากการล้างจานหรือซักผ้า สามารถนำไปใช้ประโยชน์ต่อได้อย่างไร?","options":["เททิ้งลงบนถนน","นำไปรดน้ำต้นไม้หรือล้างพื้นบริเวณรอบบ้าน","นำมาใช้ดื่ม","นำมาใช้ทำอาหาร"],"answer":1,"explanation":"น้ำซักล้างที่ไม่ปนเปื้อนสารเคมีอันตรายสามารถนำมารดน้ำต้นไม้หรือล้างลานซีเมนต์เพื่อประหยัดน้ำได้"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/2] การแยกขยะในบ้าน","difficulty":"easy","question_type":"mcq","question_text":"เปลือกผลไม้และเศษอาหารจากห้องครัวควรคัดแยกไว้ในถังขยะประเภทใดเพื่อนำไปทำปุ๋ยหมัก?","options":["ขยะเปียกหรือขยะอินทรีย์","ขยะรีไซเคิล","ขยะอันตราย","ขยะติดเชื้อ"],"answer":0,"explanation":"ขยะเปียกหรือขยะอินทรีย์ย่อยสลายได้ง่าย เหมาะสำหรับนำไปทำปุ๋ยหมักบำรุงดิน"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] ไม้ดอกและไม้ประดับ","difficulty":"easy","question_type":"mcq","question_text":"ข้อใดเป็น \"ไม้ดอก\" (พืชที่ปลูกเพื่อชื่นชมความสวยงามของดอก)?","options":["ดาวเรือง, กุหลาบ, มะลิ, กล้วยไม้","พลูด่าง, สาวน้อยปะแป้ง, ลิ้นมังกร","ผักบุ้ง, คะน้า","ต้นยางพารา, ต้นปาล์ม"],"answer":0,"explanation":"ดาวเรือง กุหลาบ มะลิ มีดอกสวยงามมีกลิ่นหอม จัดเป็นไม้ดอก ส่วนพลูด่าง ลิ้นมังกร เน้นใบสวยงามจัดเป็นไม้ประดับ"},{"subject":"การงานอาชีพ","grade":"ป.4","topic":"[ง 1.1 ป.4/1] ไม้ประดับ (Foliage plants)","difficulty":"easy","question_type":"mcq","question_text":"พืชในข้อใดจัดเป็น \"ไม้ประดับ\" ที่นิยมปลูกเพื่อชมความสวยงามของใบและลำต้น?","options":["ดอกบัว","พลูด่าง และ เฟิร์นข้าหลวง","ดอกชบา","มะลิซ้อน"],"answer":1,"explanation":"พลูด่างและเฟิร์นข้าหลวงมีใบและทรงพุ่มที่สวยงาม จึงนิยมปลูกประดับตกแต่งอาคารสถานที่"}]'::jsonb, 30, 50, 'CAR401', true);